{
  "name": "Padel Pro Manager",
  "description": "A comprehensive Padel tournament management application featuring player profiles, live scoring, team generation, and statistical reporting."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS'
}

export interface Player {
  id: string;
  name: string;
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Match {
  id: string;
  team1: string[];
  team2: string[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
}

import React from 'react';
import { Screen } from '../types';

interface NavigationProps {
  currentScreen: Screen;
  setScreen: (screen: Screen) => void;
}

export const Navigation: React.FC<NavigationProps> = ({ currentScreen, setScreen }) => {
  const navItems = [
    { id: Screen.HOME, icon: 'home', label: 'Início' },
    { id: Screen.LIVE_GAME, icon: 'sports_tennis', label: 'Jogos' },
    { id: Screen.GLOBAL_STATS, icon: 'bar_chart', label: 'Estatísticas' },
    { id: Screen.PROFILE, icon: 'person', label: 'Perfil' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-t border-white/5 pb-6 pt-3 z-50 max-w-md mx-auto">
      <div className="flex justify-around items-center">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setScreen(item.id)}
            className={`flex flex-col items-center gap-1 w-16 transition-colors ${
              currentScreen === item.id ? 'text-primary' : 'text-slate-500 hover:text-white'
            }`}
          >
            <span className={`material-symbols-outlined text-[24px] ${currentScreen === item.id ? 'filled' : ''}`}>
              {item.icon}
            </span>
            <span className={`text-[10px] font-medium ${currentScreen === item.id ? 'font-bold' : ''}`}>
              {item.label}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
};

