            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.TEAM_SETUP ? 'Definir Equipas' : ''}
               {currentScreen === Screen.LIVE_GAME ? 'Resultados Ronda 1' : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados' : ''}
            </h2>
             <div className="w-12"></div>
