import React, { useState } from 'react';
import { Screen, Player, Match } from '../types';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  // State for 4 slots in Match 1
  const [teamA, setTeamA] = useState<Player[]>([]);
  const [teamB, setTeamB] = useState<Player[]>([]);

  // Players available are those not in Team A or Team B
  const availablePlayers = players.filter(p => !teamA.find(ta => ta.id === p.id) && !teamB.find(tb => tb.id === p.id));

  const handlePlayerClick = (player: Player) => {
    // Add to first available slot
    if (teamA.length < 2) {
      setTeamA([...teamA, player]);
    } else if (teamB.length < 2) {
      setTeamB([...teamB, player]);
    }
  };

  const removePlayer = (player: Player, team: 'A' | 'B') => {
    if (team === 'A') {
      setTeamA(teamA.filter(p => p.id !== player.id));
    } else {
      setTeamB(teamB.filter(p => p.id !== player.id));
    }
  };

  const handleRandomize = () => {
    // Shuffle all players
    const shuffled = [...players].sort(() => 0.5 - Math.random());
    // Take first 4 for this match
    const selected = shuffled.slice(0, 4);

    setTeamA([selected[0], selected[1]]);
    setTeamB([selected[2], selected[3]]);
  };

  const handleStart = () => {
    if (teamA.length !== 2 || teamB.length !== 2) return;

    // Create Match Object
    const newMatch: Match = {
      id: `match-${Date.now()}`,
      team1: teamA,
      team2: teamB,
      score1: 0,
      score2: 0,
      court: 1,
      status: 'live',
      round: 1
    };

    onStartTournament([newMatch]);
  };

  const handleGenerateFullRound = () => {
      // Automatism: Generate matches for ALL players (8 players -> 2 courts)
      const shuffled = [...players].sort(() => 0.5 - Math.random());
      const matches: Match[] = [];

      // Match 1
      matches.push({
          id: 'm1',
          team1: [shuffled[0], shuffled[1]],
          team2: [shuffled[2], shuffled[3]],
          score1: 0,
          score2: 0,
          court: 1,
          status: 'live',
          round: 1
      });

      // Match 2 (if enough players)
      if (players.length >= 8) {
         matches.push({
          id: 'm2',
          team1: [shuffled[4], shuffled[5]],
          team2: [shuffled[6], shuffled[7]],
          score1: 0,
          score2: 0,
          court: 2,
          status: 'live',
          round: 1
        });
      }

      onStartTournament(matches);
  };

  return (
    <div className="relative flex h-full flex-col overflow-x-hidden pb-32 animate-fade-in">
       <div className="px-6 pt-6 pb-2">
        <p className="text-center text-[#9db9a8] text-sm font-normal leading-relaxed">
            Selecione jogadores ou use o sorteio automático para a Ronda 1.
        </p>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3 px-4 mb-4">
        <button 
            onClick={handleRandomize}
            className="flex items-center justify-center gap-2 bg-surface-dark border border-white/10 text-white py-3 rounded-xl text-sm font-bold active:scale-95 transition-all"
        >
            <span className="material-symbols-outlined text-primary">shuffle</span>
            Preencher Jogo
        </button>
        <button 
            onClick={handleGenerateFullRound}
            className="flex items-center justify-center gap-2 bg-primary/20 border border-primary/50 text-primary py-3 rounded-xl text-sm font-bold active:scale-95 transition-all"
        >
            <span className="material-symbols-outlined">auto_fix_high</span>
            Gerar Ronda 1
        </button>
      </div>

      <div className="w-full px-4 py-2">
        <div className="mb-3 flex items-center justify-between px-1">
            <h3 className="text-xs font-bold uppercase tracking-wider text-[#9db9a8]">JOGADORES DISPONÍVEIS</h3>
            <span className="text-xs font-bold text-background-dark bg-[#9db9a8] px-2 py-0.5 rounded-full">{availablePlayers.length}</span>
        </div>

