  const [teamB, setTeamB] = useState<Player[]>([]);
  const [teamC, setTeamC] = useState<Player[]>([]);
  const [teamD, setTeamD] = useState<Player[]>([]);

  // Drag-to-scroll State
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isDown, setIsDown] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [isDragging, setIsDragging] = useState(false);

  // Players available are those not in any team, SORTED ALPHABETICALLY
  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  ).sort((a, b) => a.name.localeCompare(b.name));

  const handlePlayerClick = (player: Player) => {
    // Prevent selection if user was just dragging the list
    if (isDragging) return;

    // Add to first available slot sequentially
    if (teamA.length < 2) {
      setTeamA([...teamA, player]);
    } else if (teamB.length < 2) {
      setTeamB([...teamB, player]);
    } else if (teamC.length < 2) {
      setTeamC([...teamC, player]);
    } else if (teamD.length < 2) {
      setTeamD([...teamD, player]);
    }
  };

  const removePlayer = (player: Player, team: 'A' | 'B' | 'C' | 'D') => {
    if (team === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (team === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (team === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (team === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleRandomizeAll = () => {
    const currentAssignedIds = new Set([
        ...teamA.map(p => p.id),
        ...teamB.map(p => p.id),
        ...teamC.map(p => p.id),
        ...teamD.map(p => p.id)
    ]);

    // Players not yet assigned
    const pool = players.filter(p => !currentAssignedIds.has(p.id));
    const shuffled = [...pool].sort(() => 0.5 - Math.random());

    let poolIndex = 0;

    // Fill A
    const newA = [...teamA];
    while(newA.length < 2 && poolIndex < shuffled.length) newA.push(shuffled[poolIndex++]);
    setTeamA(newA);

    // Fill B
    const newB = [...teamB];
    while(newB.length < 2 && poolIndex < shuffled.length) newB.push(shuffled[poolIndex++]);
    setTeamB(newB);

    // Fill C
    const newC = [...teamC];
    while(newC.length < 2 && poolIndex < shuffled.length) newC.push(shuffled[poolIndex++]);
    setTeamC(newC);

    // Fill D
    const newD = [...teamD];
    while(newD.length < 2 && poolIndex < shuffled.length) newD.push(shuffled[poolIndex++]);
    setTeamD(newD);
  };

  const handleClearAll = () => {
    setTeamA([]);
    setTeamB([]);
    setTeamC([]);
    setTeamD([]);
  };

  const handleStart = () => {
    if (teamA.length !== 2 || teamB.length !== 2 || teamC.length !== 2 || teamD.length !== 2) return;

    const timestamp = Date.now();

    const matches: Match[] = [
        {
            id: `match-1-${timestamp}`,
            team1: teamA,
            team2: teamB,
            score1: 0,
            score2: 0,
            court: 1,
            status: 'live',
            round: 1
        },
        {
            id: `match-2-${timestamp}`,
            team1: teamC,
            team2: teamD,
            score1: 0,
            score2: 0,
            court: 2,
            status: 'live',
            round: 1
        }
    ];

    onStartTournament(matches);
  };

  // --- Drag Scroll Handlers ---
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollRef.current) return;
    setIsDown(true);
    setIsDragging(false);
    setStartX(e.pageX - scrollRef.current.offsetLeft);
    setScrollLeft(scrollRef.current.scrollLeft);
  };

  const handleMouseLeave = () => {
    setIsDown(false);
  };

  const handleMouseUp = () => {
    setIsDown(false);
    // Small timeout to allow click event to register if it wasn't a drag
    setTimeout(() => setIsDragging(false), 50);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDown || !scrollRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollRef.current.offsetLeft;
    const walk = (x - startX) * 2; // Scroll-fast

    // Only register as drag if moved significantly
    if (Math.abs(walk) > 5) {
        setIsDragging(true);
        scrollRef.current.scrollLeft = scrollLeft - walk;
    }
  };

  const renderTeamSlot = (team: Player[], teamName: string, teamId: 'A' | 'B' | 'C' | 'D', colorClass: string, ringColor: string) => (
    <div className="flex flex-col rounded-2xl bg-surface-dark p-3 shadow-sm border border-white/5">
        <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
                <div className={`h-6 w-1 ${colorClass} rounded-full`}></div>
                <h3 className="text-sm font-bold text-white">Equipa {teamId}</h3>
            </div>
            <span className={`text-[10px] font-bold ${team.length === 2 ? 'text-green-400' : 'text-slate-500'}`}>{team.length}/2</span>
        </div>
        <div className="grid grid-cols-2 gap-2">
            {[0, 1].map(index => {
                const player = team[index];
                return player ? (
                    <div key={player.id} className="relative flex flex-col items-center justify-center rounded-lg border border-white/10 bg-[#28392f] p-2 animate-fade-in-up">
                        <button onClick={() => removePlayer(player, teamId)} className="absolute -top-1 -right-1 rounded-full bg-surface-dark text-slate-400 hover:text-red-400 transition-colors p-0.5 border border-white/10">
                            <span className="material-symbols-outlined text-[14px]">close</span>
                        </button>
                        <img src={player.image} className={`mb-1 h-8 w-8 rounded-full object-cover ring-2 ${ringColor}`} />
                        <span className="text-xs font-semibold text-center leading-tight truncate w-full text-white">{player.name.split(' ')[0]}</span>
                    </div>
                ) : (
                    <div key={`empty-${teamId}-${index}`} className="flex h-[70px] flex-col items-center justify-center rounded-lg border border-dashed border-white/10 bg-black/20">
                         <div className="flex h-6 w-6 items-center justify-center rounded-full bg-white/5 mb-1">
                            <span className="material-symbols-outlined text-slate-600 text-[16px]">add</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  return (
    <div className="relative flex h-full flex-col overflow-x-hidden pb-40 animate-fade-in">
       <div className="px-4 pt-4 pb-2">
        <p className="text-center text-[#9db9a8] text-xs font-normal leading-relaxed">
            Organize as 4 equipas para os 2 campos.
        </p>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3 px-4 mb-4">
        <button 
            onClick={handleClearAll}
            className="flex items-center justify-center gap-2 bg-surface-dark border border-white/10 text-white py-2.5 rounded-xl text-xs font-bold active:scale-95 transition-all hover:bg-white/5"
        >
            <span className="material-symbols-outlined text-sm">restart_alt</span>
            Limpar
        </button>
        <button 
            onClick={handleRandomizeAll}
            className="flex items-center justify-center gap-2 bg-primary/10 border border-primary/30 text-primary py-2.5 rounded-xl text-xs font-bold active:scale-95 transition-all hover:bg-primary/20"
        >
            <span className="material-symbols-outlined text-sm">auto_fix_high</span>
            Preencher Auto
        </button>
      </div>

      {/* Available Players List (Horizontal Scroll + Drag) */}
      <div className="w-full px-4 mb-2">
        <div className="mb-2 flex items-center justify-between px-1">
            <h3 className="text-[10px] font-bold uppercase tracking-wider text-[#9db9a8]">Disponíveis ({availablePlayers.length})</h3>
            <span className="text-[10px] text-slate-500 font-medium">Arraste para ver mais &rarr;</span>
        </div>

        <div 
            ref={scrollRef}
            onMouseDown={handleMouseDown}
            onMouseLeave={handleMouseLeave}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            className="flex overflow-x-auto gap-2 p-2 bg-surface-dark rounded-xl border border-white/5 shadow-inner min-h-[60px] hide-scrollbar cursor-grab active:cursor-grabbing select-none"
        >
            {availablePlayers.length === 0 && <p className="text-slate-600 text-xs w-full text-center py-2 flex items-center justify-center">Vazio</p>}
            {availablePlayers.map((p) => (
                <button 
                    key={p.id} 
                    onClick={() => handlePlayerClick(p)}
                    className="flex-shrink-0 flex flex-col items-center justify-center gap-1 w-14 active:scale-95 transition-all"
                >
                    <div className="size-8 rounded-full bg-white/10 overflow-hidden ring-1 ring-white/20 pointer-events-none">
                        {p.image ? <img src={p.image} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-white text-[16px]">person</span>}
                    </div>
                    <p className="text-white text-[10px] font-medium leading-none truncate w-full text-center pointer-events-none">{p.name.split(' ')[0]}</p>
                </button>
            ))}
        </div>
      </div>

      <div className="flex flex-col gap-4 px-4 mt-2">
        {/* Match 1 Section */}
        <div className="space-y-2">
            <div className="flex items-center justify-between px-1">
                 <h3 className="text-xs font-bold text-primary uppercase tracking-wider flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">stadium</span> Campo 1
                 </h3>
                 <span className="text-[10px] text-slate-500">Jogo 1</span>
            </div>
            <div className="grid grid-cols-2 gap-2">
                {renderTeamSlot(teamA, 'Equipa A', 'A', 'bg-primary', 'ring-primary/30')}
                {renderTeamSlot(teamB, 'Equipa B', 'B', 'bg-blue-400', 'ring-blue-400/30')}
            </div>
        </div>

        {/* Match 2 Section */}
        <div className="space-y-2 pb-4">
            <div className="flex items-center justify-between px-1">
                 <h3 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">stadium</span> Campo 2
                 </h3>
                 <span className="text-[10px] text-slate-500">Jogo 2</span>
            </div>
            <div className="grid grid-cols-2 gap-2">
                {renderTeamSlot(teamC, 'Equipa C', 'C', 'bg-purple-500', 'ring-purple-500/30')}
                {renderTeamSlot(teamD, 'Equipa D', 'D', 'bg-orange-400', 'ring-orange-400/30')}
            </div>
        </div>

      </div>

      <div className="fixed bottom-16 left-0 right-0 z-30 bg-[#102217]/90 backdrop-blur-xl border-t border-white/5 px-4 pt-4 pb-8 max-w-md mx-auto">
        <button 
            onClick={handleStart}
            disabled={!isReady}
            className={`group w-full rounded-xl font-bold text-base py-4 shadow-lg transition-all flex items-center justify-center gap-2 ${
                isReady 
                ? 'bg-primary text-background-dark hover:bg-primary-dark cursor-pointer' 
                : 'bg-gray-700 text-gray-500 cursor-not-allowed'
            }`}
        >
            <span>Iniciar Torneio (2 Jogos)</span>
            <span className="material-symbols-outlined" style={{ fontSize: '20px' }}>sports_tennis</span>
        </button>
      </div>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS'
}

export interface Player {
  id: string;
  name: string;
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
}

export interface Tournament {
  id: string;
  date: string; // ISO String or YYYY-MM-DD
  time: string;
  duration: number; // in hours
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
}

