const DEFAULT_LOCATIONS: Location[] = [
  { id: '1', name: 'Clube Central Padel', type: 'Indoor' },
  { id: '2', name: 'Padel Center Odivelas', type: 'Indoor' },
  { id: '3', name: 'Monsanto Padel Club', type: 'Outdoor' },
