import React, { useState } from 'react';
import { Screen, Location } from '../types';

interface LocationManagerProps {
  setScreen: (screen: Screen) => void;
  locations: Location[];
  setLocations: React.Dispatch<React.SetStateAction<Location[]>>;
}

export const LocationManagerScreen: React.FC<LocationManagerProps> = ({ setScreen, locations, setLocations }) => {
  const [newLocName, setNewLocName] = useState('');
  const [newLocType, setNewLocType] = useState<'Indoor' | 'Outdoor'>('Indoor');
  const [isAdding, setIsAdding] = useState(false);

  const handleAdd = () => {
    if (!newLocName.trim()) return;
    const newLocation: Location = {
        id: `loc-${Date.now()}`,
        name: newLocName,
        type: newLocType
    };
    setLocations([...locations, newLocation]);
    setNewLocName('');
    setIsAdding(false);
  };

  const handleDelete = (id: string) => {
    if (confirm('Tem a certeza que deseja remover este local?')) {
        setLocations(locations.filter(l => l.id !== id));
    }
  };

  return (
    <div className="flex flex-col h-full px-4 pb-24 animate-fade-in">
        {/* Add Section */}
        {isAdding ? (
            <div className="bg-card-dark p-4 rounded-2xl border border-primary/30 shadow-lg mb-6 animate-fade-in-up">
                <h3 className="font-bold text-white mb-3">Adicionar Local</h3>
                <input 
                    type="text" 
                    placeholder="Nome do Clube / Campo" 
                    value={newLocName}
                    onChange={(e) => setNewLocName(e.target.value)}
                    className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 mb-3"
                    autoFocus
                />
                <div className="flex gap-2 mb-4">
                    <button 
                        onClick={() => setNewLocType('Indoor')}
                        className={`flex-1 py-2 rounded-lg text-sm font-bold border transition-colors ${newLocType === 'Indoor' ? 'bg-primary text-background-dark border-primary' : 'bg-transparent border-white/10 text-gray-400'}`}
                    >
                        Indoor
                    </button>
                    <button 
                         onClick={() => setNewLocType('Outdoor')}
                        className={`flex-1 py-2 rounded-lg text-sm font-bold border transition-colors ${newLocType === 'Outdoor' ? 'bg-blue-500 text-white border-blue-500' : 'bg-transparent border-white/10 text-gray-400'}`}
                    >
                        Outdoor
                    </button>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-400 font-bold hover:text-white">Cancelar</button>
                    <button onClick={handleAdd} className="flex-1 py-3 bg-white text-background-dark rounded-xl font-bold hover:bg-gray-200">Guardar</button>
                </div>
            </div>
        ) : (
            <button 
                onClick={() => setIsAdding(true)}
                className="w-full py-4 mb-6 border-2 border-dashed border-white/10 rounded-2xl flex items-center justify-center gap-2 text-gray-400 hover:text-primary hover:border-primary/50 hover:bg-primary/5 transition-all"
            >
                <span className="material-symbols-outlined">add_location</span>
                <span className="font-bold">Adicionar Novo Local</span>
            </button>
        )}

        {/* List */}
        <div className="flex flex-col gap-3">
             <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider px-1">Locais Guardados ({locations.length})</h3>
             {locations.length === 0 && (
                 <div className="text-center py-10 text-gray-600">
                     <p>Nenhum local configurado.</p>
                 </div>
             )}
             {locations.map((loc) => (
                 <div key={loc.id} className="flex items-center justify-between p-4 bg-surface-dark rounded-xl border border-white/5 hover:border-white/10 transition-colors">
                     <div className="flex items-center gap-3">
                         <div className={`size-10 rounded-full flex items-center justify-center ${loc.type === 'Indoor' ? 'bg-primary/10 text-primary' : 'bg-blue-500/10 text-blue-400'}`}>
                             <span className="material-symbols-outlined">{loc.type === 'Indoor' ? 'roofing' : 'sunny'}</span>
                         </div>
                         <div>
                             <h4 className="font-bold text-white">{loc.name}</h4>
                             <span className="text-xs text-gray-400 font-medium px-2 py-0.5 bg-white/5 rounded-md">{loc.type}</span>
                         </div>
                     </div>
                     <button 
                        onClick={() => handleDelete(loc.id)}
                        className="size-8 flex items-center justify-center text-gray-500 hover:text-red-400 hover:bg-red-500/10 rounded-full transition-colors"
                    >
                         <span className="material-symbols-outlined text-[20px]">delete</span>
                     </button>
                 </div>
             ))}
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament 
}) => {
  const [isCreating, setIsCreating] = useState(false);

  // Form State
  const [date, setDate] = useState('');
  const [time, setTime] = useState('19:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  // Initialize selected players with first 8 when opening form
  const initCreation = () => {
    // Default to today
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    // Pre-select first 8 players
    setSelectedPlayers(players.slice(0, 8).map(p => p.id));
    // Pre-select first location
    if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
  };

  const togglePlayer = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const handleSubmit = () => {
    if (!date || !time || !locationId) return;

    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled'
    };

    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  // Helper to get location name
  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>

            <div className="space-y-5">
                {/* Date & Time */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Data</label>
                        <input 
                            type="date" 
                            value={date}
                            onChange={(e) => setDate(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Hora</label>
                        <input 
                            type="time" 
                            value={time}
                            onChange={(e) => setTime(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans"
                        />
                    </div>
                </div>

                {/* Duration */}
                <div className="space-y-2">
                    <div className="flex justify-between">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Duração</label>
                        <span className="text-xs font-bold text-primary">{duration}h</span>
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="4" 
                        step="0.5" 
                        value={duration}
                        onChange={(e) => setDuration(parseFloat(e.target.value))}
                        className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer"
                    />
                    <div className="flex justify-between text-[10px] text-gray-500 font-mono">
                        <span>1h</span>
                        <span>4h</span>
                    </div>
                </div>

                {/* Location */}
                <div className="space-y-2">
                     <div className="flex justify-between items-center">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Local</label>
                        <button onClick={() => setScreen(Screen.LOCATIONS)} className="text-[10px] font-bold text-primary hover:underline flex items-center gap-1">
                            <span className="material-symbols-outlined text-[14px]">settings</span>
                            Gerir
                        </button>
                    </div>
                    <div className="relative">
                        <select 
                            value={locationId}
                            onChange={(e) => setLocationId(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans appearance-none"
