                            <div className="flex items-center gap-1 text-xs text-gray-400 mt-0.5">
                                <span className="material-symbols-outlined text-[14px] text-yellow-500">emoji_events</span>
                                <span>{t.winner}</span>
                            </div>
                        </div>
                        <div className="px-3 py-1 bg-primary/10 rounded-md border border-primary/20">
                            <span className="text-sm font-bold text-primary">{t.score}</span>
                        </div>
                    </div>
                ))}
            </div>
        </section>

        {/* Quick Stats Teaser */}
        <div className="grid grid-cols-2 gap-3">
            <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <p className="text-gray-400 text-xs font-bold uppercase mb-1">Jogos Realizados</p>
                <p className="text-2xl font-bold text-white">24</p>
            </div>
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <p className="text-gray-400 text-xs font-bold uppercase mb-1">Total Horas</p>
                <p className="text-2xl font-bold text-white">48h</p>
            </div>
        </div>
    </div>
  );
};

