                        >
                            {locations.map(loc => (
                                <option key={loc.id} value={loc.id}>{loc.name} ({loc.type})</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute right-4 top-3.5 pointer-events-none text-gray-400">expand_more</span>
                    </div>
                </div>

                {/* Players Confirmation */}
                <div className="space-y-3">
                    <div className="flex justify-between items-end">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Confirmar Jogadores</label>
                        <span className={`text-xs font-bold px-2 py-0.5 rounded-md ${selectedPlayers.length === 8 ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
                            {selectedPlayers.length} Selecionados
                        </span>
                    </div>

                    <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto pr-1">
                        {renderAddPlayerButton()}
                        {[...players].sort((a,b) => a.name.localeCompare(b.name)).map(p => {
                            const isSelected = selectedPlayers.includes(p.id);
                            return (
                                <button 
                                    key={p.id}
                                    onClick={() => togglePlayer(p.id)}
                                    className={`flex flex-col items-center gap-1 p-2 rounded-xl border transition-all ${isSelected ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}
                                >
                                    <img src={p.image} className="size-8 rounded-full object-cover" />
                                    <span className="text-[9px] font-bold truncate w-full text-center">{p.name.split(' ')[0]}</span>
                                    <div className={`size-3 rounded-full flex items-center justify-center ${isSelected ? 'bg-primary text-black' : 'bg-white/10'}`}>
                                        {isSelected && <span className="material-symbols-outlined text-[10px]">check</span>}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            <div className="mt-auto">
                <button 
                    onClick={handleSubmit}
                    className="w-full bg-primary hover:bg-primary/90 text-background-dark font-bold py-4 rounded-xl shadow-lg shadow-primary/30 flex items-center justify-center gap-2"
                >
                    <span className="material-symbols-outlined">calendar_add_on</span>
                    Agendar Torneio
                </button>
            </div>
        </div>
    );
  }

  // --- VIEW: SCHEDULED TOURNAMENT ---
  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);

    // Get confirmed players object and sort alphabetically
    const confirmedPlayers = activeTournament.confirmedPlayerIds
        .map(id => players.find(p => p.id === id))
        .filter((p): p is Player => p !== undefined)
        .sort((a, b) => a.name.localeCompare(b.name));

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <div>
            <h1 className="text-3xl font-bold tracking-tight mb-1">Painel Principal</h1>
            <p className="text-slate-400">Próximo evento confirmado.</p>
        </div>

        <section>
            <div className="relative overflow-hidden rounded-2xl bg-card-dark shadow-lg ring-1 ring-white/10 group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/20 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
            <div className="p-5 relative z-10">
                <div className="flex items-start justify-between mb-4">
                <div>
                    <span className="inline-flex items-center rounded-full bg-primary/20 px-2.5 py-0.5 text-xs font-semibold text-primary mb-2">
                    AGENDADO
                    </span>
                    <h3 className="text-xl font-bold text-white mb-1">Próximo Torneio</h3>
                    <p className="text-slate-400 text-sm flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">calendar_today</span>
                    {new Date(activeTournament.date).toLocaleDateString('pt-PT', { weekday: 'long', day: 'numeric', month: 'long' })}
                    </p>
                </div>
                <div className="bg-white/5 p-2 rounded-lg">
                    <span className="material-symbols-outlined text-primary">sports_tennis</span>
                </div>
                </div>

                <div className="grid grid-cols-2 gap-3 mb-5">
                <div className="bg-black/20 rounded-lg p-3">
                    <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">Hora</p>
                    <p className="text-white font-semibold">{activeTournament.time}</p>
                    <p className="text-xs text-primary mt-1">Duração {activeTournament.duration}h</p>
                </div>
                <div className="bg-black/20 rounded-lg p-3">
                    <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">Localização</p>
                    <p className="text-white font-semibold truncate">{locName}</p>
                    <p className="text-xs text-slate-400 mt-1 truncate">Campo Reservado</p>
                </div>
                </div>

                <div className="relative h-32 rounded-lg overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent z-10"></div>
                <div className="absolute bottom-3 left-3 z-20 flex items-center gap-2">
                    <span className="material-symbols-outlined text-white text-lg">location_on</span>
                    <span className="text-white text-sm font-medium">{locName}</span>
                </div>
                <img 
                    alt="Padel Court" 
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" 
                    src="https://lh3.googleusercontent.com/aida-public/AB6AXuAQ3WLPB3bP7mHLApKN3bXHorTuQW8ZR3-3oFyzYVi3I4RIuR3eM6Kvj8Om5GCcSi0Z4ns3B-KN1hnORdzN1ppulo63zhVq1FTNZBmEmN4J4vhFyUs7P0Pi8osXw1BDLRDQulfXXxXimZ06horwk35ct2H_PAeBzQrdi8exswQYm15wsYkbAsKROL4MT_GyvuafLJ-F7xHNtH3yFLEW0i4u49xTzLqNT_YJSoZJdP4hHJuhvADuM9XOKYNl1J_faNOMXVDbJ_etLf0" 
                />
                </div>
            </div>
            </div>
        </section>

        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1">
            <h3 className="text-lg font-bold flex items-center gap-2">
                Confirmados
                <span className="text-sm font-normal text-slate-500 bg-white/5 px-2 py-0.5 rounded-md">{confirmedPlayers.length} Jogadores</span>
