const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);

  // New States
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);

  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    // When tournament is created, we go back to Home (Scheduled View)
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  // Filter players for the Team Setup screen based on tournament confirmation
  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
          />
        );
      case Screen.PROFILE:
        return <ProfileScreen />;
      case Screen.LIVE_GAME:
        return <LiveGameScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} />;
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} />;
      case Screen.GLOBAL_STATS:
        return <GlobalStatsScreen />;
      case Screen.TEAM_SETUP:
        return (
            <TeamSetupScreen 
                setScreen={setScreen} 
                players={getConfirmedPlayers()} 
                onStartTournament={handleStartTournament} 
            />
        );
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} />;
      default:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
          />
        );
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {/* Header - Simple generic header for sub-screens that don't have their own */}
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? 'Resultados Ronda 1' : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {/* Special Header for Team Setup to allow going back */}
        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               Definir Equipas
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}

        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament
}) => {
  const [isCreating, setIsCreating] = useState(false);

  // Form State
  const [date, setDate] = useState('');
  const [time, setTime] = useState('19:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  // Quick Add Player State
  const [isAddingPlayer, setIsAddingPlayer] = useState(false);
  const [newPlayerName, setNewPlayerName] = useState('');

  // Initialize selected players with first 8 when opening form
  const initCreation = () => {
    // Default to today
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    // Pre-select first 8 players
    setSelectedPlayers(players.slice(0, 8).map(p => p.id));
    // Pre-select first location
    if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
  };

  const togglePlayer = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  // Helper to create and add a new player
  const saveNewPlayer = () => {
    if (!newPlayerName.trim()) {
        setIsAddingPlayer(false);
        return;
    }

    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: newPlayerName,
        level: 'N/A',
        image: `https://ui-avatars.com/api/?name=${encodeURIComponent(newPlayerName)}&background=random&color=fff&bold=true`
    };

    onAddPlayer(newPlayer);

    // Automatically select the new player in the form
    if (isCreating) {
        setSelectedPlayers(prev => [...prev, newId]);
    } 
    // If in Dashboard view, update the active tournament immediately
    else if (activeTournament) {
         onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }

    setNewPlayerName('');
    setIsAddingPlayer(false);
  };

  const handleSubmit = () => {
    if (!date || !time || !locationId) return;

    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled'
    };

    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  // Helper to get location name
  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  // --- Render Add Player Button/Input ---
  const renderAddPlayerButton = (isInDashboard = false) => {
    if (isAddingPlayer) {
        return (
            <div className={`flex flex-col items-center gap-1 p-2 rounded-xl border border-primary bg-primary/10 animate-fade-in ${isInDashboard ? 'justify-center h-full min-h-[80px]' : ''}`}>
                <div className="size-6 rounded-full bg-primary flex items-center justify-center mb-0.5">
                     <span className="material-symbols-outlined text-black text-[16px]">person_add</span>
                </div>
                 <input 
                    autoFocus
                    value={newPlayerName}
                    onChange={(e) => setNewPlayerName(e.target.value)}
                    onBlur={saveNewPlayer}
                    onKeyDown={(e) => e.key === 'Enter' && saveNewPlayer()}
                    className="w-full bg-transparent text-center text-[10px] text-white border-b border-white/20 focus:border-primary outline-none p-0"
                    placeholder="Nome..."
                />
            </div>
        );
    }

    if (isInDashboard) {
        return (
            <button 
                onClick={() => setIsAddingPlayer(true)}
                className="flex flex-col items-center justify-center gap-1 h-full min-h-[80px] rounded-full border border-dashed border-white/10 bg-white/5 hover:bg-white/10 hover:border-white/30 transition-all group"
            >
                <span className="material-symbols-outlined text-gray-500 group-hover:text-primary text-[24px]">add</span>
                <span className="text-[9px] font-bold text-gray-500 group-hover:text-gray-300">Novo</span>
            </button>
        );
    }

    return (
        <button 
            onClick={() => setIsAddingPlayer(true)}
            className="flex flex-col items-center gap-1 p-2 rounded-xl border border-dashed border-white/20 bg-white/5 hover:bg-white/10 hover:border-white/40 transition-all group justify-center"
        >
             <div className="size-8 rounded-full bg-white/5 group-hover:bg-white/10 flex items-center justify-center transition-colors">
                <span className="material-symbols-outlined text-gray-400 group-hover:text-white text-[20px]">add</span>
            </div>
            <span className="text-[9px] font-bold text-gray-500 group-hover:text-gray-300 truncate w-full text-center">Novo</span>
        </button>
    );
  };

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>

            <div className="space-y-5">
                {/* Date & Time */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Data</label>
                        <input 
                            type="date" 
                            value={date}
                            onChange={(e) => setDate(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Hora</label>
                        <input 
                            type="time" 
                            value={time}
                            onChange={(e) => setTime(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans"
                        />
                    </div>
                </div>

                {/* Duration */}
                <div className="space-y-2">
                    <div className="flex justify-between">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Duração</label>
                        <span className="text-xs font-bold text-primary">{duration}h</span>
                    </div>
                    <input 
                        type="range" 
                        min="1" 
                        max="4" 
                        step="0.5" 
                        value={duration}
                        onChange={(e) => setDuration(parseFloat(e.target.value))}
                        className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer"
                    />
                    <div className="flex justify-between text-[10px] text-gray-500 font-mono">
                        <span>1h</span>
                        <span>4h</span>
                    </div>
                </div>

                {/* Location */}
                <div className="space-y-2">
                     <div className="flex justify-between items-center">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Local</label>
                        <button onClick={() => setScreen(Screen.LOCATIONS)} className="text-[10px] font-bold text-primary hover:underline flex items-center gap-1">
                            <span className="material-symbols-outlined text-[14px]">settings</span>
                            Gerir
                        </button>
                    </div>
                    <div className="relative">
                        <select 
                            value={locationId}
                            onChange={(e) => setLocationId(e.target.value)}
                            className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 font-sans appearance-none"
                        >
                            {locations.map(loc => (
                                <option key={loc.id} value={loc.id}>{loc.name} ({loc.type})</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute right-4 top-3.5 pointer-events-none text-gray-400">expand_more</span>
                    </div>
                </div>

                {/* Players Confirmation */}
                <div className="space-y-3">
                    <div className="flex justify-between items-end">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider">Confirmar Jogadores</label>
                        <span className={`text-xs font-bold px-2 py-0.5 rounded-md ${selectedPlayers.length === 8 ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
                            {selectedPlayers.length} Selecionados
                        </span>
                    </div>

                    <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto pr-1">
                        {[...players].sort((a,b) => a.name.localeCompare(b.name)).map(p => {
                            const isSelected = selectedPlayers.includes(p.id);
                            return (
                                <button 
                                    key={p.id}
                                    onClick={() => togglePlayer(p.id)}
                                    className={`flex flex-col items-center gap-1 p-2 rounded-xl border transition-all ${isSelected ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}
                                >
                                    <img src={p.image} className="size-8 rounded-full object-cover" />
                                    <span className="text-[9px] font-bold truncate w-full text-center">{p.name.split(' ')[0]}</span>
                                    <div className={`size-3 rounded-full flex items-center justify-center ${isSelected ? 'bg-primary text-black' : 'bg-white/10'}`}>
                                        {isSelected && <span className="material-symbols-outlined text-[10px]">check</span>}
                                    </div>
                                </button>
                            );
                        })}
                        {renderAddPlayerButton(false)}
                    </div>
                </div>
            </div>

            <div className="mt-auto">
                <button 
                    onClick={handleSubmit}
                    className="w-full bg-primary hover:bg-primary/90 text-background-dark font-bold py-4 rounded-xl shadow-lg shadow-primary/30 flex items-center justify-center gap-2"
                >
                    <span className="material-symbols-outlined">calendar_add_on</span>
                    Agendar Torneio
                </button>
            </div>
        </div>
    );
  }

  // --- VIEW: SCHEDULED TOURNAMENT ---
  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);

    // Get confirmed players object and sort alphabetically
    const confirmedPlayers = activeTournament.confirmedPlayerIds
        .map(id => players.find(p => p.id === id))
        .filter((p): p is Player => p !== undefined)
        .sort((a, b) => a.name.localeCompare(b.name));

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <div>
            <h1 className="text-3xl font-bold tracking-tight mb-1">Painel Principal</h1>
            <p className="text-slate-400">Próximo evento confirmado.</p>
        </div>

        <section>
            <div className="relative overflow-hidden rounded-2xl bg-card-dark shadow-lg ring-1 ring-white/10 group">
