import React from 'react';
import { Screen, Match, Player } from '../types';

interface ResultsProps {
  setScreen: (screen: Screen) => void;
  matches?: Match[];
}

export const TournamentResultsScreen: React.FC<ResultsProps> = ({ setScreen, matches = [] }) => {

  // Calculate Standings
  const calculateStandings = () => {
    const stats = new Map<string, { 
        id: string,
        name: string,
        teamName: string, 
        wins: number, 
        pointsDiff: number 
    }>();

    // Helper to get or create stats for a team (using team ID pair as key)
    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) {
            stats.set(key, {
                id: key,
                name: team.map(p => p.name.split(' ')[0]).join(' & '),
                teamName: team.map(p => p.name.split(' ')[0]).join(' & '),
                wins: 0,
                pointsDiff: 0
            });
        }
        return stats.get(key)!;
    };

    matches.forEach(m => {
        const stats1 = getStats(m.team1);
        const stats2 = getStats(m.team2);

        // Update Points Difference
        stats1.pointsDiff += (m.score1 - m.score2);
        stats2.pointsDiff += (m.score2 - m.score1);

        // Update Wins
        if (m.score1 > m.score2) {
            stats1.wins += 1;
        } else if (m.score2 > m.score1) {
            stats2.wins += 1;
        }
        // Tie? Usually not in padel but if so, 0 wins added
    });

    return Array.from(stats.values()).sort((a, b) => {
        if (b.wins !== a.wins) return b.wins - a.wins; // Sort by Wins
        return b.pointsDiff - a.pointsDiff; // Tie-breaker: Points Diff
    });
  };

  const standings = calculateStandings();
  const winner = standings[0];

  return (
    <div className="flex-1 flex flex-col w-full max-w-md mx-auto px-4 pb-32 animate-fade-in">
        <h1 className="text-lg font-bold leading-tight tracking-tight text-center my-6">Resultados Finais</h1>

        {/* Winner Spotlight Section */}
        {winner && (
            <div className="flex flex-col items-center mt-2 mb-8 animate-fade-in-up">
                <div className="relative mb-6">
                    {/* Glow effect */}
                    <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-150"></div>
                    <div className="relative bg-gradient-to-br from-surface-dark to-background-dark border border-primary/30 p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center aspect-square size-48">
                        <span className="material-symbols-outlined text-primary text-[80px] drop-shadow-[0_0_15px_rgba(96,122,251,0.5)]">emoji_events</span>
                    </div>
                    {/* Winner Badge */}
                    <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 bg-primary text-background-dark font-bold px-4 py-1.5 rounded-full shadow-lg whitespace-nowrap text-sm tracking-wide">
                        Equipa Vencedora
                    </div>
                </div>
                <div className="flex flex-col items-center text-center mt-4 space-y-2">
                    <h2 className="text-white text-2xl font-bold leading-tight">
                        {winner.teamName}
                    </h2>
                    <div className="flex items-center gap-2 px-4 py-2 bg-surface-dark/50 rounded-full border border-white/5">
                        <span className="text-gray-400 text-sm font-medium">{winner.wins} Vitórias</span>
                        <span className="w-1 h-1 rounded-full bg-gray-500"></span>
                        <span className="text-primary text-sm font-bold">{winner.pointsDiff > 0 ? '+' : ''}{winner.pointsDiff} DP</span>
                    </div>
                </div>
            </div>
        )}

        {/* Standings Table */}
        <div className="w-full bg-surface-dark rounded-3xl p-5 shadow-sm border border-white/5">
            {/* Table Header */}
            <div className="grid grid-cols-[3rem_1fr_3rem_3rem] gap-2 pb-4 border-b border-white/10 mb-2">
                <div className="text-center text-[#9db9a8] text-xs font-medium uppercase tracking-wider">Pos</div>
                <div className="text-left pl-2 text-[#9db9a8] text-xs font-medium uppercase tracking-wider">Equipa</div>
                <div className="text-center text-[#9db9a8] text-xs font-medium uppercase tracking-wider" title="Vitórias">V</div>
                <div className="text-right text-[#9db9a8] text-xs font-medium uppercase tracking-wider" title="Diferença de Pontos">DP</div>
            </div>

            <div className="flex flex-col gap-1">
                {standings.map((team, idx) => {
                    const isTop = idx === 0;
                    return (
                        <div key={idx} className="grid grid-cols-[3rem_1fr_3rem_3rem] gap-2 items-center py-3 border-b border-white/5 last:border-0">
                            <div className="flex justify-center">
                                <div className={`flex items-center justify-center size-8 rounded-full font-bold text-sm shadow-md ${isTop ? 'bg-primary text-background-dark' : 'bg-white/10 text-white'}`}>
                                    {idx + 1}
                                </div>
                            </div>
                            <div className="pl-2 truncate font-bold text-white">
                                {team.teamName}
                            </div>
                            <div className="text-center font-medium text-white">{team.wins}</div>
                            <div className={`text-right font-medium ${team.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}`}>
                                {team.pointsDiff > 0 ? '+' : ''}{team.pointsDiff}
                            </div>
                        </div>
                    );
                })}
                {standings.length === 0 && <p className="text-center text-gray-500 py-4">Sem dados de jogos.</p>}
            </div>
        </div>

        <button 
            onClick={() => setScreen(Screen.GLOBAL_STATS)}
            className="mt-6 w-full bg-surface-dark hover:bg-surface-dark/80 text-white border border-white/10 font-bold text-base h-14 rounded-full flex items-center justify-center gap-2"
        >
            <span className="material-symbols-outlined">bar_chart</span>
            <span>Ver Estatísticas Globais</span>
        </button>

         <button 
            onClick={() => setScreen(Screen.HOME)}
            className="mt-2 w-full text-gray-400 hover:text-white font-medium text-sm py-2"
        >
            Voltar ao Início
        </button>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS'
}

export interface Player {
  id: string;
  name: string;
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
}

export interface Tournament {
  id: string;
  date: string; // ISO String or YYYY-MM-DD
  time: string;
  duration: number; // in hours
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[]; // Optional to store history results
}

