        </section>

        {/* Quick Stats Teaser - DYNAMIC */}
        <div className="grid grid-cols-2 gap-3">
            <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <p className="text-gray-400 text-xs font-bold uppercase mb-1">Jogos Realizados</p>
                <p className="text-2xl font-bold text-white">{totalGames}</p>
            </div>
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <p className="text-gray-400 text-xs font-bold uppercase mb-1">Total Horas</p>
                <p className="text-2xl font-bold text-white">{totalHours}h</p>
            </div>
        </div>
    </div>
  );
};

