                    );
                })
            )}
        </section>

        {/* Curiosities & History Summary */}
        <section className="grid grid-cols-2 gap-3">
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-2">
