const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);

  // New States
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);

  // History State
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([
      { id: 'old-1', date: '2023-10-15', time: '19:00', duration: 2, locationId: '1', confirmedPlayerIds: [], status: 'finished', matches: [] },
      { id: 'old-2', date: '2023-10-08', time: '20:00', duration: 1.5, locationId: '3', confirmedPlayerIds: [], status: 'finished', matches: [] }
  ]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches);
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleNextRound = () => {
    if (currentRound === 1) {
        // Logic: Winners stay on court, Losers swap courts
        const r1Matches = matches.filter(m => m.round === 1);
        const matchC1 = r1Matches.find(m => m.court === 1)!;
        const matchC2 = r1Matches.find(m => m.court === 2)!;

        // Determine winners and losers
        const winnerC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const loserC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winnerC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const loserC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        // Generate Round 2 Matches
        const round2Matches: Match[] = [
            {
                id: `match-r2-1-${Date.now()}`,
                team1: winnerC1,
                team2: loserC2,
                score1: 0,
                score2: 0,
                court: 1,
                status: 'live',
                round: 2
            },
            {
                id: `match-r2-2-${Date.now()}`,
                team1: winnerC2,
                team2: loserC1,
                score1: 0,
                score2: 0,
                court: 2,
                status: 'live',
                round: 2
            }
        ];

        setMatches([...matches, ...round2Matches]);
        setCurrentRound(2);
    } 
    else if (currentRound === 2) {
        // Round 3 logic
        const r1Matches = matches.filter(m => m.round === 1);
        const teams = [
            r1Matches[0].team1,
            r1Matches[0].team2,
            r1Matches[1].team1,
            r1Matches[1].team2,
        ];

        const played = new Set<string>();
        matches.forEach(m => {
             const t1Id = m.team1[0].id; 
             const t2Id = m.team2[0].id;
             const key = [t1Id, t2Id].sort().join('-');
             played.add(key);
        });

        const newMatches: Match[] = [];
        const usedTeams = new Set<string>();

        for (let i = 0; i < teams.length; i++) {
             const t1 = teams[i];
             const t1Key = t1[0].id;
             if (usedTeams.has(t1Key)) continue;

             for (let j = i + 1; j < teams.length; j++) {
                 const t2 = teams[j];
                 const t2Key = t2[0].id;
                 if (usedTeams.has(t2Key)) continue;

                 const pairKey = [t1Key, t2Key].sort().join('-');

                 if (!played.has(pairKey)) {
                     newMatches.push({
                         id: `match-r3-${newMatches.length + 1}-${Date.now()}`,
                         team1: t1,
                         team2: t2,
                         score1: 0,
                         score2: 0,
                         court: newMatches.length + 1,
                         status: 'live',
                         round: 3
                     });
                     usedTeams.add(t1Key);
                     usedTeams.add(t2Key);
                     break; 
                 }
             }
        }

        setMatches([...matches, ...newMatches]);
        setCurrentRound(3);
    }
    else {
        // After Round 3, go to Summary
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finishedTournament: Tournament = {
            ...activeTournament,
            status: 'finished',
            matches: matches 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  const handleViewHistory = (tournament: Tournament) => {
    setSelectedHistoryTournament(tournament);
    setScreen(Screen.HISTORY_DETAIL);
  };

  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
      case Screen.PROFILE:
        return <ProfileScreen />;
      case Screen.LIVE_GAME:
        return (
            <LiveGameScreen 
                setScreen={setScreen} 
                matches={matches.filter(m => m.round === currentRound)} 
                updateMatchScore={updateMatchScore}
                onNextRound={handleNextRound}
                currentRound={currentRound}
            />
        );
      case Screen.TOURNAMENT_SUMMARY:
          return (
              <TournamentSummaryScreen 
                  setScreen={setScreen}
                  matches={matches}
                  updateMatchScore={updateMatchScore}
                  onFinish={handleFinishTournament}
              />
          );
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return (
            <GlobalStatsScreen 
                history={tournamentHistory} 
                players={players} 
                onViewTournament={handleViewHistory} 
            />
        );
      case Screen.HISTORY_DETAIL:
        if (!selectedHistoryTournament) return <GlobalStatsScreen history={tournamentHistory} players={players} />;
        return <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} />;
      case Screen.TEAM_SETUP:
        return (
            <TeamSetupScreen 
                setScreen={setScreen} 
                players={getConfirmedPlayers()} 
                onStartTournament={handleStartTournament} 
            />
        );
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} />;
      default:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {/* Header - Simple generic header for sub-screens that don't have their own */}
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP && currentScreen !== Screen.TOURNAMENT_SUMMARY && currentScreen !== Screen.HISTORY_DETAIL) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? `Ronda ${currentRound}` : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados Finais' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {/* Special Header for Team Setup */}
        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               Definir Equipas
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}

        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match } from '../types';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  onViewTournament?: (tournament: Tournament) => void;
}

interface PlayerStats {
  id: string;
  name: string;
  image: string;
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  pointsDiff: number;
  tournamentsPlayed: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], onViewTournament }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');

  // --- Filtering Logic ---
  const filteredHistory = useMemo(() => {
    if (timeRange === 'all') return history;

    const now = new Date();
    return history.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') {
        return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      }
      if (timeRange === 'year') {
        return tDate.getFullYear() === now.getFullYear();
      }
      return true;
    });
  }, [history, timeRange]);

  // --- Stats Calculation Engine ---
  const { playerStats, totalGames, totalPoints, activePlayersCount, bestDuo, curiosities } = useMemo(() => {
    const stats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, names: string[] }>();
    let tGames = 0;
    let tPoints = 0;

    // Curiosities trackers
    let maxDiff = { diff: -1, winner: '', loser: '' };

    // Initialize stats for all known players
    players.forEach(p => {
        stats.set(p.id, {
            id: p.id,
            name: p.name,
            image: p.image,
            gamesPlayed: 0,
            wins: 0,
            losses: 0,
            pointsScored: 0,
            pointsConceded: 0,
            pointsDiff: 0,
            tournamentsPlayed: 0
        });
    });

    filteredHistory.forEach(t => {
       const tournamentPlayers = new Set<string>();

       if (t.matches) {
           tGames += t.matches.length;

           t.matches.forEach(m => {
               if (m.status !== 'finished' && m.status !== 'live') return; // Only count played games

               tPoints += (m.score1 + m.score2);

               // Track Curiosities: Biggest Win
               const diff = Math.abs(m.score1 - m.score2);
               if (diff > maxDiff.diff) {
                   maxDiff = {
                       diff: diff,
                       winner: m.score1 > m.score2 ? m.team1.map(p=>p.name.split(' ')[0]).join('&') : m.team2.map(p=>p.name.split(' ')[0]).join('&'),
                       loser: m.score1 > m.score2 ? m.team2.map(p=>p.name.split(' ')[0]).join('&') : m.team1.map(p=>p.name.split(' ')[0]).join('&'),
                   };
               }

               // Process Team 1
               const t1Id = m.team1.map(p => p.id).sort().join('-');
               if (!duoStats.has(t1Id)) duoStats.set(t1Id, { wins: 0, games: 0, names: m.team1.map(p => p.name.split(' ')[0]) });
               const d1 = duoStats.get(t1Id)!;
               d1.games += 1;
               if (m.score1 > m.score2) d1.wins += 1;

               m.team1.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score1;
                       ps.pointsConceded += m.score2;
                       ps.pointsDiff += (m.score1 - m.score2);
                       if (m.score1 > m.score2) ps.wins++;
                       else ps.losses++;
                   }
               });

               // Process Team 2
               const t2Id = m.team2.map(p => p.id).sort().join('-');
               if (!duoStats.has(t2Id)) duoStats.set(t2Id, { wins: 0, games: 0, names: m.team2.map(p => p.name.split(' ')[0]) });
               const d2 = duoStats.get(t2Id)!;
               d2.games += 1;
               if (m.score2 > m.score1) d2.wins += 1;

               m.team2.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score2;
                       ps.pointsConceded += m.score1;
                       ps.pointsDiff += (m.score2 - m.score1);
                       if (m.score2 > m.score1) ps.wins++;
                       else ps.losses++;
                   }
               });
           });
       }

       // Increment tournament count for players involved
       tournamentPlayers.forEach(pid => {
           const ps = stats.get(pid);
           if (ps) ps.tournamentsPlayed++;
       });
    });

    // Find Best Duo (Min 2 games to qualify)
    let bestDuoData = { names: ['-', '-'], winRate: 0, wins: 0, games: 0 };
    duoStats.forEach((val) => {
        if (val.games >= 2) {
            const rate = (val.wins / val.games) * 100;
            if (rate > bestDuoData.winRate || (rate === bestDuoData.winRate && val.wins > bestDuoData.wins)) {
                bestDuoData = { names: val.names, winRate: Math.round(rate), wins: val.wins, games: val.games };
            }
        }
    });

    // Determine "Muralha" (Least points conceded per game, min 3 games)
    let muralha = { name: '-', avg: 999 };
    stats.forEach(p => {
        if (p.gamesPlayed >= 3) {
            const avg = p.pointsConceded / p.gamesPlayed;
            if (avg < muralha.avg) muralha = { name: p.name.split(' ')[0], avg: parseFloat(avg.toFixed(1)) };
        }
    });

    const activePlayers = Array.from(stats.values()).filter(p => p.gamesPlayed > 0);

    return {
        playerStats: activePlayers.sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff),
        totalGames: tGames,
        totalPoints: tPoints,
        activePlayersCount: activePlayers.length,
        bestDuo: bestDuoData,
        curiosities: {
            biggestWin: maxDiff,
            muralha: muralha
        }
    };
  }, [filteredHistory, players]);

  // --- Export Function ---
  const handleExport = () => {
    let text = `🎾 *Estatísticas Padel Pro Manager*\n📅 Período: ${timeRange === 'all' ? 'Tudo' : timeRange}\n\n`;
    text += `🏆 *Resumo*\n- Jogos: ${totalGames}\n- Pontos: ${totalPoints}\n- Jogadores: ${activePlayersCount}\n\n`;
    text += `🥇 *Top 3 Jogadores*\n`;
    playerStats.slice(0, 3).forEach((p, i) => {
        text += `${i+1}. ${p.name} (${p.wins}V / ${p.pointsDiff > 0 ? '+' : ''}${p.pointsDiff})\n`;
    });
    text += `\n🔥 *Dupla Forte:* ${bestDuo.names.join(' & ')} (${bestDuo.winRate}%)\n`;

    navigator.clipboard.writeText(text).then(() => {
        alert("Resumo copiado para a área de transferência!");
    });
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-4 pb-24 animate-fade-in">
