                <button onClick={() => setTimeRange('month')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'month' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Mês</button>
                <button onClick={() => setTimeRange('year')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'year' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Ano</button>
             </div>
