const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);

  // New States
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);

  // History State
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([
      { id: 'old-1', date: '2023-10-15', time: '19:00', duration: 2, locationId: '1', confirmedPlayerIds: [], status: 'finished', matches: [] },
      { id: 'old-2', date: '2023-10-08', time: '20:00', duration: 1.5, locationId: '3', confirmedPlayerIds: [], status: 'finished', matches: [] }
  ]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches);
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleNextRound = () => {
    if (currentRound === 1) {
        // Logic: Winners stay on court, Losers swap courts
        const r1Matches = matches.filter(m => m.round === 1);
        const matchC1 = r1Matches.find(m => m.court === 1)!;
        const matchC2 = r1Matches.find(m => m.court === 2)!;

        // Determine winners and losers
        const winnerC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const loserC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winnerC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const loserC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        // Generate Round 2 Matches
        const round2Matches: Match[] = [
            {
                id: `match-r2-1-${Date.now()}`,
                team1: winnerC1,
                team2: loserC2,
                score1: 0,
                score2: 0,
                court: 1,
                status: 'live',
                round: 2
            },
            {
                id: `match-r2-2-${Date.now()}`,
                team1: winnerC2,
                team2: loserC1,
                score1: 0,
                score2: 0,
                court: 2,
                status: 'live',
                round: 2
            }
        ];

        setMatches([...matches, ...round2Matches]);
        setCurrentRound(2);
    } 
    else if (currentRound === 2) {
        // Round 3 logic
        const r1Matches = matches.filter(m => m.round === 1);
        const teams = [
            r1Matches[0].team1,
            r1Matches[0].team2,
            r1Matches[1].team1,
            r1Matches[1].team2,
        ];

        const played = new Set<string>();
        matches.forEach(m => {
             const t1Id = m.team1[0].id; 
             const t2Id = m.team2[0].id;
             const key = [t1Id, t2Id].sort().join('-');
             played.add(key);
        });

        const newMatches: Match[] = [];
        const usedTeams = new Set<string>();

        for (let i = 0; i < teams.length; i++) {
             const t1 = teams[i];
             const t1Key = t1[0].id;
             if (usedTeams.has(t1Key)) continue;

             for (let j = i + 1; j < teams.length; j++) {
                 const t2 = teams[j];
                 const t2Key = t2[0].id;
                 if (usedTeams.has(t2Key)) continue;

                 const pairKey = [t1Key, t2Key].sort().join('-');

                 if (!played.has(pairKey)) {
                     newMatches.push({
                         id: `match-r3-${newMatches.length + 1}-${Date.now()}`,
                         team1: t1,
                         team2: t2,
                         score1: 0,
                         score2: 0,
                         court: newMatches.length + 1,
                         status: 'live',
                         round: 3
                     });
                     usedTeams.add(t1Key);
                     usedTeams.add(t2Key);
                     break; 
                 }
             }
        }

        setMatches([...matches, ...newMatches]);
        setCurrentRound(3);
    }
    else {
        // After Round 3, go to Summary
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finishedTournament: Tournament = {
            ...activeTournament,
            status: 'finished',
            matches: matches 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  const handleViewHistory = (tournament: Tournament) => {
    setSelectedHistoryTournament(tournament);
    setScreen(Screen.HISTORY_DETAIL);
  };

  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
      case Screen.PROFILE:
        return <ProfileScreen />;
      case Screen.LIVE_GAME:
        return (
            <LiveGameScreen 
                setScreen={setScreen} 
                matches={matches.filter(m => m.round === currentRound)} 
                updateMatchScore={updateMatchScore}
                onNextRound={handleNextRound}
                currentRound={currentRound}
            />
        );
      case Screen.TOURNAMENT_SUMMARY:
          return (
              <TournamentSummaryScreen 
                  setScreen={setScreen}
                  matches={matches}
                  updateMatchScore={updateMatchScore}
                  onFinish={handleFinishTournament}
              />
          );
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return (
            <GlobalStatsScreen 
                history={tournamentHistory} 
                players={players} 
                onViewTournament={handleViewHistory} 
            />
        );
      case Screen.HISTORY_DETAIL:
        if (!selectedHistoryTournament) return <GlobalStatsScreen history={tournamentHistory} players={players} />;
        return <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} />;
      case Screen.TEAM_SETUP:
        return (
            <TeamSetupScreen 
                setScreen={setScreen} 
                players={getConfirmedPlayers()} 
                onStartTournament={handleStartTournament} 
            />
        );
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} />;
      default:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {/* Header - Simple generic header for sub-screens that don't have their own */}
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP && currentScreen !== Screen.TOURNAMENT_SUMMARY && currentScreen !== Screen.HISTORY_DETAIL) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? `Ronda ${currentRound}` : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados Finais' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {/* Special Header for Team Setup */}
        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               Definir Equipas
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}

        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Screen, Location } from '../types';

interface LocationManagerProps {
  setScreen: (screen: Screen) => void;
  locations: Location[];
  setLocations: React.Dispatch<React.SetStateAction<Location[]>>;
}

export const LocationManagerScreen: React.FC<LocationManagerProps> = ({ setScreen, locations, setLocations }) => {
  const [newLocName, setNewLocName] = useState('');
  const [newLocType, setNewLocType] = useState<'Indoor' | 'Outdoor'>('Indoor');
  const [newAddress, setNewAddress] = useState('');
  const [newMapsUrl, setNewMapsUrl] = useState('');
  const [newImageUrl, setNewImageUrl] = useState('');

  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSave = () => {
    if (!newLocName.trim()) return;

    if (editingId) {
        // UPDATE MODE
        setLocations(prev => prev.map(loc => {
            if (loc.id === editingId) {
                return {
                    ...loc,
                    name: newLocName,
                    type: newLocType,
                    address: newAddress,
                    imageUrl: newImageUrl,
                    googleMapsUrl: newMapsUrl
                };
            }
            return loc;
        }));
    } else {
        // CREATE MODE
        const newLocation: Location = {
            id: `loc-${Date.now()}`,
            name: newLocName,
            type: newLocType,
            address: newAddress,
            imageUrl: newImageUrl,
            googleMapsUrl: newMapsUrl
        };
        setLocations([...locations, newLocation]);
    }

    resetForm();
  };

  const handleEdit = (loc: Location) => {
    setEditingId(loc.id);
    setNewLocName(loc.name);
    setNewLocType(loc.type);
    setNewAddress(loc.address || '');
    setNewMapsUrl(loc.googleMapsUrl || '');
    setNewImageUrl(loc.imageUrl || '');
    setIsAdding(true);
    // Scroll to top to see form
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (id: string) => {
    if (confirm('Tem a certeza que deseja remover este local?')) {
        setLocations(locations.filter(l => l.id !== id));
    }
  };

  const resetForm = () => {
    setNewLocName('');
    setNewAddress('');
    setNewMapsUrl('');
    setNewImageUrl('');
    setNewLocType('Indoor');
    setEditingId(null);
    setIsAdding(false);
  };

  const openMaps = (url?: string) => {
      if(url) window.open(url, '_blank');
      else alert("Link do Google Maps não configurado.");
  };

  return (
    <div className="flex flex-col h-full px-4 pb-24 animate-fade-in">
        <div className="py-4">
             <h2 className="text-3xl font-bold leading-tight tracking-tight">Gerir <br/> <span className="text-primary">Locais</span></h2>
        </div>

        {/* Form Section (Add/Edit) */}
        {isAdding ? (
            <div className="bg-card-dark p-4 rounded-2xl border border-primary/30 shadow-lg mb-6 animate-fade-in-up">
                <h3 className="font-bold text-white mb-3">{editingId ? 'Editar Local' : 'Adicionar Local'}</h3>

                <div className="space-y-3">
                    <input 
                        type="text" 
                        placeholder="Nome do Clube / Campo" 
                        value={newLocName}
                        onChange={(e) => setNewLocName(e.target.value)}
                        className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50"
                        autoFocus
                    />

                    <div className="flex gap-2">
                        <button 
                            onClick={() => setNewLocType('Indoor')}
                            className={`flex-1 py-2 rounded-lg text-sm font-bold border transition-colors ${newLocType === 'Indoor' ? 'bg-primary text-background-dark border-primary' : 'bg-transparent border-white/10 text-gray-400'}`}
                        >
                            Indoor
                        </button>
                        <button 
                             onClick={() => setNewLocType('Outdoor')}
                            className={`flex-1 py-2 rounded-lg text-sm font-bold border transition-colors ${newLocType === 'Outdoor' ? 'bg-blue-500 text-white border-blue-500' : 'bg-transparent border-white/10 text-gray-400'}`}
                        >
                            Outdoor
                        </button>
                    </div>

                    <input 
                        type="text" 
                        placeholder="Morada completa" 
                        value={newAddress}
                        onChange={(e) => setNewAddress(e.target.value)}
                        className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm"
                    />

                    <input 
                        type="text" 
                        placeholder="Link Google Maps (https://maps...)" 
                        value={newMapsUrl}
                        onChange={(e) => setNewMapsUrl(e.target.value)}
                        className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm"
                    />

                    <input 
                        type="text" 
                        placeholder="Link da Foto (URL)" 
                        value={newImageUrl}
                        onChange={(e) => setNewImageUrl(e.target.value)}
                        className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm"
                    />

                    <div className="flex gap-3 pt-2">
                        <button onClick={resetForm} className="flex-1 py-3 text-gray-400 font-bold hover:text-white">Cancelar</button>
                        <button onClick={handleSave} className="flex-1 py-3 bg-white text-background-dark rounded-xl font-bold hover:bg-gray-200">
                            {editingId ? 'Atualizar' : 'Guardar'}
                        </button>
                    </div>
                </div>
            </div>
        ) : (
            <button 
                onClick={() => setIsAdding(true)}
                className="w-full py-4 mb-6 border-2 border-dashed border-white/10 rounded-2xl flex items-center justify-center gap-2 text-gray-400 hover:text-primary hover:border-primary/50 hover:bg-primary/5 transition-all"
            >
                <span className="material-symbols-outlined">add_location</span>
                <span className="font-bold">Adicionar Novo Local</span>
            </button>
        )}

        {/* List */}
        <div className="flex flex-col gap-4">
             <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider px-1">Locais Guardados ({locations.length})</h3>
             {locations.length === 0 && (
                 <div className="text-center py-10 text-gray-600">
                     <p>Nenhum local configurado.</p>
                 </div>
             )}
             {locations.map((loc) => (
                 <div key={loc.id} className="group relative bg-surface-dark rounded-xl overflow-hidden border border-white/5 hover:border-white/20 transition-all">
                     {/* Image Banner */}
                     <div className="h-28 w-full bg-gray-800 relative">
                        {loc.imageUrl ? (
                             <img src={loc.imageUrl} className="w-full h-full object-cover opacity-60 group-hover:opacity-80 transition-opacity" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center opacity-20">
                                <span className="material-symbols-outlined text-4xl">stadium</span>
                            </div>
                        )}
                        <div className="absolute top-2 right-2">
                            <span className={`text-[10px] font-bold px-2 py-1 rounded-md backdrop-blur-md border border-white/10 ${loc.type === 'Indoor' ? 'bg-primary/20 text-white' : 'bg-blue-500/20 text-white'}`}>
                                {loc.type}
                            </span>
                        </div>
                     </div>

                     {/* Content */}
                     <div className="p-4">
                        <div className="flex justify-between items-start mb-2">
                            <h4 className="font-bold text-white text-lg leading-tight flex-1 pr-2">{loc.name}</h4>
                            <div className="flex gap-1">
                                <button 
                                    onClick={() => handleEdit(loc)}
                                    className="size-8 flex items-center justify-center bg-white/5 hover:bg-white/10 text-gray-300 rounded-full transition-colors"
                                >
                                    <span className="material-symbols-outlined text-[18px]">edit</span>
                                </button>
                                <button 
                                    onClick={() => handleDelete(loc.id)}
                                    className="size-8 flex items-center justify-center bg-white/5 hover:bg-red-500/20 text-gray-500 hover:text-red-400 rounded-full transition-colors"
                                >
                                    <span className="material-symbols-outlined text-[18px]">delete</span>
                                </button>
                            </div>
                        </div>

                        {loc.address && (
                            <div className="flex items-start gap-2 text-gray-400 text-xs mb-3">
                                <span className="material-symbols-outlined text-[14px] mt-0.5">location_on</span>
                                <span className="leading-relaxed">{loc.address}</span>
                            </div>
                        )}

                        <button 
                            onClick={() => openMaps(loc.googleMapsUrl)}
                            className="w-full py-2 bg-white/5 hover:bg-white/10 rounded-lg text-primary text-xs font-bold flex items-center justify-center gap-2 transition-colors border border-white/5"
                        >
                            <span className="material-symbols-outlined text-[16px]">map</span>
                            Abrir GPS
                        </button>
                     </div>
                 </div>
             ))}
        </div>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL'
}

export interface Player {
  id: string;
  name: string;
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
}

export interface Tournament {
  id: string;
  date: string; // ISO String or YYYY-MM-DD
  time: string;
  duration: number; // in hours
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[]; // Optional to store history results
}

