             );
            })}
        </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location } from '../types';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
}

interface PlayerStats {
  id: string;
  name: string;
  image: string;
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  pointsDiff: number;
  tournamentsPlayed: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');

  // --- Filtering Logic ---
  const filteredHistory = useMemo(() => {
    if (timeRange === 'all') return history;

    const now = new Date();
    return history.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') {
        return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      }
      if (timeRange === 'year') {
        return tDate.getFullYear() === now.getFullYear();
      }
      return true;
    });
  }, [history, timeRange]);

  // --- Stats Calculation Engine ---
  const { playerStats, totalGames, totalPoints, activePlayersCount, bestDuo, curiosities, topLocations } = useMemo(() => {
    const stats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, names: string[] }>();
    const locationCounts = new Map<string, number>();
    let tGames = 0;
    let tPoints = 0;

    // Curiosities trackers
    let maxDiff = { diff: -1, winner: '', loser: '' };

    // Initialize stats for all known players
    players.forEach(p => {
        stats.set(p.id, {
            id: p.id,
            name: p.name,
            image: p.image,
            gamesPlayed: 0,
            wins: 0,
            losses: 0,
            pointsScored: 0,
            pointsConceded: 0,
            pointsDiff: 0,
            tournamentsPlayed: 0
        });
    });

    filteredHistory.forEach(t => {
       // Location Stats
       const locCount = locationCounts.get(t.locationId) || 0;
       locationCounts.set(t.locationId, locCount + 1);

       const tournamentPlayers = new Set<string>();

       if (t.matches) {
           tGames += t.matches.length;

           t.matches.forEach(m => {
               if (m.status !== 'finished' && m.status !== 'live') return; // Only count played games

               tPoints += (m.score1 + m.score2);

               // Track Curiosities: Biggest Win
               const diff = Math.abs(m.score1 - m.score2);
               if (diff > maxDiff.diff) {
                   maxDiff = {
                       diff: diff,
                       winner: m.score1 > m.score2 ? m.team1.map(p=>p.name.split(' ')[0]).join('&') : m.team2.map(p=>p.name.split(' ')[0]).join('&'),
                       loser: m.score1 > m.score2 ? m.team2.map(p=>p.name.split(' ')[0]).join('&') : m.team1.map(p=>p.name.split(' ')[0]).join('&'),
                   };
               }

               // Process Team 1
               const t1Id = m.team1.map(p => p.id).sort().join('-');
               if (!duoStats.has(t1Id)) duoStats.set(t1Id, { wins: 0, games: 0, names: m.team1.map(p => p.name.split(' ')[0]) });
               const d1 = duoStats.get(t1Id)!;
               d1.games += 1;
               if (m.score1 > m.score2) d1.wins += 1;

               m.team1.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score1;
                       ps.pointsConceded += m.score2;
                       ps.pointsDiff += (m.score1 - m.score2);
                       if (m.score1 > m.score2) ps.wins++;
                       else ps.losses++;
                   }
               });

               // Process Team 2
               const t2Id = m.team2.map(p => p.id).sort().join('-');
               if (!duoStats.has(t2Id)) duoStats.set(t2Id, { wins: 0, games: 0, names: m.team2.map(p => p.name.split(' ')[0]) });
               const d2 = duoStats.get(t2Id)!;
               d2.games += 1;
               if (m.score2 > m.score1) d2.wins += 1;

               m.team2.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score2;
                       ps.pointsConceded += m.score1;
                       ps.pointsDiff += (m.score2 - m.score1);
                       if (m.score2 > m.score1) ps.wins++;
                       else ps.losses++;
                   }
               });
           });
       }

       // Increment tournament count for players involved
       tournamentPlayers.forEach(pid => {
           const ps = stats.get(pid);
           if (ps) ps.tournamentsPlayed++;
       });
    });

    // Find Best Duo (Min 2 games to qualify)
    let bestDuoData = { names: ['-', '-'], winRate: 0, wins: 0, games: 0 };
    duoStats.forEach((val) => {
        if (val.games >= 2) {
            const rate = (val.wins / val.games) * 100;
            if (rate > bestDuoData.winRate || (rate === bestDuoData.winRate && val.wins > bestDuoData.wins)) {
                bestDuoData = { names: val.names, winRate: Math.round(rate), wins: val.wins, games: val.games };
            }
        }
    });

    // Determine "Muralha" (Least points conceded per game, min 3 games)
    let muralha = { name: '-', avg: 999 };
    stats.forEach(p => {
        if (p.gamesPlayed >= 3) {
            const avg = p.pointsConceded / p.gamesPlayed;
            if (avg < muralha.avg) muralha = { name: p.name.split(' ')[0], avg: parseFloat(avg.toFixed(1)) };
        }
    });

    // Calculate Top Locations
    const topLocs = Array.from(locationCounts.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([id, count]) => {
            const loc = locations.find(l => l.id === id);
            return {
                name: loc?.name || 'Local Desconhecido',
                type: loc?.type || 'Indoor',
                count
            };
        });

    const activePlayers = Array.from(stats.values()).filter(p => p.gamesPlayed > 0);

    return {
        playerStats: activePlayers.sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff),
        totalGames: tGames,
        totalPoints: tPoints,
        activePlayersCount: activePlayers.length,
        bestDuo: bestDuoData,
        curiosities: {
            biggestWin: maxDiff,
            muralha: muralha
        },
        topLocations: topLocs
    };
  }, [filteredHistory, players, locations]);

  // --- Export Function ---
  const handleExport = () => {
    let text = `🎾 *Estatísticas Padel Pro Manager*\n📅 Período: ${timeRange === 'all' ? 'Tudo' : timeRange}\n\n`;
    text += `🏆 *Resumo*\n- Jogos: ${totalGames}\n- Pontos: ${totalPoints}\n- Jogadores: ${activePlayersCount}\n\n`;
    text += `🥇 *Top 3 Jogadores*\n`;
    playerStats.slice(0, 3).forEach((p, i) => {
        text += `${i+1}. ${p.name} (${p.wins}V / ${p.pointsDiff > 0 ? '+' : ''}${p.pointsDiff})\n`;
    });
    text += `\n🔥 *Dupla Forte:* ${bestDuo.names.join(' & ')} (${bestDuo.winRate}%)\n`;

    navigator.clipboard.writeText(text).then(() => {
        alert("Resumo copiado para a área de transferência!");
    });
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-4 pb-24 animate-fade-in">
        {/* Header Actions */}
        <div className="flex items-center justify-between">
             <div className="flex bg-surface-dark rounded-lg p-1 border border-white/5">
                <button onClick={() => setTimeRange('all')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'all' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Tudo</button>
                <button onClick={() => setTimeRange('month')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'month' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Mês</button>
                <button onClick={() => setTimeRange('year')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'year' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Ano</button>
             </div>
             <button onClick={handleExport} className="size-9 bg-white/5 rounded-full flex items-center justify-center text-primary hover:bg-white/10 active:scale-95 transition-all">
                <span className="material-symbols-outlined text-[20px]">ios_share</span>
             </button>
        </div>

        {/* Overview Cards */}
        <section>
            <div className="grid grid-cols-3 gap-3">
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>sports_tennis</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Jogos</p>
                    <p className="text-white text-2xl font-bold leading-none">{totalGames}</p>
                </div>
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>scoreboard</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Pontos</p>
                    <p className="text-white text-2xl font-bold leading-none">{totalPoints}</p>
                </div>
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>groups</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Ativos</p>
                    <p className="text-white text-2xl font-bold leading-none">{activePlayersCount}</p>
                </div>
            </div>
        </section>

        {/* Top Locations Stats */}
        {topLocations.length > 0 && (
            <section className="bg-surface-dark rounded-2xl p-5 border border-white/5">
                <div className="flex items-center gap-2 mb-4">
                    <span className="material-symbols-outlined text-yellow-500">star</span>
                    <h3 className="text-sm font-bold text-white uppercase tracking-wider">Locais Mais Utilizados</h3>
                </div>
                <div className="flex flex-col gap-3">
                    {topLocations.map((loc, idx) => (
                        <div key={idx} className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className={`size-6 rounded-full flex items-center justify-center text-xs font-bold ${
                                    idx === 0 ? 'bg-yellow-500 text-black' : 
                                    idx === 1 ? 'bg-gray-400 text-black' : 
                                    'bg-orange-700 text-white'
                                }`}>
                                    {idx + 1}
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-white leading-tight">{loc.name}</p>
                                    <p className="text-[10px] text-gray-500">{loc.type}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-1.5 bg-white/5 px-2 py-1 rounded-md">
                                <span className="text-xs font-bold text-white">{loc.count}</span>
                                <span className="text-[10px] text-gray-500 uppercase">Torneios</span>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        )}

        {/* Strongest Duo Hero */}
        {bestDuo.games > 0 && (
            <section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#28392f] to-surface-dark border border-primary/20 p-5 shadow-lg">
                <div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-primary/10 blur-2xl"></div>
                <div className="flex justify-between items-start relative z-10">
                    <div>
                        <div className="flex items-center gap-2 mb-3">
                            <span className="flex items-center justify-center size-6 rounded-full bg-orange-500/20 text-orange-400">
                                <span className="material-symbols-outlined" style={{ fontSize: '16px' }}>local_fire_department</span>
                            </span>
                            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Dupla Imbatível</h3>
                        </div>
                        <div className="flex items-center gap-3 mb-2">
                            <span className="text-xl font-bold text-white">{bestDuo.names[0]}</span>
                            <span className="text-gray-500 font-bold">&</span>
                            <span className="text-xl font-bold text-white">{bestDuo.names[1]}</span>
                        </div>
                        <p className="text-gray-400 text-xs">{bestDuo.wins} vitórias em {bestDuo.games} jogos juntos</p>
                    </div>
                    <div className="flex flex-col items-center justify-center bg-surface-dark/50 rounded-xl p-3 backdrop-blur-sm border border-white/5">
                        <div className="text-3xl font-bold text-primary">{bestDuo.winRate}%</div>
                        <div className="text-[10px] uppercase font-bold text-gray-400 tracking-wider">Win Rate</div>
                    </div>
                </div>
            </section>
        )}

        {/* Rankings Table */}
        <section className="flex flex-col gap-2">
            <div className="flex items-center justify-between px-2 pb-2">
                <h2 className="text-white text-lg font-bold uppercase tracking-tight">Classificação</h2>
            </div>

            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider">
                <div className="col-span-1 text-center">#</div>
                <div className="col-span-5">Jogador</div>
                <div className="col-span-2 text-center">J</div>
                <div className="col-span-2 text-center">V</div>
                <div className="col-span-2 text-right">Pts</div>
            </div>

            {playerStats.length === 0 ? (
                 <div className="text-center py-8 text-gray-500 border border-dashed border-white/10 rounded-xl">
                    Sem dados para mostrar neste período.
                 </div>
            ) : (
                playerStats.map((p, i) => {
                    const highlight = i < 3;
                    return (
                        <div key={p.id} className={`grid grid-cols-12 gap-2 items-center p-3 rounded-xl ${highlight ? 'bg-[#28392f] border border-primary/30 shadow-[0_0_15px_rgba(43,238,121,0.05)] relative overflow-hidden group' : 'bg-surface-dark border border-white/5'}`}>
                            {highlight && i === 0 && <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary"></div>}
                            <div className={`col-span-1 flex justify-center ${highlight ? '' : 'text-white font-bold text-sm'}`}>
                                {i === 0 ? <span className="material-symbols-outlined text-primary text-sm">emoji_events</span> : i + 1}
                            </div>
                            <div className="col-span-5 flex items-center gap-2">
                                <img alt={p.name} className="size-8 rounded-full object-cover border border-white/10" src={p.image} />
                                <span className="text-white font-bold text-xs truncate">{p.name.split(' ')[0]} {p.name.split(' ')[1]?.charAt(0)}.</span>
                            </div>
                            <div className="col-span-2 text-center text-gray-400 font-medium text-xs">{p.gamesPlayed}</div>
                            <div className="col-span-2 text-center text-white font-bold text-sm">{p.wins}</div>
                            <div className={`col-span-2 text-right font-bold text-xs ${p.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}`}>
                                {p.pointsDiff > 0 ? '+' : ''}{p.pointsDiff}
                            </div>
                        </div>
                    );
                })
            )}
        </section>

        {/* Curiosities & History Summary */}
        <section className="grid grid-cols-2 gap-3">
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-2">
                    <span className="material-symbols-outlined text-yellow-500">fitness_center</span>
                    <span className="text-[10px] font-bold text-gray-400 uppercase">Maior Esmagador</span>
                </div>
                {curiosities.biggestWin.diff > -1 ? (
                    <div>
                        <p className="text-white font-bold text-sm truncate">{curiosities.biggestWin.winner}</p>
                        <p className="text-xs text-primary mt-1">Venceu por {curiosities.biggestWin.diff} pts</p>
                    </div>
                ) : <p className="text-gray-500 text-xs">Sem dados</p>}
            </div>
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-2">
                    <span className="material-symbols-outlined text-blue-400">shield</span>
                    <span className="text-[10px] font-bold text-gray-400 uppercase">A Muralha</span>
                </div>
                {curiosities.muralha.name !== '-' ? (
                    <div>
                        <p className="text-white font-bold text-sm truncate">{curiosities.muralha.name}</p>
                        <p className="text-xs text-blue-400 mt-1">Sofre {curiosities.muralha.avg} pts/jogo</p>
                    </div>
                ) : <p className="text-gray-500 text-xs">Sem dados</p>}
            </div>
        </section>

        {/* History List Compact */}
        <section>
             <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Histórico Recente</h3>
             <div className="space-y-2">
                 {filteredHistory.slice(0, 5).map(t => (
                     <button 
                        key={t.id} 
                        onClick={() => onViewTournament && onViewTournament(t)}
                        className="w-full flex justify-between items-center p-3 bg-card-dark rounded-lg border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all active:scale-[0.98] group"
                    >
                         <div className="flex items-center gap-3">
                             <div className="flex flex-col items-center justify-center size-10 bg-white/5 rounded-lg group-hover:bg-white/10 transition-colors">
                                <span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', {month: 'short'})}</span>
                                <span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span>
                             </div>
                             <div className="text-left">
                                 <p className="text-xs font-bold text-white group-hover:text-primary transition-colors">{t.matches ? t.matches.length : 0} Jogos</p>
                                 <p className="text-[10px] text-gray-400">Ver Resultados &rarr;</p>
                             </div>
                         </div>
                         <span className="text-xs font-bold text-primary bg-primary/10 px-2 py-1 rounded">{t.duration}h</span>
                     </button>
                 ))}
                 {filteredHistory.length === 0 && <p className="text-xs text-center text-gray-500">Sem histórico.</p>}
             </div>
        </section>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE', // Now acts as "Player Details"
  PLAYERS = 'PLAYERS', // The List
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL'
}

export interface Player {
  id: string;
  name: string; // First Name
  lastName?: string;
  nickname?: string; // Display priority
  birthDate?: string;
  hand?: 'Destro' | 'Canhoto';
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
  date?: string; // Helpful for sorting history
}

export interface Tournament {
  id: string;
  date: string; // ISO String or YYYY-MM-DD
  time: string;
  duration: number; // in hours
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[]; // Optional to store history results
}

import React from 'react';
import { Screen } from '../types';

interface NavigationProps {
  currentScreen: Screen;
  setScreen: (screen: Screen) => void;
}

export const Navigation: React.FC<NavigationProps> = ({ currentScreen, setScreen }) => {
  const navItems = [
    { id: Screen.HOME, icon: 'home', label: 'Início' },
    { id: Screen.LOCATIONS, icon: 'location_on', label: 'Locais' },
    { id: Screen.GLOBAL_STATS, icon: 'bar_chart', label: 'Estatísticas' },
    { id: Screen.PLAYERS, icon: 'groups', label: 'Jogadores' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-t border-white/5 pb-6 pt-3 z-50 max-w-md mx-auto">
      <div className="flex justify-around items-center">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setScreen(item.id)}
            className={`flex flex-col items-center gap-1 w-16 transition-colors ${
              (currentScreen === item.id || (item.id === Screen.PLAYERS && currentScreen === Screen.PROFILE)) ? 'text-primary' : 'text-slate-500 hover:text-white'
            }`}
          >
            <span className={`material-symbols-outlined text-[24px] ${currentScreen === item.id ? 'filled' : ''}`}>
              {item.icon}
            </span>
            <span className={`text-[10px] font-medium ${currentScreen === item.id ? 'font-bold' : ''}`}>
              {item.label}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
};

