import React, { useState, useMemo } from 'react';
import { Screen, Player } from '../types';

interface PlayerListProps {
  setScreen: (screen: Screen) => void;
  players?: Player[];
  onPlayerClick?: (id: string) => void;
  onAddPlayer?: (player: Player) => void;
  onUpdatePlayer?: (player: Player) => void;
}

export const PlayerListScreen: React.FC<PlayerListProps> = ({ setScreen, players = [], onPlayerClick, onAddPlayer, onUpdatePlayer }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLevel, setFilterLevel] = useState('Todos');
  const [isEditing, setIsEditing] = useState(false);
  const [editingPlayerId, setEditingPlayerId] = useState<string | null>(null);

  // Form State
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [nickname, setNickname] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [hand, setHand] = useState<'Destro' | 'Canhoto'>('Destro');
  const [level, setLevel] = useState('Nível 3');
  const [image, setImage] = useState('');

  // Filtering & Sorting
  const filteredPlayers = useMemo(() => {
    return players.filter(p => {
        const fullName = `${p.name} ${p.lastName || ''} ${p.nickname || ''}`.toLowerCase();
        const matchesSearch = fullName.includes(searchTerm.toLowerCase());
        const matchesLevel = filterLevel === 'Todos' || p.level === filterLevel;
        return matchesSearch && matchesLevel;
    }).sort((a, b) => {
        // Sort by Nickname if exists, else First Name
        const nameA = a.nickname || a.name;
        const nameB = b.nickname || b.name;
        return nameA.localeCompare(nameB);
    });
  }, [players, searchTerm, filterLevel]);

  const handleEditClick = (e: React.MouseEvent, p: Player) => {
      e.stopPropagation();
      setEditingPlayerId(p.id);
      setFirstName(p.name);
      setLastName(p.lastName || '');
      setNickname(p.nickname || '');
      setBirthDate(p.birthDate || '');
      setHand(p.hand || 'Destro');
      setLevel(p.level);
      setImage(p.image);
      setIsEditing(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddNew = () => {
      setEditingPlayerId(null);
      setFirstName('');
      setLastName('');
      setNickname('');
      setBirthDate('');
      setHand('Destro');
      setLevel('Nível 3');
      setImage('');
      setIsEditing(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSave = () => {
      if (!firstName.trim()) return;

      const pImage = image.trim() || `https://ui-avatars.com/api/?name=${encodeURIComponent(nickname || firstName)}&background=random&color=fff&bold=true`;

      const playerData: Player = {
          id: editingPlayerId || `p-${Date.now()}`,
          name: firstName,
          lastName,
          nickname,
          birthDate,
          hand,
          level,
          image: pImage
      };

      if (editingPlayerId && onUpdatePlayer) {
          onUpdatePlayer(playerData);
      } else if (onAddPlayer) {
          onAddPlayer(playerData);
      }

      setIsEditing(false);
  };

  return (
    <div className="flex flex-col gap-3 px-4 pb-24 animate-fade-in">
      <div className="py-2">
