      </div>

       {/* Search & Filter Section */}
       {!isEditing && (
      <div className="py-2 space-y-4">
        {/* Search Bar */}
        <label className="flex flex-col w-full">
            <div className="relative flex w-full items-center rounded-2xl h-12 bg-card-dark shadow-sm ring-1 ring-white/5 overflow-hidden group focus-within:ring-2 focus-within:ring-primary transition-all">
                <div className="absolute left-4 flex items-center justify-center text-gray-500">
