                    <div className="relative bg-gradient-to-br from-surface-dark to-background-dark border border-primary/30 p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center aspect-square size-48">
                        <span className="material-symbols-outlined text-primary text-[80px] drop-shadow-[0_0_15px_rgba(96,122,251,0.5)]">emoji_events</span>
                    </div>
                    {/* Winner Badge */}
                    <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 bg-primary text-background-dark font-bold px-4 py-1.5 rounded-full shadow-lg whitespace-nowrap text-sm tracking-wide">
                        Equipa Vencedora
                    </div>
                </div>
                <div className="flex flex-col items-center text-center mt-4 space-y-2">
                    <h2 className="text-white text-2xl font-bold leading-tight">
                        {winner.teamName}
                    </h2>
                    <div className="flex items-center gap-2 px-4 py-2 bg-surface-dark/50 rounded-full border border-white/5">
                        <span className="text-gray-400 text-sm font-medium">{winner.wins} Vitórias</span>
                        <span className="w-1 h-1 rounded-full bg-gray-500"></span>
                        <span className="text-primary text-sm font-bold">{winner.pointsDiff > 0 ? '+' : ''}{winner.pointsDiff} DP</span>
