        {/* Rankings Table */}
        <section className="flex flex-col gap-2">
            <div className="flex items-center justify-between px-2 pb-2">
                <h2 className="text-white text-lg font-bold uppercase tracking-tight">Classificação</h2>
            </div>

            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider">
