import React, { useMemo } from 'react';
import { Screen, Tournament, Match, Player, Location } from '../types';

interface HistoryDetailProps {
  setScreen: (screen: Screen) => void;
  tournament: Tournament;
  locations: Location[];
}

export const HistoryDetailScreen: React.FC<HistoryDetailProps> = ({ setScreen, tournament, locations }) => {
  const matches = tournament.matches || [];
  const locationName = locations.find(l => l.id === tournament.locationId)?.name || 'Local Desconhecido';

  // --- Calculate Standings Logic (Reused) ---
  const standings = useMemo(() => {
    const stats = new Map<string, { 
        id: string,
        teamName: string, 
        wins: number, 
        pointsDiff: number 
    }>();

    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) {
            stats.set(key, {
                id: key,
                teamName: team.map(p => p.nickname || p.name.split(' ')[0]).join(' & '),
                wins: 0,
                pointsDiff: 0
            });
        }
        return stats.get(key)!;
    };

    matches.forEach(m => {
        const stats1 = getStats(m.team1);
        const stats2 = getStats(m.team2);

        stats1.pointsDiff += (m.score1 - m.score2);
        stats2.pointsDiff += (m.score2 - m.score1);

        if (m.score1 > m.score2) stats1.wins += 1;
        else if (m.score2 > m.score1) stats2.wins += 1;
    });

    return Array.from(stats.values()).sort((a, b) => {
        if (b.wins !== a.wins) return b.wins - a.wins;
        return b.pointsDiff - a.pointsDiff;
    });
  }, [matches]);

  const rounds = Array.from(new Set(matches.map(m => m.round))).sort((a, b) => a - b);

  return (
    <div className="flex-1 flex flex-col gap-6 p-4 pb-24 animate-fade-in bg-background-dark min-h-screen relative z-20">
        <header className="flex items-center justify-between sticky top-0 bg-background-dark/95 backdrop-blur-md py-2 z-30">
            <button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                <span className="material-symbols-outlined text-white">arrow_back</span>
            </button>
            <div className="flex flex-col items-center">
                <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">{new Date(tournament.date).toLocaleDateString()}</span>
                <h2 className="text-sm font-bold text-white max-w-[200px] truncate">{locationName}</h2>
            </div>
            <div className="w-10"></div>
        </header>

        {/* Podium / Winner */}
        {standings.length > 0 && (
            <div className="bg-surface-dark rounded-2xl p-4 border border-white/5 shadow-lg">
                <h3 className="text-center text-xs font-bold text-primary uppercase tracking-wider mb-4">Classificação Final</h3>
                <div className="flex flex-col gap-2">
                    {standings.slice(0, 3).map((team, idx) => (
                        <div key={idx} className="flex items-center justify-between p-2 rounded-lg bg-white/5">
                            <div className="flex items-center gap-3">
                                <div className={`size-6 rounded-full flex items-center justify-center text-xs font-bold ${
                                    idx === 0 ? 'bg-yellow-500 text-black' : 
                                    idx === 1 ? 'bg-gray-400 text-black' : 
                                    'bg-orange-700 text-white'
                                }`}>
                                    {idx + 1}
                                </div>
                                <span className="text-sm font-bold text-white">{team.teamName}</span>
                            </div>
                            <div className="text-xs font-medium text-gray-400">
                                {team.wins}V <span className={team.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}>({team.pointsDiff > 0 ? '+' : ''}{team.pointsDiff})</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* Match History List */}
        <div className="space-y-6">
            {rounds.map(round => (
                <div key={round}>
                    <div className="flex items-center gap-2 mb-3 px-1">
                        <div className="h-px flex-1 bg-white/10"></div>
                        <span className="text-xs font-bold text-gray-500 uppercase">Ronda {round}</span>
                        <div className="h-px flex-1 bg-white/10"></div>
                    </div>
                    <div className="flex flex-col gap-3">
                        {matches.filter(m => m.round === round).map(match => (
                            <div key={match.id} className="bg-card-dark rounded-xl border border-white/5 p-3 flex flex-col gap-2">
                                <div className="flex justify-between items-center text-[10px] text-gray-500 uppercase font-bold tracking-wider mb-1">
                                    <span>Campo {match.court}</span>
                                    {match.score1 > match.score2 ? (
                                        <span className="text-primary">Vitória Equipa 1</span>
                                    ) : match.score2 > match.score1 ? (
                                        <span className="text-purple-400">Vitória Equipa 2</span>
                                    ) : <span>Empate</span>}
                                </div>

                                <div className="flex items-center justify-between">
                                    {/* Team 1 */}
                                    <div className="flex items-center gap-2 flex-1 overflow-hidden">
                                        <div className="flex -space-x-2 shrink-0">
                                            {match.team1.map(p => (
                                                <img key={p.id} src={p.image} className="w-6 h-6 rounded-full border border-card-dark object-cover opacity-80" />
                                            ))}
                                        </div>
                                        <span className={`text-xs font-bold truncate ${match.score1 > match.score2 ? 'text-white' : 'text-gray-400'}`}>
                                            {match.team1.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                        </span>
                                    </div>

                                    {/* Score */}
                                    <div className="flex items-center gap-2 px-3">
                                        <span className={`text-lg font-bold ${match.score1 > match.score2 ? 'text-primary' : 'text-gray-500'}`}>{match.score1}</span>
                                        <span className="text-gray-600">-</span>
                                        <span className={`text-lg font-bold ${match.score2 > match.score1 ? 'text-purple-400' : 'text-gray-500'}`}>{match.score2}</span>
                                    </div>

                                    {/* Team 2 */}
                                    <div className="flex items-center gap-2 flex-1 justify-end overflow-hidden">
                                        <span className={`text-xs font-bold truncate ${match.score2 > match.score1 ? 'text-white' : 'text-gray-400'}`}>
                                            {match.team2.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                        </span>
                                        <div className="flex -space-x-2 shrink-0">
                                            {match.team2.map(p => (
                                                <img key={p.id} src={p.image} className="w-6 h-6 rounded-full border border-card-dark object-cover opacity-80" />
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
}

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, currentMatches, setScreen }) => {
  const player = players.find(p => p.id === playerId);

  // -- STATS CALCULATION --
  const stats = useMemo(() => {
    if (!playerId) return null;

    let wins = 0;
    let losses = 0;
    let gamesPlayed = 0;
    let totalPointsScored = 0;
    let totalPointsConceded = 0;
    let tournamentsParticipated = 0;
    let tournamentsWon = 0;

    // Partner Stats tracking
    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number }>();

    // Streaks
    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let currentLossStreak = 0;
    let maxLossStreak = 0;

    // 1. Process Tournament Wins & Participation
    history.forEach(t => {
        if (t.matches && t.matches.length > 0 && t.status === 'finished') {
            const playerInTournament = t.matches.some(m => 
                m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)
            );

            if (playerInTournament) {
                tournamentsParticipated++;

                // Calculate Tournament Winner Logic (Local Scope)
                const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();

                const getTeamKey = (team: Player[]) => team.map(p => p.id).sort().join('-');

                t.matches.forEach(m => {
                    const key1 = getTeamKey(m.team1);
                    const key2 = getTeamKey(m.team2);

                    if (!teamStats.has(key1)) teamStats.set(key1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
                    if (!teamStats.has(key2)) teamStats.set(key2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });

                    const s1 = teamStats.get(key1)!;
                    const s2 = teamStats.get(key2)!;

                    s1.diff += (m.score1 - m.score2);
                    s2.diff += (m.score2 - m.score1);

                    if (m.score1 > m.score2) s1.wins++;
                    else if (m.score2 > m.score1) s2.wins++;
                });

                // Sort standings
                const standings = Array.from(teamStats.values()).sort((a, b) => {
                    if (b.wins !== a.wins) return b.wins - a.wins;
                    return b.diff - a.diff;
                });

                // Check if player is in the winning team (Index 0)
                if (standings.length > 0 && standings[0].playerIds.includes(playerId)) {
                    tournamentsWon++;
                }
            }
        }
    });

    // 2. Collect all matches involving this player (History + Current) for Game Stats
    const allMatches: Match[] = [];

    // From History
    history.forEach(t => {
        if (t.matches) {
            t.matches.forEach(m => {
                 const inTeam1 = m.team1.some(p => p.id === playerId);
                 const inTeam2 = m.team2.some(p => p.id === playerId);
                 if (inTeam1 || inTeam2) {
                     allMatches.push({...m, date: t.date}); 
                 }
            });
        }
    });

    // From Current Live
    currentMatches.forEach(m => {
        const inTeam1 = m.team1.some(p => p.id === playerId);
        const inTeam2 = m.team2.some(p => p.id === playerId);
        if (inTeam1 || inTeam2) {
            allMatches.push({...m, date: new Date().toISOString()});
        }
    });

    // Sort matches by date
    allMatches.sort((a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime());

    // Process Game Stats
    const chronologicalMatches = [...allMatches].reverse();

    chronologicalMatches.forEach(m => {
        if (m.status === 'finished') {
            const inTeam1 = m.team1.some(p => p.id === playerId);
            const myTeam = inTeam1 ? 1 : 2;
            const won = (myTeam === 1 && m.score1 > m.score2) || (myTeam === 2 && m.score2 > m.score1);

            gamesPlayed++;

            // Points
            if (inTeam1) {
                totalPointsScored += m.score1;
                totalPointsConceded += m.score2;
            } else {
                totalPointsScored += m.score2;
                totalPointsConceded += m.score1;
            }

            // Win/Loss & Streaks
            if (won) {
                wins++;
                currentWinStreak++;
                currentLossStreak = 0;
                if (currentWinStreak > maxWinStreak) maxWinStreak = currentWinStreak;
            } else {
                losses++;
                currentLossStreak++;
                currentWinStreak = 0;
                if (currentLossStreak > maxLossStreak) maxLossStreak = currentLossStreak;
            }

            // Partners
            const myTeammates = inTeam1 ? m.team1 : m.team2;
            const partner = myTeammates.find(p => p.id !== playerId);
            if (partner) {
                if (!partners.has(partner.id)) {
                    partners.set(partner.id, { 
                        id: partner.id, 
                        name: partner.nickname || partner.name, 
                        image: partner.image,
                        wins: 0, 
                        games: 0 
                    });
                }
                const pStats = partners.get(partner.id)!;
                pStats.games++;
                if (won) pStats.wins++;
            }
        }
    });

    const winRate = gamesPlayed > 0 ? Math.round((wins / gamesPlayed) * 100) : 0;
    const tournamentWinRate = tournamentsParticipated > 0 ? Math.round((tournamentsWon / tournamentsParticipated) * 100) : 0;
    const pointBalance = totalPointsScored - totalPointsConceded;

    const topPartners = Array.from(partners.values())
        .sort((a, b) => b.wins - a.wins || b.games - a.games)
        .slice(0, 5);

    return {
        wins,
        losses,
        gamesPlayed,
        tournamentsParticipated,
        tournamentsWon,
        winRate,
        tournamentWinRate,
        totalPointsScored,
        totalPointsConceded,
        pointBalance,
        maxWinStreak,
        maxLossStreak,
        topPartners,
        recentMatches: allMatches.slice(0, 5)
    };

  }, [playerId, history, currentMatches]);

  if (!player || !stats) return <div className="p-10 text-center">Jogador não encontrado.</div>;

  const displayName = player.nickname ? `${player.name} "${player.nickname}" ${player.lastName || ''}` : `${player.name} ${player.lastName || ''}`;
  const age = player.birthDate ? new Date().getFullYear() - new Date(player.birthDate).getFullYear() : 'N/A';

  return (
    <div className="flex flex-col gap-6 pb-24 animate-fade-in relative">

      {/* Bio Header */}
      <div className="flex flex-col items-center px-4 pt-4">
        <div className="relative mb-4">
          <div 
            className="bg-center bg-no-repeat bg-cover rounded-full h-32 w-32 ring-4 ring-card-dark shadow-xl bg-surface-dark"
            style={{ backgroundImage: `url("${player.image}")` }}
          ></div>
          <div className="absolute bottom-0 right-0 bg-primary text-background-dark text-xs font-bold px-3 py-1 rounded-full border-4 border-background-dark flex items-center gap-1 shadow-lg">
             {player.hand === 'Canhoto' ? 'Canhoto' : 'Destro'}
          </div>
        </div>

        <h1 className="text-2xl font-bold text-center mb-1 leading-tight">{player.nickname || player.name}</h1>
        <p className="text-gray-400 text-sm mb-3">{player.name} {player.lastName}</p>

        <div className="flex items-center gap-3 text-sm">
             <span className="bg-white/5 px-3 py-1 rounded-full border border-white/10 text-gray-300">
                {age !== 'N/A' ? `${age} Anos` : 'Idade N/A'}
             </span>
             <span className={`px-3 py-1 rounded-full border border-white/10 font-bold ${
                 player.level === 'Pro' ? 'bg-purple-500/20 text-purple-300' : 'bg-primary/20 text-primary'
             }`}>
                {player.level}
             </span>
        </div>
      </div>

      {/* Main Stats Grid - Segregated */}
      <div className="px-4">
        <div className="grid grid-cols-2 gap-3">

            {/* 1. Games Stats */}
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 shadow-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 p-2 opacity-10">
                    <span className="material-symbols-outlined text-4xl">sports_tennis</span>
                </div>
                <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider mb-1">Jogos</p>
                <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-bold text-white">{stats.gamesPlayed}</span>
                    <span className="text-xs text-gray-400">Realizados</span>
                </div>

                <div className="w-full h-1.5 bg-gray-700 rounded-full mt-2 overflow-hidden flex">
                    <div style={{width: `${stats.winRate}%`}} className="bg-green-500 h-full"></div>
                    <div className="flex-1 bg-red-500 h-full"></div>
                </div>
                <div className="flex justify-between text-[10px] mt-1 font-bold">
                    <span className="text-green-500">{stats.wins} Ganhos</span>
                    <span className="text-red-500">{stats.losses} Perdidos</span>
                </div>
            </div>

            {/* 2. Tournaments Stats */}
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 shadow-sm relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-2 opacity-10">
                    <span className="material-symbols-outlined text-4xl text-yellow-500">emoji_events</span>
                </div>
                <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider mb-1">Torneios</p>
                <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-bold text-white">{stats.tournamentsParticipated}</span>
                    <span className="text-xs text-gray-400">Total</span>
                </div>
                <div className="flex items-center gap-2 mt-2 bg-yellow-500/10 p-1.5 rounded-lg border border-yellow-500/20">
                     <span className="material-symbols-outlined text-yellow-500 text-sm">emoji_events</span>
                     <span className="text-sm font-bold text-yellow-500">{stats.tournamentsWon} Ganhos</span>
                </div>
            </div>

            {/* 3. Point Balance */}
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 shadow-sm">
                 <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider mb-1">Saldo Pontos</p>
                 <span className={`text-2xl font-bold ${stats.pointBalance > 0 ? 'text-green-400' : 'text-red-400'}`}>
                     {stats.pointBalance > 0 ? '+' : ''}{stats.pointBalance}
                 </span>
                 <div className="flex justify-between items-center mt-2 text-[10px] border-t border-white/5 pt-1">
                    <div className="text-center">
                        <div className="text-green-400 font-bold">{stats.totalPointsScored}</div>
                        <div className="text-gray-500">Marcados</div>
                    </div>
                    <div className="text-center">
                        <div className="text-red-400 font-bold">{stats.totalPointsConceded}</div>
                        <div className="text-gray-500">Sofridos</div>
                    </div>
                 </div>
            </div>

            {/* 4. Ratios */}
             <div className="bg-card-dark p-4 rounded-2xl border border-white/5 shadow-sm">
                 <p className="text-gray-500 text-[10px] font-bold uppercase tracking-wider mb-1">Performance</p>
                 <div className="flex flex-col gap-2">
                     <div className="flex justify-between items-center">
                        <span className="text-[10px] text-gray-400">Win Rate</span>
                        <span className="text-sm font-bold text-primary">{stats.winRate}%</span>
                     </div>
                     <div className="w-full h-1 bg-gray-700 rounded-full overflow-hidden">
                        <div style={{width: `${stats.winRate}%`}} className="bg-primary h-full"></div>
                     </div>
                     <p className="text-[9px] text-gray-500 mt-0.5">Baseado em jogos ganhos</p>
                 </div>
            </div>
        </div>
      </div>

      {/* Curiosities / Streaks */}
      <div className="px-4">
          <div className="bg-surface-dark rounded-2xl p-4 border border-white/5 flex justify-around">
               <div className="text-center">
                   <p className="text-[10px] text-gray-500 uppercase font-bold">Série Vitórias</p>
                   <p className="text-xl font-bold text-green-400 flex items-center justify-center gap-1">
                       {stats.maxWinStreak} <span className="material-symbols-outlined text-sm">local_fire_department</span>
                   </p>
               </div>
               <div className="w-px bg-white/10"></div>
               <div className="text-center">
                   <p className="text-[10px] text-gray-500 uppercase font-bold">Série Derrotas</p>
                   <p className="text-xl font-bold text-red-400 flex items-center justify-center gap-1">
                       {stats.maxLossStreak} <span className="material-symbols-outlined text-sm">sentiment_very_dissatisfied</span>
                   </p>
               </div>
          </div>
      </div>

      {/* Partners List */}
      <div className="flex flex-col gap-3">
        <div className="px-4 flex justify-between items-end">
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">Melhores Parceiros</h3>
        </div>
        {stats.topPartners.length === 0 ? (
            <p className="px-4 text-xs text-gray-500">Sem dados de parceiros ainda.</p>
        ) : (
            <div className="flex overflow-x-auto hide-scrollbar px-4 gap-3 pb-2">
            {stats.topPartners.map((partner, idx) => {
                const pRate = Math.round((partner.wins / partner.games) * 100);
                return (
                    <div key={idx} className="flex-shrink-0 w-28 bg-card-dark p-3 rounded-xl border border-white/5 flex flex-col items-center gap-2">
                    <div className="size-10 rounded-full bg-cover bg-center" style={{ backgroundImage: `url("${partner.image}")` }}></div>
                    <div className="text-center w-full">
                        <p className="font-bold text-xs truncate w-full text-white">{partner.name}</p>
                        <div className="flex justify-center gap-1 mt-1">
                            <span className="text-[10px] font-bold text-primary bg-primary/10 px-1.5 rounded">{partner.wins}V</span>
                            <span className="text-[10px] text-gray-500">{partner.games}J</span>
                        </div>
                        <p className={`text-[9px] font-bold mt-1 ${pRate >= 50 ? 'text-green-400' : 'text-red-400'}`}>{pRate}% Win</p>
                    </div>
                    </div>
                )
            })}
            </div>
        )}
      </div>

      {/* Match History */}
      <div className="px-4">
          <h3 className="text-sm font-bold text-white uppercase tracking-wider mb-3">Últimos 5 Jogos</h3>
          <div className="flex flex-col gap-2">
              {stats.recentMatches.map((m, idx) => {
                  const inTeam1 = m.team1.some(p => p.id === playerId);
                  const myTeam = inTeam1 ? m.team1 : m.team2;
                  const oppTeam = inTeam1 ? m.team2 : m.team1;
                  const myScore = inTeam1 ? m.score1 : m.score2;
                  const oppScore = inTeam1 ? m.score2 : m.score1;
                  const won = myScore > oppScore;
                  const isDraw = myScore === oppScore;
                  const partner = myTeam.find(p => p.id !== playerId);

                  return (
                      <div key={idx} className="flex items-center justify-between bg-card-dark p-3 rounded-xl border border-white/5">
                          <div className="flex items-center gap-3">
                              <div className={`w-1 h-8 rounded-full ${won ? 'bg-green-500' : isDraw ? 'bg-gray-500' : 'bg-red-500'}`}></div>
                              <div className="flex flex-col">
                                  <div className="flex items-center gap-1">
                                      <span className={`text-sm font-bold ${won ? 'text-green-400' : isDraw ? 'text-gray-400' : 'text-red-400'}`}>
                                          {won ? 'Vitória' : isDraw ? 'Empate' : 'Derrota'}
                                      </span>
                                      <span className="text-xs text-white font-bold">{myScore}-{oppScore}</span>
                                  </div>
                                  <p className="text-[10px] text-gray-500 truncate max-w-[150px]">
                                      c/ {partner ? (partner.nickname || partner.name) : '?'} vs {oppTeam.map(p => p.nickname || p.name).join(' & ')}
                                  </p>
                              </div>
                          </div>
                          <span className="text-[10px] font-mono text-gray-600">
                              {m.date ? new Date(m.date).toLocaleDateString(undefined, {month:'short', day:'numeric'}) : '-'}
                          </span>
                      </div>
                  );
              })}
              {stats.recentMatches.length === 0 && <p className="text-xs text-gray-500 text-center py-4">Sem jogos registados.</p>}
          </div>
      </div>

    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location } from '../types';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
}

interface PlayerStats {
  id: string;
  name: string;
  image: string;
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  pointsDiff: number;
  tournamentsPlayed: number;
  tournamentsWon: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');

  // --- Filtering Logic ---
  const filteredHistory = useMemo(() => {
    if (timeRange === 'all') return history;

    const now = new Date();
    return history.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') {
        return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      }
      if (timeRange === 'year') {
        return tDate.getFullYear() === now.getFullYear();
      }
      return true;
    });
  }, [history, timeRange]);

  // --- Stats Calculation Engine ---
  const { playerStats, totalGames, totalPoints, activePlayersCount, bestDuo, curiosities, topLocations } = useMemo(() => {
    const stats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, names: string[] }>();
    const locationCounts = new Map<string, number>();
    let tGames = 0;
    let tPoints = 0;

    // Curiosities trackers
    let maxDiff = { diff: -1, winner: '', loser: '' };

    // Initialize stats for all known players
    players.forEach(p => {
        stats.set(p.id, {
            id: p.id,
            name: p.nickname || p.name,
            image: p.image,
            gamesPlayed: 0,
            wins: 0,
            losses: 0,
            pointsScored: 0,
            pointsConceded: 0,
            pointsDiff: 0,
            tournamentsPlayed: 0,
            tournamentsWon: 0
        });
    });

    filteredHistory.forEach(t => {
       // Location Stats
       const locCount = locationCounts.get(t.locationId) || 0;
       locationCounts.set(t.locationId, locCount + 1);

       const tournamentPlayers = new Set<string>();

       // --- 1. Calculate Tournament Winner ---
       let tournamentWinnerIds: string[] = [];
       if (t.matches && t.matches.length > 0 && t.status === 'finished') {
           const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
           const getTeamKey = (team: Player[]) => team.map(p => p.id).sort().join('-');

           t.matches.forEach(m => {
               const k1 = getTeamKey(m.team1);
               const k2 = getTeamKey(m.team2);
               if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
               if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });

               const s1 = teamStats.get(k1)!;
               const s2 = teamStats.get(k2)!;
               s1.diff += (m.score1 - m.score2);
               s2.diff += (m.score2 - m.score1);
               if (m.score1 > m.score2) s1.wins++;
               else if (m.score2 > m.score1) s2.wins++;
           });

           const standings = Array.from(teamStats.values()).sort((a, b) => {
               if (b.wins !== a.wins) return b.wins - a.wins;
               return b.diff - a.diff;
           });

           if (standings.length > 0) {
               tournamentWinnerIds = standings[0].playerIds;
               tournamentWinnerIds.forEach(wid => {
                   const ps = stats.get(wid);
                   if (ps) ps.tournamentsWon++;
               });
           }
       }
       // --------------------------------------

       if (t.matches) {
           tGames += t.matches.length;

           t.matches.forEach(m => {
               if (m.status !== 'finished' && m.status !== 'live') return; // Only count played games

               tPoints += (m.score1 + m.score2);

               const getTeamName = (team: Player[]) => team.map(p => p.nickname || p.name.split(' ')[0]).join('&');

               // Track Curiosities: Biggest Win
               const diff = Math.abs(m.score1 - m.score2);
               if (diff > maxDiff.diff) {
                   maxDiff = {
                       diff: diff,
                       winner: m.score1 > m.score2 ? getTeamName(m.team1) : getTeamName(m.team2),
                       loser: m.score1 > m.score2 ? getTeamName(m.team2) : getTeamName(m.team1),
                   };
               }

               // Process Team 1
               const t1Id = m.team1.map(p => p.id).sort().join('-');
               if (!duoStats.has(t1Id)) duoStats.set(t1Id, { wins: 0, games: 0, names: m.team1.map(p => p.nickname || p.name.split(' ')[0]) });
               const d1 = duoStats.get(t1Id)!;
               d1.games += 1;
               if (m.score1 > m.score2) d1.wins += 1;

               m.team1.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score1;
                       ps.pointsConceded += m.score2;
                       ps.pointsDiff += (m.score1 - m.score2);
                       if (m.score1 > m.score2) ps.wins++;
                       else ps.losses++;
                   }
               });

               // Process Team 2
               const t2Id = m.team2.map(p => p.id).sort().join('-');
               if (!duoStats.has(t2Id)) duoStats.set(t2Id, { wins: 0, games: 0, names: m.team2.map(p => p.nickname || p.name.split(' ')[0]) });
               const d2 = duoStats.get(t2Id)!;
               d2.games += 1;
               if (m.score2 > m.score1) d2.wins += 1;

               m.team2.forEach(p => {
                   tournamentPlayers.add(p.id);
                   const ps = stats.get(p.id);
                   if (ps) {
                       ps.gamesPlayed++;
                       ps.pointsScored += m.score2;
                       ps.pointsConceded += m.score1;
                       ps.pointsDiff += (m.score2 - m.score1);
                       if (m.score2 > m.score1) ps.wins++;
                       else ps.losses++;
                   }
               });
           });
       }

       // Increment tournament count for players involved
       tournamentPlayers.forEach(pid => {
           const ps = stats.get(pid);
           if (ps) ps.tournamentsPlayed++;
       });
    });

    // Find Best Duo (Min 2 games to qualify)
    let bestDuoData = { names: ['-', '-'], winRate: 0, wins: 0, games: 0 };
    duoStats.forEach((val) => {
        if (val.games >= 2) {
            const rate = (val.wins / val.games) * 100;
            if (rate > bestDuoData.winRate || (rate === bestDuoData.winRate && val.wins > bestDuoData.wins)) {
                bestDuoData = { names: val.names, winRate: Math.round(rate), wins: val.wins, games: val.games };
            }
        }
    });

    // Determine "Muralha" (Least points conceded per game, min 3 games)
    let muralha = { name: '-', avg: 999 };
    stats.forEach(p => {
        if (p.gamesPlayed >= 3) {
            const avg = p.pointsConceded / p.gamesPlayed;
            if (avg < muralha.avg) muralha = { name: p.name.split(' ')[0], avg: parseFloat(avg.toFixed(1)) };
        }
    });

    // Calculate Top Locations
    const topLocs = Array.from(locationCounts.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([id, count]) => {
            const loc = locations.find(l => l.id === id);
            return {
                name: loc?.name || 'Local Desconhecido',
                type: loc?.type || 'Indoor',
                count
            };
        });

    const activePlayers = Array.from(stats.values()).filter(p => p.gamesPlayed > 0);

    return {
        playerStats: activePlayers.sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff),
        totalGames: tGames,
        totalPoints: tPoints,
        activePlayersCount: activePlayers.length,
        bestDuo: bestDuoData,
        curiosities: {
            biggestWin: maxDiff,
            muralha: muralha
        },
        topLocations: topLocs
    };
  }, [filteredHistory, players, locations]);

  // --- Export Function ---
  const handleExport = () => {
    let text = `🎾 *Estatísticas Padel Pro Manager*\n📅 Período: ${timeRange === 'all' ? 'Tudo' : timeRange}\n\n`;
    text += `🏆 *Resumo*\n- Jogos: ${totalGames}\n- Pontos: ${totalPoints}\n- Jogadores: ${activePlayersCount}\n\n`;
    text += `🥇 *Top 3 Jogadores*\n`;
    playerStats.slice(0, 3).forEach((p, i) => {
        text += `${i+1}. ${p.name} (${p.wins} Jogos V / ${p.tournamentsWon} Torneios V)\n`;
    });

    navigator.clipboard.writeText(text).then(() => {
        alert("Resumo copiado para a área de transferência!");
    });
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-4 pb-24 animate-fade-in">
        {/* Header Actions */}
        <div className="flex items-center justify-between">
             <div className="flex bg-surface-dark rounded-lg p-1 border border-white/5">
                <button onClick={() => setTimeRange('all')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'all' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Tudo</button>
                <button onClick={() => setTimeRange('month')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'month' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Mês</button>
                <button onClick={() => setTimeRange('year')} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === 'year' ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>Ano</button>
             </div>
             <button onClick={handleExport} className="size-9 bg-white/5 rounded-full flex items-center justify-center text-primary hover:bg-white/10 active:scale-95 transition-all">
                <span className="material-symbols-outlined text-[20px]">ios_share</span>
             </button>
        </div>

        {/* Overview Cards */}
        <section>
            <div className="grid grid-cols-3 gap-3">
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>sports_tennis</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Jogos</p>
                    <p className="text-white text-2xl font-bold leading-none">{totalGames}</p>
                </div>
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>scoreboard</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Pontos</p>
                    <p className="text-white text-2xl font-bold leading-none">{totalPoints}</p>
                </div>
                <div className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm">
                    <span className="material-symbols-outlined text-primary mb-1" style={{ fontSize: '24px' }}>groups</span>
                    <p className="text-gray-400 text-xs font-medium uppercase">Ativos</p>
                    <p className="text-white text-2xl font-bold leading-none">{activePlayersCount}</p>
                </div>
            </div>
        </section>

        {/* Top Locations Stats */}
        {topLocations.length > 0 && (
            <section className="bg-surface-dark rounded-2xl p-5 border border-white/5">
                <div className="flex items-center gap-2 mb-4">
                    <span className="material-symbols-outlined text-yellow-500">star</span>
                    <h3 className="text-sm font-bold text-white uppercase tracking-wider">Locais Mais Utilizados</h3>
                </div>
                <div className="flex flex-col gap-3">
                    {topLocations.map((loc, idx) => (
                        <div key={idx} className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className={`size-6 rounded-full flex items-center justify-center text-xs font-bold ${
                                    idx === 0 ? 'bg-yellow-500 text-black' : 
                                    idx === 1 ? 'bg-gray-400 text-black' : 
                                    'bg-orange-700 text-white'
                                }`}>
                                    {idx + 1}
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-white leading-tight">{loc.name}</p>
                                    <p className="text-[10px] text-gray-500">{loc.type}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-1.5 bg-white/5 px-2 py-1 rounded-md">
                                <span className="text-xs font-bold text-white">{loc.count}</span>
                                <span className="text-[10px] text-gray-500 uppercase">Torneios</span>
                            </div>
                        </div>
                    ))}
                </div>
            </section>
        )}

        {/* Strongest Duo Hero */}
        {bestDuo.games > 0 && (
            <section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#28392f] to-surface-dark border border-primary/20 p-5 shadow-lg">
                <div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-primary/10 blur-2xl"></div>
                <div className="flex justify-between items-start relative z-10">
                    <div>
                        <div className="flex items-center gap-2 mb-3">
                            <span className="flex items-center justify-center size-6 rounded-full bg-orange-500/20 text-orange-400">
                                <span className="material-symbols-outlined" style={{ fontSize: '16px' }}>local_fire_department</span>
                            </span>
                            <h3 className="text-sm font-bold text-white uppercase tracking-wider">Dupla Imbatível</h3>
                        </div>
                        <div className="flex items-center gap-3 mb-2">
                            <span className="text-xl font-bold text-white">{bestDuo.names[0]}</span>
                            <span className="text-gray-500 font-bold">&</span>
                            <span className="text-xl font-bold text-white">{bestDuo.names[1]}</span>
                        </div>
                        <p className="text-gray-400 text-xs">{bestDuo.wins} vitórias em {bestDuo.games} jogos juntos</p>
                    </div>
                    <div className="flex flex-col items-center justify-center bg-surface-dark/50 rounded-xl p-3 backdrop-blur-sm border border-white/5">
                        <div className="text-3xl font-bold text-primary">{bestDuo.winRate}%</div>
                        <div className="text-[10px] uppercase font-bold text-gray-400 tracking-wider">Win Rate</div>
                    </div>
                </div>
            </section>
        )}

        {/* Rankings Table */}
        <section className="flex flex-col gap-2">
            <div className="flex items-center justify-between px-2 pb-2">
                <h2 className="text-white text-lg font-bold uppercase tracking-tight">Classificação</h2>
            </div>

            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider">
                <div className="col-span-1 text-center">#</div>
                <div className="col-span-4">Jogador</div>
                <div className="col-span-2 text-center" title="Jogos">J</div>
                <div className="col-span-2 text-center" title="Jogos Ganhos">V</div>
                <div className="col-span-1 text-center text-yellow-500" title="Torneios Ganhos">T</div>
                <div className="col-span-2 text-right">Pts</div>
            </div>

            {playerStats.length === 0 ? (
                 <div className="text-center py-8 text-gray-500 border border-dashed border-white/10 rounded-xl">
                    Sem dados para mostrar neste período.
                 </div>
            ) : (
                playerStats.map((p, i) => {
                    const highlight = i < 3;
                    return (
                        <div key={p.id} className={`grid grid-cols-12 gap-2 items-center p-3 rounded-xl ${highlight ? 'bg-[#28392f] border border-primary/30 shadow-[0_0_15px_rgba(43,238,121,0.05)] relative overflow-hidden group' : 'bg-surface-dark border border-white/5'}`}>
                            {highlight && i === 0 && <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary"></div>}
                            <div className={`col-span-1 flex justify-center ${highlight ? '' : 'text-white font-bold text-sm'}`}>
                                {i === 0 ? <span className="material-symbols-outlined text-primary text-sm">emoji_events</span> : i + 1}
                            </div>
                            <div className="col-span-4 flex items-center gap-2">
                                <img alt={p.name} className="size-8 rounded-full object-cover border border-white/10" src={p.image} />
                                <span className="text-white font-bold text-xs truncate">{p.name.split(' ')[0]} {p.name.split(' ')[1]?.charAt(0)}.</span>
                            </div>
                            <div className="col-span-2 text-center text-gray-400 font-medium text-xs">{p.gamesPlayed}</div>
                            <div className="col-span-2 text-center text-white font-bold text-sm">{p.wins}</div>
                            <div className="col-span-1 text-center text-yellow-500 font-bold text-sm">{p.tournamentsWon}</div>
                            <div className={`col-span-2 text-right font-bold text-xs ${p.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}`}>
                                {p.pointsDiff > 0 ? '+' : ''}{p.pointsDiff}
                            </div>
                        </div>
                    );
                })
            )}
        </section>

        {/* Curiosities & History Summary */}
        <section className="grid grid-cols-2 gap-3">
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-2">
                    <span className="material-symbols-outlined text-yellow-500">fitness_center</span>
                    <span className="text-[10px] font-bold text-gray-400 uppercase">Maior Esmagador</span>
                </div>
                {curiosities.biggestWin.diff > -1 ? (
                    <div>
                        <p className="text-white font-bold text-sm truncate">{curiosities.biggestWin.winner}</p>
                        <p className="text-xs text-primary mt-1">Venceu por {curiosities.biggestWin.diff} pts</p>
                    </div>
                ) : <p className="text-gray-500 text-xs">Sem dados</p>}
            </div>
             <div className="bg-surface-dark p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-2">
                    <span className="material-symbols-outlined text-blue-400">shield</span>
                    <span className="text-[10px] font-bold text-gray-400 uppercase">A Muralha</span>
                </div>
                {curiosities.muralha.name !== '-' ? (
                    <div>
                        <p className="text-white font-bold text-sm truncate">{curiosities.muralha.name}</p>
                        <p className="text-xs text-blue-400 mt-1">Sofre {curiosities.muralha.avg} pts/jogo</p>
                    </div>
                ) : <p className="text-gray-500 text-xs">Sem dados</p>}
            </div>
        </section>

        {/* History List Compact */}
        <section>
             <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Histórico Recente</h3>
             <div className="space-y-2">
                 {filteredHistory.slice(0, 5).map(t => (
                     <button 
                        key={t.id} 
                        onClick={() => onViewTournament && onViewTournament(t)}
                        className="w-full flex justify-between items-center p-3 bg-card-dark rounded-lg border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all active:scale-[0.98] group"
                    >
                         <div className="flex items-center gap-3">
                             <div className="flex flex-col items-center justify-center size-10 bg-white/5 rounded-lg group-hover:bg-white/10 transition-colors">
                                <span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', {month: 'short'})}</span>
                                <span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span>
                             </div>
                             <div className="text-left">
                                 <p className="text-xs font-bold text-white group-hover:text-primary transition-colors">{t.matches ? t.matches.length : 0} Jogos</p>
                                 <p className="text-[10px] text-gray-400">Ver Resultados &rarr;</p>
                             </div>
                         </div>
                         <span className="text-xs font-bold text-primary bg-primary/10 px-2 py-1 rounded">{t.duration}h</span>
                     </button>
                 ))}
                 {filteredHistory.length === 0 && <p className="text-xs text-center text-gray-500">Sem histórico.</p>}
             </div>
        </section>
    </div>
  );
};

