const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);

  // New States
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);

  // History State
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([
      { 
          id: 'old-1', 
          date: '2023-10-15', 
          time: '19:00', 
          duration: 2, 
          locationId: '1', 
          confirmedPlayerIds: ['1','2','3','4','5','6','7','8'], 
          status: 'finished', 
          matches: [
              { id: 'm1', team1: [MOCK_PLAYERS[0], MOCK_PLAYERS[1]], team2: [MOCK_PLAYERS[2], MOCK_PLAYERS[3]], score1: 6, score2: 2, court: 1, status: 'finished', round: 1, date: '2023-10-15T19:00:00Z' },
              { id: 'm2', team1: [MOCK_PLAYERS[4], MOCK_PLAYERS[5]], team2: [MOCK_PLAYERS[6], MOCK_PLAYERS[7]], score1: 4, score2: 6, court: 2, status: 'finished', round: 1, date: '2023-10-15T19:00:00Z' },
              { id: 'm3', team1: [MOCK_PLAYERS[0], MOCK_PLAYERS[1]], team2: [MOCK_PLAYERS[6], MOCK_PLAYERS[7]], score1: 5, score2: 7, court: 1, status: 'finished', round: 2, date: '2023-10-15T19:30:00Z' }
          ] 
      }
  ]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const handleStartTournament = (generatedMatches: Match[]) => {
    // Add date to live matches for tracking
    const stampedMatches = generatedMatches.map(m => ({ ...m, date: new Date().toISOString() }));
    setMatches(stampedMatches);
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();

    // Mark current round matches as finished
    const updatedMatches = matches.map(m => 
        m.round === currentRound ? { ...m, status: 'finished' as const } : m
    );

    if (currentRound === 1) {
        // Logic: Winners stay on court, Losers swap courts
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const matchC1 = r1Matches.find(m => m.court === 1)!;
        const matchC2 = r1Matches.find(m => m.court === 2)!;

        // Determine winners and losers
        const winnerC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const loserC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winnerC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const loserC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        // Generate Round 2 Matches
        const round2Matches: Match[] = [
            {
                id: `match-r2-1-${Date.now()}`,
                team1: winnerC1,
                team2: loserC2,
                score1: 0,
                score2: 0,
                court: 1,
                status: 'live',
                round: 2,
                date: timestamp
            },
            {
                id: `match-r2-2-${Date.now()}`,
                team1: winnerC2,
                team2: loserC1,
                score1: 0,
                score2: 0,
                court: 2,
                status: 'live',
                round: 2,
                date: timestamp
            }
        ];

        setMatches([...updatedMatches, ...round2Matches]);
        setCurrentRound(2);
    } 
    else if (currentRound === 2) {
        // Round 3 logic
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const teams = [
            r1Matches[0].team1,
            r1Matches[0].team2,
            r1Matches[1].team1,
            r1Matches[1].team2,
        ];

        const played = new Set<string>();
        updatedMatches.forEach(m => {
             const t1Id = m.team1[0].id; 
             const t2Id = m.team2[0].id;
             const key = [t1Id, t2Id].sort().join('-');
             played.add(key);
        });

        const newMatches: Match[] = [];
        const usedTeams = new Set<string>();

        for (let i = 0; i < teams.length; i++) {
             const t1 = teams[i];
             const t1Key = t1[0].id;
             if (usedTeams.has(t1Key)) continue;

             for (let j = i + 1; j < teams.length; j++) {
                 const t2 = teams[j];
                 const t2Key = t2[0].id;
                 if (usedTeams.has(t2Key)) continue;

                 const pairKey = [t1Key, t2Key].sort().join('-');

                 if (!played.has(pairKey)) {
                     newMatches.push({
                         id: `match-r3-${newMatches.length + 1}-${Date.now()}`,
                         team1: t1,
                         team2: t2,
                         score1: 0,
                         score2: 0,
                         court: newMatches.length + 1,
                         status: 'live',
                         round: 3,
                         date: timestamp
                     });
                     usedTeams.add(t1Key);
                     usedTeams.add(t2Key);
                     break; 
                 }
             }
        }

        setMatches([...updatedMatches, ...newMatches]);
        setCurrentRound(3);
    }
    else {
        // Just update status if finishing after round 3 (though usually handled by finish button)
        setMatches(updatedMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        // Force all matches to finished status
        const finalMatches = matches.map(m => ({ ...m, status: 'finished' as const }));

        const finishedTournament: Tournament = {
            ...activeTournament,
            status: 'finished',
            matches: finalMatches 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdatePlayer = (updatedPlayer: Player) => {
    setPlayers(prev => prev.map(p => p.id === updatedPlayer.id ? updatedPlayer : p));
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  const handleViewHistory = (tournament: Tournament) => {
    setSelectedHistoryTournament(tournament);
    setScreen(Screen.HISTORY_DETAIL);
  };

  const handleViewPlayer = (playerId: string) => {
      setSelectedPlayerId(playerId);
      setScreen(Screen.PROFILE);
  };

  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
      case Screen.PROFILE:
        return (
            <ProfileScreen 
                playerId={selectedPlayerId} 
                players={players}
                history={tournamentHistory}
                currentMatches={matches}
                setScreen={setScreen}
            />
        );
      case Screen.LIVE_GAME:
        return (
            <LiveGameScreen 
                setScreen={setScreen} 
                matches={matches.filter(m => m.round === currentRound)} 
                updateMatchScore={updateMatchScore}
                onNextRound={handleNextRound}
                currentRound={currentRound}
            />
        );
      case Screen.TOURNAMENT_SUMMARY:
          return (
              <TournamentSummaryScreen 
                  setScreen={setScreen}
                  matches={matches}
                  updateMatchScore={updateMatchScore}
                  onFinish={handleFinishTournament}
              />
          );
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return (
            <GlobalStatsScreen 
                history={tournamentHistory} 
                players={players} 
                onViewTournament={handleViewHistory} 
                locations={locations}
            />
        );
      case Screen.HISTORY_DETAIL:
        if (!selectedHistoryTournament) return <GlobalStatsScreen history={tournamentHistory} players={players} />;
        return <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} />;
      case Screen.TEAM_SETUP:
        return (
            <TeamSetupScreen 
                setScreen={setScreen} 
                players={getConfirmedPlayers()} 
                onStartTournament={handleStartTournament} 
            />
        );
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} players={players} onPlayerClick={handleViewPlayer} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default:
        return (
          <HomeScreen 
            setScreen={setScreen} 
            activeTournament={activeTournament}
            players={players}
            locations={locations}
            onCreateTournament={handleCreateTournament}
            onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament}
            history={tournamentHistory}
          />
        );
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {/* Header - Simple generic header for sub-screens that don't have their own */}
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP && currentScreen !== Screen.TOURNAMENT_SUMMARY && currentScreen !== Screen.HISTORY_DETAIL) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? `Ronda ${currentRound}` : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados Finais' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
               {currentScreen === Screen.PROFILE ? 'Perfil de Jogador' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {/* Special Header for Team Setup */}
        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               Definir Equipas
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}

        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Screen, Tournament, Match, Player, Location } from '../types';

interface HistoryDetailProps {
  setScreen: (screen: Screen) => void;
  tournament: Tournament;
  locations: Location[];
}

export const HistoryDetailScreen: React.FC<HistoryDetailProps> = ({ setScreen, tournament, locations }) => {
  const matches = tournament.matches || [];
  const locationName = locations.find(l => l.id === tournament.locationId)?.name || 'Local Desconhecido';

  // --- Calculate Standings Logic (Reused) ---
  const standings = useMemo(() => {
    const stats = new Map<string, { 
        id: string,
        teamName: string, 
        wins: number, 
        pointsDiff: number 
    }>();

    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) {
            stats.set(key, {
                id: key,
                teamName: team.map(p => p.nickname || p.name.split(' ')[0]).join(' & '),
                wins: 0,
                pointsDiff: 0
            });
        }
        return stats.get(key)!;
    };

    matches.forEach(m => {
        const stats1 = getStats(m.team1);
        const stats2 = getStats(m.team2);

        stats1.pointsDiff += (m.score1 - m.score2);
        stats2.pointsDiff += (m.score2 - m.score1);

        if (m.score1 > m.score2) stats1.wins += 1;
        else if (m.score2 > m.score1) stats2.wins += 1;
    });

    return Array.from(stats.values()).sort((a, b) => {
        if (b.wins !== a.wins) return b.wins - a.wins;
        return b.pointsDiff - a.pointsDiff;
    });
  }, [matches]);

  // Fix: Explicitly type sort parameters as numbers to resolve TS error on line 53
  const rounds = Array.from(new Set(matches.map(m => m.round))).sort((a: number, b: number) => a - b);

  return (
    <div className="flex-1 flex flex-col gap-6 p-4 pb-24 animate-fade-in bg-background-dark min-h-screen relative z-20">
        <header className="flex items-center justify-between sticky top-0 bg-background-dark/95 backdrop-blur-md py-2 z-30">
            <button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                <span className="material-symbols-outlined text-white">arrow_back</span>
            </button>
            <div className="flex flex-col items-center">
                <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">{new Date(tournament.date).toLocaleDateString()}</span>
                <h2 className="text-sm font-bold text-white max-w-[200px] truncate">{locationName}</h2>
            </div>
            <div className="w-10"></div>
        </header>

        {/* Podium / Winner */}
        {standings.length > 0 && (
            <div className="bg-surface-dark rounded-2xl p-4 border border-white/5 shadow-lg">
                <h3 className="text-center text-xs font-bold text-primary uppercase tracking-wider mb-4">Classificação Final</h3>
                <div className="flex flex-col gap-2">
                    {standings.slice(0, 3).map((team, idx) => (
                        <div key={idx} className="flex items-center justify-between p-2 rounded-lg bg-white/5">
                            <div className="flex items-center gap-3">
                                <div className={`size-6 rounded-full flex items-center justify-center text-xs font-bold ${
                                    idx === 0 ? 'bg-yellow-500 text-black' : 
                                    idx === 1 ? 'bg-gray-400 text-black' : 
                                    'bg-orange-700 text-white'
                                }`}>
                                    {idx + 1}
                                </div>
                                <span className="text-sm font-bold text-white">{team.teamName}</span>
                            </div>
                            <div className="text-xs font-medium text-gray-400">
                                {team.wins}V <span className={team.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}>({team.pointsDiff > 0 ? '+' : ''}{team.pointsDiff})</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* Match History List */}
        <div className="space-y-6">
            {rounds.map(round => (
                <div key={round}>
                    <div className="flex items-center gap-2 mb-3 px-1">
                        <div className="h-px flex-1 bg-white/10"></div>
                        <span className="text-xs font-bold text-gray-500 uppercase">Ronda {round}</span>
                        <div className="h-px flex-1 bg-white/10"></div>
                    </div>
                    <div className="flex flex-col gap-3">
                        {matches.filter(m => m.round === round).map(match => (
                            <div key={match.id} className="bg-card-dark rounded-xl border border-white/5 p-3 flex flex-col gap-2">
                                <div className="flex justify-between items-center text-[10px] text-gray-500 uppercase font-bold tracking-wider mb-1">
                                    <span>Campo {match.court}</span>
                                    {match.score1 > match.score2 ? (
                                        <span className="text-primary">Vitória Equipa 1</span>
                                    ) : match.score2 > match.score1 ? (
                                        <span className="text-purple-400">Vitória Equipa 2</span>
                                    ) : <span>Empate</span>}
                                </div>

                                <div className="flex items-center justify-between">
                                    {/* Team 1 */}
                                    <div className="flex items-center gap-2 flex-1 overflow-hidden">
                                        <div className="flex -space-x-2 shrink-0">
                                            {match.team1.map(p => (
                                                <img key={p.id} src={p.image} className="w-6 h-6 rounded-full border border-card-dark object-cover opacity-80" />
                                            ))}
                                        </div>
                                        <span className={`text-xs font-bold truncate ${match.score1 > match.score2 ? 'text-white' : 'text-gray-400'}`}>
                                            {match.team1.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                        </span>
                                    </div>

                                    {/* Score */}
                                    <div className="flex items-center gap-2 px-3">
                                        <span className={`text-lg font-bold ${match.score1 > match.score2 ? 'text-primary' : 'text-gray-500'}`}>{match.score1}</span>
                                        <span className="text-gray-600">-</span>
                                        <span className={`text-lg font-bold ${match.score2 > match.score1 ? 'text-purple-400' : 'text-gray-500'}`}>{match.score2}</span>
                                    </div>

                                    {/* Team 2 */}
                                    <div className="flex items-center gap-2 flex-1 justify-end overflow-hidden">
                                        <span className={`text-xs font-bold truncate ${match.score2 > match.score1 ? 'text-white' : 'text-gray-400'}`}>
                                            {match.team2.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                        </span>
                                        <div className="flex -space-x-2 shrink-0">
                                            {match.team2.map(p => (
                                                <img key={p.id} src={p.image} className="w-6 h-6 rounded-full border border-card-dark object-cover opacity-80" />
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  // Guest Creation State
  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  // New Tournament Form State
  const [date, setDate] = useState('');
  const [time, setTime] = useState('19:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  // Stats Calculation
  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  // Find Favorite Location
  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);
    if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: `https://ui-avatars.com/api/?name=${encodeURIComponent(guestNickname || guestName)}&background=random&color=fff&bold=true`
    };

    // Add to global list
    onAddPlayer(newPlayer);

    // Auto-confirm in active tournament
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }

    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled'
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  // --- SUB-VIEW: CREATION ---
  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>

            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>

                <div className="space-y-2">
                    <div className="flex justify-between">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label>
                        <span className="text-xs font-bold text-primary">{duration}h</span>
                    </div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>

                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>

                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button 
                                key={p.id} 
                                onClick={() => togglePlayerInForm(p.id)}
                                className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}
                            >
                                <img src={p.image} className="size-8 rounded-full object-cover mb-1" />
                                <span className="text-[9px] font-bold truncate w-full text-center">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  // --- SUB-VIEW: ACTIVE TOURNAMENT DASHBOARD ---
  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const isReady = confirmedCount === 8;
    const confirmedPlayers = activeTournament.confirmedPlayerIds
        .map(id => players.find(p => p.id === id))
        .filter((p): p is Player => p !== undefined);

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {/* Player Management Modal Overlay */}
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark/95 backdrop-blur-md p-4 animate-fade-in flex flex-col">
                    <header className="flex items-center justify-between mb-4">
                        <h2 className="text-xl font-bold">Gestão de Confirmados</h2>
                        <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center">
                            <span className="material-symbols-outlined">close</span>
                        </button>
                    </header>

                    {isAddingGuest ? (
                        <div className="bg-primary/10 border border-primary/30 p-4 rounded-2xl mb-4 animate-fade-in-up">
                            <h3 className="text-xs font-bold text-primary uppercase mb-3">Novo Convidado</h3>
                            <div className="space-y-3">
                                <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <input type="text" placeholder="Alcunha" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <div className="flex gap-2">
                                    <button onClick={() => setIsAddingGuest(false)} className="flex-1 py-2 text-gray-400 font-bold text-xs uppercase">Cancelar</button>
                                    <button onClick={handleSaveGuest} className="flex-1 py-2 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase">Guardar e Confirmar</button>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex gap-2 mb-4">
                            <div className="relative flex-1">
                                <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">search</span>
                                <input type="text" placeholder="Pesquisar..." value={playerSearchTerm} onChange={(e) => setPlayerSearchTerm(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white" />
                            </div>
                            <button onClick={() => setIsAddingGuest(true)} className="bg-primary/20 text-primary border border-primary/30 px-4 rounded-xl flex items-center justify-center">
                                <span className="material-symbols-outlined text-sm">person_add</span>
                            </button>
                        </div>
                    )}

                    <div className="grid grid-cols-4 gap-3 overflow-y-auto pb-24">
                        {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                            const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                            return (
                                <button key={p.id} onClick={() => togglePlayerInActiveTournament(p.id)} className={`flex flex-col items-center p-2 rounded-2xl border transition-all ${isConfirmed ? 'bg-primary/20 border-primary scale-105' : 'bg-card-dark border-white/5 opacity-50'}`}>
                                    <div className="relative mb-1">
                                        <img src={p.image} className="size-10 rounded-full object-cover" />
                                        {isConfirmed && <div className="absolute -bottom-1 -right-1 bg-primary text-black rounded-full p-0.5 border border-background-dark"><span className="material-symbols-outlined text-[10px] font-bold block">check</span></div>}
                                    </div>
                                    <span className="text-[9px] font-bold truncate w-full text-center">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            );
                        })}
                    </div>
                    <div className="fixed bottom-6 left-4 right-4 max-w-md mx-auto">
                        <button onClick={() => setIsManagingPlayers(false)} className={`w-full font-bold py-4 rounded-2xl shadow-xl transition-all ${isReady ? 'bg-emerald-500 text-background-dark' : 'bg-primary text-background-dark'}`}>
                            Concluído ({confirmedCount}/8)
                        </button>
                    </div>
                </div>
            )}

            <header>
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-slate-400">Próxima sessão confirmada.</p>
            </header>

            {/* Main Active Tournament Card */}
            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isReady ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isReady ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-primary/20 text-primary border-primary/30'}`}>
                                    {isReady ? 'QUÓRUM ATINGIDO' : 'A AGUARDAR CONFIRMAÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isReady ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">sports_tennis</span>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isReady ? 'text-emerald-400' : 'text-white'}`}>
                                {isReady ? 'TUDO PRONTO' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isReady ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            <button onClick={() => setScreen(Screen.TEAM_SETUP)} disabled={!isReady} className={`w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all ${isReady ? 'bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100' : 'bg-white/5 text-gray-600 border border-white/5 opacity-50 cursor-not-allowed'}`}>
                <span className="material-symbols-outlined">casino</span>
                <span>Realizar Sorteio de Equipas</span>
            </button>

            {/* Confirmed Players Grid */}
            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Gerir Todos</button>
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            <img src={p.image} className={`size-14 rounded-full object-cover border-2 ${isReady ? 'border-emerald-500 shadow-lg' : 'border-white/10'}`} />
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => setIsManagingPlayers(true)} className="flex flex-col items-center gap-2">
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all">
                                 <span className="material-symbols-outlined text-gray-700">person_add</span>
                            </div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={() => onUpdateTournament(null as any)} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 text-center mt-6">Remover agendamento atual</button>
        </div>
    );
  }

  // --- SUB-VIEW: EMPTY DASHBOARD (STATS & HISTORY) ---
  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1>
                <p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p>
            </div>
            <button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all">
                <span className="material-symbols-outlined font-bold">add</span>
            </button>
        </header>

        {/* Global Stats Overview */}
        <section className="grid grid-cols-3 gap-3">
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
                <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
                <span className="text-xl font-bold text-white">{totalGames}</span>
                <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
            </div>
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
                <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
                <span className="text-xl font-bold text-white">{totalHours}h</span>
                <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
            </div>
            <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden">
                <span className="material-symbols-outlined text-emerald-400 mb-1">star</span>
                <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
                <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
            </div>
        </section>

        {/* Create Tournament CTA */}
        <button 
            onClick={initCreation} 
            className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"
        >
            <div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500">
                <span className="material-symbols-outlined text-6xl">event_available</span>
            </div>
            <span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span>
            <span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span>
            <span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span>
        </button>

        {/* Tournament History (Last 5) */}
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1">
                <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3>
                <button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button>
            </div>

            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button 
                        key={t.id} 
                        onClick={() => setScreen(Screen.GLOBAL_STATS)} // Should ideally go to detail
