import React, { useMemo, useState } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
}

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, currentMatches, setScreen }) => {
  const [dateFilter, setDateFilter] = useState<'all' | '30' | '90' | 'year'>('all');
  const player = players.find(p => p.id === playerId);

  // -- ADVANCED STATS ENGINE --
  const stats = useMemo(() => {
    if (!playerId) return null;

    const now = new Date();
    const filterDays = dateFilter === '30' ? 30 : dateFilter === '90' ? 90 : dateFilter === 'year' ? 365 : Infinity;

    // Helper to check if tournament is within filter
    const isWithinFilter = (dateStr: string) => {
        if (filterDays === Infinity) return true;
        const d = new Date(dateStr);
        const diff = (now.getTime() - d.getTime()) / (1000 * 3600 * 24);
        return diff <= filterDays;
    };

    // Global counters
    let wins = 0;
    let losses = 0;
    let gamesPlayed = 0;
    let totalPointsScored = 0;
    let totalPointsConceded = 0;
    let tournamentsParticipated = 0;
    let tournamentsWon = 0;

    // Streak logic
    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let currentTournamentWinStreak = 0;
    let maxTournamentWinStreak = 0;
    let currentDrySpell = 0;
    let maxDrySpell = 0;

    // Specialty logic
    let clutchGames = 0; // diff <= 2
    let blowoutGames = 0; // diff >= 6

    // Partner tracking
    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number }>();

    // Chronological tracking for trends
    const chronologicalTournaments = [...history].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // 1. Process Tournaments for Streaks and Participation
    chronologicalTournaments.forEach(t => {
        if (!isWithinFilter(t.date)) return;

        const playerInTournament = t.matches?.some(m => 
            m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)
        );

        if (playerInTournament) {
            tournamentsParticipated++;

            // Calculate Tournament Winner
            const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
            const getTeamKey = (team: Player[]) => team.map(p => p.id).sort().join('-');

            t.matches?.forEach(m => {
                const key1 = getTeamKey(m.team1);
                const key2 = getTeamKey(m.team2);
                if (!teamStats.has(key1)) teamStats.set(key1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
                if (!teamStats.has(key2)) teamStats.set(key2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });
                const s1 = teamStats.get(key1)!;
                const s2 = teamStats.get(key2)!;
                s1.diff += (m.score1 - m.score2);
                s2.diff += (m.score2 - m.score1);
                if (m.score1 > m.score2) s1.wins++;
                else if (m.score2 > m.score1) s2.wins++;
            });

            const standings = Array.from(teamStats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
            const wonTournament = standings.length > 0 && standings[0].playerIds.includes(playerId);

            if (wonTournament) {
                tournamentsWon++;
                currentTournamentWinStreak++;
                maxTournamentWinStreak = Math.max(maxTournamentWinStreak, currentTournamentWinStreak);
                currentDrySpell = 0;
            } else {
                currentTournamentWinStreak = 0;
                currentDrySpell++;
                maxDrySpell = Math.max(maxDrySpell, currentDrySpell);
            }
        }
    });

    // 2. Process Individual Matches
    const allMatches: (Match & { date: string })[] = [];
    history.forEach(t => {
        if (t.matches && isWithinFilter(t.date)) {
            t.matches.forEach(m => {
                if (m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)) {
                    allMatches.push({ ...m, date: t.date });
                }
            });
        }
    });

    // Sort for trend graph
    const trendMatches = [...allMatches]
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
        .slice(-12);

    allMatches.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()).forEach(m => {
        if (m.status === 'finished') {
            const inTeam1 = m.team1.some(p => p.id === playerId);
            const myScore = inTeam1 ? m.score1 : m.score2;
            const oppScore = inTeam1 ? m.score2 : m.score1;
            const diff = Math.abs(myScore - oppScore);
            const won = myScore > oppScore;

            gamesPlayed++;
            totalPointsScored += myScore;
            totalPointsConceded += oppScore;

            if (won) {
                wins++;
                currentWinStreak++;
                maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
            } else {
                losses++;
                currentWinStreak = 0;
            }

            if (diff <= 2 && diff > 0) clutchGames++;
