            // Matches Logic
            tMatches.forEach(m => {
                const matchWithDate = { ...m, date: t.date, locationName: locName };
                myMatches.push(matchWithDate);

                const inTeam1 = m.team1.some(p => p.id === playerId);
                const myScore = inTeam1 ? m.score1 : m.score2;
                const oppScore = inTeam1 ? m.score2 : m.score1;
                const won = myScore > oppScore;
                const diff = Math.abs(myScore - oppScore);

                if (won) myWonMatches.push(matchWithDate);
                if (diff > 0 && diff <= 2) myClutchMatches.push(matchWithDate);
                if (diff >= 6) myBlowoutMatches.push(matchWithDate);

                // Partners
                const myTeam = inTeam1 ? m.team1 : m.team2;
                myTeam.forEach(p => {
                    if (p.id === playerId) return;
                    if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matchIds: [] });
                    const pd = partners.get(p.id)!;
                    pd.games++;
                    pd.matchIds.push(m.id);
                    if (won) pd.wins++;
                });

                // Rivals
                const oppTeam = inTeam1 ? m.team2 : m.team1;
                oppTeam.forEach(p => {
                    if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matchIds: [] });
                    const rd = rivals.get(p.id)!;
                    rd.games++;
                    rd.matchIds.push(m.id);
                    if (won) rd.winsAgainst++;
                    else rd.lossesAgainst++;
                });
            });
        }
    });

    const partnerArr = Array.from(partners.values()).sort((a, b) => b.games - a.games);
    const topRivals = Array.from(rivals.values()).sort((a, b) => b.lossesAgainst - a.lossesAgainst || b.games - a.games);
    const victims = Array.from(rivals.values()).sort((a, b) => b.winsAgainst - a.winsAgainst || b.games - a.games);

    return {
        myTournaments,
        myWonTournaments,
        myMatches,
        myWonMatches,
        myClutchMatches,
        myBlowoutMatches,
        partnerArr,
        topRivals: topRivals.slice(0, 5),
        victims: victims.slice(0, 5),
        pointsScored: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score1 : m.score2), 0),
        pointsConceded: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score2 : m.score1), 0),
    };
  }, [playerId, history, dateFilter]);

  if (!player || !stats) return null;

  const renderDrillDown = () => {
      if (!drillDown) return null;
      return (
          <div className="fixed inset-0 z-[100] bg-background-dark/95 backdrop-blur-xl animate-fade-in flex flex-col p-4">
              <header className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold">{drillDown.title}</h2>
                  <button onClick={() => setDrillDown(null)} className="size-10 rounded-full bg-white/5 flex items-center justify-center">
                      <span className="material-symbols-outlined">close</span>
                  </button>
              </header>

              <div className="flex-1 overflow-y-auto space-y-3 pb-20">
                  {drillDown.type === 'matches' ? (
                      drillDown.items.map((m: any) => (
                          <div key={m.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col gap-2">
                              <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase">
                                  <span>{new Date(m.date).toLocaleDateString()}</span>
                                  <span>Ronda {m.round}</span>
                              </div>
                              <div className="flex items-center justify-between">
                                  <div className="flex-1 text-xs font-bold text-white truncate">
                                      {m.team1.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}
                                  </div>
                                  <div className="flex items-center gap-2 px-4">
                                      <span className={`text-lg font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-500'}`}>{m.score1}</span>
                                      <span className="text-gray-700">-</span>
                                      <span className={`text-lg font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-500'}`}>{m.score2}</span>
                                  </div>
                                  <div className="flex-1 text-right text-xs font-bold text-white truncate">
                                      {m.team2.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}
                                  </div>
                              </div>
                          </div>
                      ))
                  ) : (
                      drillDown.items.map((t: any) => (
                        <div key={t.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex justify-between items-center">
                            <div>
                                <p className="text-sm font-bold text-white">{new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                                <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">{t.matches?.length || 0} Jogos realizados</p>
                            </div>
                            <span className="material-symbols-outlined text-primary">chevron_right</span>
                        </div>
                      ))
                  )}
              </div>
          </div>
      );
  };

  return (
    <div className="flex flex-col gap-6 pb-28 animate-fade-in bg-background-dark min-h-screen">
      {renderDrillDown()}

      {/* Header Profile */}
      <header className="px-4 pt-6 flex flex-col items-center">
        <div className="relative size-24 mb-4">
          <img src={player.image} className="size-full rounded-full object-cover border-4 border-card-dark shadow-xl" />
          <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark text-[10px] font-black px-2 py-0.5 rounded-md border-2 border-background-dark">
             {player.level.toUpperCase()}
          </div>
        </div>
        <h1 className="text-2xl font-black text-white">{player.nickname || player.name}</h1>
        <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest mt-1">{player.name} {player.lastName}</p>
      </header>

      {/* Tabs & Filters */}
      <div className="px-4 space-y-4">
          <div className="flex bg-card-dark/50 p-1 rounded-xl border border-white/5">
              {[
                  { id: 'overview', label: 'Geral' },
                  { id: 'tournaments', label: 'Torneios' },
                  { id: 'matches', label: 'Jogos' },
                  { id: 'relations', label: 'Relações' }
              ].map(tab => (
                  <button 
                    key={tab.id} 
                    onClick={() => setActiveTab(tab.id as TabType)}
                    className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${activeTab === tab.id ? 'bg-primary text-background-dark shadow-lg' : 'text-gray-500 hover:text-white'}`}
                  >
                      {tab.label}
                  </button>
              ))}
          </div>

          <div className="flex gap-2">
              {['all', '30', '90', 'year'].map(f => (
                  <button 
                    key={f} 
                    onClick={() => setDateFilter(f as any)}
                    className={`flex-1 py-1.5 text-[9px] font-bold rounded-lg border transition-all ${dateFilter === f ? 'bg-white/10 text-white border-white/20' : 'text-gray-600 border-transparent'}`}
                  >
                      {f === 'all' ? 'TUDO' : f === '30' ? '30 DIAS' : f === '90' ? '90 DIAS' : 'ANO'}
                  </button>
              ))}
          </div>
      </div>

      <div className="px-4 space-y-6">
          {/* TAB: OVERVIEW */}
          {activeTab === 'overview' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-2 gap-3">
                      <button onClick={() => setDrillDown({ title: 'Histórico de Jogos', type: 'matches', items: stats.myMatches })} className="bg-card-dark p-5 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-3xl font-black text-white">{stats.myMatches.length}</span>
                          <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest">Jogos Totais</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Torneios Ganhos', type: 'tournaments', items: stats.myWonTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-3xl font-black text-yellow-500">{stats.myWonTournaments.length}</span>
                          <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest">Títulos</span>
                      </button>
                  </div>

                  <div className="bg-card-dark p-5 rounded-3xl border border-white/5">
                      <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Última Tendência</h3>
                      <div className="flex gap-2 h-16 items-end">
                          {stats.myMatches.slice(-10).map((m, i) => {
                              const won = stats.myWonMatches.some(wm => wm.id === m.id);
                              return (
                                  <div key={i} className={`flex-1 rounded-t-lg transition-all ${won ? 'bg-primary shadow-[0_0_10px_rgba(96,122,251,0.3)]' : 'bg-red-500/20'}`} style={{ height: won ? '100%' : '40%' }}></div>
                              );
                          })}
                      </div>
                  </div>
              </div>
          )}

          {/* TAB: TOURNAMENTS */}
          {activeTab === 'tournaments' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setDrillDown({ title: 'Participações', type: 'tournaments', items: stats.myTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Participações</span>
                        <span className="text-2xl font-black text-white">{stats.myTournaments.length}</span>
                    </button>
                    <button onClick={() => setDrillDown({ title: 'Vitórias em Torneios', type: 'tournaments', items: stats.myWonTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Vitórias</span>
                        <span className="text-2xl font-black text-primary">{stats.myWonTournaments.length}</span>
                    </button>
                  </div>

                  <div className="bg-card-dark rounded-2xl p-5 border border-white/5 divide-y divide-white/5">
                      <div className="py-3 flex justify-between items-center">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Win Rate Eventos</span>
                          <span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? Math.round((stats.myWonTournaments.length / stats.myTournaments.length) * 100) : 0}%</span>
                      </div>
                      <div className="py-3 flex justify-between items-center">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Média Jogos/Torneio</span>
                          <span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? (stats.myMatches.length / stats.myTournaments.length).toFixed(1) : 0}</span>
                      </div>
                  </div>
              </div>
          )}

          {/* TAB: MATCHES */}
          {activeTab === 'matches' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-3 gap-3">
                      <button onClick={() => setDrillDown({ title: 'Vitórias Individuais', type: 'matches', items: stats.myWonMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-primary">{stats.myWonMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Jogos Disputados', type: 'matches', items: stats.myClutchMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-purple-400">{stats.myClutchMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Disputados</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Domínio Total', type: 'matches', items: stats.myBlowoutMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-emerald-400">{stats.myBlowoutMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Blowouts</span>
                      </button>
                  </div>

                  <div className="bg-card-dark p-6 rounded-3xl border border-white/5 flex items-end justify-around h-32">
                        <div className="flex flex-col items-center gap-2">
                            <div className="w-12 bg-primary rounded-t-lg" style={{ height: `${Math.max(20, (stats.pointsScored / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-xs font-black text-white">{stats.pointsScored}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Marcados</span>
                        </div>
                        <div className="flex flex-col items-center gap-2">
                            <div className="w-12 bg-red-500/30 rounded-t-lg" style={{ height: `${Math.max(20, (stats.pointsConceded / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-xs font-black text-white">{stats.pointsConceded}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Sofridos</span>
                        </div>
                  </div>
              </div>
          )}

          {/* TAB: RELATIONS (Partners & Rivals) */}
          {activeTab === 'relations' && (
              <div className="space-y-6 animate-fade-in">
                  {/* Partners Section */}
                  <section>
                      <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-3 ml-1">Parceiros Frequentes</h3>
                      <div className="space-y-2">
                          {stats.partnerArr.slice(0, 3).map(p => (
                              <div key={p.id} className="bg-card-dark p-3 rounded-2xl border border-white/5 flex items-center justify-between">
                                  <div className="flex items-center gap-3">
                                      <img src={p.image} className="size-8 rounded-full border border-white/10" />
                                      <span className="text-sm font-bold text-white">{p.name}</span>
                                  </div>
                                  <div className="flex items-center gap-4">
                                      <div className="text-right">
                                          <p className="text-[10px] font-black text-white">{p.games} Jogos</p>
                                          <p className="text-[8px] text-primary uppercase font-bold">{Math.round((p.wins / p.games) * 100)}% Win Rate</p>
                                      </div>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </section>

                  {/* Rivals Section */}
                  <section className="grid grid-cols-1 gap-6">
                      <div>
                          <h3 className="text-[10px] font-bold text-emerald-500 uppercase tracking-widest mb-3 ml-1">Fregueses (Mais Vitórias Contra)</h3>
                          <div className="space-y-2">
                              {stats.victims.filter(v => v.winsAgainst > 0).map(r => (
                                  <div key={r.id} className="bg-emerald-500/5 p-3 rounded-2xl border border-emerald-500/10 flex items-center justify-between">
                                      <div className="flex items-center gap-3">
                                          <img src={r.image} className="size-8 rounded-full" />
                                          <span className="text-sm font-bold text-white">{r.name}</span>
                                      </div>
                                      <span className="text-xs font-black text-emerald-400">{r.winsAgainst} V</span>
                                  </div>
                              ))}
                          </div>
                      </div>

                      <div>
                          <h3 className="text-[10px] font-bold text-red-500 uppercase tracking-widest mb-3 ml-1">Bestas Negras (Mais Derrotas Contra)</h3>
                          <div className="space-y-2">
                              {stats.topRivals.filter(r => r.lossesAgainst > 0).map(r => (
                                  <div key={r.id} className="bg-red-500/5 p-3 rounded-2xl border border-red-500/10 flex items-center justify-between">
                                      <div className="flex items-center gap-3">
                                          <img src={r.image} className="size-8 rounded-full grayscale" />
                                          <span className="text-sm font-bold text-white">{r.name}</span>
                                      </div>
                                      <span className="text-xs font-black text-red-400">{r.lossesAgainst} D</span>
                                  </div>
                              ))}
                          </div>
                      </div>
                  </section>
              </div>
          )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
}

type TabType = 'overview' | 'tournaments' | 'matches' | 'relations';

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, currentMatches, setScreen }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [dateFilter, setDateFilter] = useState<'all' | '30' | '90' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);

  const player = players.find(p => p.id === playerId);

  // -- ADVANCED STATS ENGINE --
  const stats = useMemo(() => {
    if (!playerId) return null;

    const now = new Date();
    const filterDays = dateFilter === '30' ? 30 : dateFilter === '90' ? 90 : dateFilter === 'year' ? 365 : Infinity;

    const isWithinFilter = (dateStr: string) => {
        if (filterDays === Infinity) return true;
        const d = new Date(dateStr);
        const diff = (now.getTime() - d.getTime()) / (1000 * 3600 * 24);
        return diff <= filterDays;
    };

    // Data containers for Drill-down
    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];
    const myMatches: (Match & { date: string })[] = [];
    const myWonMatches: (Match & { date: string })[] = [];
    const myLostMatches: (Match & { date: string })[] = [];
    const myClutchMatches: (Match & { date: string })[] = [];
    const myBlowoutMatches: (Match & { date: string })[] = [];

    // Partner & Rival tracking
    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number, matches: any[] }>();
    const rivals = new Map<string, { id: string, name: string, image: string, winsAgainst: number, lossesAgainst: number, games: number, matches: any[] }>();

    // Streaks
    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let currentTWinStreak = 0;
    let maxTWinStreak = 0;

    // 1. Process History chronologically for streaks
    const chronologicalHistory = [...history].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    chronologicalHistory.forEach(t => {
        const withinFilter = isWithinFilter(t.date);

        const tMatches = t.matches?.filter(m => 
            m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)
        ) || [];

        if (tMatches.length > 0) {
            if (withinFilter) myTournaments.push(t);

            // Tournament Standing Calculation
            const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
                if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });
                const s1 = teamStats.get(k1)!;
                const s2 = teamStats.get(k2)!;
                s1.diff += (m.score1 - m.score2);
                s2.diff += (m.score2 - m.score1);
                if (m.score1 > m.score2) s1.wins++;
                else if (m.score2 > m.score1) s2.wins++;
            });

            const standings = Array.from(teamStats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
            const wonTournament = standings.length > 0 && standings[0].playerIds.includes(playerId);

            if (wonTournament) {
                if (withinFilter) myWonTournaments.push(t);
                currentTWinStreak++;
                maxTWinStreak = Math.max(maxTWinStreak, currentTWinStreak);
            } else {
                currentTWinStreak = 0;
            }

            // Individual Matches Processing
            tMatches.forEach(m => {
                const matchWithDate = { ...m, date: t.date };
                const inTeam1 = m.team1.some(p => p.id === playerId);
                const myScore = inTeam1 ? m.score1 : m.score2;
                const oppScore = inTeam1 ? m.score2 : m.score1;
                const won = myScore > oppScore;
                const diff = Math.abs(myScore - oppScore);

                if (withinFilter) {
                    myMatches.push(matchWithDate);
                    if (won) {
                        myWonMatches.push(matchWithDate);
                        currentWinStreak++;
                        maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
                    } else {
                        myLostMatches.push(matchWithDate);
                        currentWinStreak = 0;
                    }
                    if (diff > 0 && diff <= 2) myClutchMatches.push(matchWithDate);
                    if (diff >= 6) myBlowoutMatches.push(matchWithDate);

                    // Partners Analysis
                    const myTeam = inTeam1 ? m.team1 : m.team2;
                    myTeam.forEach(p => {
                        if (p.id === playerId) return;
                        if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                        const pd = partners.get(p.id)!;
                        pd.games++;
                        pd.matches.push(matchWithDate);
                        if (won) pd.wins++;
                    });

                    // Rivals Analysis
                    const oppTeam = inTeam1 ? m.team2 : m.team1;
                    oppTeam.forEach(p => {
                        if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                        const rd = rivals.get(p.id)!;
                        rd.games++;
                        rd.matches.push(matchWithDate);
                        if (won) rd.winsAgainst++;
                        else rd.lossesAgainst++;
                    });
                }
            });
        }
    });

    const partnerArr = Array.from(partners.values()).sort((a, b) => b.games - a.games);
    const topRivals = Array.from(rivals.values()).sort((a, b) => b.lossesAgainst - a.lossesAgainst || b.games - a.games);
    const victims = Array.from(rivals.values()).sort((a, b) => b.winsAgainst - a.winsAgainst || b.games - a.games);

    return {
        myTournaments,
        myWonTournaments,
        myMatches,
        myWonMatches,
        myLostMatches,
        myClutchMatches,
        myBlowoutMatches,
        partnerArr,
        topRivals: topRivals.slice(0, 8),
        victims: victims.slice(0, 8),
        pointsScored: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score1 : m.score2), 0),
        pointsConceded: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score2 : m.score1), 0),
        maxWinStreak,
        maxTWinStreak
    };
  }, [playerId, history, dateFilter]);

  if (!player || !stats) return null;

  const renderDrillDown = () => {
      if (!drillDown) return null;
      return (
          <div className="fixed inset-0 z-[100] bg-background-dark/95 backdrop-blur-xl animate-fade-in flex flex-col p-4">
              <header className="flex items-center justify-between mb-6">
                  <div>
                    <h2 className="text-xl font-bold">{drillDown.title}</h2>
                    <p className="text-[10px] text-gray-500 uppercase tracking-widest font-bold">{drillDown.items.length} Entradas Encontradas</p>
                  </div>
