                      </div>
                      <div className="flex gap-1.5 h-16 items-end">
                          {stats.myMatches.slice(-12).map((m, i) => {
                              const won = stats.myWonMatches.some(wm => wm.id === m.id);
                              return (
                                  <div 
                                    key={i} 
                                    onClick={() => setDrillDown({ title: 'Detalhe do Jogo', type: 'matches', items: [m] })}
                                    className={`flex-1 rounded-t-lg cursor-pointer transition-all hover:opacity-80 ${won ? 'bg-primary shadow-[0_0_10px_rgba(96,122,251,0.3)]' : 'bg-red-500/20'}`} 
                                    style={{ height: won ? '100%' : '40%' }}
                                  ></div>
                              );
                          })}
                      </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div className="bg-surface-dark border border-white/5 p-4 rounded-2xl flex items-center gap-3">
                        <span className="material-symbols-outlined text-primary text-xl">local_fire_department</span>
                        <div>
                            <p className="text-xs font-black text-white">{stats.maxWinStreak} Jogos</p>
                            <p className="text-[8px] text-gray-500 uppercase font-bold">Best Win Streak</p>
                        </div>
                    </div>
                    <div className="bg-surface-dark border border-white/5 p-4 rounded-2xl flex items-center gap-3">
                        <span className="material-symbols-outlined text-yellow-500 text-xl">military_tech</span>
                        <div>
                            <p className="text-xs font-black text-white">{stats.maxTWinStreak} Torneios</p>
                            <p className="text-[8px] text-gray-500 uppercase font-bold">Best Title Streak</p>
                        </div>
                    </div>
                  </div>
              </div>
          )}

          {/* TAB: TOURNAMENTS */}
          {activeTab === 'tournaments' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setDrillDown({ title: 'Todas as Participações', type: 'tournaments', items: stats.myTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left group">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Presenças</span>
                        <div className="flex items-baseline gap-1">
                            <span className="text-2xl font-black text-white group-hover:text-primary transition-colors">{stats.myTournaments.length}</span>
                            <span className="text-[10px] text-gray-600">Eventos</span>
                        </div>
                    </button>
                    <button onClick={() => setDrillDown({ title: 'Palmarés de Vitórias', type: 'tournaments', items: stats.myWonTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left group">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Vitórias</span>
                        <div className="flex items-baseline gap-1">
                            <span className="text-2xl font-black text-yellow-500 group-hover:scale-105 transition-transform">{stats.myWonTournaments.length}</span>
                            <span className="text-[10px] text-gray-600">Títulos</span>
                        </div>
                    </button>
                  </div>

                  <div className="bg-card-dark rounded-2xl p-5 border border-white/5 divide-y divide-white/5">
                      <div className="py-3 flex justify-between items-center group">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Eficiência em Torneios</span>
                          <span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? Math.round((stats.myWonTournaments.length / stats.myTournaments.length) * 100) : 0}%</span>
                      </div>
                      <div className="py-3 flex justify-between items-center">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Média de Jogos / Evento</span>
                          <span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? (stats.myMatches.length / stats.myTournaments.length).toFixed(1) : 0}</span>
                      </div>
                  </div>
              </div>
          )}

          {/* TAB: MATCHES */}
          {activeTab === 'matches' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-3 gap-2">
                      <button onClick={() => setDrillDown({ title: 'Vitórias Detalhadas', type: 'matches', items: stats.myWonMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors">
                          <span className="text-xl font-black text-primary">{stats.myWonMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Jogos Disputados (Clutch)', type: 'matches', items: stats.myClutchMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors">
                          <span className="text-xl font-black text-purple-400">{stats.myClutchMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Disputados</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Esmagamentos (Blowouts)', type: 'matches', items: stats.myBlowoutMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors">
                          <span className="text-xl font-black text-emerald-400">{stats.myBlowoutMatches.length}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Blowouts</span>
                      </button>
                  </div>

                  <div className="bg-card-dark p-6 rounded-3xl border border-white/5 flex items-end justify-around h-36 relative overflow-hidden">
                        <div className="absolute top-0 left-0 right-0 p-3 flex justify-center">
                            <span className="text-[9px] font-black text-gray-600 uppercase tracking-[0.2em]">Diferencial de Pontos</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 group cursor-pointer" onClick={() => setDrillDown({ title: 'Pontos Marcados', type: 'matches', items: stats.myMatches })}>
                            <div className="w-12 bg-primary rounded-t-lg group-hover:bg-primary-dark transition-colors shadow-lg" style={{ height: `${Math.max(20, (stats.pointsScored / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-sm font-black text-white">{stats.pointsScored}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Marcados</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 group cursor-pointer" onClick={() => setDrillDown({ title: 'Pontos Sofridos', type: 'matches', items: stats.myMatches })}>
                            <div className="w-12 bg-red-500/20 rounded-t-lg group-hover:bg-red-500/40 transition-colors" style={{ height: `${Math.max(20, (stats.pointsConceded / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-sm font-black text-white">{stats.pointsConceded}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Sofridos</span>
                        </div>
                  </div>
              </div>
          )}

          {/* TAB: RELATIONS (Partners & Rivals) */}
          {activeTab === 'relations' && (
              <div className="space-y-6 animate-fade-in">
                  {/* Partners Section */}
                  <section>
                      <div className="flex items-center justify-between mb-4 px-1">
                        <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Parceiros Principais</h3>
                        <span className="text-[9px] text-primary font-bold">TOP FREQUÊNCIA</span>
                      </div>
                      <div className="flex flex-col gap-2">
                          {stats.partnerArr.slice(0, 4).map(p => (
                              <button 
                                key={p.id} 
                                onClick={() => setDrillDown({ title: `Jogos com ${p.name}`, type: 'matches', items: p.matches })}
                                className="bg-card-dark p-3 rounded-2xl border border-white/5 flex items-center justify-between group active:scale-[0.98] transition-all"
                              >
                                  <div className="flex items-center gap-3">
                                      {renderAvatar(p, 'size-9')}
                                      <div className="text-left">
                                        <span className="text-xs font-black text-white block">{p.name}</span>
                                        <span className="text-[9px] text-gray-500 font-bold uppercase">{p.games} Partidas Juntas</span>
                                      </div>
                                  </div>
                                  <div className="flex items-center gap-4">
                                      <div className="text-right">
                                          <p className="text-[10px] font-black text-white">{p.wins} Vitórias</p>
                                          <p className="text-[9px] text-primary uppercase font-bold">{Math.round((p.wins / p.games) * 100)}% Win Rate</p>
                                      </div>
                                      <span className="material-symbols-outlined text-gray-700 text-sm">chevron_right</span>
                                  </div>
                              </button>
                          ))}
                          {stats.partnerArr.length === 0 && <p className="text-[10px] text-gray-600 italic text-center py-4">Sem parceiros registados.</p>}
                      </div>
                  </section>

                  {/* Rivals Section (Head-to-Head) */}
                  <section className="space-y-6">
                      <div>
                          <h3 className="text-[10px] font-bold text-emerald-500 uppercase tracking-widest mb-3 ml-1">Fregueses (Onde Mais Ganha)</h3>
                          <div className="grid grid-cols-2 gap-2">
                              {stats.victims.filter(v => v.winsAgainst > 0).map(r => (
                                  <button 
                                    key={r.id} 
                                    onClick={() => setDrillDown({ title: `Vitórias contra ${r.name}`, type: 'matches', items: r.matches.filter(m => {
                                        const inTeam1 = m.team1.some((p: any) => p.id === playerId);
                                        return (inTeam1 ? m.score1 : m.score2) > (inTeam1 ? m.score2 : m.score1);
                                    }) })}
                                    className="bg-emerald-500/5 p-3 rounded-xl border border-emerald-500/10 flex items-center justify-between group active:scale-95 transition-all"
                                  >
                                      <div className="flex items-center gap-2 truncate">
                                          {renderAvatar(r, 'size-6')}
                                          <span className="text-[10px] font-black text-white truncate">{r.name.split(' ')[0]}</span>
                                      </div>
                                      <span className="text-[11px] font-black text-emerald-400">{r.winsAgainst}V</span>
                                  </button>
                              ))}
                          </div>
                      </div>

                      <div>
                          <h3 className="text-[10px] font-bold text-red-500 uppercase tracking-widest mb-3 ml-1">Bestas Negras (Onde Mais Perde)</h3>
                          <div className="grid grid-cols-2 gap-2">
                              {stats.topRivals.filter(r => r.lossesAgainst > 0).map(r => (
                                  <button 
                                    key={r.id} 
                                    onClick={() => setDrillDown({ title: `Derrotas contra ${r.name}`, type: 'matches', items: r.matches.filter(m => {
                                        const inTeam1 = m.team1.some((p: any) => p.id === playerId);
                                        return (inTeam1 ? m.score1 : m.score2) < (inTeam1 ? m.score2 : m.score1);
                                    }) })}
                                    className="bg-red-500/5 p-3 rounded-xl border border-red-500/10 flex items-center justify-between group active:scale-95 transition-all"
                                  >
                                      <div className="flex items-center gap-2 truncate">
                                          {renderAvatar(r, 'size-6')}
                                          <span className="text-[10px] font-black text-white truncate">{r.name.split(' ')[0]}</span>
                                      </div>
                                      <span className="text-[11px] font-black text-red-400">{r.lossesAgainst}D</span>
                                  </button>
                              ))}
                          </div>
                      </div>
                  </section>
              </div>
          )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
}

type TabType = 'overview' | 'tournaments' | 'matches' | 'relations';

const getColorForId = (id: string) => {
  const colors = [
    'bg-blue-500', 'bg-emerald-500', 'bg-purple-500', 'bg-orange-500', 
    'bg-rose-500', 'bg-cyan-500', 'bg-amber-500', 'bg-indigo-500'
  ];
  const index = Math.abs(id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)) % colors.length;
  return colors[index];
};

export const renderGlobalAvatar = (p: { id: string, image?: string }, sizeClass: string = 'size-10') => {
  const usePlaceholder = !p.image || p.image.includes('ui-avatars.com') || p.image.includes('googleusercontent.com') || p.image === '';

  if (usePlaceholder) {
      return (
          <div className={`${sizeClass} rounded-full ${getColorForId(p.id)} flex items-center justify-center border-2 border-white/10 text-white shadow-inner shrink-0`}>
              <span className="material-symbols-outlined text-[0.6em] select-none" style={{ fontSize: '1.5em' }}>person</span>
          </div>
      );
  }
  return <img src={p.image} className={`${sizeClass} rounded-full object-cover border-2 border-white/10 shadow-md shrink-0`} alt="Avatar" />;
};

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, currentMatches, setScreen }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [dateFilter, setDateFilter] = useState<'all' | '30' | '90' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);

  const player = players.find(p => p.id === playerId);

  const stats = useMemo(() => {
    if (!playerId) return null;
    const now = new Date();
    const filterDays = dateFilter === '30' ? 30 : dateFilter === '90' ? 90 : dateFilter === 'year' ? 365 : Infinity;

    const isWithinFilter = (dateStr: string) => {
        if (filterDays === Infinity) return true;
        const d = new Date(dateStr);
        const diff = (now.getTime() - d.getTime()) / (1000 * 3600 * 24);
        return diff <= filterDays;
    };

    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];
    const myMatches: (Match & { date: string })[] = [];
    const myWonMatches: (Match & { date: string })[] = [];
    const myLostMatches: (Match & { date: string })[] = [];
    const myClutchMatches: (Match & { date: string })[] = [];
    const myBlowoutMatches: (Match & { date: string })[] = [];

    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number, matches: any[] }>();
    const rivals = new Map<string, { id: string, name: string, image: string, winsAgainst: number, lossesAgainst: number, games: number, matches: any[] }>();

    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let currentTWinStreak = 0;
    let maxTWinStreak = 0;

    const chronologicalHistory = [...history].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    chronologicalHistory.forEach(t => {
        const withinFilter = isWithinFilter(t.date);
        const tMatches = t.matches?.filter(m => 
            m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)
        ) || [];

        if (tMatches.length > 0) {
            if (withinFilter) myTournaments.push(t);
            const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
                if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });
                const s1 = teamStats.get(k1)!;
                const s2 = teamStats.get(k2)!;
                s1.diff += (m.score1 - m.score2);
                s2.diff += (m.score2 - m.score1);
                if (m.score1 > m.score2) s1.wins++;
                else if (m.score2 > m.score1) s2.wins++;
            });
            const standings = Array.from(teamStats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
            const wonTournament = standings.length > 0 && standings[0].playerIds.includes(playerId);

            if (wonTournament) {
                if (withinFilter) myWonTournaments.push(t);
                currentTWinStreak++;
                maxTWinStreak = Math.max(maxTWinStreak, currentTWinStreak);
            } else {
                currentTWinStreak = 0;
            }

            tMatches.forEach(m => {
                const matchWithDate = { ...m, date: t.date };
                const inTeam1 = m.team1.some(p => p.id === playerId);
                const myScore = inTeam1 ? m.score1 : m.score2;
                const oppScore = inTeam1 ? m.score2 : m.score1;
                const won = myScore > oppScore;
                const diff = Math.abs(myScore - oppScore);

                if (withinFilter) {
                    myMatches.push(matchWithDate);
                    if (won) {
                        myWonMatches.push(matchWithDate);
                        currentWinStreak++;
                        maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
                    } else {
                        myLostMatches.push(matchWithDate);
                        currentWinStreak = 0;
                    }
                    if (diff > 0 && diff <= 2) myClutchMatches.push(matchWithDate);
                    if (diff >= 6) myBlowoutMatches.push(matchWithDate);
                    const myTeam = inTeam1 ? m.team1 : m.team2;
                    myTeam.forEach(p => {
                        if (p.id === playerId) return;
                        if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                        const pd = partners.get(p.id)!;
                        pd.games++;
                        pd.matches.push(matchWithDate);
                        if (won) pd.wins++;
                    });
                    const oppTeam = inTeam1 ? m.team2 : m.team1;
                    oppTeam.forEach(p => {
                        if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                        const rd = rivals.get(p.id)!;
                        rd.games++;
                        rd.matches.push(matchWithDate);
                        if (won) rd.winsAgainst++;
                        else rd.lossesAgainst++;
                    });
                }
            });
        }
    });

    const partnerArr = Array.from(partners.values()).sort((a, b) => b.games - a.games);
    return {
        myTournaments, myWonTournaments, myMatches, myWonMatches, myLostMatches, myClutchMatches, myBlowoutMatches,
        partnerArr, topRivals: Array.from(rivals.values()).sort((a, b) => b.lossesAgainst - a.lossesAgainst).slice(0, 8),
        victims: Array.from(rivals.values()).sort((a, b) => b.winsAgainst - a.winsAgainst).slice(0, 8),
        pointsScored: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score1 : m.score2), 0),
        pointsConceded: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score2 : m.score1), 0),
        maxWinStreak, maxTWinStreak
    };
  }, [playerId, history, dateFilter]);

  if (!player || !stats) return null;

  const renderDrillDown = () => {
      if (!drillDown) return null;
      return (
          <div className="fixed inset-0 z-[100] bg-background-dark/95 backdrop-blur-xl animate-fade-in flex flex-col p-4">
              <header className="flex items-center justify-between mb-6">
                  <div>
                    <h2 className="text-xl font-bold">{drillDown.title}</h2>
                    <p className="text-[10px] text-gray-500 uppercase tracking-widest font-bold">{drillDown.items.length} Entradas</p>
                  </div>
                  <button onClick={() => setDrillDown(null)} className="size-10 rounded-full bg-white/5 flex items-center justify-center">
                      <span className="material-symbols-outlined">close</span>
                  </button>
              </header>
              <div className="flex-1 overflow-y-auto space-y-3 pb-24 pr-1 hide-scrollbar">
                  {drillDown.type === 'matches' ? (
                      drillDown.items.map((m: any, idx: number) => {
                          const inTeam1 = m.team1.some((p: any) => p.id === playerId);
                          const won = (inTeam1 ? m.score1 : m.score2) > (inTeam1 ? m.score2 : m.score1);
                          return (
                            <div key={m.id + idx} className={`bg-card-dark p-4 rounded-2xl border ${won ? 'border-primary/20' : 'border-white/5'} flex flex-col gap-2 relative overflow-hidden shadow-sm`}>
                                {won && <div className="absolute top-0 right-0 p-1"><span className="material-symbols-outlined text-primary text-xs">check_circle</span></div>}
                                <div className="flex justify-between text-[9px] font-bold text-gray-500 uppercase">
                                    <span>{new Date(m.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'short' })}</span>
                                    <span>Ronda {m.round}</span>
                                </div>
                                <div className="flex items-center justify-between gap-4">
                                    <div className="flex-1 text-[11px] font-bold text-white truncate text-right">
                                        {m.team1.map((p: any) => p.nickname || p.name.split(' ')[0]).join(' / ')}
                                    </div>
                                    <div className="flex items-center gap-2 px-3 py-1 bg-background-dark rounded-lg">
                                        <span className={`text-sm font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-500'}`}>{m.score1}</span>
                                        <span className="text-gray-700 font-bold">-</span>
                                        <span className={`text-sm font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-500'}`}>{m.score2}</span>
                                    </div>
                                    <div className="flex-1 text-[11px] font-bold text-white truncate text-left">
                                        {m.team2.map((p: any) => p.nickname || p.name.split(' ')[0]).join(' / ')}
                                    </div>
                                </div>
                            </div>
                          );
                      })
                  ) : (
                      drillDown.items.map((t: any) => (
                        <div key={t.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex justify-between items-center group active:scale-[0.98] transition-all">
                            <div>
                                <p className="text-sm font-bold text-white">{new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                                <p className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">{t.matches?.length || 0} Jogos realizados</p>
                            </div>
                            <span className="material-symbols-outlined text-primary group-hover:translate-x-1 transition-transform">chevron_right</span>
                        </div>
                      ))
                  )}
              </div>
          </div>
      );
  };

  return (
    <div className="flex flex-col gap-6 pb-28 animate-fade-in bg-background-dark min-h-screen">
      {renderDrillDown()}
      <header className="px-4 pt-8 flex flex-col items-center">
        <div className="relative mb-4">
          <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-110"></div>
          {renderGlobalAvatar(player, 'size-24')}
          <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark text-[10px] font-black px-2 py-0.5 rounded-md border-2 border-background-dark shadow-lg">
             {player.level.toUpperCase()}
          </div>
        </div>
        <h1 className="text-2xl font-black text-white leading-tight">{player.nickname || player.name}</h1>
        <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest mt-1">{player.name} {player.lastName}</p>
        <div className="flex gap-2 mt-4">
            <span className="text-[9px] font-black bg-white/5 border border-white/10 px-3 py-1 rounded-full text-gray-400 uppercase">MAO: {player.hand || 'Destro'}</span>
            <span className="text-[9px] font-black bg-primary/10 border border-primary/20 px-3 py-1 rounded-full text-primary uppercase">NIVEL: {player.level}</span>
        </div>
      </header>
      <div className="px-4 space-y-4">
          <div className="flex bg-card-dark/50 p-1 rounded-xl border border-white/5">
              {[
                  { id: 'overview', label: 'Geral', icon: 'dashboard' },
                  { id: 'tournaments', label: 'Torneios', icon: 'emoji_events' },
                  { id: 'matches', label: 'Jogos', icon: 'sports_tennis' },
                  { id: 'relations', label: 'Relações', icon: 'groups' }
              ].map(tab => (
                  <button 
                    key={tab.id} 
                    onClick={() => setActiveTab(tab.id as TabType)}
                    className={`flex-1 py-2 flex flex-col items-center gap-0.5 rounded-lg transition-all ${activeTab === tab.id ? 'bg-primary text-background-dark shadow-lg' : 'text-gray-500 hover:text-white'}`}
                  >
                      <span className="material-symbols-outlined text-sm">{tab.icon}</span>
                      <span className="text-[8px] font-black uppercase tracking-tighter">{tab.label}</span>
                  </button>
              ))}
          </div>
          <div className="flex gap-2">
              {[ { id: 'all', label: 'TUDO' }, { id: '30', label: '30D' }, { id: '90', label: '90D' }, { id: 'year', label: 'ANO' } ].map(f => (
                  <button 
                    key={f.id} 
                    onClick={() => setDateFilter(f.id as any)}
                    className={`flex-1 py-1.5 text-[9px] font-bold rounded-lg border transition-all ${dateFilter === f.id ? 'bg-white/10 text-white border-white/20' : 'text-gray-600 border-transparent'}`}
                  >
                      {f.label}
                  </button>
              ))}
          </div>
      </div>
      <div className="px-4 space-y-6">
          {activeTab === 'overview' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-2 gap-3">
                      <button onClick={() => setDrillDown({ title: 'Resumo de Jogos', type: 'matches', items: stats.myMatches })} className="bg-card-dark p-5 rounded-2xl border border-white/5 flex flex-col items-center group active:scale-95 transition-all">
                          <span className="text-3xl font-black text-white group-hover:text-primary">{stats.myMatches.length}</span>
                          <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest">Jogos Totais</span>
                      </button>
                      <button onClick={() => setDrillDown({ title: 'Resumo de Títulos', type: 'tournaments', items: stats.myWonTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 flex flex-col items-center group active:scale-95 transition-all">
                          <span className="text-3xl font-black text-yellow-500 group-hover:scale-110 transition-transform">{stats.myWonTournaments.length}</span>
                          <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest">Títulos</span>
                      </button>
                  </div>
                  <div className="bg-card-dark p-5 rounded-3xl border border-white/5">
                      <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Últimas 12 Partidas</h3>
                      <div className="flex gap-1.5 h-16 items-end">
                          {stats.myMatches.slice(-12).map((m, i) => {
                              const won = stats.myWonMatches.some(wm => wm.id === m.id);
                              return (
                                  <div 
                                    key={i} 
                                    onClick={() => setDrillDown({ title: 'Detalhe do Jogo', type: 'matches', items: [m] })}
                                    className={`flex-1 rounded-t-lg cursor-pointer transition-all hover:opacity-80 ${won ? 'bg-primary shadow-[0_0_10px_rgba(96,122,251,0.3)]' : 'bg-red-500/20'}`} 
                                    style={{ height: won ? '100%' : '40%' }}
                                  ></div>
                              );
                          })}
                      </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="bg-surface-dark border border-white/5 p-4 rounded-2xl flex items-center gap-3">
                        <span className="material-symbols-outlined text-primary text-xl">local_fire_department</span>
                        <div><p className="text-xs font-black text-white">{stats.maxWinStreak} Jogos</p><p className="text-[8px] text-gray-500 uppercase font-bold">Best Win Streak</p></div>
                    </div>
                    <div className="bg-surface-dark border border-white/5 p-4 rounded-2xl flex items-center gap-3">
                        <span className="material-symbols-outlined text-yellow-500 text-xl">military_tech</span>
                        <div><p className="text-xs font-black text-white">{stats.maxTWinStreak} Torneios</p><p className="text-[8px] text-gray-500 uppercase font-bold">Best Title Streak</p></div>
                    </div>
                  </div>
              </div>
          )}
          {activeTab === 'tournaments' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setDrillDown({ title: 'Todas as Participações', type: 'tournaments', items: stats.myTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left group">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Presenças</span>
                        <div className="flex items-baseline gap-1"><span className="text-2xl font-black text-white group-hover:text-primary transition-colors">{stats.myTournaments.length}</span><span className="text-[10px] text-gray-600">Eventos</span></div>
                    </button>
                    <button onClick={() => setDrillDown({ title: 'Palmarés de Vitórias', type: 'tournaments', items: stats.myWonTournaments })} className="bg-card-dark p-5 rounded-2xl border border-white/5 text-left group">
                        <span className="text-[9px] font-bold text-gray-500 uppercase block mb-1">Vitórias</span>
                        <div className="flex items-baseline gap-1"><span className="text-2xl font-black text-yellow-500 group-hover:scale-105 transition-transform">{stats.myWonTournaments.length}</span><span className="text-[10px] text-gray-600">Títulos</span></div>
                    </button>
                  </div>
                  <div className="bg-card-dark rounded-2xl p-5 border border-white/5 divide-y divide-white/5">
                      <div className="py-3 flex justify-between items-center group"><span className="text-[10px] font-bold text-gray-400 uppercase">Eficiência</span><span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? Math.round((stats.myWonTournaments.length / stats.myTournaments.length) * 100) : 0}%</span></div>
                      <div className="py-3 flex justify-between items-center"><span className="text-[10px] font-bold text-gray-400 uppercase">Média Jogos/Evento</span><span className="text-sm font-black text-white">{stats.myTournaments.length > 0 ? (stats.myMatches.length / stats.myTournaments.length).toFixed(1) : 0}</span></div>
                  </div>
              </div>
          )}
          {activeTab === 'matches' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-3 gap-2">
                      <button onClick={() => setDrillDown({ title: 'Vitórias Detalhadas', type: 'matches', items: stats.myWonMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors"><span className="text-xl font-black text-primary">{stats.myWonMatches.length}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span></button>
                      <button onClick={() => setDrillDown({ title: 'Jogos Disputados (Clutch)', type: 'matches', items: stats.myClutchMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors"><span className="text-xl font-black text-purple-400">{stats.myClutchMatches.length}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Clutch</span></button>
                      <button onClick={() => setDrillDown({ title: 'Blowouts', type: 'matches', items: stats.myBlowoutMatches })} className="bg-card-dark p-4 rounded-xl border border-white/5 flex flex-col items-center hover:bg-white/5 transition-colors"><span className="text-xl font-black text-emerald-400">{stats.myBlowoutMatches.length}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Blowouts</span></button>
                  </div>
                  <div className="bg-card-dark p-6 rounded-3xl border border-white/5 flex items-end justify-around h-36 relative overflow-hidden">
                        <div className="absolute top-0 left-0 right-0 p-3 flex justify-center"><span className="text-[9px] font-black text-gray-600 uppercase tracking-[0.2em]">Diferencial de Pontos</span></div>
                        <div className="flex flex-col items-center gap-2 group cursor-pointer" onClick={() => setDrillDown({ title: 'Pontos Marcados', type: 'matches', items: stats.myMatches })}>
                            <div className="w-12 bg-primary rounded-t-lg group-hover:bg-primary-dark transition-colors shadow-lg" style={{ height: `${Math.max(20, (stats.pointsScored / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-sm font-black text-white">{stats.pointsScored}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Marcados</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 group cursor-pointer" onClick={() => setDrillDown({ title: 'Pontos Sofridos', type: 'matches', items: stats.myMatches })}>
                            <div className="w-12 bg-red-500/20 rounded-t-lg group-hover:bg-red-500/40 transition-colors" style={{ height: `${Math.max(20, (stats.pointsConceded / (stats.pointsScored + stats.pointsConceded)) * 100)}%` }}></div>
                            <span className="text-sm font-black text-white">{stats.pointsConceded}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Sofridos</span>
                        </div>
                  </div>
              </div>
          )}
          {activeTab === 'relations' && (
              <div className="space-y-6 animate-fade-in">
                  <section>
                      <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-4 px-1">Parceiros Principais</h3>
                      <div className="flex flex-col gap-2">
                          {stats.partnerArr.slice(0, 4).map(p => (
                              <button key={p.id} onClick={() => setDrillDown({ title: `Jogos com ${p.name}`, type: 'matches', items: p.matches })} className="bg-card-dark p-3 rounded-2xl border border-white/5 flex items-center justify-between group active:scale-[0.98] transition-all">
                                  <div className="flex items-center gap-3">{renderGlobalAvatar(p, 'size-9')}<div className="text-left"><span className="text-xs font-black text-white block">{p.name}</span><span className="text-[9px] text-gray-500 font-bold uppercase">{p.games} Jogos</span></div></div>
                                  <div className="flex items-center gap-4"><div className="text-right"><p className="text-[10px] font-black text-white">{p.wins} V</p><p className="text-[9px] text-primary uppercase font-bold">{Math.round((p.wins / p.games) * 100)}% WR</p></div><span className="material-symbols-outlined text-gray-700 text-sm">chevron_right</span></div>
                              </button>
                          ))}
                      </div>
                  </section>
                  <section className="space-y-6">
                      <div>
                          <h3 className="text-[10px] font-bold text-emerald-500 uppercase tracking-widest mb-3 ml-1">Fregueses</h3>
                          <div className="grid grid-cols-2 gap-2">
                              {stats.victims.filter(v => v.winsAgainst > 0).map(r => (
                                  <button key={r.id} onClick={() => setDrillDown({ title: `Vitórias vs ${r.name}`, type: 'matches', items: r.matches.filter(m => {const inT1 = m.team1.some((p:any) => p.id === playerId); return (inT1 ? m.score1 : m.score2) > (inT1 ? m.score2 : m.score1); }) })} className="bg-emerald-500/5 p-3 rounded-xl border border-emerald-500/10 flex items-center justify-between group active:scale-95 transition-all">
                                      <div className="flex items-center gap-2 truncate">{renderGlobalAvatar(r, 'size-6')}<span className="text-[10px] font-black text-white truncate">{r.name.split(' ')[0]}</span></div><span className="text-[11px] font-black text-emerald-400">{r.winsAgainst}V</span>
                                  </button>
                              ))}
                          </div>
                      </div>
                      <div>
                          <h3 className="text-[10px] font-bold text-red-500 uppercase tracking-widest mb-3 ml-1">Bestas Negras</h3>
                          <div className="grid grid-cols-2 gap-2">
                              {stats.topRivals.filter(r => r.lossesAgainst > 0).map(r => (
                                  <button key={r.id} onClick={() => setDrillDown({ title: `Derrotas vs ${r.name}`, type: 'matches', items: r.matches.filter(m => {const inT1 = m.team1.some((p:any) => p.id === playerId); return (inT1 ? m.score1 : m.score2) < (inT1 ? m.score2 : m.score1); }) })} className="bg-red-500/5 p-3 rounded-xl border border-red-500/10 flex items-center justify-between group active:scale-95 transition-all">
                                      <div className="flex items-center gap-2 truncate">{renderGlobalAvatar(r, 'size-6')}<span className="text-[10px] font-black text-white truncate">{r.name.split(' ')[0]}</span></div><span className="text-[11px] font-black text-red-400">{r.lossesAgainst}D</span>
                                  </button>
                              ))}
                          </div>
                      </div>
                  </section>
              </div>
          )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('19:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);
    if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: '' // Will use placeholder
    };
    onAddPlayer(newPlayer);
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }
    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled'
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const isReady = confirmedCount === 8;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark/95 backdrop-blur-md p-4 animate-fade-in flex flex-col">
                    <header className="flex items-center justify-between mb-4"><h2 className="text-xl font-bold">Gestão de Confirmados</h2><button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button></header>
                    {isAddingGuest ? (
                        <div className="bg-primary/10 border border-primary/30 p-4 rounded-2xl mb-4 animate-fade-in-up">
                            <h3 className="text-xs font-bold text-primary uppercase mb-3">Novo Convidado</h3>
                            <div className="space-y-3">
                                <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <input type="text" placeholder="Alcunha" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <div className="flex gap-2"><button onClick={() => setIsAddingGuest(false)} className="flex-1 py-2 text-gray-400 font-bold text-xs uppercase">Cancelar</button><button onClick={handleSaveGuest} className="flex-1 py-2 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase">Guardar</button></div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex gap-2 mb-4">
                            <div className="relative flex-1"><span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">search</span><input type="text" placeholder="Pesquisar..." value={playerSearchTerm} onChange={(e) => setPlayerSearchTerm(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white" /></div>
                            <button onClick={() => setIsAddingGuest(true)} className="bg-primary/20 text-primary border border-primary/30 px-4 rounded-xl flex items-center justify-center"><span className="material-symbols-outlined text-sm">person_add</span></button>
                        </div>
                    )}
                    <div className="grid grid-cols-4 gap-3 overflow-y-auto pb-24 hide-scrollbar">
                        {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                            const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                            return (
                                <button key={p.id} onClick={() => togglePlayerInActiveTournament(p.id)} className={`flex flex-col items-center p-2 rounded-2xl border transition-all ${isConfirmed ? 'bg-primary/20 border-primary scale-105' : 'bg-card-dark border-white/5 opacity-50'}`}>
                                    <div className="relative mb-1">
                                        {renderGlobalAvatar(p, 'size-10')}
                                        {isConfirmed && <div className="absolute -bottom-1 -right-1 bg-primary text-black rounded-full p-0.5 border border-background-dark"><span className="material-symbols-outlined text-[10px] font-bold block">check</span></div>}
                                    </div>
                                    <span className="text-[9px] font-bold truncate w-full text-center">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            );
                        })}
                    </div>
                    <div className="fixed bottom-6 left-4 right-4 max-w-md mx-auto">
                        <button onClick={() => setIsManagingPlayers(false)} className={`w-full font-bold py-4 rounded-2xl shadow-xl transition-all ${isReady ? 'bg-emerald-500 text-background-dark' : 'bg-primary text-background-dark'}`}>Concluído ({confirmedCount}/8)</button>
                    </div>
                </div>
            )}
            <header><h1 className="text-3xl font-bold tracking-tight">Dashboard</h1><p className="text-slate-400">Próxima sessão confirmada.</p></header>
            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isReady ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div><div className="flex items-center gap-2 mb-2"><span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isReady ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-primary/20 text-primary border-primary/30'}`}>{isReady ? 'QUÓRUM ATINGIDO' : 'A AGUARDAR CONFIRMAÇÕES'}</span></div><h3 className="text-xl font-bold text-white mb-1">{locName}</h3><p className="text-slate-400 text-xs flex items-center gap-1.5"><span className="material-symbols-outlined text-sm">calendar_today</span>{new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}</p></div>
                        <div className={`p-2.5 rounded-xl border ${isReady ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}><span className="material-symbols-outlined text-2xl">sports_tennis</span></div>
                    </div>
                    <div className="space-y-2"><div className="flex justify-between items-end"><span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span><span className={`text-xs font-bold font-mono ${isReady ? 'text-emerald-400' : 'text-white'}`}>{isReady ? 'TUDO PRONTO' : `FALTAM ${8 - confirmedCount}`}</span></div><div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5"><div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isReady ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div></div></div>
                </div>
            </section>
            <button onClick={() => setScreen(Screen.TEAM_SETUP)} disabled={!isReady} className={`w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all ${isReady ? 'bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100' : 'bg-white/5 text-gray-600 border border-white/5 opacity-50 cursor-not-allowed'}`}><span className="material-symbols-outlined">casino</span><span>Realizar Sorteio de Equipas</span></button>
            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3><button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Gerir Todos</button></div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => setIsManagingPlayers(true)} className="flex flex-col items-center gap-2">
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>
            <button onClick={() => onUpdateTournament(null as any)} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 text-center mt-6">Remover agendamento atual</button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>
        <section className="grid grid-cols-3 gap-3"><div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm"><span className="material-symbols-outlined text-primary mb-1">sports_tennis</span><span className="text-xl font-bold text-white">{totalGames}</span><span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span></div><div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm"><span className="material-symbols-outlined text-purple-400 mb-1">schedule</span><span className="text-xl font-bold text-white">{totalHours}h</span><span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span></div><div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden"><span className="material-symbols-outlined text-emerald-400 mb-1">star</span><span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span><span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span></div></section>
        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React from 'react';
import { Screen, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface LiveGameScreenProps {
  setScreen: (screen: Screen) => void;
  matches: Match[];
  updateMatchScore: (matchId: string, team: 1 | 2, increment: boolean) => void;
  onNextRound: () => void;
  currentRound: number;
}

export const LiveGameScreen: React.FC<LiveGameScreenProps> = ({ 
    setScreen, 
    matches, 
    updateMatchScore, 
    onNextRound, 
    currentRound 
}) => {

  if (matches.length === 0) {
      return (
          <div className="flex flex-col items-center justify-center h-[60vh] px-6 text-center animate-fade-in">
              <span className="material-symbols-outlined text-6xl text-slate-600 mb-4">sports_tennis</span>
              <h2 className="text-xl font-bold text-white mb-2">Sem jogos ativos</h2>
              <p className="text-slate-400 mb-6">Configure as equipas primeiro para iniciar a primeira ronda.</p>
              <button 
                onClick={() => setScreen(Screen.TEAM_SETUP)}
                className="bg-primary text-background-dark font-bold py-3 px-6 rounded-xl hover:bg-primary/90 transition-colors"
              >
                  Configurar Equipas
              </button>
          </div>
      );
  }

  return (
    <div className="flex-1 flex flex-col gap-6 p-4 pb-32 max-w-md mx-auto w-full animate-fade-in">
      <div className="flex justify-center -mt-2 mb-2">
        <div className="flex items-center gap-2 px-3 py-1.5 bg-card-dark rounded-full border border-white/10">
            <span className="material-symbols-outlined text-primary text-sm animate-pulse">timer</span>
            <span className="font-mono font-medium text-sm tracking-wider">00:00:00</span>
        </div>
      </div>
      <div className="flex flex-col items-center justify-center py-2">
        <h2 className="text-3xl font-bold tracking-tight text-center uppercase text-white">Ronda {currentRound}</h2>
        <div className="h-1 w-12 bg-primary mt-2 rounded-full"></div>
      </div>
      <div className="flex flex-col gap-6">
      {matches.map((match) => (
        <article key={match.id} className="bg-card-dark rounded-2xl p-5 shadow-lg border border-white/5 relative overflow-hidden group">
            <div className={`absolute top-0 left-0 w-1.5 h-full ${match.court === 1 ? 'bg-primary' : 'bg-purple-500'}`}></div>
            <header className="flex items-center justify-between mb-6 pl-2">
                <h3 className="text-xl font-bold tracking-tight flex items-center gap-2"><span className={`material-symbols-outlined ${match.court === 1 ? 'text-primary' : 'text-purple-500'}`}>stadium</span>CAMPO {match.court}</h3>
                <span className="px-2 py-0.5 rounded text-xs font-bold bg-green-500/20 text-green-400 border border-green-500/20">EM JOGO</span>
            </header>
            <div className="space-y-6 pl-2">
                <div className="flex items-center justify-between gap-3">
                    <div className="flex flex-col flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                             <div className="flex -space-x-2">
                                {match.team1.map(p => (
                                    <div key={p.id}>{renderGlobalAvatar(p, 'size-6')}</div>
                                ))}
                             </div>
                        </div>
                        <span className="text-lg font-medium truncate leading-tight">{match.team1.map(p => p.nickname || p.name.split(' ')[0]).join(' / ')}</span>
                    </div>
                    <div className="flex items-center gap-3 shrink-0 bg-background-dark rounded-xl p-1.5 border border-white/5">
                        <button onClick={() => updateMatchScore(match.id, 1, false)} className="w-12 h-12 flex items-center justify-center rounded-lg bg-white/10 active:scale-95 transition-transform hover:bg-white/20"><span className="material-symbols-outlined text-2xl">remove</span></button>
                        <span className="w-10 text-center text-2xl font-bold">{match.score1}</span>
                        <button onClick={() => updateMatchScore(match.id, 1, true)} className={`w-12 h-12 flex items-center justify-center rounded-lg text-white active:scale-95 transition-transform shadow-md ${match.court === 1 ? 'bg-primary shadow-blue-900/20' : 'bg-purple-500 shadow-purple-900/20'}`}><span className="material-symbols-outlined text-2xl">add</span></button>
                    </div>
                </div>
                <div className="h-px w-full bg-white/5"></div>
                <div className="flex items-center justify-between gap-3">
                    <div className="flex flex-col flex-1 min-w-0">
                         <div className="flex items-center gap-2 mb-1">
                             <div className="flex -space-x-2">
                                {match.team2.map(p => (
                                    <div key={p.id}>{renderGlobalAvatar(p, 'size-6')}</div>
                                ))}
                             </div>
                        </div>
                        <span className="text-lg font-medium truncate leading-tight">{match.team2.map(p => p.nickname || p.name.split(' ')[0]).join(' / ')}</span>
                    </div>
                    <div className="flex items-center gap-3 shrink-0 bg-background-dark rounded-xl p-1.5 border border-white/5">
                        <button onClick={() => updateMatchScore(match.id, 2, false)} className="w-12 h-12 flex items-center justify-center rounded-lg bg-white/10 active:scale-95 transition-transform hover:bg-white/20"><span className="material-symbols-outlined text-2xl">remove</span></button>
                        <span className="w-10 text-center text-2xl font-bold">{match.score2}</span>
                         <button onClick={() => updateMatchScore(match.id, 2, true)} className={`w-12 h-12 flex items-center justify-center rounded-lg text-white active:scale-95 transition-transform shadow-md ${match.court === 1 ? 'bg-primary shadow-blue-900/20' : 'bg-purple-500 shadow-purple-900/20'}`}><span className="material-symbols-outlined text-2xl">add</span></button>
                    </div>
                </div>
            </div>
        </article>
      ))}
      </div>
       <button onClick={onNextRound} className="w-full bg-primary hover:bg-blue-600 text-white font-bold text-xl h-16 rounded-xl shadow-lg shadow-primary/30 active:scale-[0.98] transition-all flex items-center justify-center gap-3 mt-4">
          {currentRound < 3 ? (<><span className="material-symbols-outlined text-2xl">play_circle</span>SEGUINTE (RONDA {currentRound + 1})</>) : (<><span className="material-symbols-outlined text-2xl">assignment</span>VER RESUMO</>)}
      </button>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Screen, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  const [teamA, setTeamA] = useState<Player[]>([]);
  const [teamB, setTeamB] = useState<Player[]>([]);
  const [teamC, setTeamC] = useState<Player[]>([]);
  const [teamD, setTeamD] = useState<Player[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const [isDown, setIsDown] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [isDragging, setIsDragging] = useState(false);

  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  ).sort((a, b) => (a.nickname || a.name).localeCompare(b.nickname || b.name));

  const handlePlayerClick = (player: Player) => {
    if (isDragging) return;
    if (teamA.length < 2) setTeamA([...teamA, player]);
    else if (teamB.length < 2) setTeamB([...teamB, player]);
    else if (teamC.length < 2) setTeamC([...teamC, player]);
    else if (teamD.length < 2) setTeamD([...teamD, player]);
  };

  const removePlayer = (player: Player, team: 'A' | 'B' | 'C' | 'D') => {
    if (team === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (team === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (team === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (team === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleRandomizeAll = () => {
    const currentAssignedIds = new Set([...teamA.map(p => p.id), ...teamB.map(p => p.id), ...teamC.map(p => p.id), ...teamD.map(p => p.id)]);
    const pool = players.filter(p => !currentAssignedIds.has(p.id));
    const shuffled = [...pool].sort(() => 0.5 - Math.random());
    let poolIndex = 0;
    const newA = [...teamA]; while(newA.length < 2 && poolIndex < shuffled.length) newA.push(shuffled[poolIndex++]); setTeamA(newA);
    const newB = [...teamB]; while(newB.length < 2 && poolIndex < shuffled.length) newB.push(shuffled[poolIndex++]); setTeamB(newB);
    const newC = [...teamC]; while(newC.length < 2 && poolIndex < shuffled.length) newC.push(shuffled[poolIndex++]); setTeamC(newC);
    const newD = [...teamD]; while(newD.length < 2 && poolIndex < shuffled.length) newD.push(shuffled[poolIndex++]); setTeamD(newD);
  };

  const handleClearAll = () => { setTeamA([]); setTeamB([]); setTeamC([]); setTeamD([]); };

  const handleStart = () => {
    if (teamA.length !== 2 || teamB.length !== 2 || teamC.length !== 2 || teamD.length !== 2) return;
    const timestamp = Date.now();
    const dateStr = new Date().toISOString();
    const matches: Match[] = [
        { id: `match-1-${timestamp}`, team1: teamA, team2: teamB, score1: 0, score2: 0, court: 1, status: 'live', round: 1, date: dateStr },
        { id: `match-2-${timestamp}`, team1: teamC, team2: teamD, score1: 0, score2: 0, court: 2, status: 'live', round: 1, date: dateStr }
    ];
    onStartTournament(matches);
  };

  const handleMouseDown = (e: React.MouseEvent) => { if (!scrollRef.current) return; setIsDown(true); setIsDragging(false); setStartX(e.pageX - scrollRef.current.offsetLeft); setScrollLeft(scrollRef.current.scrollLeft); };
  const handleMouseLeave = () => { setIsDown(false); };
  const handleMouseUp = () => { setIsDown(false); setTimeout(() => setIsDragging(false), 50); };
  const handleMouseMove = (e: React.MouseEvent) => { if (!isDown || !scrollRef.current) return; e.preventDefault(); const x = e.pageX - scrollRef.current.offsetLeft; const walk = (x - startX) * 2; if (Math.abs(walk) > 5) { setIsDragging(true); scrollRef.current.scrollLeft = scrollLeft - walk; } };

  const renderTeamSlot = (team: Player[], teamName: string, teamId: 'A' | 'B' | 'C' | 'D', colorClass: string, ringColor: string) => (
    <div className="flex flex-col rounded-2xl bg-surface-dark p-3 shadow-sm border border-white/5">
        <div className="flex items-center justify-between mb-2"><div className="flex items-center gap-2"><div className={`h-6 w-1 ${colorClass} rounded-full`}></div><h3 className="text-sm font-bold text-white">Equipa {teamId}</h3></div><span className={`text-[10px] font-bold ${team.length === 2 ? 'text-green-400' : 'text-slate-500'}`}>{team.length}/2</span></div>
        <div className="grid grid-cols-2 gap-2">
            {[0, 1].map(index => {
                const player = team[index];
                return player ? (
                    <div key={player.id} className="relative flex flex-col items-center justify-center rounded-lg border border-white/10 bg-[#28392f] p-2 animate-fade-in-up">
                        <button onClick={() => removePlayer(player, teamId)} className="absolute -top-1 -right-1 rounded-full bg-surface-dark text-slate-400 hover:text-red-400 transition-colors p-0.5 border border-white/10 z-10"><span className="material-symbols-outlined text-[14px]">close</span></button>
                        <div className={`mb-1 ring-2 ${ringColor} rounded-full`}>{renderGlobalAvatar(player, 'size-8')}</div>
                        <span className="text-xs font-semibold text-center leading-tight truncate w-full text-white">{player.nickname || player.name}</span>
                    </div>
                ) : (
                    <div key={`empty-${teamId}-${index}`} className="flex h-[70px] flex-col items-center justify-center rounded-lg border border-dashed border-white/10 bg-black/20"><div className="flex h-6 w-6 items-center justify-center rounded-full bg-white/5 mb-1"><span className="material-symbols-outlined text-slate-600 text-[16px]">add</span></div></div>
                );
            })}
        </div>
    </div>
  );

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  return (
    <div className="relative flex h-full flex-col overflow-x-hidden pb-40 animate-fade-in">
       <div className="px-4 pt-4 pb-2"><p className="text-center text-[#9db9a8] text-xs font-normal leading-relaxed">Organize as 4 equipas para os 2 campos.</p></div>
      <div className="grid grid-cols-2 gap-3 px-4 mb-4"><button onClick={handleClearAll} className="flex items-center justify-center gap-2 bg-surface-dark border border-white/10 text-white py-2.5 rounded-xl text-xs font-bold active:scale-95 transition-all hover:bg-white/5"><span className="material-symbols-outlined text-sm">restart_alt</span>Limpar</button><button onClick={handleRandomizeAll} className="flex items-center justify-center gap-2 bg-primary/10 border border-primary/30 text-primary py-2.5 rounded-xl text-xs font-bold active:scale-95 transition-all hover:bg-primary/20"><span className="material-symbols-outlined text-sm">auto_fix_high</span>Preencher Auto</button></div>
      <div className="w-full px-4 mb-2">
        <div className="mb-2 flex items-center justify-between px-1"><h3 className="text-[10px] font-bold uppercase tracking-wider text-[#9db9a8]">Disponíveis ({availablePlayers.length})</h3><span className="text-[10px] text-slate-500 font-medium">Arraste &rarr;</span></div>
        <div ref={scrollRef} onMouseDown={handleMouseDown} onMouseLeave={handleMouseLeave} onMouseUp={handleMouseUp} onMouseMove={handleMouseMove} className="flex overflow-x-auto gap-2 p-2 bg-surface-dark rounded-xl border border-white/5 shadow-inner min-h-[60px] hide-scrollbar cursor-grab active:cursor-grabbing select-none">
            {availablePlayers.length === 0 && <p className="text-slate-600 text-xs w-full text-center py-2 flex items-center justify-center">Vazio</p>}
            {availablePlayers.map((p) => (
                <button key={p.id} onClick={() => handlePlayerClick(p)} className="flex-shrink-0 flex flex-col items-center justify-center gap-1 w-14 active:scale-95 transition-all">
                    <div className="pointer-events-none">{renderGlobalAvatar(p, 'size-8')}</div>
                    <p className="text-white text-[10px] font-medium leading-none truncate w-full text-center pointer-events-none">{p.nickname || p.name.split(' ')[0]}</p>
                </button>
            ))}
        </div>
      </div>
      <div className="flex flex-col gap-4 px-4 mt-2">
        <div className="space-y-2"><div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold text-primary uppercase tracking-wider flex items-center gap-1"><span className="material-symbols-outlined text-sm">stadium</span> Campo 1</h3><span className="text-[10px] text-slate-500">Jogo 1</span></div><div className="grid grid-cols-2 gap-2">{renderTeamSlot(teamA, 'Equipa A', 'A', 'bg-primary', 'ring-primary/30')}{renderTeamSlot(teamB, 'Equipa B', 'B', 'bg-blue-400', 'ring-blue-400/30')}</div></div>
        <div className="space-y-2 pb-4"><div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1"><span className="material-symbols-outlined text-sm">stadium</span> Campo 2</h3><span className="text-[10px] text-slate-500">Jogo 2</span></div><div className="grid grid-cols-2 gap-2">{renderTeamSlot(teamC, 'Equipa C', 'C', 'bg-purple-500', 'ring-purple-500/30')}{renderTeamSlot(teamD, 'Equipa D', 'D', 'bg-orange-400', 'ring-orange-400/30')}</div></div>
      </div>
      <div className="fixed bottom-16 left-0 right-0 z-30 bg-[#102217]/90 backdrop-blur-xl border-t border-white/5 px-4 pt-4 pb-8 max-w-md mx-auto"><button onClick={handleStart} disabled={!isReady} className={`group w-full rounded-xl font-bold text-base py-4 shadow-lg transition-all flex items-center justify-center gap-2 ${isReady ? 'bg-primary text-background-dark cursor-pointer' : 'bg-gray-700 text-gray-500 cursor-not-allowed'}`}><span>Iniciar Torneio</span><span className="material-symbols-outlined">sports_tennis</span></button></div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
}

interface PlayerStats {
  id: string;
  name: string;
  image: string;
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  pointsDiff: number;
  tournamentsPlayed: number;
  tournamentsWon: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');

  const filteredHistory = useMemo(() => {
    if (timeRange === 'all') return history;
    const now = new Date();
    return history.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      if (timeRange === 'year') return tDate.getFullYear() === now.getFullYear();
      return true;
    });
  }, [history, timeRange]);

  const { playerStats, totalGames, totalPoints, activePlayersCount, bestDuo, curiosities, topLocations } = useMemo(() => {
    const stats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, names: string[] }>();
    const locationCounts = new Map<string, number>();
    let tGames = 0, tPoints = 0;
    let maxDiff = { diff: -1, winner: '', loser: '' };

    players.forEach(p => {
        stats.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, gamesPlayed: 0, wins: 0, losses: 0, pointsScored: 0, pointsConceded: 0, pointsDiff: 0, tournamentsPlayed: 0, tournamentsWon: 0 });
    });

    filteredHistory.forEach(t => {
       locationCounts.set(t.locationId, (locationCounts.get(t.locationId) || 0) + 1);
       const tournamentPlayers = new Set<string>();
       if (t.matches && t.matches.length > 0 && t.status === 'finished') {
           const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
           t.matches.forEach(m => {
               const k1 = m.team1.map(p => p.id).sort().join('-');
               const k2 = m.team2.map(p => p.id).sort().join('-');
               if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
               if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });
               const s1 = teamStats.get(k1)!, s2 = teamStats.get(k2)!;
               s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
               if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
           });
           const standings = Array.from(teamStats.values()).sort((a, b) => (b.wins - a.wins || b.diff - a.diff));
           if (standings.length > 0) standings[0].playerIds.forEach(wid => stats.get(wid) && stats.get(wid)!.tournamentsWon++);
       }
       if (t.matches) {
           tGames += t.matches.length;
           t.matches.forEach(m => {
               if (m.status !== 'finished' && m.status !== 'live') return;
               tPoints += (m.score1 + m.score2);
               const diff = Math.abs(m.score1 - m.score2);
               const getTName = (team: Player[]) => team.map(p => p.nickname || p.name.split(' ')[0]).join('&');
               if (diff > maxDiff.diff) maxDiff = { diff, winner: m.score1 > m.score2 ? getTName(m.team1) : getTName(m.team2), loser: m.score1 > m.score2 ? getTName(m.team2) : getTName(m.team1) };
               [m.team1, m.team2].forEach((team, idx) => {
                   const tId = team.map(p => p.id).sort().join('-');
                   if (!duoStats.has(tId)) duoStats.set(tId, { wins: 0, games: 0, names: team.map(p => p.nickname || p.name.split(' ')[0]) });
                   const ds = duoStats.get(tId)!; ds.games++; if ((idx === 0 && m.score1 > m.score2) || (idx === 1 && m.score2 > m.score1)) ds.wins++;
                   team.forEach(p => {
                       tournamentPlayers.add(p.id); const ps = stats.get(p.id);
                       if (ps) { ps.gamesPlayed++; ps.pointsScored += (idx === 0 ? m.score1 : m.score2); ps.pointsConceded += (idx === 0 ? m.score2 : m.score1); ps.pointsDiff += (idx === 0 ? m.score1 - m.score2 : m.score2 - m.score1); if ((idx === 0 && m.score1 > m.score2) || (idx === 1 && m.score2 > m.score1)) ps.wins++; else ps.losses++; }
                   });
               });
           });
       }
       tournamentPlayers.forEach(pid => stats.get(pid) && stats.get(pid)!.tournamentsPlayed++);
    });

    let bestDuoData = { names: ['-', '-'], winRate: 0, wins: 0, games: 0 };
    duoStats.forEach(v => { if (v.games >= 2) { const r = (v.wins / v.games) * 100; if (r > bestDuoData.winRate) bestDuoData = { names: v.names, winRate: Math.round(r), wins: v.wins, games: v.games }; } });
    let muralha = { name: '-', avg: 999 };
    stats.forEach(p => { if (p.gamesPlayed >= 3) { const a = p.pointsConceded / p.gamesPlayed; if (a < muralha.avg) muralha = { name: p.name.split(' ')[0], avg: parseFloat(a.toFixed(1)) }; } });

    const activePlayers = Array.from(stats.values()).filter(p => p.gamesPlayed > 0);
    return { playerStats: activePlayers.sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff), totalGames: tGames, totalPoints: tPoints, activePlayersCount: activePlayers.length, bestDuo: bestDuoData, curiosities: { biggestWin: maxDiff, muralha }, topLocations: Array.from(locationCounts.entries()).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([id,count]) => ({ name: locations.find(l=>l.id===id)?.name || 'Desconhecido', type: locations.find(l=>l.id===id)?.type || 'Indoor', count })) };
  }, [filteredHistory, players, locations]);

  const handleExport = () => {
    let t = `🎾 *Stats Período: ${timeRange}*\n🏆 Jogos: ${totalGames} • Pontos: ${totalPoints}\n🥇 Top 3:\n`;
    playerStats.slice(0, 3).forEach((p, i) => t += `${i+1}. ${p.name} (${p.wins}V)\n`);
    navigator.clipboard.writeText(t).then(() => alert("Copiado!"));
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-4 pb-24 animate-fade-in">
        <div className="flex items-center justify-between">
             <div className="flex bg-surface-dark rounded-lg p-1 border border-white/5">
                {['all', 'month', 'year'].map(r => <button key={r} onClick={() => setTimeRange(r as any)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${timeRange === r ? 'bg-primary text-background-dark shadow-sm' : 'text-gray-400 hover:text-white'}`}>{r==='all'?'Tudo':r==='month'?'Mês':'Ano'}</button>)}
             </div>
             <button onClick={handleExport} className="size-9 bg-white/5 rounded-full flex items-center justify-center text-primary"><span className="material-symbols-outlined text-[20px]">ios_share</span></button>
        </div>
        <section><div className="grid grid-cols-3 gap-3">
            {[{i:'sports_tennis', l:'Jogos', v:totalGames, c:'primary'}, {i:'scoreboard', l:'Pontos', v:totalPoints, c:'primary'}, {i:'groups', l:'Ativos', v:activePlayersCount, c:'primary'}].map(s => (
                <div key={s.l} className="flex flex-col gap-1 rounded-xl p-4 bg-surface-dark border border-white/5 shadow-sm"><span className={`material-symbols-outlined text-${s.c} mb-1`} style={{ fontSize: '24px' }}>{s.i}</span><p className="text-gray-400 text-[9px] font-bold uppercase">{s.l}</p><p className="text-white text-2xl font-bold leading-none">{s.v}</p></div>
            ))}
        </div></section>
        {topLocations.length > 0 && <section className="bg-surface-dark rounded-2xl p-5 border border-white/5"><div className="flex items-center gap-2 mb-4"><span className="material-symbols-outlined text-yellow-500">star</span><h3 className="text-sm font-bold text-white uppercase tracking-wider">Locais de Eleição</h3></div><div className="flex flex-col gap-3">{topLocations.map((loc, idx) => (<div key={idx} className="flex items-center justify-between"><div className="flex items-center gap-3"><div className={`size-6 rounded-full flex items-center justify-center text-xs font-bold ${idx===0?'bg-yellow-500 text-black':idx===1?'bg-gray-400 text-black':'bg-orange-700 text-white'}`}>{idx+1}</div><div><p className="text-sm font-bold text-white leading-tight">{loc.name}</p><p className="text-[10px] text-gray-500">{loc.type}</p></div></div><div className="flex items-center gap-1.5 bg-white/5 px-2 py-1 rounded-md"><span className="text-xs font-bold text-white">{loc.count}</span><span className="text-[10px] text-gray-500 uppercase">T</span></div></div>))}</div></section>}
        {bestDuo.games > 0 && <section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#28392f] to-surface-dark border border-primary/20 p-5 shadow-lg"><div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-primary/10 blur-2xl"></div><div className="flex justify-between items-start relative z-10"><div><div className="flex items-center gap-2 mb-3"><span className="flex items-center justify-center size-6 rounded-full bg-orange-500/20 text-orange-400"><span className="material-symbols-outlined" style={{ fontSize: '16px' }}>local_fire_department</span></span><h3 className="text-sm font-bold text-white uppercase tracking-wider">Dupla Imbatível</h3></div><div className="flex items-center gap-3 mb-2"><span className="text-xl font-bold text-white">{bestDuo.names[0]}</span><span className="text-gray-500 font-bold">&</span><span className="text-xl font-bold text-white">{bestDuo.names[1]}</span></div><p className="text-gray-400 text-xs">{bestDuo.wins} vitórias em {bestDuo.games} jogos</p></div><div className="flex flex-col items-center justify-center bg-surface-dark/50 rounded-xl p-3 backdrop-blur-sm border border-white/5"><div className="text-3xl font-bold text-primary">{bestDuo.winRate}%</div><div className="text-[10px] uppercase font-bold text-gray-400">WR</div></div></div></section>}
        <section className="flex flex-col gap-2">
            <h2 className="text-white text-lg font-bold uppercase tracking-tight px-2 pb-2">Classificação</h2>
            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider"><div className="col-span-1 text-center">#</div><div className="col-span-4">Jogador</div><div className="col-span-2 text-center">J</div><div className="col-span-2 text-center">V</div><div className="col-span-1 text-center text-yellow-500">T</div><div className="col-span-2 text-right">Pts</div></div>
            {playerStats.length === 0 ? (<div className="text-center py-8 text-gray-500 border border-dashed border-white/10 rounded-xl">Sem dados.</div>) : (
