        <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
            {['Todos', 'Nível 1', 'Nível 2', 'Nível 3', 'Pro'].map(lvl => (
                <button key={lvl} onClick={() => setFilterLevel(lvl)} className={`flex h-9 shrink-0 items-center justify-center px-4 rounded-full font-semibold text-xs transition-all ${filterLevel === lvl ? 'bg-primary text-background-dark shadow-md' : 'bg-card-dark ring-1 ring-white/10 text-gray-300'}`}>{lvl}</button>
