          <div className="bg-card-dark p-5 rounded-2xl border border-primary/30 shadow-lg mb-6 animate-fade-in-up">
              <h3 className="font-bold text-white mb-4 border-b border-white/5 pb-2">{editingPlayerId ? 'Editar Perfil' : 'Novo Jogador'}</h3>
