            {filteredPlayers.length === 0 && <p className="text-center text-gray-500 py-10">Vazio.</p>}
            {filteredPlayers.map((p) => (
                <div key={p.id} onClick={() => onPlayerClick && onPlayerClick(p.id)} className="group relative flex items-center justify-between p-3 rounded-2xl bg-card-dark shadow-sm ring-1 ring-white/5 hover:ring-primary/50 transition-all duration-300 cursor-pointer">
                    <div className="flex items-center gap-4">
                        <div className="relative">
                            {renderGlobalAvatar(p, 'size-14')}
                            <div className="absolute -bottom-1 -right-1 flex items-center justify-center size-5 bg-surface-dark rounded-full border border-white/10"><span className="text-[10px] font-bold text-gray-400">{p.hand === 'Canhoto' ? 'L' : 'R'}</span></div>
                        </div>
                        <div className="flex flex-col justify-center">
                            <p className="text-base font-bold leading-tight line-clamp-1 mb-0.5 text-white">{p.nickname || p.name}</p>
                            <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium w-fit border border-white/5 ${p.level === 'Pro' ? 'bg-purple-500/20 text-purple-300' : p.level === 'Nível 3' ? 'bg-primary/20 text-primary' : 'bg-gray-700/50 text-gray-400'}`}>{p.level}</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-2"><button onClick={(e) => handleEditClick(e, p)} className="size-9 flex items-center justify-center rounded-full text-gray-400 hover:text-primary hover:bg-primary/10 transition-colors"><span className="material-symbols-outlined text-[20px]">edit</span></button><div className="size-9 flex items-center justify-center rounded-full text-gray-400 group-hover:text-white group-hover:bg-white/5 transition-colors"><span className="material-symbols-outlined text-[20px]">chevron_right</span></div></div>
