        {!isEditing && (
            <div className="fixed bottom-24 right-6 z-30 max-w-md"><button onClick={handleAddNew} className="flex items-center justify-center size-14 rounded-full bg-primary text-background-dark shadow-lg shadow-primary/30 active:scale-95 transition-all"><span className="material-symbols-outlined text-[32px] font-bold">add</span></button></div>
