import React, { useMemo } from 'react';
import { Screen, Tournament, Match, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HistoryDetailProps {
  setScreen: (screen: Screen) => void;
  tournament: Tournament;
  locations: Location[];
}

export const HistoryDetailScreen: React.FC<HistoryDetailProps> = ({ setScreen, tournament, locations }) => {
  const matches = tournament.matches || [];
  const locationName = locations.find(l => l.id === tournament.locationId)?.name || 'Local Desconhecido';

  const standings = useMemo(() => {
    const stats = new Map<string, { id: string, teamName: string, wins: number, pointsDiff: number }>();
    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) stats.set(key, { id: key, teamName: team.map(p => p.nickname || p.name.split(' ')[0]).join(' & '), wins: 0, pointsDiff: 0 });
        return stats.get(key)!;
    };
    matches.forEach(m => {
        const s1 = getStats(m.team1); const s2 = getStats(m.team2);
        s1.pointsDiff += (m.score1 - m.score2); s2.pointsDiff += (m.score2 - m.score1);
        if (m.score1 > m.score2) s1.wins += 1; else if (m.score2 > m.score1) s2.wins += 1;
    });
    return Array.from(stats.values()).sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff);
  }, [matches]);

  const rounds = Array.from(new Set(matches.map(m => m.round))).sort((a: number, b: number) => a - b);

  return (
    <div className="flex-1 flex flex-col gap-6 p-4 pb-24 animate-fade-in bg-background-dark min-h-screen relative z-20">
        <header className="flex items-center justify-between sticky top-0 bg-background-dark/95 backdrop-blur-md py-2 z-30">
            <button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors"><span className="material-symbols-outlined text-white">arrow_back</span></button>
            <div className="flex flex-col items-center"><span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">{new Date(tournament.date).toLocaleDateString()}</span><h2 className="text-sm font-bold text-white max-w-[200px] truncate">{locationName}</h2></div><div className="w-10"></div>
        </header>
        {standings.length > 0 && (
            <div className="bg-surface-dark rounded-2xl p-4 border border-white/5 shadow-lg">
                <h3 className="text-center text-[10px] font-bold text-primary uppercase tracking-wider mb-4">Classificação Final</h3>
                <div className="flex flex-col gap-2">
                    {standings.slice(0, 3).map((team, idx) => (
                        <div key={idx} className="flex items-center justify-between p-2 rounded-lg bg-white/5">
                            <div className="flex items-center gap-3"><div className={`size-6 rounded-full flex items-center justify-center text-[10px] font-bold ${idx===0?'bg-yellow-500 text-black':idx===1?'bg-gray-400 text-black':'bg-orange-700 text-white'}`}>{idx+1}</div><span className="text-xs font-bold text-white">{team.teamName}</span></div>
                            <div className="text-[10px] font-medium text-gray-400">{team.wins}V <span className={team.pointsDiff > 0 ? 'text-green-400' : 'text-red-400'}>({team.pointsDiff > 0 ? '+' : ''}{team.pointsDiff})</span></div>
                        </div>
                    ))}
                </div>
            </div>
        )}
        <div className="space-y-6">
            {rounds.map(round => (
                <div key={round}>
                    <div className="flex items-center gap-2 mb-3 px-1"><div className="h-px flex-1 bg-white/10"></div><span className="text-[10px] font-bold text-gray-500 uppercase">Ronda {round}</span><div className="h-px flex-1 bg-white/10"></div></div>
                    <div className="flex flex-col gap-3">
                        {matches.filter(m => m.round === round).map(match => (
                            <div key={match.id} className="bg-card-dark rounded-xl border border-white/5 p-3 flex flex-col gap-2">
                                <div className="flex justify-between items-center text-[9px] text-gray-500 uppercase font-bold tracking-wider mb-1"><span>Campo {match.court}</span><span className={match.score1 > match.score2 ? 'text-primary' : match.score2 > match.score1 ? 'text-purple-400' : ''}>{match.score1 > match.score2 ? 'V Equipa 1' : match.score2 > match.score1 ? 'V Equipa 2' : 'Empate'}</span></div>
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2 flex-1 overflow-hidden"><div className="flex -space-x-2 shrink-0">{match.team1.map(p => <div key={p.id}>{renderGlobalAvatar(p, 'size-6')}</div>)}</div><span className={`text-[10px] font-bold truncate ${match.score1 > match.score2 ? 'text-white' : 'text-gray-400'}`}>{match.team1.map(p => p.nickname || p.name.split(' ')[0]).join('/')}</span></div>
                                    <div className="flex items-center gap-2 px-3"><span className={`text-lg font-bold ${match.score1 > match.score2 ? 'text-primary' : 'text-gray-500'}`}>{match.score1}</span><span className="text-gray-600">-</span><span className={`text-lg font-bold ${match.score2 > match.score1 ? 'text-purple-400' : 'text-gray-500'}`}>{match.score2}</span></div>
                                    <div className="flex items-center gap-2 flex-1 justify-end overflow-hidden"><span className={`text-[10px] font-bold truncate ${match.score2 > match.score1 ? 'text-white' : 'text-gray-400'}`}>{match.team2.map(p => p.nickname || p.name.split(' ')[0]).join('/')}</span><div className="flex -space-x-2 shrink-0">{match.team2.map(p => <div key={p.id}>{renderGlobalAvatar(p, 'size-6')}</div>)}</div></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
  onUpdatePlayer?: (player: Player) => void;
}

type TabType = 'overview' | 'tournaments' | 'matches' | 'relations';

const getColorForId = (id: string) => {
  const colors = [
    'bg-blue-500', 'bg-emerald-500', 'bg-purple-500', 'bg-orange-500', 
    'bg-rose-500', 'bg-cyan-500', 'bg-amber-500', 'bg-indigo-500'
  ];
  const index = Math.abs(id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)) % colors.length;
  return colors[index];
};

export const renderGlobalAvatar = (p: { id: string, image?: string }, sizeClass: string = 'size-10') => {
  const usePlaceholder = !p.image || p.image.includes('ui-avatars.com') || p.image.includes('googleusercontent.com') || p.image === '';

  if (usePlaceholder) {
      return (
          <div className={`${sizeClass} rounded-full ${getColorForId(p.id)} flex items-center justify-center border-2 border-white/10 text-white shadow-inner shrink-0`}>
              <span className="material-symbols-outlined text-[0.6em] select-none" style={{ fontSize: '1.5em' }}>person</span>
          </div>
      );
  }
  return <img src={p.image} className={`${sizeClass} rounded-full object-cover border-2 border-white/10 shadow-md shrink-0`} alt="Avatar" />;
};

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, currentMatches, setScreen, onUpdatePlayer }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [dateFilter, setDateFilter] = useState<'all' | '30' | '90' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);
  const [isEditing, setIsEditing] = useState(false);

  const player = players.find(p => p.id === playerId);

  // Form states
  const [editFirstName, setEditFirstName] = useState('');
  const [editLastName, setEditLastName] = useState('');
  const [editNickname, setEditNickname] = useState('');
  const [editBirthDate, setEditBirthDate] = useState('');
  const [editHand, setEditHand] = useState<'Destro' | 'Canhoto'>('Destro');
  const [editLevel, setEditLevel] = useState('Nível 3');
  const [editImage, setEditImage] = useState('');

  useEffect(() => {
    if (player) {
        setEditFirstName(player.name);
        setEditLastName(player.lastName || '');
        setEditNickname(player.nickname || '');
        setEditBirthDate(player.birthDate || '');
        setEditHand(player.hand || 'Destro');
        setEditLevel(player.level);
        setEditImage(player.image);
    }
  }, [player, isEditing]);

  const handleSaveEdit = () => {
    if (player && onUpdatePlayer) {
        onUpdatePlayer({
            ...player,
            name: editFirstName,
            lastName: editLastName,
            nickname: editNickname,
            birthDate: editBirthDate,
            hand: editHand,
            level: editLevel,
            image: editImage
        });
        setIsEditing(false);
    }
  };

  const stats = useMemo(() => {
    if (!playerId) return null;
    const now = new Date();
    const filterDays = dateFilter === '30' ? 30 : dateFilter === '90' ? 90 : dateFilter === 'year' ? 365 : Infinity;

    const isWithinFilter = (dateStr: string) => {
        if (filterDays === Infinity) return true;
        const d = new Date(dateStr);
        const diff = (now.getTime() - d.getTime()) / (1000 * 3600 * 24);
        return diff <= filterDays;
    };

    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];
    const myMatches: (Match & { date: string })[] = [];
    const myWonMatches: (Match & { date: string })[] = [];
    const myLostMatches: (Match & { date: string })[] = [];
    const myClutchMatches: (Match & { date: string })[] = [];
    const myBlowoutMatches: (Match & { date: string })[] = [];

    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number, matches: any[] }>();
    const rivals = new Map<string, { id: string, name: string, image: string, winsAgainst: number, lossesAgainst: number, games: number, matches: any[] }>();

    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let currentTWinStreak = 0;
    let maxTWinStreak = 0;

    const chronologicalHistory = [...history].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    chronologicalHistory.forEach(t => {
        const withinFilter = isWithinFilter(t.date);
        const tMatches = t.matches?.filter(m => 
            m.team1.some(p => p.id === playerId) || m.team2.some(p => p.id === playerId)
        ) || [];

        if (tMatches.length > 0) {
            if (withinFilter) myTournaments.push(t);
            const teamStats = new Map<string, { wins: number, diff: number, playerIds: string[] }>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, playerIds: m.team1.map(p=>p.id) });
                if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, playerIds: m.team2.map(p=>p.id) });
                const s1 = teamStats.get(k1)!;
                const s2 = teamStats.get(k2)!;
                s1.diff += (m.score1 - m.score2);
                s2.diff += (m.score2 - m.score1);
                if (m.score1 > m.score2) s1.wins++;
                else if (m.score2 > m.score1) s2.wins++;
            });
            const standings = Array.from(teamStats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
            const wonTournament = standings.length > 0 && standings[0].playerIds.includes(playerId);

            if (wonTournament) {
                if (withinFilter) myWonTournaments.push(t);
                currentTWinStreak++;
                maxTWinStreak = Math.max(maxTWinStreak, currentTWinStreak);
            } else {
                currentTWinStreak = 0;
            }

            tMatches.forEach(m => {
                const matchWithDate = { ...m, date: t.date };
                const inTeam1 = m.team1.some(p => p.id === playerId);
                const myScore = inTeam1 ? m.score1 : m.score2;
                const oppScore = inTeam1 ? m.score2 : m.score1;
                const won = myScore > oppScore;
                const diff = Math.abs(myScore - oppScore);

                if (withinFilter) {
                    myMatches.push(matchWithDate);
                    if (won) {
                        myWonMatches.push(matchWithDate);
                        currentWinStreak++;
                        maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
                    } else {
                        myLostMatches.push(matchWithDate);
                        currentWinStreak = 0;
                    }
                    if (diff > 0 && diff <= 2) myClutchMatches.push(matchWithDate);
                    if (diff >= 6) myBlowoutMatches.push(matchWithDate);
                    const myTeam = inTeam1 ? m.team1 : m.team2;
                    myTeam.forEach(p => {
                        if (p.id === playerId) return;
                        if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                        const pd = partners.get(p.id)!;
                        pd.games++;
                        pd.matches.push(matchWithDate);
                        if (won) pd.wins++;
                    });
                    const oppTeam = inTeam1 ? m.team2 : m.team1;
                    oppTeam.forEach(p => {
                        if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                        const rd = rivals.get(p.id)!;
                        rd.games++;
                        rd.matches.push(matchWithDate);
                        if (won) rd.winsAgainst++;
                        else rd.lossesAgainst++;
                    });
                }
            });
        }
    });

    const partnerArr = Array.from(partners.values()).sort((a, b) => b.games - a.games);
    return {
        myTournaments, myWonTournaments, myMatches, myWonMatches, myLostMatches, myClutchMatches, myBlowoutMatches,
        partnerArr, topRivals: Array.from(rivals.values()).sort((a, b) => b.lossesAgainst - a.lossesAgainst).slice(0, 8),
        victims: Array.from(rivals.values()).sort((a, b) => b.winsAgainst - a.winsAgainst).slice(0, 8),
        pointsScored: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score1 : m.score2), 0),
        pointsConceded: myMatches.reduce((acc, m) => acc + (m.team1.some(p => p.id === playerId) ? m.score2 : m.score1), 0),
        maxWinStreak, maxTWinStreak
    };
  }, [playerId, history, dateFilter]);

