const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);

  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);

  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([
      { 
          id: 'old-1', 
          date: '2023-10-15', 
          time: '19:00', 
          duration: 2, 
          locationId: '1', 
          confirmedPlayerIds: ['1','2','3','4','5','6','7','8'], 
          status: 'finished', 
          matches: [
              { id: 'm1', team1: [MOCK_PLAYERS[0], MOCK_PLAYERS[1]], team2: [MOCK_PLAYERS[2], MOCK_PLAYERS[3]], score1: 6, score2: 2, court: 1, status: 'finished', round: 1, date: '2023-10-15T19:00:00Z' },
              { id: 'm2', team1: [MOCK_PLAYERS[4], MOCK_PLAYERS[5]], team2: [MOCK_PLAYERS[6], MOCK_PLAYERS[7]], score1: 4, score2: 6, court: 2, status: 'finished', round: 1, date: '2023-10-15T19:00:00Z' },
              { id: 'm3', team1: [MOCK_PLAYERS[0], MOCK_PLAYERS[1]], team2: [MOCK_PLAYERS[6], MOCK_PLAYERS[7]], score1: 5, score2: 7, court: 1, status: 'finished', round: 2, date: '2023-10-15T19:30:00Z' }
          ] 
      }
  ]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const handleStartTournament = (generatedMatches: Match[]) => {
    const stampedMatches = generatedMatches.map(m => ({ ...m, date: new Date().toISOString() }));
    setMatches(stampedMatches);
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();
    const updatedMatches = matches.map(m => 
        m.round === currentRound ? { ...m, status: 'finished' as const } : m
    );

    if (currentRound === 1) {
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const matchC1 = r1Matches.find(m => m.court === 1)!;
        const matchC2 = r1Matches.find(m => m.court === 2)!;

        const winnerC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const loserC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winnerC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const loserC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        const round2Matches: Match[] = [
            { id: `match-r2-1-${Date.now()}`, team1: winnerC1, team2: loserC2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: timestamp },
            { id: `match-r2-2-${Date.now()}`, team1: winnerC2, team2: loserC1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: timestamp }
        ];

        setMatches([...updatedMatches, ...round2Matches]);
        setCurrentRound(2);
    } 
    else if (currentRound === 2) {
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const teams = [ r1Matches[0].team1, r1Matches[0].team2, r1Matches[1].team1, r1Matches[1].team2 ];
        const played = new Set<string>();
        updatedMatches.forEach(m => {
             const t1Id = m.team1[0].id; const t2Id = m.team2[0].id;
             const key = [t1Id, t2Id].sort().join('-'); played.add(key);
        });

        const newMatches: Match[] = [];
        const usedTeams = new Set<string>();

        for (let i = 0; i < teams.length; i++) {
             const t1 = teams[i]; const t1Key = t1[0].id;
             if (usedTeams.has(t1Key)) continue;
             for (let j = i + 1; j < teams.length; j++) {
                 const t2 = teams[j]; const t2Key = t2[0].id;
                 if (usedTeams.has(t2Key)) continue;
                 const pairKey = [t1Key, t2Key].sort().join('-');
                 if (!played.has(pairKey)) {
                     newMatches.push({ id: `match-r3-${newMatches.length + 1}-${Date.now()}`, team1: t1, team2: t2, score1: 0, score2: 0, court: newMatches.length + 1, status: 'live', round: 3, date: timestamp });
                     usedTeams.add(t1Key); usedTeams.add(t2Key); break; 
                 }
             }
        }
        setMatches([...updatedMatches, ...newMatches]);
        setCurrentRound(3);
    } else {
        setMatches(updatedMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finalMatches = matches.map(m => ({ ...m, status: 'finished' as const }));
        const finishedTournament: Tournament = { ...activeTournament, status: 'finished', matches: finalMatches };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdatePlayer = (updatedPlayer: Player) => {
    setPlayers(prev => prev.map(p => p.id === updatedPlayer.id ? updatedPlayer : p));
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  const handleViewHistory = (tournament: Tournament) => {
    setSelectedHistoryTournament(tournament);
    setScreen(Screen.HISTORY_DETAIL);
  };

  const handleViewPlayer = (playerId: string) => {
      setSelectedPlayerId(playerId);
      setScreen(Screen.PROFILE);
  };

  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} activeTournament={activeTournament} players={players} locations={locations}
            onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament} history={tournamentHistory}
          />
        );
      case Screen.PROFILE:
        return (
            <ProfileScreen 
                playerId={selectedPlayerId} players={players} history={tournamentHistory}
                currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer}
            />
        );
      case Screen.LIVE_GAME:
        return (
            <LiveGameScreen 
                setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} 
                updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound}
            />
        );
      case Screen.TOURNAMENT_SUMMARY:
          return (
              <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />
          );
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return <GlobalStatsScreen history={tournamentHistory} players={players} onViewTournament={handleViewHistory} locations={locations} />;
      case Screen.HISTORY_DETAIL:
        if (!selectedHistoryTournament) return <GlobalStatsScreen history={tournamentHistory} players={players} />;
        return <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} />;
      case Screen.TEAM_SETUP:
        return <TeamSetupScreen setScreen={setScreen} players={getConfirmedPlayers()} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} players={players} onPlayerClick={handleViewPlayer} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default:
        return null;
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP && currentScreen !== Screen.TOURNAMENT_SUMMARY && currentScreen !== Screen.HISTORY_DETAIL) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? `Ronda ${currentRound}` : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados Finais' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
               {currentScreen === Screen.PROFILE ? 'Perfil de Jogador' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">Definir Equipas</h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}
        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL',
  TOURNAMENT_HISTORY = 'TOURNAMENT_HISTORY'
}

export interface Player {
  id: string;
  name: string;
  lastName?: string;
  nickname?: string;
  birthDate?: string;
  hand?: 'Destro' | 'Canhoto';
  level: string;
  image: string;
  stats?: {
    wins: number;
    total: number;
  };
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
  date?: string;
}

export interface Tournament {
  id: string;
  date: string;
  time: string;
  duration: number;
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[];
}

import React from 'react';
import { Screen } from '../types';

interface NavigationProps {
  currentScreen: Screen;
  setScreen: (screen: Screen) => void;
}

export const Navigation: React.FC<NavigationProps> = ({ currentScreen, setScreen }) => {
  const navItems = [
    { id: Screen.HOME, icon: 'home', label: 'Início' },
    { id: Screen.TOURNAMENT_HISTORY, icon: 'history', label: 'Histórico' },
    { id: Screen.GLOBAL_STATS, icon: 'bar_chart', label: 'Stats' },
    { id: Screen.PLAYERS, icon: 'groups', label: 'Jogadores' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-background-dark/95 backdrop-blur-md border-t border-white/5 pb-6 pt-3 z-50 max-w-md mx-auto">
      <div className="flex justify-around items-center">
        {navItems.map((item) => {
          const isActive = currentScreen === item.id || 
                          (item.id === Screen.TOURNAMENT_HISTORY && currentScreen === Screen.HISTORY_DETAIL) ||
                          (item.id === Screen.PLAYERS && currentScreen === Screen.PROFILE);
          return (
            <button
              key={item.id}
              onClick={() => setScreen(item.id)}
              className={`flex flex-col items-center gap-1 w-16 transition-all ${
                isActive ? 'text-primary scale-110' : 'text-slate-500 hover:text-white'
              }`}
            >
              <span className={`material-symbols-outlined text-[24px] ${isActive ? 'fill-1' : ''}`}>
                {item.icon}
              </span>
              <span className={`text-[10px] font-bold uppercase tracking-tighter ${isActive ? 'opacity-100' : 'opacity-60'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Screen, Tournament, Location } from '../types';

interface HistoryProps {
  history: Tournament[];
  locations: Location[];
  onViewTournament: (t: Tournament) => void;
}

export const TournamentHistoryScreen: React.FC<HistoryProps> = ({ history, locations, onViewTournament }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState<string>('all');

  const filteredHistory = useMemo(() => {
    return history
      .filter(t => {
        const loc = locations.find(l => l.id === t.locationId);
        const matchesSearch = loc?.name.toLowerCase().includes(searchTerm.toLowerCase());
        const tDate = new Date(t.date);
        const monthYear = `${tDate.getFullYear()}-${String(tDate.getMonth() + 1).padStart(2, '0')}`;
        const matchesMonth = selectedMonth === 'all' || monthYear === selectedMonth;
        return matchesSearch && matchesMonth && t.status === 'finished';
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [history, searchTerm, selectedMonth, locations]);

  const months = useMemo(() => {
    const m = new Set<string>();
    history.forEach(t => {
      const d = new Date(t.date);
      m.add(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
    });
    return Array.from(m).sort().reverse();
  }, [history]);

  return (
    <div className="flex flex-col gap-6 px-4 pt-6 pb-32 animate-fade-in">
      <header>
        <h1 className="text-3xl font-black text-white">Registo <br/><span className="text-primary">Histórico</span></h1>
        <p className="text-gray-500 text-sm mt-1">Consulte todos os torneios realizados.</p>
      </header>

      <div className="space-y-3">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Filtrar por local..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-card-dark border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:ring-2 focus:ring-primary/50 outline-none transition-all"
          />
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 hide-scrollbar">
          <button 
            onClick={() => setSelectedMonth('all')}
            className={`px-4 py-2 rounded-full text-[10px] font-black uppercase whitespace-nowrap border transition-all ${selectedMonth === 'all' ? 'bg-primary border-primary text-background-dark' : 'bg-white/5 border-white/10 text-gray-500'}`}
          >
            Todos os Meses
          </button>
          {months.map(m => {
            const [year, month] = m.split('-');
            const date = new Date(parseInt(year), parseInt(month) - 1);
            const label = date.toLocaleDateString('pt-PT', { month: 'long', year: 'numeric' });
            return (
              <button 
                key={m}
                onClick={() => setSelectedMonth(m)}
                className={`px-4 py-2 rounded-full text-[10px] font-black uppercase whitespace-nowrap border transition-all ${selectedMonth === m ? 'bg-primary border-primary text-background-dark' : 'bg-white/5 border-white/10 text-gray-500'}`}
              >
                {label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex flex-col gap-4">
        {filteredHistory.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 opacity-30">
            <span className="material-symbols-outlined text-6xl mb-4">history_toggle_off</span>
            <p className="text-sm font-bold">Nenhum registo encontrado</p>
          </div>
        ) : (
          filteredHistory.map(t => {
            const loc = locations.find(l => l.id === t.locationId);
            return (
              <button 
                key={t.id} 
                onClick={() => onViewTournament(t)}
                className="bg-card-dark p-5 rounded-3xl border border-white/5 hover:border-primary/30 transition-all text-left group active:scale-[0.98]"
              >
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-[10px] font-black text-primary uppercase tracking-widest block mb-1">
                      {new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                    </span>
                    <h3 className="text-xl font-black text-white group-hover:text-primary transition-colors">{loc?.name}</h3>
                  </div>
                  <div className="size-10 rounded-2xl bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                    <span className="material-symbols-outlined text-gray-500 group-hover:text-primary">chevron_right</span>
                  </div>
                </div>

                <div className="flex items-center gap-4 text-gray-500">
                  <div className="flex items-center gap-1.5">
                    <span className="material-symbols-outlined text-[16px]">sports_tennis</span>
                    <span className="text-[10px] font-bold uppercase">{t.matches?.length || 0} Jogos</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <span className="material-symbols-outlined text-[16px]">schedule</span>
                    <span className="text-[10px] font-bold uppercase">{t.time} • {t.duration}h</span>
                  </div>
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Screen, Tournament, Match, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HistoryDetailProps {
  setScreen: (screen: Screen) => void;
  tournament: Tournament;
  locations: Location[];
}

export const HistoryDetailScreen: React.FC<HistoryDetailProps> = ({ setScreen, tournament, locations }) => {
  const matches = tournament.matches || [];
  const loc = locations.find(l => l.id === tournament.locationId);

  const standings = useMemo(() => {
    const stats = new Map<string, { id: string, teamName: string, wins: number, pointsDiff: number, players: Player[] }>();
    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) stats.set(key, { id: key, teamName: team.map(p => p.nickname || p.name.split(' ')[0]).join(' & '), wins: 0, pointsDiff: 0, players: team });
        return stats.get(key)!;
    };
    matches.forEach(m => {
        const s1 = getStats(m.team1); const s2 = getStats(m.team2);
        s1.pointsDiff += (m.score1 - m.score2); s2.pointsDiff += (m.score2 - m.score1);
        if (m.score1 > m.score2) s1.wins += 1; else if (m.score2 > m.score1) s2.wins += 1;
    });
    return Array.from(stats.values()).sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff);
  }, [matches]);

  const rounds = Array.from(new Set(matches.map(m => m.round))).sort((a: number, b: number) => a - b);

  return (
    <div className="flex-1 flex flex-col gap-6 p-4 pb-32 animate-fade-in bg-background-dark min-h-screen">
        <header className="flex items-center justify-between py-2">
            <button 
              onClick={() => setScreen(Screen.TOURNAMENT_HISTORY)} 
              className="size-11 rounded-full flex items-center justify-center bg-white/5 border border-white/10 hover:bg-white/10 transition-colors"
            >
              <span className="material-symbols-outlined text-white">arrow_back</span>
            </button>
            <div className="flex flex-col items-center">
              <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">{new Date(tournament.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' })}</span>
              <h2 className="text-lg font-black text-white truncate max-w-[200px]">{loc?.name}</h2>
            </div>
            <div className="size-11"></div>
        </header>

        {/* Resumo / Vencedor Geral */}
        {standings.length > 0 && (
            <section className="bg-gradient-to-br from-primary/20 to-card-dark rounded-[2.5rem] p-6 border border-primary/20 shadow-2xl relative overflow-hidden">
                <div className="absolute -right-6 -top-6 size-32 bg-primary/10 blur-3xl rounded-full"></div>
                <div className="flex flex-col items-center gap-3 relative z-10">
                    <span className="material-symbols-outlined text-primary text-5xl">emoji_events</span>
                    <div className="text-center">
                      <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1">Grande Vencedor</p>
                      <h3 className="text-2xl font-black text-white">{standings[0].teamName}</h3>
                    </div>
                    <div className="flex gap-4 mt-2">
                        <div className="flex flex-col items-center">
                            <span className="text-lg font-black text-white">{standings[0].wins}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span>
                        </div>
                        <div className="w-px h-8 bg-white/10"></div>
                        <div className="flex flex-col items-center">
                            <span className="text-lg font-black text-white">+{standings[0].pointsDiff}</span>
                            <span className="text-[8px] font-bold text-gray-500 uppercase">Dif. Pontos</span>
                        </div>
                    </div>
                </div>
            </section>
        )}

        {/* Lista de Jogos por Ronda */}
        <div className="space-y-8">
            {rounds.map(round => (
                <div key={round} className="space-y-4">
                    <div className="flex items-center gap-4 px-2">
                        <span className="text-xs font-black text-gray-500 uppercase tracking-widest">Ronda {round}</span>
                        <div className="h-px flex-1 bg-white/5"></div>
                    </div>
                    <div className="flex flex-col gap-4">
                        {matches.filter(m => m.round === round).map(match => {
                            const team1Wins = match.score1 > match.score2;
                            const team2Wins = match.score2 > match.score1;

                            return (
                                <div key={match.id} className="bg-card-dark rounded-3xl border border-white/5 p-5 shadow-lg flex flex-col gap-4 relative overflow-hidden group">
                                    <div className="flex items-center justify-between text-[9px] font-bold text-gray-600 uppercase tracking-widest border-b border-white/5 pb-3">
                                        <span>Campo {match.court}</span>
                                        <span className="text-primary">Finalizado</span>
                                    </div>

                                    <div className="flex items-center justify-between gap-2">
                                        {/* Equipa 1 */}
                                        <div className={`flex flex-col items-center gap-2 flex-1 transition-all duration-500 ${team2Wins ? 'opacity-40 grayscale' : 'scale-105'}`}>
                                            <div className="flex -space-x-2">
                                                {match.team1.map(p => <div key={p.id}>{renderGlobalAvatar(p, 'size-8')}</div>)}
                                            </div>
                                            <span className={`text-[10px] font-bold text-center leading-tight ${team1Wins ? 'text-primary' : 'text-white'}`}>
                                                {match.team1.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                            </span>
                                            {team1Wins && <span className="text-[8px] font-black bg-primary/20 text-primary px-2 py-0.5 rounded-full uppercase">Win</span>}
                                        </div>

                                        {/* Score */}
                                        <div className="flex items-center gap-3 bg-background-dark/50 px-4 py-2 rounded-2xl border border-white/5">
                                            <span className={`text-2xl font-black ${team1Wins ? 'text-primary' : 'text-gray-600'}`}>{match.score1}</span>
                                            <span className="text-gray-800 font-black">-</span>
                                            <span className={`text-2xl font-black ${team2Wins ? 'text-primary' : 'text-gray-600'}`}>{match.score2}</span>
                                        </div>

                                        {/* Equipa 2 */}
                                        <div className={`flex flex-col items-center gap-2 flex-1 transition-all duration-500 ${team1Wins ? 'opacity-40 grayscale' : 'scale-105'}`}>
                                            <div className="flex -space-x-2">
                                                {match.team2.map(p => <div key={p.id}>{renderGlobalAvatar(p, 'size-8')}</div>)}
                                            </div>
                                            <span className={`text-[10px] font-bold text-center leading-tight ${team2Wins ? 'text-primary' : 'text-white'}`}>
                                                {match.team2.map(p => p.nickname || p.name.split(' ')[0]).join('/')}
                                            </span>
                                            {team2Wins && <span className="text-[8px] font-black bg-primary/20 text-primary px-2 py-0.5 rounded-full uppercase">Win</span>}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
        </div>
    </div>
  );
};

