  ]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const handleStartTournament = (generatedMatches: Match[]) => {
    const stampedMatches = generatedMatches.map(m => ({ ...m, date: new Date().toISOString() }));
    setMatches(stampedMatches);
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleCreateTournament = (tournament: Tournament) => {
    setActiveTournament(tournament);
    setScreen(Screen.HOME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return {
        ...m,
        [team === 1 ? 'score1' : 'score2']: newScore
      };
    }));
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();
    const updatedMatches = matches.map(m => 
        m.round === currentRound ? { ...m, status: 'finished' as const } : m
    );

    if (currentRound === 1) {
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const matchC1 = r1Matches.find(m => m.court === 1)!;
        const matchC2 = r1Matches.find(m => m.court === 2)!;

        const winnerC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const loserC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winnerC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const loserC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        const round2Matches: Match[] = [
            { id: `match-r2-1-${Date.now()}`, team1: winnerC1, team2: loserC2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: timestamp },
            { id: `match-r2-2-${Date.now()}`, team1: winnerC2, team2: loserC1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: timestamp }
        ];

        setMatches([...updatedMatches, ...round2Matches]);
        setCurrentRound(2);
    } 
    else if (currentRound === 2) {
        const r1Matches = updatedMatches.filter(m => m.round === 1);
        const teams = [ r1Matches[0].team1, r1Matches[0].team2, r1Matches[1].team1, r1Matches[1].team2 ];
        const played = new Set<string>();
        updatedMatches.forEach(m => {
             const t1Id = m.team1[0].id; const t2Id = m.team2[0].id;
             const key = [t1Id, t2Id].sort().join('-'); played.add(key);
        });

        const newMatches: Match[] = [];
        const usedTeams = new Set<string>();

        for (let i = 0; i < teams.length; i++) {
             const t1 = teams[i]; const t1Key = t1[0].id;
             if (usedTeams.has(t1Key)) continue;
             for (let j = i + 1; j < teams.length; j++) {
                 const t2 = teams[j]; const t2Key = t2[0].id;
                 if (usedTeams.has(t2Key)) continue;
                 const pairKey = [t1Key, t2Key].sort().join('-');
                 if (!played.has(pairKey)) {
                     newMatches.push({ id: `match-r3-${newMatches.length + 1}-${Date.now()}`, team1: t1, team2: t2, score1: 0, score2: 0, court: newMatches.length + 1, status: 'live', round: 3, date: timestamp });
                     usedTeams.add(t1Key); usedTeams.add(t2Key); break; 
                 }
             }
        }
        setMatches([...updatedMatches, ...newMatches]);
        setCurrentRound(3);
    } else {
        setMatches(updatedMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finalMatches = matches.map(m => ({ ...m, status: 'finished' as const }));
        const finishedTournament: Tournament = { ...activeTournament, status: 'finished', matches: finalMatches };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleAddPlayer = (newPlayer: Player) => {
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleUpdatePlayer = (updatedPlayer: Player) => {
    setPlayers(prev => prev.map(p => p.id === updatedPlayer.id ? updatedPlayer : p));
  };

  const handleUpdateTournament = (updated: Tournament) => {
    setActiveTournament(updated);
  };

  const handleViewHistory = (tournament: Tournament) => {
    setSelectedHistoryTournament(tournament);
    setScreen(Screen.HISTORY_DETAIL);
  };

  const handleViewPlayer = (playerId: string) => {
      setSelectedPlayerId(playerId);
      setScreen(Screen.PROFILE);
  };

  const getConfirmedPlayers = () => {
    if (!activeTournament) return players;
    return players.filter(p => activeTournament.confirmedPlayerIds.includes(p.id));
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return (
          <HomeScreen 
            setScreen={setScreen} activeTournament={activeTournament} players={players} locations={locations}
            onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer}
            onUpdateTournament={handleUpdateTournament} history={tournamentHistory}
          />
        );
      case Screen.PROFILE:
        return (
            <ProfileScreen 
                playerId={selectedPlayerId} players={players} history={tournamentHistory}
                currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer}
            />
        );
      case Screen.LIVE_GAME:
        return (
            <LiveGameScreen 
                setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} 
                updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound}
            />
        );
      case Screen.TOURNAMENT_SUMMARY:
          return (
              <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />
          );
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return <GlobalStatsScreen history={tournamentHistory} players={players} onViewTournament={handleViewHistory} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY:
        return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={handleViewHistory} />;
      case Screen.HISTORY_DETAIL:
        if (!selectedHistoryTournament) return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={handleViewHistory} />;
        return <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} />;
      case Screen.TEAM_SETUP:
        return <TeamSetupScreen setScreen={setScreen} players={getConfirmedPlayers()} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS:
         return <PlayerListScreen setScreen={setScreen} players={players} onPlayerClick={handleViewPlayer} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} />;
      case Screen.LOCATIONS:
         return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default:
        return null;
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS, Screen.TOURNAMENT_HISTORY].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {(!showNav && currentScreen !== Screen.HOME && currentScreen !== Screen.TEAM_SETUP && currentScreen !== Screen.TOURNAMENT_SUMMARY && currentScreen !== Screen.HISTORY_DETAIL) && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">
               {currentScreen === Screen.LIVE_GAME ? `Ronda ${currentRound}` : ''}
               {currentScreen === Screen.TOURNAMENT_RESULTS ? 'Resultados Finais' : ''}
               {currentScreen === Screen.LOCATIONS ? 'Gerir Locais' : ''}
               {currentScreen === Screen.PROFILE ? 'Perfil de Jogador' : ''}
            </h2>
             <div className="w-12"></div>
          </header>
        )}

        {currentScreen === Screen.TEAM_SETUP && (
           <header className="sticky top-0 z-50 flex items-center bg-background-dark/95 backdrop-blur-md p-4 pb-2 justify-between border-b border-white/5">
            <button onClick={() => setScreen(Screen.HOME)} className="text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-white/10 transition-colors">
              <span className="material-symbols-outlined text-[24px]">arrow_back</span>
            </button>
            <h2 className="text-white text-lg font-bold leading-tight flex-1 text-center">Definir Equipas</h2>
             <div className="w-12"></div>
          </header>
        )}

        {renderScreen()}
        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { Screen } from '../types';

interface NavigationProps {
  currentScreen: Screen;
  setScreen: (screen: Screen) => void;
}

export const Navigation: React.FC<NavigationProps> = ({ currentScreen, setScreen }) => {
  const navItems = [
    { id: Screen.HOME, icon: 'home', label: 'Início' },
    { id: Screen.TOURNAMENT_HISTORY, icon: 'history', label: 'Histórico' },
    { id: Screen.GLOBAL_STATS, icon: 'bar_chart', label: 'Stats' },
    { id: Screen.PLAYERS, icon: 'groups', label: 'Jogadores' },
    { id: Screen.LOCATIONS, icon: 'location_on', label: 'Locais' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-background-dark/95 backdrop-blur-md border-t border-white/5 pb-6 pt-3 z-50 max-w-md mx-auto">
      <div className="flex justify-around items-center px-2">
        {navItems.map((item) => {
          const isActive = currentScreen === item.id || 
                          (item.id === Screen.TOURNAMENT_HISTORY && currentScreen === Screen.HISTORY_DETAIL) ||
                          (item.id === Screen.PLAYERS && currentScreen === Screen.PROFILE);
          return (
            <button
              key={item.id}
              onClick={() => setScreen(item.id)}
              className={`flex flex-col items-center gap-1 flex-1 transition-all ${
                isActive ? 'text-primary scale-110' : 'text-slate-500 hover:text-white'
              }`}
            >
              <span className={`material-symbols-outlined text-[22px] ${isActive ? 'fill-1' : ''}`}>
                {item.icon}
              </span>
              <span className={`text-[8px] font-black uppercase tracking-tighter ${isActive ? 'opacity-100' : 'opacity-60'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL',
  TOURNAMENT_HISTORY = 'TOURNAMENT_HISTORY'
}

export interface Player {
  id: string;
  name: string;
  lastName?: string;
  nickname?: string;
  birthDate?: string;
  hand?: 'Destro' | 'Canhoto';
  level: string; // Agora calculado dinamicamente, mas mantido para compatibilidade
  rankingPoints?: number; // Pontos atuais
  image: string;
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
  date?: string;
}

export interface Tournament {
  id: string;
  date: string;
  time: string;
  duration: number;
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[];
}

