              </div>
              <div className="fixed bottom-6 left-4 right-4 max-w-md mx-auto">
                <button onClick={() => { if(onUpdatePlayer) { onUpdatePlayer({...player, name: editFirstName, lastName: editLastName, nickname: editNickname, image: editImage}); setIsEditing(false); } }} className="w-full py-4 bg-primary text-background-dark font-bold rounded-2xl shadow-xl shadow-primary/20">Guardar Alterações</button>
              </div>
          </div>
