  { id: '4', name: 'Lisboa Racket Centre', type: 'Outdoor', address: 'Rua Alferes Malheiro, Lisboa' }
];

const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  // --- Lógica de Cálculo de Ranking Dinâmico ---
  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();

    players.forEach(p => {
        rankings.set(p.id, { 
            current: 1000, 
            history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] 
        });
    });

    const sortedHistory = [...tournamentHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;

        // Identificar Vencedor da Final (Ronda 2, Campo 1)
        const finalMatch = t.matches.find(m => m.round === 2 && m.court === 1);
        let championsIds: string[] = [];
        if (finalMatch) {
            championsIds = (finalMatch.score1 > finalMatch.score2 ? finalMatch.team1 : finalMatch.team2).map(p => p.id);
        }

        // Atualizar pontos por jogo
        t.matches.forEach(m => {
            const updatePlayer = (p: Player, won: boolean) => {
                const data = rankings.get(p.id);
                if (data) {
                    data.current += won ? 20 : -12;
                    if (data.current < 800) data.current = 800; 
                }
            };
            m.team1.forEach(p => updatePlayer(p, m.score1 > m.score2));
            m.team2.forEach(p => updatePlayer(p, m.score2 > m.score1));
        });

        // Aplicar bónus de campeão e registar histórico
        const affectedPlayersInTournament = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affectedPlayersInTournament.add(p.id)));

        affectedPlayersInTournament.forEach(pid => {
            const data = rankings.get(pid);
            if (data) {
                if (championsIds.includes(pid)) data.current += 50;

                const getLevel = (pts: number) => {
                    if (pts >= 1600) return 'Pro';
                    if (pts >= 1400) return 'Nível 3';
                    if (pts >= 1200) return 'Nível 2';
                    return 'Nível 1';
                };

                data.history.push({ 
                    date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), 
                    points: data.current,
                    level: getLevel(data.current)
                });
            }
        });
    });

    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const rankingData = playerRankings.get(p.id);
        const pts = rankingData?.current || 1000;
        const getLevel = (pts: number) => {
            if (pts >= 1600) return 'Pro';
            if (pts >= 1400) return 'Nível 3';
            if (pts >= 1200) return 'Nível 2';
            return 'Nível 1';
        };
        return { ...p, rankingPoints: pts, level: getLevel(pts) };
    });
  }, [players, playerRankings]);

  // --- Gestão de Torneio (2 Rondas) ---
  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches.map(m => ({ ...m, date: new Date().toISOString() })));
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const currentScore = team === 1 ? m.score1 : m.score2;
      const newScore = increment ? currentScore + 1 : Math.max(0, currentScore - 1);
      return { ...m, [team === 1 ? 'score1' : 'score2']: newScore };
    }));
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();
    const currentRoundMatches = matches.filter(m => m.round === currentRound);

    // Finalizar jogos da ronda atual
    const updatedMatches = matches.map(m => 
      m.round === currentRound ? { ...m, status: 'finished' as const } : m
    );

    if (currentRound === 1) {
        // Lógica de Emparelhamento da Ronda 2 (Finais)
        const matchC1 = currentRoundMatches.find(m => m.court === 1)!;
        const matchC2 = currentRoundMatches.find(m => m.court === 2)!;

        const winC1 = matchC1.score1 > matchC1.score2 ? matchC1.team1 : matchC1.team2;
        const losC1 = matchC1.score1 > matchC1.score2 ? matchC1.team2 : matchC1.team1;

        const winC2 = matchC2.score1 > matchC2.score2 ? matchC2.team1 : matchC2.team2;
        const losC2 = matchC2.score1 > matchC2.score2 ? matchC2.team2 : matchC2.team1;

        const round2Matches: Match[] = [
            { id: `m-r2-final-${Date.now()}`, team1: winC1, team2: winC2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: timestamp },
            { id: `m-r2-placement-${Date.now()}`, team1: losC1, team2: losC2, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: timestamp }
        ];

        setMatches([...updatedMatches, ...round2Matches]);
        setCurrentRound(2);
    } else {
        // Fim da Ronda 2 -> Resumo
        setMatches(updatedMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finalMatches = matches.map(m => ({ ...m, status: 'finished' as const }));
        const finishedTournament: Tournament = { 
            ...activeTournament, 
            status: 'finished', 
            matches: finalMatches, 
            date: new Date().toISOString() 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={(t) => {setActiveTournament(t); setScreen(Screen.HOME);}} onAddPlayer={(p) => setPlayers([...players, p])} onUpdateTournament={setActiveTournament} history={tournamentHistory} />;
      case Screen.PROFILE:
        return <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />;
      case Screen.LIVE_GAME:
        return <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />;
      case Screen.TOURNAMENT_SUMMARY:
        return <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />;
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return <GlobalStatsScreen history={tournamentHistory} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY:
        return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />;
      case Screen.HISTORY_DETAIL:
        return selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} /> : null;
      case Screen.TEAM_SETUP:
        return <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS:
        return <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={(p) => setPlayers([...players, p])} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} />;
      case Screen.LOCATIONS:
        return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default: return null;
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS, Screen.TOURNAMENT_HISTORY].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {renderScreen()}
        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

