import React, { useState } from 'react';
import { Screen, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  const [teamA, setTeamA] = useState<Player[]>([]);
  const [teamB, setTeamB] = useState<Player[]>([]);
  const [teamC, setTeamC] = useState<Player[]>([]);
  const [teamD, setTeamD] = useState<Player[]>([]);

  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  ).sort((a, b) => (a.nickname || a.name).localeCompare(b.nickname || b.name));

  const handlePlayerClick = (player: Player) => {
    if (teamA.length < 2) setTeamA([...teamA, player]);
    else if (teamB.length < 2) setTeamB([...teamB, player]);
    else if (teamC.length < 2) setTeamC([...teamC, player]);
    else if (teamD.length < 2) setTeamD([...teamD, player]);
  };

  const removePlayer = (player: Player, team: 'A' | 'B' | 'C' | 'D') => {
    if (team === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (team === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (team === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (team === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleRandomizeAll = () => {
    const currentAssignedIds = new Set([...teamA.map(p => p.id), ...teamB.map(p => p.id), ...teamC.map(p => p.id), ...teamD.map(p => p.id)]);
    const pool = players.filter(p => !currentAssignedIds.has(p.id));
    const shuffled = [...pool].sort(() => 0.5 - Math.random());
    let poolIndex = 0;
    const newA = [...teamA]; while(newA.length < 2 && poolIndex < shuffled.length) newA.push(shuffled[poolIndex++]); setTeamA(newA);
    const newB = [...teamB]; while(newB.length < 2 && poolIndex < shuffled.length) newB.push(shuffled[poolIndex++]); setTeamB(newB);
    const newC = [...teamC]; while(newC.length < 2 && poolIndex < shuffled.length) newC.push(shuffled[poolIndex++]); setTeamC(newC);
    const newD = [...teamD]; while(newD.length < 2 && poolIndex < shuffled.length) newD.push(shuffled[poolIndex++]); setTeamD(newD);
  };

  const handleClearAll = () => { setTeamA([]); setTeamB([]); setTeamC([]); setTeamD([]); };

  const handleStart = () => {
    if (teamA.length !== 2 || teamB.length !== 2 || teamC.length !== 2 || teamD.length !== 2) return;
    const timestamp = Date.now();
    const dateStr = new Date().toISOString();
    const matches: Match[] = [
        { id: `match-1-${timestamp}`, team1: teamA, team2: teamB, score1: 0, score2: 0, court: 1, status: 'live', round: 1, date: dateStr },
        { id: `match-2-${timestamp}`, team1: teamC, team2: teamD, score1: 0, score2: 0, court: 2, status: 'live', round: 1, date: dateStr }
    ];
    onStartTournament(matches);
  };

  const renderTeamSlot = (team: Player[], teamId: 'A' | 'B' | 'C' | 'D', colorClass: string) => (
    <div className="flex flex-col rounded-xl bg-card-dark p-2 border border-white/5 h-full">
        <div className="flex items-center justify-between mb-1.5 px-1">
            <h3 className={`text-[9px] font-black uppercase ${colorClass}`}>Equipa {teamId}</h3>
            <span className="text-[8px] font-bold text-gray-500">{team.length}/2</span>
        </div>
        <div className="flex flex-col gap-1.5 flex-1 justify-center">
            {[0, 1].map(index => {
                const player = team[index];
                return player ? (
                    <div key={player.id} className="relative flex items-center gap-2 bg-background-dark/50 p-1.5 rounded-lg border border-white/5 animate-fade-in-up">
                        <button onClick={() => removePlayer(player, teamId)} className="absolute -top-1 -right-1 size-4 rounded-full bg-red-500 text-white flex items-center justify-center border border-background-dark z-10"><span className="material-symbols-outlined text-[10px]">close</span></button>
                        {renderGlobalAvatar(player, 'size-6')}
                        <span className="text-[9px] font-black text-white truncate flex-1 uppercase tracking-tighter">{player.nickname || player.name.split(' ')[0]}</span>
                    </div>
                ) : (
                    <div key={`empty-${teamId}-${index}`} className="flex items-center gap-2 h-9 border-2 border-dashed border-white/5 bg-black/10 rounded-lg"></div>
                );
            })}
        </div>
    </div>
  );

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  return (
    <div className="flex flex-col h-screen max-h-screen overflow-hidden animate-fade-in bg-background-dark">
      <header className="px-4 pt-4 pb-2 flex items-center justify-between shrink-0">
          <div>
            <h2 className="text-xl font-black text-white">Sorteio</h2>
            <p className="text-[8px] font-bold text-gray-500 uppercase tracking-widest">3 Rondas • Equipas Fixas</p>
          </div>
          <div className="flex gap-2">
              <button onClick={handleClearAll} className="size-9 rounded-xl bg-white/5 flex items-center justify-center text-gray-400"><span className="material-symbols-outlined text-[20px]">restart_alt</span></button>
              <button onClick={handleRandomizeAll} className="size-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary"><span className="material-symbols-outlined text-[20px]">auto_fix_high</span></button>
          </div>
      </header>

      {/* Barra Horizontal de Jogadores */}
      <div className="px-4 py-2 shrink-0">
          <div className="flex overflow-x-auto gap-2 p-2 bg-card-dark rounded-xl border border-white/5 hide-scrollbar min-h-[56px] items-center">
              {availablePlayers.length === 0 && <span className="text-[9px] font-black text-gray-600 uppercase w-full text-center">Todos Selecionados</span>}
              {availablePlayers.map(p => (
                  <button key={p.id} onClick={() => handlePlayerClick(p)} className="flex-shrink-0 flex flex-col items-center gap-1 transition-transform active:scale-90">
                      {renderGlobalAvatar(p, 'size-8')}
                      <span className="text-[7px] font-black text-white uppercase truncate w-8 text-center">{p.nickname || p.name.split(' ')[0]}</span>
                  </button>
              ))}
          </div>
      </div>

      {/* Grelha de Equipas 2x2 */}
      <main className="flex-1 px-4 py-2 grid grid-cols-2 gap-3 overflow-hidden">
          <div className="space-y-3 flex flex-col">
              <div className="text-[8px] font-black text-primary uppercase text-center bg-primary/5 py-1 rounded-md border border-primary/10">Campo 1</div>
              <div className="flex-1">{renderTeamSlot(teamA, 'A', 'text-primary')}</div>
              <div className="flex-1">{renderTeamSlot(teamB, 'B', 'text-blue-400')}</div>
          </div>
          <div className="space-y-3 flex flex-col">
              <div className="text-[8px] font-black text-purple-400 uppercase text-center bg-purple-400/5 py-1 rounded-md border border-purple-400/10">Campo 2</div>
              <div className="flex-1">{renderTeamSlot(teamC, 'C', 'text-purple-400')}</div>
              <div className="flex-1">{renderTeamSlot(teamD, 'D', 'text-orange-400')}</div>
          </div>
      </main>

      {/* Rodapé Fixo */}
      <footer className="p-4 bg-background-dark/80 backdrop-blur-md border-t border-white/5 shrink-0 mb-4">
          <button 
              onClick={handleStart} 
              disabled={!isReady} 
              className={`w-full py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2 shadow-2xl transition-all ${isReady ? 'bg-primary text-background-dark scale-100' : 'bg-white/5 text-gray-700 opacity-50'}`}
          >
              <span className="material-symbols-outlined">sports_tennis</span>
              <span>INICIAR TORNEIO</span>
          </button>
      </footer>
    </div>
  );
};

