};

import React, { useState } from 'react';
import { Screen, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  const [teamA, setTeamA] = useState<Player[]>([]);
  const [teamB, setTeamB] = useState<Player[]>([]);
  const [teamC, setTeamC] = useState<Player[]>([]);
  const [teamD, setTeamD] = useState<Player[]>([]);

  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  );

  const handlePlayerClick = (player: Player) => {
    if (teamA.length < 2) setTeamA([...teamA, player]);
    else if (teamB.length < 2) setTeamB([...teamB, player]);
    else if (teamC.length < 2) setTeamC([...teamC, player]);
    else if (teamD.length < 2) setTeamD([...teamD, player]);
  };

  const removePlayer = (player: Player, teamId: 'A' | 'B' | 'C' | 'D') => {
    if (teamId === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (teamId === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (teamId === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (teamId === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleAutoAssign = () => {
    const pool = [...players].sort(() => 0.5 - Math.random());
    setTeamA([pool[0], pool[1]]);
    setTeamB([pool[2], pool[3]]);
    setTeamC([pool[4], pool[5]]);
    setTeamD([pool[6], pool[7]]);
  };

  const handleClear = () => {
    setTeamA([]); setTeamB([]); setTeamC([]); setTeamD([]);
  };

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  const handleStart = () => {
    if (!isReady) return;
    const timestamp = Date.now();
    const dateStr = new Date().toISOString();
    const matches: Match[] = [
        { id: `m1-${timestamp}`, team1: teamA, team2: teamB, score1: 0, score2: 0, court: 1, status: 'live', round: 1, date: dateStr },
        { id: `m2-${timestamp}`, team1: teamC, team2: teamD, score1: 0, score2: 0, court: 2, status: 'live', round: 1, date: dateStr }
    ];
    onStartTournament(matches);
  };

  const renderTeamCard = (team: Player[], label: string, teamId: 'A' | 'B' | 'C' | 'D', color: string) => (
    <div className={`flex flex-col bg-background-dark/60 rounded-2xl p-2 border border-white/5 h-full relative group`}>
        <div className="flex justify-between items-center mb-1 px-1">
            <span className={`text-[8px] font-black uppercase tracking-widest ${color}`}>Equipa {label}</span>
            <span className="text-[7px] font-bold text-gray-500">{team.length}/2</span>
        </div>
        <div className="flex flex-col gap-1 flex-1">
            {[0, 1].map(idx => (
                <div key={idx} className="h-9 rounded-xl border border-dashed border-white/5 bg-black/20 flex items-center px-2 overflow-hidden">
                    {team[idx] ? (
                        <div className="flex items-center gap-2 w-full animate-fade-in">
                            {renderGlobalAvatar(team[idx], 'size-6')}
                            <span className="text-[9px] font-bold text-white truncate uppercase flex-1">{team[idx].nickname || team[idx].name.split(' ')[0]}</span>
                            <button onClick={() => removePlayer(team[idx], teamId)} className="text-gray-500 hover:text-red-400">
                                <span className="material-symbols-outlined text-sm">close</span>
                            </button>
                        </div>
                    ) : (
                        <span className="text-[8px] text-gray-700 font-bold uppercase tracking-tighter w-full text-center">Vago</span>
                    )}
                </div>
            ))}
        </div>
    </div>
  );

  return (
    <div className="h-screen max-h-screen flex flex-col bg-background-dark p-4 overflow-hidden animate-fade-in">
      {/* Header Minimal */}
      <header className="flex items-center justify-between mb-3 shrink-0">
