                  {availablePlayers.length === 0 && Array.from({length: 8}).map((_, i) => (
                      <div key={i} className="size-11 rounded-full border border-dashed border-white/5 bg-black/10 opacity-20"></div>
                  ))}
                  {availablePlayers.map(p => (
                      <button 
                        key={p.id} 
                        onClick={() => handlePlayerClick(p)}
                        className="flex flex-col items-center gap-1 group active:scale-90 transition-transform"
                      >
