              className={`w-full py-4 rounded-3xl font-black text-sm flex items-center justify-center gap-3 shadow-2xl transition-all ${isReady ? 'bg-primary text-background-dark scale-100 hover:bg-primary-dark active:scale-[0.98]' : 'bg-white/5 text-gray-700 opacity-50 cursor-not-allowed'}`}
