          <p className="text-center text-[8px] font-bold text-gray-600 mt-3 uppercase tracking-widest">A Ronda 1 iniciará nos Campos 1 e 2</p>
      </footer>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location } from '../types';
import { renderGlobalAvatar, ProfileScreen } from './ProfileScreen';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
  onViewPlayer?: (id: string) => void;
}

interface PlayerStats extends Player {
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  pointsDiff: number;
  tournamentsPlayed: number;
  tournamentsWon: number;
  maxWinStreak: number;
  currentStreak: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament, onViewPlayer }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: string; data: any[] } | null>(null);

  const filteredHistory = useMemo(() => {
    const finished = history.filter(t => t.status === 'finished');
    if (timeRange === 'all') return finished;
    const now = new Date();
    return finished.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      if (timeRange === 'year') return tDate.getFullYear() === now.getFullYear();
      return true;
    });
  }, [history, timeRange]);

  const stats = useMemo(() => {
    const pStats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, p1: Player, p2: Player }>();
    const locStats = new Map<string, number>();

    let totalMatches = 0;
    let totalPoints = 0;
    let allMatches: (Match & { tournamentId: string })[] = [];

    // Initialize players
    players.forEach(p => {
      pStats.set(p.id, { 
        ...p, gamesPlayed: 0, wins: 0, losses: 0, 
        pointsScored: 0, pointsConceded: 0, pointsDiff: 0, 
        tournamentsPlayed: 0, tournamentsWon: 0, 
        maxWinStreak: 0, currentStreak: 0 
      });
    });

    filteredHistory.forEach(t => {
      locStats.set(t.locationId, (locStats.get(t.locationId) || 0) + 1);
      const tPlayers = new Set<string>();

      if (t.matches) {
        // Calculate Tournament winner
        const teamWins = new Map<string, number>();
        const teamDiff = new Map<string, number>();

        t.matches.forEach(m => {
          allMatches.push({ ...m, tournamentId: t.id });
          totalMatches++;
          totalPoints += (m.score1 + m.score2);

          const k1 = m.team1.map(p => p.id).sort().join('-');
          const k2 = m.team2.map(p => p.id).sort().join('-');

          // Duo stats
          if (!duoStats.has(k1)) duoStats.set(k1, { wins: 0, games: 0, p1: m.team1[0], p2: m.team1[1] });
          if (!duoStats.has(k2)) duoStats.set(k2, { wins: 0, games: 0, p1: m.team2[0], p2: m.team2[1] });

          const ds1 = duoStats.get(k1)!; ds1.games++;
          const ds2 = duoStats.get(k2)!; ds2.games++;

          if (m.score1 > m.score2) {
             ds1.wins++;
             teamWins.set(k1, (teamWins.get(k1) || 0) + 1);
          } else {
             ds2.wins++;
             teamWins.set(k2, (teamWins.get(k2) || 0) + 1);
          }

          // Individual stats
          [m.team1, m.team2].forEach((team, idx) => {
             const isT1 = idx === 0;
             const won = isT1 ? m.score1 > m.score2 : m.score2 > m.score1;
             team.forEach(p => {
                tPlayers.add(p.id);
                const ps = pStats.get(p.id);
                if (ps) {
                  ps.gamesPlayed++;
                  ps.pointsScored += isT1 ? m.score1 : m.score2;
                  ps.pointsConceded += isT1 ? m.score2 : m.score1;
                  ps.pointsDiff += isT1 ? (m.score1 - m.score2) : (m.score2 - m.score1);
                  if (won) {
                    ps.wins++;
                    ps.currentStreak++;
                    ps.maxWinStreak = Math.max(ps.maxWinStreak, ps.currentStreak);
                  } else {
                    ps.losses++;
                    ps.currentStreak = 0;
                  }
                }
             });
          });
        });

        const sortedTeams = Array.from(teamWins.entries()).sort((a,b) => b[1] - a[1]);
        if (sortedTeams.length > 0) {
          const winnerIds = sortedTeams[0][0].split('-');
          winnerIds.forEach(id => {
             const ps = pStats.get(id);
             if (ps) ps.tournamentsWon++;
          });
        }
      }
      tPlayers.forEach(id => {
        const ps = pStats.get(id);
        if (ps) ps.tournamentsPlayed++;
      });
    });

    // Derivações
    const sortedPlayers = Array.from(pStats.values());
    const duos = Array.from(duoStats.values())
      .filter(d => d.games >= 2)
      .map(d => ({ ...d, winRate: Math.round((d.wins / d.games) * 100) }))
      .sort((a,b) => b.winRate - a.winRate || b.games - a.games);

    const locationsRanked = Array.from(locStats.entries())
      .map(([id, count]) => ({ ...locations.find(l => l.id === id), count }))
      .sort((a,b) => b.count - a.count);

    // Jogos Equilibrados/Desequilibrados
    const matchEquilibrium = [...allMatches].sort((a,b) => Math.abs(a.score1 - a.score2) - Math.abs(b.score1 - b.score2));

    // Torneios Equilibrados (Menor média de diferença)
    const tournamentEquilibrium = filteredHistory.map(t => {
      const diffs = t.matches?.map(m => Math.abs(m.score1 - m.score2)) || [];
      const avgDiff = diffs.length > 0 ? diffs.reduce((a,b) => a+b, 0) / diffs.length : 99;
      const totalPts = t.matches?.reduce((a,b) => a + b.score1 + b.score2, 0) || 0;
      return { ...t, avgDiff, totalPts, locName: locations.find(l => l.id === t.locationId)?.name };
    }).sort((a,b) => a.avgDiff - b.avgDiff);

    const tournamentMostPoints = [...tournamentEquilibrium].sort((a,b) => b.totalPts - a.totalPts);

    return {
      totalTournaments: filteredHistory.length,
      totalMatches,
      totalPoints,
      activePlayers: sortedPlayers.filter(p => p.gamesPlayed > 0),
      mostWins: [...sortedPlayers].sort((a,b) => b.wins - a.wins),
      mostAttendance: [...sortedPlayers].sort((a,b) => b.tournamentsPlayed - a.tournamentsPlayed),
      mostPointsELO: [...sortedPlayers].sort((a,b) => (b.rankingPoints || 0) - (a.rankingPoints || 0)),
      mostStreaks: [...sortedPlayers].sort((a,b) => b.maxWinStreak - a.maxWinStreak),
      duos,
      locationsRanked,
      matchEquilibrium,
      tournamentEquilibrium,
      tournamentMostPoints
    };
  }, [filteredHistory, players, locations]);

  const StatCard = ({ icon, label, value, subValue, color, onClick }: any) => (
    <button 
      onClick={onClick}
      className="flex flex-col bg-card-dark p-4 rounded-3xl border border-white/5 shadow-sm active:scale-95 transition-all text-left group"
    >
      <div className={`size-10 rounded-2xl bg-${color}/10 flex items-center justify-center mb-3 group-hover:bg-${color}/20`}>
        <span className={`material-symbols-outlined text-${color}`}>{icon}</span>
      </div>
      <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-1">{label}</p>
      <div className="flex items-baseline gap-2">
        <span className="text-xl font-black text-white">{value}</span>
        {subValue && <span className="text-[10px] font-bold text-gray-500">{subValue}</span>}
      </div>
    </button>
  );

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="flex items-center justify-between mt-2">
        <div>
          <h1 className="text-2xl font-black text-white">Central de <span className="text-primary">Estatísticas</span></h1>
          <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">Performance Global • {timeRange.toUpperCase()}</p>
        </div>
        <div className="flex bg-white/5 rounded-xl p-1 border border-white/5">
          {['all', 'month', 'year'].map(r => (
            <button key={r} onClick={() => setTimeRange(r as any)} className={`px-3 py-1.5 text-[9px] font-black rounded-lg transition-all ${timeRange === r ? 'bg-primary text-background-dark' : 'text-gray-500 hover:text-white'}`}>{r==='all'?'TUDO':r==='month'?'MÊS':'ANO'}</button>
          ))}
        </div>
      </header>

      {/* Grid de Métricas de Volume */}
      <section className="grid grid-cols-2 gap-3">
        <StatCard 
          icon="emoji_events" label="Torneios" value={stats.totalTournaments} 
          color="yellow-500" onClick={() => setDrillDown({ title: 'Torneios Realizados', type: 'tournaments', data: filteredHistory })}
        />
        <StatCard 
          icon="sports_tennis" label="Jogos" value={stats.totalMatches} subValue={`${stats.totalPoints} pts`}
          color="primary" onClick={() => setDrillDown({ title: 'Histórico de Jogos', type: 'matches', data: stats.matchEquilibrium })}
        />
        <StatCard 
          icon="group" label="Ativos" value={stats.activePlayers.length} 
          color="emerald-400" onClick={() => setDrillDown({ title: 'Ranking de Assiduidade', type: 'players', data: stats.mostAttendance })}
        />
        <StatCard 
          icon="location_on" label="Clube Top" value={stats.locationsRanked[0]?.name || 'N/A'} 
          color="purple-400" onClick={() => setDrillDown({ title: 'Frequência de Locais', type: 'locations', data: stats.locationsRanked })}
        />
      </section>

      {/* Rankings Específicos */}
      <section className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Destaques Individuais</h3>
          <span className="material-symbols-outlined text-gray-700">trending_up</span>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Ranking de Vitórias', type: 'players-wins', data: stats.mostWins })} className="bg-card-dark/50 p-4 rounded-3xl border border-white/5 flex flex-col gap-2">
            <span className="text-[8px] font-black text-primary uppercase">Mais Vitórias</span>
            <div className="flex items-center gap-2">
              {stats.mostWins[0] && renderGlobalAvatar(stats.mostWins[0], 'size-7')}
              <span className="text-xs font-black text-white">{stats.mostWins[0]?.name.split(' ')[0] || '-'}</span>
            </div>
          </button>
          <button onClick={() => setDrillDown({ title: 'Maiores Sequências', type: 'players-streaks', data: stats.mostStreaks })} className="bg-card-dark/50 p-4 rounded-3xl border border-white/5 flex flex-col gap-2">
            <span className="text-[8px] font-black text-orange-500 uppercase">Win Streak Record</span>
            <div className="flex items-center gap-2">
               <span className="text-xl font-black text-white">{stats.mostStreaks[0]?.maxWinStreak || 0}</span>
               <span className="text-[10px] font-bold text-gray-500 uppercase">Jogos</span>
            </div>
          </button>
        </div>
      </section>

      {/* Duplas e Equilíbrio */}
      <section className="space-y-4">
        <div className="bg-gradient-to-br from-primary/10 to-card-dark p-6 rounded-[2.5rem] border border-primary/20 shadow-xl" onClick={() => setDrillDown({ title: 'Ranking de Duplas', type: 'duos', data: stats.duos })}>
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-[9px] font-black text-primary uppercase tracking-[0.2em] mb-1">Dupla Imbatível</p>
              <h4 className="text-lg font-black text-white">{stats.duos[0] ? `${stats.duos[0].p1.name.split(' ')[0]} & ${stats.duos[0].p2.name.split(' ')[0]}` : 'Sem dados'}</h4>
            </div>
            <div className="bg-primary/20 p-2 rounded-xl text-primary"><span className="material-symbols-outlined">groups</span></div>
          </div>
          <div className="flex items-center gap-6">
            <div><p className="text-[10px] font-bold text-gray-500 uppercase">Win Rate</p><p className="text-xl font-black text-primary">{stats.duos[0]?.winRate || 0}%</p></div>
            <div className="h-8 w-px bg-white/10"></div>
            <div><p className="text-[10px] font-bold text-gray-500 uppercase">Jogos</p><p className="text-xl font-black text-white">{stats.duos[0]?.games || 0}</p></div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Equilíbrio de Torneios', type: 'tournaments-eq', data: stats.tournamentEquilibrium })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-1">
             <span className="text-[8px] font-black text-gray-500 uppercase">Torneio + Equilibrado</span>
             <p className="text-xs font-black text-white truncate">{stats.tournamentEquilibrium[0]?.locName || '-'}</p>
             <p className="text-[9px] text-emerald-400 font-bold">±{stats.tournamentEquilibrium[0]?.avgDiff.toFixed(1)} pts/jogo</p>
          </button>
          <button onClick={() => setDrillDown({ title: 'Recordes de Pontuação', type: 'tournaments-pts', data: stats.tournamentMostPoints })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-1">
             <span className="text-[8px] font-black text-gray-500 uppercase">Torneio + Pontuado</span>
             <p className="text-xs font-black text-white truncate">{stats.tournamentMostPoints[0]?.locName || '-'}</p>
             <p className="text-[9px] text-primary font-bold">{stats.tournamentMostPoints[0]?.totalPts || 0} pts totais</p>
          </button>
        </div>
      </section>

      {/* Tabela de Classificação Total */}
      <section className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Classificação Total</h3>
          <span className="text-[9px] font-bold text-primary">{stats.mostPointsELO.length} Jogadores</span>
        </div>
        <div className="bg-card-dark rounded-[2rem] border border-white/5 overflow-hidden">
          <div className="grid grid-cols-12 gap-2 p-4 text-[8px] font-black text-gray-600 uppercase border-b border-white/5">
             <div className="col-span-2 text-center">POS</div>
             <div className="col-span-6">JOGADOR</div>
             <div className="col-span-2 text-center">VIT</div>
             <div className="col-span-2 text-right">ELO</div>
          </div>
          {stats.mostPointsELO.slice(0, 10).map((p, i) => (
            <button 
              key={p.id} 
              onClick={() => onViewPlayer?.(p.id)}
              className="grid grid-cols-12 gap-2 p-4 items-center hover:bg-white/5 transition-colors w-full text-left"
            >
              <div className="col-span-2 flex justify-center"><span className={`size-6 flex items-center justify-center rounded-lg text-[10px] font-black ${i===0?'bg-yellow-500 text-black':i===1?'bg-gray-400 text-black':i===2?'bg-orange-700 text-white':'bg-white/5 text-gray-500'}`}>{i+1}</span></div>
              <div className="col-span-6 flex items-center gap-3">
                {renderGlobalAvatar(p, 'size-8')}
                <div><p className="text-xs font-black text-white truncate">{p.nickname || p.name}</p><p className="text-[8px] text-gray-500 uppercase">{p.level}</p></div>
              </div>
              <div className="col-span-2 text-center text-xs font-bold text-gray-400">{p.wins}</div>
              <div className="col-span-2 text-right text-xs font-black text-primary">{p.rankingPoints}</div>
            </button>
          ))}
          <button onClick={() => setDrillDown({ title: 'Ranking Completo', type: 'players-elo', data: stats.mostPointsELO })} className="w-full py-4 text-[9px] font-black text-gray-500 uppercase hover:text-white transition-colors bg-white/5">Ver Ranking Completo</button>
        </div>
      </section>

      {/* Drill Down Modal */}
      {drillDown && (
        <div className="fixed inset-0 z-[100] bg-background-dark/98 backdrop-blur-xl animate-fade-in flex flex-col p-4">
          <header className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-xl font-black text-white">{drillDown.title}</h2>
              <p className="text-[9px] font-bold text-primary uppercase tracking-widest">{drillDown.data.length} Entradas Encontradas</p>
            </div>
            <button onClick={() => setDrillDown(null)} className="size-10 rounded-full bg-white/10 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
          </header>

          <div className="flex-1 overflow-y-auto space-y-3 pb-24 hide-scrollbar">
            {drillDown.type === 'players' || drillDown.type === 'players-wins' || drillDown.type === 'players-streaks' || drillDown.type === 'players-elo' ? (
               drillDown.data.map((p: any, i) => (
                 <div key={p.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                   <div className="flex items-center gap-4">
                      <span className="text-[10px] font-black text-gray-600 w-4">{i+1}</span>
                      {renderGlobalAvatar(p, 'size-10')}
                      <div><p className="text-sm font-black text-white">{p.nickname || p.name}</p><p className="text-[9px] text-gray-500 uppercase">{p.level}</p></div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs font-black text-primary">
                        {drillDown.type === 'players-wins' ? `${p.wins}V` : 
                         drillDown.type === 'players-streaks' ? `${p.maxWinStreak} Streak` :
                         drillDown.type === 'players-elo' ? `${p.rankingPoints} pts` :
                         `${p.tournamentsPlayed} Torneios`}
                      </p>
                   </div>
                 </div>
               ))
            ) : drillDown.type === 'duos' ? (
              drillDown.data.map((d: any, i) => (
                <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex -space-x-3">{renderGlobalAvatar(d.p1, 'size-9')}{renderGlobalAvatar(d.p2, 'size-9')}</div>
                    <div><p className="text-xs font-black text-white">{d.p1.name.split(' ')[0]} & {d.p2.name.split(' ')[0]}</p><p className="text-[9px] text-gray-500">{d.games} Jogos</p></div>
                  </div>
                  <div className="text-right"><p className="text-sm font-black text-primary">{d.winRate}% WR</p></div>
                </div>
              ))
            ) : drillDown.type === 'tournaments' || drillDown.type === 'tournaments-eq' || drillDown.type === 'tournaments-pts' ? (
              drillDown.data.map((t: any) => (
                <button key={t.id} onClick={() => { onViewTournament?.(t); setDrillDown(null); }} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between w-full text-left">
                  <div>
                    <p className="text-[9px] font-black text-primary uppercase">{new Date(t.date).toLocaleDateString()}</p>
                    <p className="text-sm font-black text-white">{locations.find(l => l.id === t.locationId)?.name}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-white">
                      {drillDown.type === 'tournaments-eq' ? `±${t.avgDiff.toFixed(1)} diff` : 
                       drillDown.type === 'tournaments-pts' ? `${t.totalPts} pts` :
                       `${t.matches?.length} Jogos`}
                    </p>
                  </div>
                </button>
              ))
            ) : drillDown.type === 'matches' ? (
               drillDown.data.map((m: any, i: number) => (
                 <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between gap-3">
                   <div className="flex-1 text-[9px] font-black text-white text-right">{m.team1.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</div>
                   <div className="bg-background-dark px-3 py-1 rounded-xl border border-white/5 flex items-center gap-2">
                     <span className={`text-sm font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-500'}`}>{m.score1}</span>
                     <span className="text-[10px] text-gray-800">-</span>
                     <span className={`text-sm font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-500'}`}>{m.score2}</span>
                   </div>
                   <div className="flex-1 text-[9px] font-black text-white text-left">{m.team2.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</div>
                 </div>
               ))
            ) : drillDown.type === 'locations' ? (
              drillDown.data.map((loc: any, i) => (
                <div key={loc.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-gray-600">{i+1}</span>
                    <div><p className="text-sm font-black text-white">{loc.name}</p><p className="text-[9px] text-gray-500 uppercase">{loc.type}</p></div>
                  </div>
                  <div className="bg-primary/10 px-3 py-1 rounded-lg text-primary text-[10px] font-black">{loc.count} T</div>
                </div>
              ))
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
};

