const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));

    const sortedHistory = [...tournamentHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;

        const teamStats = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamStats.has(k1)) teamStats.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamStats.has(k2)) teamStats.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamStats.get(k1)!, s2 = teamStats.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const champions = Array.from(teamStats.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff)[0];
        const championsIds = champions?.pids || [];

        t.matches.forEach(m => {
            const updatePlayer = (p: Player, won: boolean) => {
                const data = rankings.get(p.id);
                if (data) {
                    data.current += won ? 20 : -12;
                    if (data.current < 800) data.current = 800; 
                }
            };
            m.team1.forEach(p => updatePlayer(p, m.score1 > m.score2));
            m.team2.forEach(p => updatePlayer(p, m.score2 > m.score1));
        });

        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const data = rankings.get(pid);
            if (data) {
                if (championsIds.includes(pid)) data.current += 50;
                const getLevel = (pts: number) => {
                    if (pts >= 1600) return 'Pro';
                    if (pts >= 1400) return 'Nível 3';
                    if (pts >= 1200) return 'Nível 2';
                    return 'Nível 1';
                };
                data.history.push({ 
                    date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), 
                    points: data.current,
                    level: getLevel(data.current)
                });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const rankingData = playerRankings.get(p.id);
        const pts = rankingData?.current || 1000;
        const getLevel = (pts: number) => {
            if (pts >= 1600) return 'Pro';
            if (pts >= 1400) return 'Nível 3';
            if (pts >= 1200) return 'Nível 2';
            return 'Nível 1';
        };
        return { ...p, rankingPoints: pts, level: getLevel(pts) };
    });
  }, [players, playerRankings]);

  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches.map(m => ({ ...m, date: new Date().toISOString() })));
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();
    const currentRoundMatches = matches.filter(m => m.round === currentRound);
    const updatedAllMatches = matches.map(m => m.round === currentRound ? { ...m, status: 'finished' as const } : m);

    if (currentRound === 1) {
        // Regra Ronda 2: Vencedores ficam, Derrotados trocam
        const m1 = currentRoundMatches.find(m => m.court === 1)!;
        const m2 = currentRoundMatches.find(m => m.court === 2)!;

        const win1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
        const los1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
        const win2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
        const los2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

        // R2: Campo 1: Win1 vs Los2 | Campo 2: Win2 vs Los1
        const round2: Match[] = [
            { id: `m-r2-c1-${Date.now()}`, team1: win1, team2: los2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: timestamp },
            { id: `m-r2-c2-${Date.now()}`, team1: win2, team2: los1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: timestamp }
        ];
        setMatches([...updatedAllMatches, ...round2]);
        setCurrentRound(2);
    } else if (currentRound === 2) {
        // Regra Ronda 3: Duplas que ainda não jogaram (A-C e B-D)
        // Recuperamos as equipas originais da Ronda 1
        const m1r1 = updatedAllMatches.find(m => m.round === 1 && m.court === 1)!;
        const m2r1 = updatedAllMatches.find(m => m.round === 1 && m.court === 2)!;

        const a = m1r1.team1, b = m1r1.team2, c = m2r1.team1, d = m2r1.team2;

        const round3: Match[] = [
            { id: `m-r3-c1-${Date.now()}`, team1: a, team2: c, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: timestamp },
            { id: `m-r3-c2-${Date.now()}`, team1: b, team2: d, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: timestamp }
        ];
        setMatches([...updatedAllMatches, ...round3]);
        setCurrentRound(3);
    } else {
        setMatches(updatedAllMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const current = team === 1 ? m.score1 : m.score2;
      return { ...m, [team === 1 ? 'score1' : 'score2']: increment ? current + 1 : Math.max(0, current - 1) };
    }));
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finishedTournament: Tournament = { 
            ...activeTournament, 
            status: 'finished', 
            matches: matches.map(m => ({...m, status: 'finished'})), 
            date: new Date().toISOString() 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME:
        return <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={(t) => {setActiveTournament(t); setScreen(Screen.HOME);}} onAddPlayer={(p) => setPlayers([...players, p])} onUpdateTournament={setActiveTournament} history={tournamentHistory} />;
      case Screen.PROFILE:
        return <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />;
      case Screen.LIVE_GAME:
        return <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />;
      case Screen.TOURNAMENT_SUMMARY:
        return <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />;
      case Screen.TOURNAMENT_RESULTS:
        return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS:
        return <GlobalStatsScreen history={tournamentHistory} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY:
        return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />;
      case Screen.HISTORY_DETAIL:
        return selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} /> : null;
      case Screen.TEAM_SETUP:
        return <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS:
        return <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={(p) => setPlayers([...players, p])} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} />;
      case Screen.LOCATIONS:
        return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default: return null;
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS, Screen.TOURNAMENT_HISTORY].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {renderScreen()}
        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Screen, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  const [teamA, setTeamA] = useState<Player[]>([]);
  const [teamB, setTeamB] = useState<Player[]>([]);
  const [teamC, setTeamC] = useState<Player[]>([]);
  const [teamD, setTeamD] = useState<Player[]>([]);

  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  );

  const handlePlayerClick = (player: Player) => {
    if (teamA.length < 2) setTeamA([...teamA, player]);
    else if (teamB.length < 2) setTeamB([...teamB, player]);
    else if (teamC.length < 2) setTeamC([...teamC, player]);
    else if (teamD.length < 2) setTeamD([...teamD, player]);
  };

  const removePlayer = (player: Player, teamId: 'A' | 'B' | 'C' | 'D') => {
    if (teamId === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (teamId === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (teamId === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (teamId === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleAutoAssign = () => {
    const pool = [...players].sort(() => 0.5 - Math.random());
    setTeamA([pool[0], pool[1]]);
    setTeamB([pool[2], pool[3]]);
    setTeamC([pool[4], pool[5]]);
    setTeamD([pool[6], pool[7]]);
  };

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  const handleStart = () => {
    if (!isReady) return;
    const timestamp = Date.now();
    const dateStr = new Date().toISOString();
    // Regra: Ronda 1 - A vs B e C vs D
    const matches: Match[] = [
        { id: `m1-${timestamp}`, team1: teamA, team2: teamB, score1: 0, score2: 0, court: 1, status: 'live', round: 1, date: dateStr },
        { id: `m2-${timestamp}`, team1: teamC, team2: teamD, score1: 0, score2: 0, court: 2, status: 'live', round: 1, date: dateStr }
    ];
    onStartTournament(matches);
  };

  const renderTeamCard = (team: Player[], label: string, teamId: 'A' | 'B' | 'C' | 'D', color: string) => (
    <div className="flex flex-col bg-background-dark/50 rounded-2xl p-2.5 border border-white/5 h-full relative group">
        <div className="flex justify-between items-center mb-1.5 px-1">
            <span className={`text-[9px] font-black uppercase tracking-widest ${color}`}>Equipa {label}</span>
            <span className="text-[8px] font-bold text-gray-500">{team.length}/2</span>
        </div>
        <div className="flex flex-col gap-1.5 flex-1">
            {[0, 1].map(idx => (
                <div key={idx} className="h-10 rounded-xl border border-dashed border-white/10 bg-black/20 flex items-center px-2 overflow-hidden">
                    {team[idx] ? (
                        <div className="flex items-center gap-2 w-full animate-fade-in">
                            {renderGlobalAvatar(team[idx], 'size-7')}
                            <span className="text-[9px] font-bold text-white truncate uppercase flex-1">{team[idx].nickname || team[idx].name.split(' ')[0]}</span>
                            <button onClick={() => removePlayer(team[idx], teamId)} className="text-gray-500 hover:text-red-400">
                                <span className="material-symbols-outlined text-[16px]">close</span>
                            </button>
                        </div>
                    ) : (
                        <span className="text-[7px] text-gray-700 font-bold uppercase tracking-tighter w-full text-center">Aguardando</span>
                    )}
                </div>
            ))}
        </div>
    </div>
  );

  return (
    <div className="h-screen max-h-screen flex flex-col bg-background-dark p-4 overflow-hidden animate-fade-in">
      <header className="flex items-center justify-between mb-4 shrink-0 px-2">
          <button onClick={() => setScreen(Screen.HOME)} className="size-10 rounded-full bg-white/5 flex items-center justify-center">
              <span className="material-symbols-outlined text-[20px]">arrow_back</span>
          </button>
          <div className="text-center">
              <h2 className="text-lg font-black text-white leading-none">SORTEIO</h2>
              <span className="text-[9px] font-bold text-primary uppercase tracking-[0.2em]">Equipas & Campos</span>
          </div>
          <button onClick={() => { setTeamA([]); setTeamB([]); setTeamC([]); setTeamD([]); }} className="size-10 rounded-full bg-white/5 flex items-center justify-center text-gray-500">
              <span className="material-symbols-outlined text-[20px]">restart_alt</span>
          </button>
      </header>

      {/* Main Container "Retângulo Azul" - Otimizado para largura total */}
      <main className="flex-1 bg-gradient-to-br from-primary/15 via-card-dark to-card-dark rounded-[2.5rem] border border-primary/30 p-4 shadow-2xl flex flex-col gap-5 overflow-hidden">

          {/* Jogadores Disponíveis (Pool 4x2) */}
          <section className="shrink-0 bg-black/20 p-3 rounded-3xl border border-white/5">
              <div className="flex justify-between items-center mb-3 px-1">
                  <h3 className="text-[9px] font-black text-gray-500 uppercase tracking-[0.2em]">Pool de Jogadores</h3>
                  <button onClick={handleAutoAssign} className="flex items-center gap-1.5 text-[9px] font-black text-primary uppercase border border-primary/30 px-3 py-1.5 rounded-xl bg-primary/10">
                      <span className="material-symbols-outlined text-[14px]">auto_fix_high</span>
                      Sorteio Aleatório
                  </button>
              </div>
              <div className="grid grid-cols-4 gap-3">
                  {players.map(p => {
                      const isAssigned = teamA.find(ta => ta.id === p.id) || teamB.find(tb => tb.id === p.id) || teamC.find(tc => tc.id === p.id) || teamD.find(td => td.id === p.id);
                      return (
                          <button 
                            key={p.id} 
                            onClick={() => !isAssigned && handlePlayerClick(p)}
                            disabled={!!isAssigned}
                            className={`flex flex-col items-center gap-1.5 group transition-all duration-300 ${isAssigned ? 'opacity-20 scale-90' : 'active:scale-90'}`}
                          >
                              <div className="relative">
                                {renderGlobalAvatar(p, 'size-12')}
                                {!isAssigned && (
                                    <div className="absolute -bottom-1 -right-1 bg-primary text-black rounded-full size-4 flex items-center justify-center border-2 border-card-dark">
                                        <span className="material-symbols-outlined text-[10px] font-black">add</span>
                                    </div>
                                )}
                              </div>
                              <span className="text-[8px] font-black text-white uppercase truncate w-12 text-center">{p.nickname || p.name.split(' ')[0]}</span>
                          </button>
                      );
                  })}
              </div>
          </section>

          {/* Equipas Grid 2x2 - Largura Total */}
          <section className="flex-1 grid grid-cols-2 gap-3 pb-2">
              {renderTeamCard(teamA, 'A', 'A', 'text-primary')}
              {renderTeamCard(teamB, 'B', 'B', 'text-blue-400')}
              {renderTeamCard(teamC, 'C', 'C', 'text-purple-400')}
              {renderTeamCard(teamD, 'D', 'D', 'text-orange-400')}
          </section>
      </main>

      {/* Footer / Ação */}
      <footer className="mt-5 shrink-0 pb-4">
          <button 
              onClick={handleStart}
              disabled={!isReady}
              className={`w-full py-5 rounded-[2rem] font-black text-sm flex items-center justify-center gap-3 shadow-2xl transition-all ${isReady ? 'bg-primary text-background-dark scale-100 hover:shadow-primary/30 active:scale-[0.97]' : 'bg-white/5 text-gray-700 opacity-50 cursor-not-allowed'}`}
          >
              <span className="material-symbols-outlined font-black">play_arrow</span>
              <span>COMEÇAR RONDA 1</span>
          </button>
          <p className="text-center text-[8px] font-bold text-gray-600 mt-4 uppercase tracking-[0.3em]">C1: A vs B  •  C2: C vs D</p>
      </footer>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location, Screen } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
  onViewPlayer?: (id: string) => void;
}

interface PlayerStats extends Player {
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  tournamentsPlayed: number;
  tournamentsWon: number;
  maxWinStreak: number;
  currentStreak: number;
}

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament, onViewPlayer }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: string; data: any[] } | null>(null);

  const filteredHistory = useMemo(() => {
    const finished = history.filter(t => t.status === 'finished');
    if (timeRange === 'all') return finished;
    const now = new Date();
    return finished.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      if (timeRange === 'year') return tDate.getFullYear() === now.getFullYear();
      return true;
    });
  }, [history, timeRange]);

  const stats = useMemo(() => {
    const pStats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, p1: Player, p2: Player }>();
    const locStats = new Map<string, number>();

    let totalMatches = 0;
    let totalPoints = 0;
    let allMatches: (Match & { tournamentId: string, locationName: string })[] = [];

    players.forEach(p => {
      pStats.set(p.id, { 
        ...p, gamesPlayed: 0, wins: 0, losses: 0, 
        pointsScored: 0, pointsConceded: 0, 
        tournamentsPlayed: 0, tournamentsWon: 0, 
        maxWinStreak: 0, currentStreak: 0 
      });
    });

    filteredHistory.forEach(t => {
      const locName = locations.find(l => l.id === t.locationId)?.name || 'Local N/A';
      locStats.set(t.locationId, (locStats.get(t.locationId) || 0) + 1);
      const tPlayers = new Set<string>();

      if (t.matches) {
        const teamWins = new Map<string, number>();

        t.matches.forEach(m => {
          allMatches.push({ ...m, tournamentId: t.id, locationName });
          totalMatches++;
          totalPoints += (m.score1 + m.score2);

          const k1 = m.team1.map(p => p.id).sort().join('-');
          const k2 = m.team2.map(p => p.id).sort().join('-');

          if (!duoStats.has(k1)) duoStats.set(k1, { wins: 0, games: 0, p1: m.team1[0], p2: m.team1[1] });
          if (!duoStats.has(k2)) duoStats.set(k2, { wins: 0, games: 0, p1: m.team2[0], p2: m.team2[1] });

          const ds1 = duoStats.get(k1)!; ds1.games++;
          const ds2 = duoStats.get(k2)!; ds2.games++;

          if (m.score1 > m.score2) {
             ds1.wins++; teamWins.set(k1, (teamWins.get(k1) || 0) + 1);
          } else if (m.score2 > m.score1) {
             ds2.wins++; teamWins.set(k2, (teamWins.get(k2) || 0) + 1);
          }

          [m.team1, m.team2].forEach((team, idx) => {
             const isT1 = idx === 0;
             const won = isT1 ? m.score1 > m.score2 : m.score2 > m.score1;
             team.forEach(p => {
                tPlayers.add(p.id);
                const ps = pStats.get(p.id);
                if (ps) {
                  ps.gamesPlayed++;
                  ps.pointsScored += isT1 ? m.score1 : m.score2;
                  ps.pointsConceded += isT1 ? m.score2 : m.score1;
                  if (won) { ps.wins++; ps.currentStreak++; ps.maxWinStreak = Math.max(ps.maxWinStreak, ps.currentStreak); }
                  else { ps.losses++; ps.currentStreak = 0; }
                }
             });
          });
        });

        const sortedTeams = Array.from(teamWins.entries()).sort((a,b) => b[1] - a[1]);
        if (sortedTeams.length > 0) {
          sortedTeams[0][0].split('-').forEach(id => { const ps = pStats.get(id); if (ps) ps.tournamentsWon++; });
        }
      }
      tPlayers.forEach(id => { const ps = pStats.get(id); if (ps) ps.tournamentsPlayed++; });
    });

    const activePlayers = Array.from(pStats.values()).filter(p => p.gamesPlayed > 0);
    const duos = Array.from(duoStats.values())
      .filter(d => d.games >= 2)
      .map(d => ({ ...d, winRate: Math.round((d.wins / d.games) * 100) }))
      .sort((a,b) => b.winRate - a.winRate || b.games - a.games);

    const locationsRanked = Array.from(locStats.entries())
      .map(([id, count]) => ({ ...locations.find(l => l.id === id), count }))
      .sort((a,b) => b.count - a.count);

    // Jogos Equilibrados/Desequilibrados
    const matchEquilibrium = [...allMatches].sort((a,b) => Math.abs(a.score1 - a.score2) - Math.abs(b.score1 - b.score2));
    const matchUnbalanced = [...allMatches].sort((a,b) => Math.abs(b.score1 - b.score2) - Math.abs(a.score1 - a.score2));

    // Torneios Equilibrados
    const tournamentEquilibrium = filteredHistory.map(t => {
      const diffs = t.matches?.map(m => Math.abs(m.score1 - m.score2)) || [];
      const avgDiff = diffs.length > 0 ? diffs.reduce((a,b) => a+b, 0) / diffs.length : 99;
      const totalPts = t.matches?.reduce((a,b) => a + b.score1 + b.score2, 0) || 0;
      return { ...t, avgDiff, totalPts, locName: locations.find(l => l.id === t.locationId)?.name };
    }).sort((a,b) => a.avgDiff - b.avgDiff);

    const tournamentMostPoints = [...tournamentEquilibrium].sort((a,b) => b.totalPts - a.totalPts);

    return {
      totalTournaments: filteredHistory.length,
      totalMatches,
      totalPoints,
      activePlayers,
      mostWins: [...activePlayers].sort((a,b) => b.wins - a.wins),
      mostAttendance: [...activePlayers].sort((a,b) => b.tournamentsPlayed - a.tournamentsPlayed),
      mostPointsELO: [...activePlayers].sort((a,b) => (b.rankingPoints || 0) - (a.rankingPoints || 0)),
      mostStreaks: [...activePlayers].sort((a,b) => b.maxWinStreak - a.maxWinStreak),
      duos,
      locationsRanked,
      matchEquilibrium,
      matchUnbalanced,
      tournamentEquilibrium,
      tournamentMostPoints
    };
  }, [filteredHistory, players, locations]);

  const StatBox = ({ label, value, sub, icon, color, onClick }: any) => (
    <button onClick={onClick} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left active:scale-95 transition-all group">
      <div className={`size-10 rounded-2xl bg-${color}/10 flex items-center justify-center text-${color} group-hover:bg-${color}/20 transition-colors`}>
        <span className="material-symbols-outlined">{icon}</span>
      </div>
      <div>
        <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest">{label}</p>
        <p className="text-xl font-black text-white">{value}</p>
        {sub && <p className="text-[9px] font-bold text-gray-600 uppercase">{sub}</p>}
      </div>
    </button>
  );

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-white">Central <span className="text-primary">Global</span></h1>
          <p className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em]">Dashboard de Performance</p>
        </div>
        <div className="flex bg-white/5 rounded-xl p-1 border border-white/5">
          {['all', 'month', 'year'].map(r => (
            <button key={r} onClick={() => setTimeRange(r as any)} className={`px-3 py-1.5 text-[8px] font-black rounded-lg transition-all ${timeRange === r ? 'bg-primary text-background-dark' : 'text-gray-500'}`}>{r === 'all' ? 'TOTAL' : r === 'month' ? 'MÊS' : 'ANO'}</button>
          ))}
        </div>
      </header>

      {/* Overview Grid */}
      <section className="grid grid-cols-2 gap-3">
        <StatBox label="Torneios" value={stats.totalTournaments} icon="emoji_events" color="yellow-500" onClick={() => setDrillDown({ title: 'Torneios Realizados', type: 'tournaments', data: filteredHistory })} />
        <StatBox label="Jogos" value={stats.totalMatches} sub={`${stats.totalPoints} Pontos`} icon="sports_tennis" color="primary" onClick={() => setDrillDown({ title: 'Histórico de Jogos', type: 'matches', data: stats.matchEquilibrium })} />
        <StatBox label="Ativos" value={stats.activePlayers.length} icon="group" color="emerald-400" onClick={() => setDrillDown({ title: 'Jogadores Ativos', type: 'players-attendance', data: stats.mostAttendance })} />
        <StatBox label="Clube Favorito" value={stats.locationsRanked[0]?.name || '-'} icon="location_on" color="purple-400" onClick={() => setDrillDown({ title: 'Locais Frequentes', type: 'locations', data: stats.locationsRanked })} />
      </section>

      {/* Performance Rankings */}
      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Liderança & Rankings</h3>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Líderes de Vitórias', type: 'players-wins', data: stats.mostWins })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-3">
            <span className="text-[8px] font-black text-primary uppercase">Vitórias Individuais</span>
            <div className="flex items-center gap-2">
              {stats.mostWins[0] && renderGlobalAvatar(stats.mostWins[0], 'size-8')}
              <div className="flex flex-col">
                <span className="text-xs font-black text-white">{stats.mostWins[0]?.nickname || stats.mostWins[0]?.name.split(' ')[0] || '-'}</span>
                <span className="text-[10px] font-bold text-gray-500">{stats.mostWins[0]?.wins || 0}V</span>
              </div>
            </div>
          </button>
          <button onClick={() => setDrillDown({ title: 'Ranking de Pontos', type: 'players-elo', data: stats.mostPointsELO })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-3">
            <span className="text-[8px] font-black text-orange-400 uppercase">Ranking ELO</span>
            <div className="flex items-center gap-2">
              {stats.mostPointsELO[0] && renderGlobalAvatar(stats.mostPointsELO[0], 'size-8')}
              <div className="flex flex-col">
                <span className="text-xs font-black text-white">{stats.mostPointsELO[0]?.nickname || stats.mostPointsELO[0]?.name.split(' ')[0] || '-'}</span>
                <span className="text-[10px] font-bold text-gray-500">{stats.mostPointsELO[0]?.rankingPoints || 0} pts</span>
              </div>
            </div>
          </button>
        </div>
        <button onClick={() => setDrillDown({ title: 'Maiores Sequências', type: 'players-streaks', data: stats.mostStreaks })} className="w-full bg-card-dark p-4 rounded-3xl border border-white/5 flex justify-between items-center group">
           <div className="flex items-center gap-3">
             <div className="size-8 rounded-xl bg-red-500/10 flex items-center justify-center text-red-500"><span className="material-symbols-outlined text-[18px]">local_fire_department</span></div>
             <span className="text-xs font-black text-white uppercase">Recorde de Vitórias Seguidas</span>
           </div>
           <span className="text-sm font-black text-white">{stats.mostStreaks[0]?.maxWinStreak || 0} Jogos</span>
        </button>
      </section>

      {/* Análise de Duplas */}
      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Duplas em Destaque</h3>
        <button onClick={() => setDrillDown({ title: 'Ranking de Duplas', type: 'duos', data: stats.duos })} className="w-full bg-gradient-to-br from-primary/20 to-card-dark p-6 rounded-[2.5rem] border border-primary/20 flex flex-col gap-4 text-left shadow-xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-8 opacity-10"><span className="material-symbols-outlined text-7xl">groups</span></div>
           <div className="flex justify-between items-start">
             <div><p className="text-[9px] font-black text-primary uppercase mb-1">Dupla Imbatível</p><h4 className="text-xl font-black text-white">{stats.duos[0] ? `${stats.duos[0].p1.name.split(' ')[0]} & ${stats.duos[0].p2.name.split(' ')[0]}` : 'Sem dados'}</h4></div>
             <div className="bg-primary/20 px-3 py-1 rounded-full text-primary text-[10px] font-black">{stats.duos[0]?.winRate || 0}% WR</div>
           </div>
           <div className="flex items-center gap-4">
             <div className="flex -space-x-3">{stats.duos[0] && renderGlobalAvatar(stats.duos[0].p1, 'size-10')}{stats.duos[0] && renderGlobalAvatar(stats.duos[0].p2, 'size-10')}</div>
             <p className="text-[10px] font-bold text-gray-500 uppercase">{stats.duos[0]?.wins} Vitórias em {stats.duos[0]?.games} Jogos</p>
           </div>
        </button>
      </section>

      {/* Recordes de Equilíbrio */}
      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Equilíbrio & Recordes</h3>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Jogos Mais Equilibrados', type: 'matches-eq', data: stats.matchEquilibrium })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-emerald-400 uppercase">Jogo + Equilibrado</span>
            <p className="text-xs font-black text-white truncate">{stats.matchEquilibrium[0] ? `${stats.matchEquilibrium[0].score1}-${stats.matchEquilibrium[0].score2}` : '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">{stats.matchEquilibrium[0]?.locationName || '-'}</p>
          </button>
          <button onClick={() => setDrillDown({ title: 'Jogos Mais Desequilibrados', type: 'matches-un', data: stats.matchUnbalanced })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-red-400 uppercase">Jogo + Desequilibrado</span>
            <p className="text-xs font-black text-white truncate">{stats.matchUnbalanced[0] ? `${stats.matchUnbalanced[0].score1}-${stats.matchUnbalanced[0].score2}` : '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">{stats.matchUnbalanced[0]?.locationName || '-'}</p>
          </button>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Torneios Mais Equilibrados', type: 'tournaments-eq', data: stats.tournamentEquilibrium })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-emerald-400 uppercase">Torneio + Equilibrado</span>
            <p className="text-xs font-black text-white truncate">{stats.tournamentEquilibrium[0]?.locName || '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">Dif: ±{stats.tournamentEquilibrium[0]?.avgDiff.toFixed(1)} pts</p>
          </button>
          <button onClick={() => setDrillDown({ title: 'Torneios Mais Pontuados', type: 'tournaments-pts', data: stats.tournamentMostPoints })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-primary uppercase">Torneio + Pontuado</span>
            <p className="text-xs font-black text-white truncate">{stats.tournamentMostPoints[0]?.locName || '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">{stats.tournamentMostPoints[0]?.totalPts || 0} Pts Totais</p>
          </button>
        </div>
      </section>

      {/* Drill Down Modal */}
      {drillDown && (
        <div className="fixed inset-0 z-[100] bg-background-dark/98 backdrop-blur-2xl animate-fade-in flex flex-col p-4">
          <header className="flex items-center justify-between mb-8 shrink-0">
            <div>
              <h2 className="text-xl font-black text-white">{drillDown.title}</h2>
              <p className="text-[9px] font-black text-primary uppercase tracking-widest">{drillDown.data.length} Entradas</p>
            </div>
            <button onClick={() => setDrillDown(null)} className="size-11 rounded-full bg-white/10 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
          </header>
          <div className="flex-1 overflow-y-auto space-y-3 pb-24 hide-scrollbar">
            {drillDown.type.startsWith('players') && drillDown.data.map((p, i) => (
              <button key={p.id} onClick={() => { onViewPlayer?.(p.id); setDrillDown(null); }} className="w-full bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between text-left">
                <div className="flex items-center gap-4">
                  <span className="text-[10px] font-black text-gray-700 w-4">{i+1}</span>
                  {renderGlobalAvatar(p, 'size-10')}
                  <div><p className="text-sm font-black text-white">{p.nickname || p.name}</p><p className="text-[9px] text-gray-500 uppercase">{p.level}</p></div>
                </div>
                <p className="text-xs font-black text-primary">
                  {drillDown.type === 'players-wins' ? `${p.wins}V` : drillDown.type === 'players-streaks' ? `${p.maxWinStreak}S` : drillDown.type === 'players-elo' ? `${p.rankingPoints} pts` : `${p.tournamentsPlayed} T`}
                </p>
              </button>
            ))}
            {drillDown.type === 'duos' && drillDown.data.map((d, i) => (
              <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-3">{renderGlobalAvatar(d.p1, 'size-9')}{renderGlobalAvatar(d.p2, 'size-9')}</div>
                  <div><p className="text-xs font-black text-white">{d.p1.name.split(' ')[0]} & {d.p2.name.split(' ')[0]}</p><p className="text-[9px] text-gray-500">{d.games} Jogos</p></div>
                </div>
                <p className="text-sm font-black text-primary">{d.winRate}% WR</p>
              </div>
            ))}
            {drillDown.type.startsWith('matches') && drillDown.data.map((m, i) => (
              <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col gap-2">
                <div className="flex justify-between items-center text-[8px] font-black text-gray-600 uppercase mb-1"><span>Campo {m.court}</span><span>{m.locationName}</span></div>
                <div className="flex items-center justify-between gap-3">
                  <span className="flex-1 text-[10px] font-black text-white text-right">{m.team1.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</span>
                  <div className="bg-background-dark px-4 py-1.5 rounded-xl border border-white/10 flex items-center gap-2">
                    <span className={`text-base font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-600'}`}>{m.score1}</span>
                    <span className="text-[10px] text-gray-800">-</span>
                    <span className={`text-base font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-600'}`}>{m.score2}</span>
                  </div>
                  <span className="flex-1 text-[10px] font-black text-white text-left">{m.team2.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</span>
                </div>
              </div>
            ))}
            {drillDown.type.startsWith('tournaments') && drillDown.data.map((t) => (
              <button key={t.id} onClick={() => { onViewTournament?.(t); setDrillDown(null); }} className="w-full bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between text-left">
                <div><p className="text-[10px] font-black text-primary uppercase">{new Date(t.date).toLocaleDateString()}</p><p className="text-sm font-black text-white">{locations.find(l => l.id === t.locationId)?.name}</p></div>
                <p className="text-xs font-black text-white">
                  {drillDown.type === 'tournaments-eq' ? `±${t.avgDiff.toFixed(1)} diff` : drillDown.type === 'tournaments-pts' ? `${t.totalPts} pts` : `${t.matches?.length || 0} Jogos`}
                </p>
              </button>
            ))}
            {drillDown.type === 'locations' && drillDown.data.map((loc, i) => (
              <div key={loc.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-4"><span className="text-[10px] font-black text-gray-700 w-4">{i+1}</span><div><p className="text-sm font-black text-white">{loc.name}</p><p className="text-[9px] text-gray-500 uppercase">{loc.type}</p></div></div>
                <div className="bg-primary/10 px-3 py-1 rounded-lg text-primary text-[10px] font-black">{loc.count} Torneios</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

