           <div className="flex items-center gap-3">
             <div className="size-8 rounded-xl bg-red-500/10 flex items-center justify-center text-red-500"><span className="material-symbols-outlined text-[18px]">local_fire_department</span></div>
             <span className="text-xs font-black text-white uppercase">Recorde de Vitórias Seguidas</span>
