          </button>
          <button onClick={() => setDrillDown({ title: 'Torneios Mais Pontuados', type: 'tournaments-pts', data: stats.tournamentMostPoints })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
