                <div className="bg-primary/10 px-3 py-1 rounded-lg text-primary text-[10px] font-black">{loc.count} Torneios</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface TeamSetupScreenProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  onStartTournament: (matches: Match[]) => void;
}

export const TeamSetupScreen: React.FC<TeamSetupScreenProps> = ({ setScreen, players, onStartTournament }) => {
  const [teamA, setTeamA] = useState<Player[]>([]); // Ases
  const [teamB, setTeamB] = useState<Player[]>([]); // Reis
  const [teamC, setTeamC] = useState<Player[]>([]); // Damas
  const [teamD, setTeamD] = useState<Player[]>([]); // Valetes

  const availablePlayers = players.filter(p => 
    !teamA.find(ta => ta.id === p.id) && 
    !teamB.find(tb => tb.id === p.id) &&
    !teamC.find(tc => tc.id === p.id) &&
    !teamD.find(td => td.id === p.id)
  );

  const handlePlayerClick = (player: Player) => {
    if (teamA.length < 2) setTeamA([...teamA, player]);
    else if (teamB.length < 2) setTeamB([...teamB, player]);
    else if (teamC.length < 2) setTeamC([...teamC, player]);
    else if (teamD.length < 2) setTeamD([...teamD, player]);
  };

  const removePlayer = (player: Player, teamId: 'A' | 'B' | 'C' | 'D') => {
    if (teamId === 'A') setTeamA(teamA.filter(p => p.id !== player.id));
    if (teamId === 'B') setTeamB(teamB.filter(p => p.id !== player.id));
    if (teamId === 'C') setTeamC(teamC.filter(p => p.id !== player.id));
    if (teamId === 'D') setTeamD(teamD.filter(p => p.id !== player.id));
  };

  const handleAutoAssign = () => {
    const pool = [...players].sort(() => 0.5 - Math.random());
    setTeamA([pool[0], pool[1]]);
    setTeamB([pool[2], pool[3]]);
    setTeamC([pool[4], pool[5]]);
    setTeamD([pool[6], pool[7]]);
  };

  const isReady = teamA.length === 2 && teamB.length === 2 && teamC.length === 2 && teamD.length === 2;

  const handleStart = () => {
    if (!isReady) return;
    const timestamp = Date.now();
    const dateStr = new Date().toISOString();
    // Ronda 1: Ases vs Reis | Damas vs Valetes
    const matches: Match[] = [
        { id: `m1-${timestamp}`, team1: teamA, team2: teamB, score1: 0, score2: 0, court: 1, status: 'live', round: 1, date: dateStr },
        { id: `m2-${timestamp}`, team1: teamC, team2: teamD, score1: 0, score2: 0, court: 2, status: 'live', round: 1, date: dateStr }
    ];
    onStartTournament(matches);
  };

  const renderTeamCard = (team: Player[], label: string, teamId: 'A' | 'B' | 'C' | 'D', color: string, icon: string) => (
    <div className={`flex flex-col bg-card-dark/40 rounded-[2rem] p-3 border border-white/5 h-full relative group overflow-hidden`}>
        <div className={`absolute top-0 right-0 p-4 opacity-10 pointer-events-none`}>
            <span className="material-symbols-outlined text-4xl">{icon}</span>
        </div>
        <div className="flex justify-between items-center mb-2 px-1 relative z-10">
            <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${color}`}>{label}</span>
            <span className="text-[8px] font-bold text-gray-600">{team.length}/2</span>
        </div>
        <div className="flex flex-col gap-2 flex-1 relative z-10">
            {[0, 1].map(idx => (
                <div key={idx} className="h-11 rounded-2xl border border-dashed border-white/10 bg-black/20 flex items-center px-2.5 overflow-hidden transition-all duration-300">
                    {team[idx] ? (
                        <div className="flex items-center gap-2.5 w-full animate-fade-in">
                            {renderGlobalAvatar(team[idx], 'size-7')}
                            <span className="text-[10px] font-bold text-white truncate uppercase flex-1">{team[idx].nickname || team[idx].name.split(' ')[0]}</span>
                            <button onClick={() => removePlayer(team[idx], teamId)} className="text-gray-600 hover:text-red-400 p-1">
                                <span className="material-symbols-outlined text-[14px]">close</span>
                            </button>
                        </div>
                    ) : (
                        <span className="text-[8px] text-gray-700 font-bold uppercase tracking-widest w-full text-center">Vago</span>
                    )}
                </div>
            ))}
        </div>
    </div>
  );

  return (
    <div className="h-screen max-h-screen flex flex-col bg-background-dark p-4 overflow-hidden animate-fade-in">
      <header className="flex items-center justify-between mb-4 shrink-0 px-1">
          <button onClick={() => setScreen(Screen.HOME)} className="size-10 rounded-full bg-white/5 flex items-center justify-center">
              <span className="material-symbols-outlined text-[20px]">arrow_back</span>
          </button>
          <div className="text-center">
              <h2 className="text-lg font-black text-white leading-none">SORTEIO</h2>
              <span className="text-[9px] font-bold text-primary uppercase tracking-[0.3em]">Mesa de Cartas</span>
          </div>
          <button onClick={() => { setTeamA([]); setTeamB([]); setTeamC([]); setTeamD([]); }} className="size-10 rounded-full bg-white/5 flex items-center justify-center text-gray-500">
              <span className="material-symbols-outlined text-[20px]">restart_alt</span>
          </button>
      </header>

      {/* Main Container - "O Retângulo" */}
      <main className="flex-1 bg-gradient-to-br from-primary/10 via-card-dark to-card-dark rounded-[2.5rem] border border-primary/20 p-4 shadow-2xl flex flex-col gap-4 overflow-hidden">

          {/* Jogadores Disponíveis (Pool 4x2) */}
          <section className="shrink-0 bg-black/20 p-3 rounded-3xl border border-white/5">
              <div className="flex justify-between items-center mb-3 px-1">
                  <h3 className="text-[9px] font-black text-gray-500 uppercase tracking-[0.2em]">Jogadores Confirmados</h3>
                  <button onClick={handleAutoAssign} className="flex items-center gap-1.5 text-[9px] font-black text-primary uppercase border border-primary/30 px-3 py-1.5 rounded-xl bg-primary/10">
                      <span className="material-symbols-outlined text-[14px]">shuffle</span>
                      Baralhar
                  </button>
              </div>
              <div className="grid grid-cols-4 gap-3">
                  {players.map(p => {
                      const isAssigned = teamA.find(ta => ta.id === p.id) || teamB.find(tb => tb.id === p.id) || teamC.find(tc => tc.id === p.id) || teamD.find(td => td.id === p.id);
                      return (
                          <button 
                            key={p.id} 
                            onClick={() => !isAssigned && handlePlayerClick(p)}
                            disabled={!!isAssigned}
                            className={`flex flex-col items-center gap-1.5 transition-all duration-300 ${isAssigned ? 'opacity-20 scale-90 grayscale' : 'active:scale-90 hover:scale-105'}`}
