const App: React.FC = () => {
  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [players, setPlayers] = useState<Player[]>(MOCK_PLAYERS);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [locations, setLocations] = useState<Location[]>(DEFAULT_LOCATIONS);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const sortedHistory = [...tournamentHistory].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamWins = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamWins.has(k1)) teamWins.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamWins.has(k2)) teamWins.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamWins.get(k1)!, s2 = teamWins.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const champions = Array.from(teamWins.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff)[0];
        const championsIds = champions?.pids || [];

        t.matches.forEach(m => {
            const updatePlayer = (p: Player, won: boolean) => {
                const data = rankings.get(p.id);
                if (data) { data.current += won ? 20 : -12; if (data.current < 800) data.current = 800; }
            };
            m.team1.forEach(p => updatePlayer(p, m.score1 > m.score2));
            m.team2.forEach(p => updatePlayer(p, m.score2 > m.score1));
        });

        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const data = rankings.get(pid);
            if (data) {
                if (championsIds.includes(pid)) data.current += 50;
                const getLevel = (pts: number) => {
                    if (pts >= 1600) return 'Pro'; if (pts >= 1400) return 'Nível 3';
                    if (pts >= 1200) return 'Nível 2'; return 'Nível 1';
                };
                data.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: data.current, level: getLevel(data.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const rankingData = playerRankings.get(p.id);
        const pts = rankingData?.current || 1000;
        const getLevel = (pts: number) => { if (pts >= 1600) return 'Pro'; if (pts >= 1400) return 'Nível 3'; if (pts >= 1200) return 'Nível 2'; return 'Nível 1'; };
        return { ...p, rankingPoints: pts, level: getLevel(pts) };
    });
  }, [players, playerRankings]);

  const handleStartTournament = (generatedMatches: Match[]) => {
    setMatches(generatedMatches.map(m => ({ ...m, date: activeTournament?.date || new Date().toISOString() })));
    setCurrentRound(1);
    setScreen(Screen.LIVE_GAME);
  };

  const handleNextRound = () => {
    const timestamp = new Date().toISOString();
    const currentRoundMatches = matches.filter(m => m.round === currentRound);
    const updatedAllMatches = matches.map(m => m.round === currentRound ? { ...m, status: 'finished' as const } : m);

    if (currentRound === 1) {
        const m1 = currentRoundMatches.find(m => m.court === 1)!;
        const m2 = currentRoundMatches.find(m => m.court === 2)!;

        const win1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
        const los1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
        const win2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
        const los2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

        const round2: Match[] = [
            { id: `m-r2-c1-${Date.now()}`, team1: win1, team2: los2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: activeTournament?.date },
            { id: `m-r2-c2-${Date.now()}`, team1: win2, team2: los1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: activeTournament?.date }
        ];
        setMatches([...updatedAllMatches, ...round2]);
        setCurrentRound(2);
    } else if (currentRound === 2) {
        const m1r1 = updatedAllMatches.find(m => m.round === 1 && m.court === 1)!;
        const m2r1 = updatedAllMatches.find(m => m.round === 1 && m.court === 2)!;
        const a = m1r1.team1, b = m1r1.team2, c = m2r1.team1, d = m2r1.team2;

        const round3: Match[] = [
            { id: `m-r3-c1-${Date.now()}`, team1: a, team2: c, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: activeTournament?.date },
            { id: `m-r3-c2-${Date.now()}`, team1: b, team2: d, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: activeTournament?.date }
        ];
        setMatches([...updatedAllMatches, ...round3]);
        setCurrentRound(3);
    } else {
        setMatches(updatedAllMatches);
        setScreen(Screen.TOURNAMENT_SUMMARY);
    }
  };

  const updateMatchScore = (matchId: string, team: 1 | 2, increment: boolean) => {
    setMatches(prev => prev.map(m => {
      if (m.id !== matchId) return m;
      const current = team === 1 ? m.score1 : m.score2;
      return { ...m, [team === 1 ? 'score1' : 'score2']: increment ? current + 1 : Math.max(0, current - 1) };
    }));
  };

  const handleFinishTournament = () => {
    if (activeTournament) {
        const finishedTournament: Tournament = { 
          ...activeTournament, 
          status: 'finished', 
          matches: matches.map(m => ({...m, status: 'finished'})), 
        };
        setTournamentHistory(prev => [finishedTournament, ...prev]);
        setActiveTournament(null);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case Screen.HOME: return <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={(t) => {setActiveTournament(t); setScreen(Screen.HOME);}} onAddPlayer={(p) => setPlayers([...players, p])} onUpdateTournament={setActiveTournament} history={tournamentHistory} />;
      case Screen.PROFILE: return <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />;
      case Screen.LIVE_GAME: return <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />;
      case Screen.TOURNAMENT_SUMMARY: return <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />;
      case Screen.TOURNAMENT_RESULTS: return <TournamentResultsScreen setScreen={setScreen} matches={matches} />;
      case Screen.GLOBAL_STATS: return <GlobalStatsScreen history={tournamentHistory} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY: return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />;
      case Screen.HISTORY_DETAIL: return selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} /> : null;
      case Screen.TEAM_SETUP: return <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS: return <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={(p) => setPlayers([...players, p])} onUpdatePlayer={(up) => setPlayers(players.map(p => p.id === up.id ? up : p))} />;
      case Screen.LOCATIONS: return <LocationManagerScreen setScreen={setScreen} locations={locations} setLocations={setLocations} history={tournamentHistory} />;
      default: return null;
    }
  };

  const showNav = [Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.LOCATIONS, Screen.TOURNAMENT_HISTORY].includes(currentScreen);

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        {renderScreen()}
        {showNav && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
  onUpdatePlayer?: (player: Player) => void;
  rankingHistory?: { date: string, points: number, level: string }[];
}

type TabType = 'overview' | 'ranking' | 'relations' | 'activity';

const getColorForId = (id: string) => {
  const colors = [
    'bg-blue-600', 'bg-emerald-600', 'bg-purple-600', 
    'bg-orange-600', 'bg-rose-600', 'bg-cyan-600', 
    'bg-amber-600', 'bg-indigo-600', 'bg-lime-600',
    'bg-pink-600'
  ];
  // Simplistic hash for consistent color
  const sum = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  return colors[sum % colors.length];
};

const getInitials = (player: { name: string, lastName?: string }) => {
  const first = player.name?.[0] || '';
  const last = player.lastName?.[0] || '';
  return (first + last).toUpperCase();
};

export const renderGlobalAvatar = (p: { id: string, name: string, lastName?: string, image?: string }, sizeClass: string = 'size-10') => {
  const usePlaceholder = !p.image || p.image.trim() === '';

  if (usePlaceholder) {
    const initials = getInitials(p);
    const bgColor = getColorForId(p.id);

    return (
      <div className={`${sizeClass} rounded-full ${bgColor} flex items-center justify-center border-2 border-white/20 text-white shadow-lg shrink-0 relative overflow-hidden group`}>
        {/* Background Padel Racket Icon - Increased size to 200% to fill the circle better */}
        <span className="material-symbols-outlined absolute text-[200%] opacity-20 pointer-events-none rotate-[-15deg] translate-x-1 translate-y-1">
          sports_tennis
        </span>
        {/* Initials - Slightly larger and bolder with drop shadow for contrast */}
        <span className="relative z-10 text-[40%] font-black tracking-tighter select-none drop-shadow-md">
          {initials}
        </span>
      </div>
    );
  }

  return (
    <img 
      src={p.image} 
      className={`${sizeClass} rounded-full object-cover border-2 border-white/10 shadow-md shrink-0`} 
      alt={`${p.name} Avatar`} 
    />
  );
};

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, setScreen, onUpdatePlayer, rankingHistory = [] }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);

  const player = players.find(p => p.id === playerId);

  const [editFirstName, setEditFirstName] = useState('');
  const [editLastName, setEditLastName] = useState('');
  const [editNickname, setEditNickname] = useState('');
  const [editImage, setEditImage] = useState('');

  useEffect(() => {
    if (player) {
        setEditFirstName(player.name);
        setEditLastName(player.lastName || '');
        setEditNickname(player.nickname || '');
        setEditImage(player.image);
    }
  }, [player, isEditing]);

  const stats = useMemo(() => {
    if (!playerId) return null;

    const myMatches: Match[] = [];
    const myWonMatches: Match[] = [];
    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];

    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number, matches: Match[] }>();
    const rivals = new Map<string, { id: string, name: string, image: string, winsAgainst: number, lossesAgainst: number, games: number, matches: Match[] }>();

    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let pointsScored = 0;
    let pointsConceded = 0;

    history.forEach(t => {
        const tMatches = t.matches?.filter(m => [...m.team1, ...m.team2].some(p => p.id === playerId)) || [];
        if (tMatches.length > 0) {
            myTournaments.push(t);

            const teamWins = new Map<string, number>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (m.score1 > m.score2) teamWins.set(k1, (teamWins.get(k1) || 0) + 1);
                else if (m.score2 > m.score1) teamWins.set(k2, (teamWins.get(k2) || 0) + 1);
            });
            const sortedTeams = Array.from(teamWins.entries()).sort((a,b) => b[1] - a[1]);
            const winnersIds = sortedTeams.length > 0 ? sortedTeams[0][0].split('-') : [];
            if (winnersIds.includes(playerId)) myWonTournaments.push(t);

            tMatches.forEach(m => {
                myMatches.push(m);
                const inTeam1 = m.team1.some(p => p.id === playerId);
                const won = inTeam1 ? m.score1 > m.score2 : m.score2 > m.score1;

                pointsScored += inTeam1 ? m.score1 : m.score2;
                pointsConceded += inTeam1 ? m.score2 : m.score1;

                if (won) {
                    myWonMatches.push(m);
                    currentWinStreak++;
                    maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
                } else {
                    currentWinStreak = 0;
                }

                const myTeam = inTeam1 ? m.team1 : m.team2;
                const oppTeam = inTeam1 ? m.team2 : m.team1;

                myTeam.forEach(p => {
                    if (p.id === playerId) return;
                    if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                    const pd = partners.get(p.id)!;
                    pd.games++; pd.matches.push(m); if (won) pd.wins++;
                });

                oppTeam.forEach(p => {
                    if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                    const rd = rivals.get(p.id)!;
                    rd.games++; rd.matches.push(m); if (won) rd.winsAgainst++; else rd.lossesAgainst++;
                });
            });
        }
    });

    return {
        totalMatches: myMatches.length,
        totalWins: myWonMatches.length,
        winRate: myMatches.length > 0 ? Math.round((myWonMatches.length / myMatches.length) * 100) : 0,
        myTournaments,
        myWonTournaments,
        myMatches,
        pointsScored,
        pointsConceded,
        maxWinStreak,
        partners: Array.from(partners.values()).sort((a,b) => b.wins - a.wins || b.games - a.games),
        victims: Array.from(rivals.values()).sort((a,b) => b.winsAgainst - a.winsAgainst).slice(0, 6),
        blackBeasts: Array.from(rivals.values()).sort((a,b) => b.lossesAgainst - a.lossesAgainst).slice(0, 6)
    };
  }, [playerId, history]);

  if (!player || !stats) return null;

  const renderRankingChart = () => {
    if (rankingHistory.length < 2) return (
        <div className="h-48 flex flex-col items-center justify-center text-gray-600 bg-white/5 rounded-3xl border border-white/5">
            <span className="material-symbols-outlined text-4xl mb-2">monitoring</span>
            <p className="text-xs font-bold uppercase tracking-widest">Aguardando mais jogos...</p>
        </div>
    );

    const width = 340;
    const height = 180;
    const pts = rankingHistory.map(h => h.points);
    const maxPts = Math.max(...pts) + 50;
    const minPts = Math.min(...pts) - 50;
    const range = maxPts - minPts;

    const points = rankingHistory.map((h, i) => ({
        x: (i * (width / (rankingHistory.length - 1))),
        y: height - ((h.points - minPts) * (height / range))
    }));

    const d = points.reduce((acc, p, i) => i === 0 ? `M ${p.x},${p.y}` : `${acc} L ${p.x},${p.y}`, '');

    return (
        <div className="bg-card-dark p-6 rounded-3xl border border-white/5 shadow-xl relative overflow-hidden group">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <p className="text-[10px] font-black text-primary uppercase tracking-widest">Trajetória</p>
                    <h3 className="text-lg font-black text-white">Evolução de Ranking</h3>
                </div>
                <div className="text-right">
                    <p className="text-[10px] font-black text-gray-500 uppercase">Atual</p>
                    <p className="text-lg font-black text-primary">{player.rankingPoints} pts</p>
                </div>
            </div>
            <div className="relative h-[200px]">
                <svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
                    <defs>
                        <filter id="glow"><feGaussianBlur stdDeviation="3" result="blur" /><feComposite in="SourceGraphic" in2="blur" operator="over" /></filter>
                    </defs>
                    <line x1="0" y1={height - ((1000 - minPts) * (height/range))} x2={width} y2={height - ((1000 - minPts) * (height/range))} stroke="white" strokeOpacity="0.05" strokeDasharray="4 4" />
                    <path d={d} fill="none" stroke="#607AFB" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" filter="url(#glow)" />
                    {points.map((p, i) => (
                        <circle key={i} cx={p.x} cy={p.y} r="4" fill="#0f1323" stroke="#607AFB" strokeWidth="2" />
                    ))}
                </svg>
                <div className="flex justify-between mt-4">
                    <span className="text-[8px] font-bold text-gray-500">{rankingHistory[0].date}</span>
                    <span className="text-[8px] font-bold text-gray-500">{rankingHistory[rankingHistory.length-1].date}</span>
                </div>
            </div>
        </div>
    );
  };

  return (
    <div className="flex flex-col gap-6 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="px-4 pt-8 flex flex-col items-center relative">
        <button onClick={() => setIsEditing(true)} className="absolute top-8 right-6 size-10 rounded-full bg-white/5 flex items-center justify-center text-gray-400 border border-white/10">
          <span className="material-symbols-outlined text-[20px]">edit</span>
        </button>
        <div className="relative mb-4">
          <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-110"></div>
          {renderGlobalAvatar(player, 'size-24')}
