              </header>
              <div className="space-y-6">
                  <div className="flex flex-col items-center gap-4 py-4">
                    {renderGlobalAvatar({ id: player.id, name: player.name, lastName: player.lastName, image: editImage }, 'size-28')}
                    <input type="text" value={editImage} onChange={(e) => setEditImage(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white text-sm" placeholder="URL da Imagem" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <input type="text" value={editFirstName} onChange={(e) => setEditFirstName(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white text-sm" placeholder="Nome" />
                    <input type="text" value={editLastName} onChange={(e) => setEditLastName(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white text-sm" placeholder="Apelido" />
                  </div>
                  <input type="text" value={editNickname} onChange={(e) => setEditNickname(e.target.value)} className="w-full bg-card-dark border border-primary/30 rounded-xl px-4 py-3 text-white text-sm" placeholder="Alcunha" />
              </div>
              <div className="mt-auto pb-6">
                <button onClick={() => { if(onUpdatePlayer) { onUpdatePlayer({...player, name: editFirstName, lastName: editLastName, nickname: editNickname, image: editImage}); setIsEditing(false); } }} className="w-full py-4 bg-primary text-background-dark font-bold rounded-2xl shadow-xl">Guardar Alterações</button>
              </div>
          </div>
      )}

      {drillDown && (
          <div className="fixed inset-0 z-[120] bg-background-dark/98 backdrop-blur-xl p-4 flex flex-col animate-fade-in">
              <header className="flex items-center justify-between mb-6">
                  <div><h2 className="text-xl font-bold text-white">{drillDown.title}</h2><p className="text-[10px] text-gray-500 uppercase font-black">{drillDown.items.length} Itens</p></div>
                  <button onClick={() => setDrillDown(null)} className="size-10 rounded-full bg-white/5 flex items-center justify-center text-white"><span className="material-symbols-outlined">close</span></button>
              </header>
              <div className="flex-1 overflow-y-auto space-y-3 pb-24 hide-scrollbar">
                  {drillDown.type === 'matches' ? (
                      drillDown.items.map((m: Match, idx: number) => {
                          const inT1 = m.team1.some(p => p.id === playerId);
                          const won = (inT1 ? m.score1 : m.score2) > (inT1 ? m.score2 : m.score1);
                          return (
                              <div key={idx} className={`bg-card-dark p-4 rounded-2xl border ${won ? 'border-primary/20' : 'border-white/5'} flex justify-between items-center`}>
                                  <div className="flex-1 text-[10px] font-bold text-white truncate text-right">{m.team1.map(p => p.nickname || p.name.split(' ')[0]).join('/')}</div>
                                  <div className="mx-4 flex items-center gap-2 bg-background-dark px-3 py-1 rounded-lg">
                                      <span className={`text-sm font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-500'}`}>{m.score1}</span>
                                      <span className="text-gray-700">-</span>
                                      <span className={`text-sm font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-500'}`}>{m.score2}</span>
                                  </div>
                                  <div className="flex-1 text-[10px] font-bold text-white truncate text-left">{m.team2.map(p => p.nickname || p.name.split(' ')[0]).join('/')}</div>
                              </div>
                          );
                      })
                  ) : (
                    drillDown.items.map((t: Tournament, idx: number) => (
                        <div key={idx} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex justify-between items-center">
                            <div><p className="text-sm font-bold text-white">{new Date(t.date).toLocaleDateString('pt-PT')}</p><p className="text-[10px] text-gray-500 uppercase">{t.matches?.length} Jogos</p></div>
                            <span className="material-symbols-outlined text-primary">chevron_right</span>
                        </div>
                    ))
                  )}
              </div>
          </div>
      )}
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  EXPORT = 'EXPORT',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL',
  TOURNAMENT_HISTORY = 'TOURNAMENT_HISTORY'
}

export interface Player {
  id: string;
  name: string;
  lastName?: string;
  nickname?: string;
  birthDate?: string;
  hand?: 'Destro' | 'Canhoto';
  level: string; 
  rankingPoints?: number; 
  image: string;
  backgroundColor?: string; // Nova propriedade para cor personalizada
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
  date?: string;
}

export interface Tournament {
  id: string;
  date: string;
  time: string;
  duration: number;
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished';
  matches?: Match[];
}

import React, { useMemo, useState, useEffect } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
  onUpdatePlayer?: (player: Player) => void;
  rankingHistory?: { date: string, points: number, level: string }[];
}

type TabType = 'overview' | 'ranking' | 'relations' | 'activity';

const PRESET_COLORS = [
  'bg-blue-600', 'bg-emerald-600', 'bg-purple-600', 
  'bg-orange-600', 'bg-rose-600', 'bg-cyan-600', 
  'bg-amber-600', 'bg-indigo-600', 'bg-lime-600',
  'bg-pink-600'
];

const getColorForId = (id: string) => {
  const sum = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  return PRESET_COLORS[sum % PRESET_COLORS.length];
};

const getInitials = (player: { name: string, lastName?: string }) => {
  const first = player.name?.[0] || '';
  const last = player.lastName?.[0] || '';
  return (first + last).toUpperCase();
};

export const renderGlobalAvatar = (p: { id: string, name: string, lastName?: string, image?: string, backgroundColor?: string }, sizeClass: string = 'size-10') => {
  const usePlaceholder = !p.image || p.image.trim() === '';

  if (usePlaceholder) {
    const initials = getInitials(p);
    const bgColor = p.backgroundColor || getColorForId(p.id);

    return (
      <div className={`${sizeClass} rounded-full ${bgColor} flex items-center justify-center border-2 border-white/20 text-white shadow-lg shrink-0 relative overflow-hidden group`}>
        {/* Background Padel Racket Icon - Increased scale and opacity for better integration */}
        <span className="material-symbols-outlined absolute text-[220%] opacity-25 pointer-events-none rotate-[-12deg] translate-x-1 translate-y-1">
          sports_tennis
        </span>
        {/* Initials - Now much larger (50%) and bolder */}
        <span className="relative z-10 text-[48%] font-black tracking-tighter select-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.4)]">
          {initials}
        </span>
      </div>
    );
  }

  return (
    <img 
      src={p.image} 
      className={`${sizeClass} rounded-full object-cover border-2 border-white/10 shadow-md shrink-0`} 
      alt={`${p.name} Avatar`} 
    />
  );
};

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, setScreen, onUpdatePlayer, rankingHistory = [] }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);

  const player = players.find(p => p.id === playerId);

  const [editFirstName, setEditFirstName] = useState('');
  const [editLastName, setEditLastName] = useState('');
  const [editNickname, setEditNickname] = useState('');
  const [editImage, setEditImage] = useState('');
  const [editColor, setEditColor] = useState('');

  useEffect(() => {
    if (player) {
        setEditFirstName(player.name);
        setEditLastName(player.lastName || '');
        setEditNickname(player.nickname || '');
        setEditImage(player.image);
        setEditColor(player.backgroundColor || getColorForId(player.id));
    }
  }, [player, isEditing]);

  const stats = useMemo(() => {
    if (!playerId) return null;
    const myMatches: Match[] = [];
    const myWonMatches: Match[] = [];
    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];
    const partners = new Map<string, any>();
    const rivals = new Map<string, any>();
    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let pointsScored = 0;
    let pointsConceded = 0;

    history.forEach(t => {
        const tMatches = t.matches?.filter(m => [...m.team1, ...m.team2].some(p => p.id === playerId)) || [];
        if (tMatches.length > 0) {
            myTournaments.push(t);
            const teamWins = new Map<string, number>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (m.score1 > m.score2) teamWins.set(k1, (teamWins.get(k1) || 0) + 1);
                else if (m.score2 > m.score1) teamWins.set(k2, (teamWins.get(k2) || 0) + 1);
            });
            const winnersIds = teamWins.size > 0 ? Array.from(teamWins.entries()).sort((a,b) => b[1] - a[1])[0][0].split('-') : [];
            if (winnersIds.includes(playerId)) myWonTournaments.push(t);

            tMatches.forEach(m => {
                myMatches.push(m);
                const inT1 = m.team1.some(p => p.id === playerId);
                const won = inT1 ? m.score1 > m.score2 : m.score2 > m.score1;
                pointsScored += inT1 ? m.score1 : m.score2;
                pointsConceded += inT1 ? m.score2 : m.score1;
                if (won) { myWonMatches.push(m); currentWinStreak++; maxWinStreak = Math.max(maxWinStreak, currentWinStreak); }
                else currentWinStreak = 0;

                const myTeam = inT1 ? m.team1 : m.team2;
                const oppTeam = inT1 ? m.team2 : m.team1;

                myTeam.forEach(p => {
                    if (p.id === playerId) return;
                    if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                    const pd = partners.get(p.id)!; pd.games++; if (won) pd.wins++;
                });
                oppTeam.forEach(p => {
                    if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                    const rd = rivals.get(p.id)!; rd.games++; if (won) rd.winsAgainst++; else rd.lossesAgainst++;
                });
            });
        }
    });

    return {
        totalMatches: myMatches.length,
        totalWins: myWonMatches.length,
        winRate: myMatches.length > 0 ? Math.round((myWonMatches.length / myMatches.length) * 100) : 0,
        myTournaments, myWonTournaments, myMatches, pointsScored, pointsConceded, maxWinStreak,
        partners: Array.from(partners.values()).sort((a,b) => b.wins - a.wins),
        victims: Array.from(rivals.values()).sort((a,b) => b.winsAgainst - a.winsAgainst).slice(0, 6),
        blackBeasts: Array.from(rivals.values()).sort((a,b) => b.lossesAgainst - a.lossesAgainst).slice(0, 6)
    };
  }, [playerId, history]);

  if (!player || !stats) return null;

  return (
    <div className="flex flex-col gap-6 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="px-4 pt-8 flex flex-col items-center relative">
        <button onClick={() => setIsEditing(true)} className="absolute top-8 right-6 size-10 rounded-full bg-white/5 flex items-center justify-center text-gray-400 border border-white/10">
          <span className="material-symbols-outlined text-[20px]">edit</span>
        </button>
        <div className="relative mb-4">
          <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-110"></div>
          {renderGlobalAvatar(player, 'size-24')}
          <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark text-[10px] font-black px-2 py-0.5 rounded-md border-2 border-background-dark shadow-lg">
             {player.level.toUpperCase()}
          </div>
        </div>
        <h1 className="text-2xl font-black text-white leading-tight">{player.nickname || player.name}</h1>
        <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest mt-1">{player.name} {player.lastName}</p>
      </header>

      <div className="px-4">
          <div className="flex bg-card-dark/50 p-1 rounded-2xl border border-white/5 overflow-x-auto hide-scrollbar">
              {[
                { id: 'overview', label: 'Geral', icon: 'dashboard' },
                { id: 'ranking', label: 'Ranking', icon: 'monitoring' },
                { id: 'relations', label: 'Relações', icon: 'groups' },
                { id: 'activity', label: 'Histórico', icon: 'history' }
              ].map(tab => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as TabType)} className={`flex-1 min-w-[80px] py-3 flex flex-col items-center gap-1 rounded-xl transition-all ${activeTab === tab.id ? 'bg-primary text-background-dark shadow-lg' : 'text-gray-500'}`}>
                    <span className="material-symbols-outlined text-sm">{tab.icon}</span>
                    <span className="text-[8px] font-black uppercase">{tab.label}</span>
                </button>
              ))}
          </div>
      </div>

      <div className="px-4 space-y-6">
          {activeTab === 'overview' && (
              <div className="space-y-4">
                  <div className="grid grid-cols-3 gap-3">
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center"><span className="text-xl font-black text-white">{stats.totalMatches}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Jogos</span></div>
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center"><span className="text-xl font-black text-primary">{stats.totalWins}</span><span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span></div>
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center"><span className="text-xl font-black text-emerald-400">{stats.winRate}%</span><span className="text-[8px] font-bold text-gray-500 uppercase">WR</span></div>
                  </div>
              </div>
          )}
          {/* Outras tabs mantidas simplificadas conforme arquivo original */}
      </div>

      {isEditing && (
          <div className="fixed inset-0 z-[110] bg-background-dark/95 backdrop-blur-xl animate-fade-in flex flex-col p-4 overflow-y-auto">
              <header className="flex items-center justify-between mb-8 shrink-0">
                  <h2 className="text-xl font-bold">Editar Perfil</h2>
                  <button onClick={() => setIsEditing(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center text-white"><span className="material-symbols-outlined">close</span></button>
              </header>
              <div className="space-y-8">
                  <div className="flex flex-col items-center gap-4 py-4 shrink-0">
