import React from 'react';
import { Screen, Player, Location, Tournament } from '../types';

interface SettingsProps {
  setScreen: (screen: Screen) => void;
  players: Player[];
  locations: Location[];
  history: Tournament[];
  onImportData: (data: { players: Player[], locations: Location[], history: Tournament[] }) => void;
  onResetData: () => void;
}

export const SettingsScreen: React.FC<SettingsProps> = ({ setScreen, players, locations, history, onImportData, onResetData }) => {

  const handleExport = () => {
    const data = {
      players,
      locations,
      history,
      exportDate: new Date().toISOString(),
      version: "1.0"
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `padel_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.players && json.locations && json.history) {
          if (window.confirm('Isto irá substituir todos os dados atuais pelos dados do ficheiro. Continuar?')) {
            onImportData({
              players: json.players,
              locations: json.locations,
              history: json.history
            });
            alert('Dados importados com sucesso!');
          }
        } else {
          alert('Ficheiro inválido. Certifique-se que é um backup da app.');
        }
      } catch (err) {
        alert('Erro ao ler o ficheiro.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="flex flex-col gap-8 px-4 pt-8 pb-32 animate-fade-in">
      <header>
        <h1 className="text-3xl font-black text-white">Definições <br/><span className="text-primary">& Backup</span></h1>
        <p className="text-gray-500 text-sm mt-1">Gira os dados e ficheiros da sua aplicação.</p>
      </header>

      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Cópia de Segurança</h3>
        <div className="bg-card-dark rounded-3xl border border-white/5 p-6 space-y-6">
          <div className="flex flex-col gap-2">
            <h4 className="text-sm font-bold text-white">Exportar para JSON</h4>
            <p className="text-xs text-gray-500">Descarregue todos os dados atuais (jogadores, locais e histórico) num único ficheiro para salvaguarda.</p>
            <button 
              onClick={handleExport}
              className="mt-2 w-full bg-primary text-background-dark font-black py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-primary/20 active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined">download</span>
              EXPORTAR BACKUP
            </button>
          </div>

          <div className="h-px bg-white/5"></div>

          <div className="flex flex-col gap-2">
            <h4 className="text-sm font-bold text-white">Importar de JSON</h4>
            <p className="text-xs text-gray-500">Substitua os dados atuais por um ficheiro de backup guardado anteriormente.</p>
            <label className="mt-2 w-full bg-white/5 text-white border border-white/10 font-black py-4 rounded-2xl flex items-center justify-center gap-2 cursor-pointer hover:bg-white/10 transition-all">
              <span className="material-symbols-outlined">upload</span>
              CARREGAR FICHEIRO
              <input type="file" accept=".json" onChange={handleImport} className="hidden" />
            </label>
          </div>
        </div>
      </section>

      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-red-500 uppercase tracking-widest px-1">Zona de Perigo</h3>
        <div className="bg-red-500/5 rounded-3xl border border-red-500/10 p-6">
          <h4 className="text-sm font-bold text-red-500 mb-1">Limpar todos os dados</h4>
          <p className="text-xs text-gray-500 mb-4">Esta ação irá apagar todos os jogadores, locais e histórico do seu telemóvel e repor os dados iniciais do sistema.</p>
          <button 
            onClick={() => { if(window.confirm('TEM A CERTEZA? Isto irá apagar TUDO o que não estiver guardado no código do GitHub.')) onResetData(); }}
            className="w-full bg-red-500/10 text-red-500 border border-red-500/30 font-black py-3 rounded-2xl text-xs uppercase hover:bg-red-500 hover:text-white transition-all"
          >
            Reset Total da App
          </button>
        </div>
      </section>

      <div className="bg-card-dark rounded-2xl p-4 border border-white/5">
        <div className="flex items-center gap-3 text-gray-500">
          <span className="material-symbols-outlined text-sm">info</span>
          <p className="text-[10px] leading-relaxed">
            Nota: Para que os dados fiquem "gravados no GitHub", deve editar as variáveis <b>MOCK_PLAYERS</b> no ficheiro <b>App.tsx</b> com os seus dados reais e fazer o commit.
          </p>
        </div>
      </div>
    </div>
  );
};

