                            <span className={`text-[9px] font-black px-3 py-1.5 rounded-xl backdrop-blur-xl border border-white/10 uppercase ${loc.type === 'Indoor' ? 'bg-primary/40 text-white' : 'bg-blue-500/40 text-white'}`}>
                                {loc.type}
