import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  // Inicializa com listas vazias para permitir introdução manual total (White Label)
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  // Função auxiliar para comparar se dois objetos de torneio são diferentes (para evitar re-renders desnecessários)
  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) return null;
    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };
      const ts = `&ts=${Date.now()}`;
      const [pRes, lRes, tRes] = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/locations?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/tournaments?select=data${ts}`, { headers }).then(r => r.json())
      ]);

      if (!Array.isArray(pRes)) return null;

      // Processamento e Ordenação Segura
      const playersData = pRes.length > 0 ? pRes.map((i: any) => i.data) : [];
      const locationsData = lRes.length > 0 ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = tRes.length > 0 ? tRes.map((i: any) => i.data) : [];

      // Ordenar torneios por data (mais recente primeiro)
      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };
    } catch (e) { 
        console.error("Cloud Fetch Error:", e);
        return null; 
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
        body: JSON.stringify({ id, data })
      });
    } catch (e) {
        console.error("Push Error:", e);
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}` }
      });
    } catch (e) {}
  };

  // Lógica centralizada de atualização de dados
  const refreshAllData = useCallback(async () => {
    const cloudData = await fetchCloudData(cloudConfig);

    let loadedPlayers: Player[] = [];
    let loadedLocations: Location[] = [];
    let allTournaments: Tournament[] = [];

    if (cloudData) {
      loadedPlayers = cloudData.players;
      loadedLocations = cloudData.locations;
      allTournaments = cloudData.tournaments;
    } else {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');
      if (p) loadedPlayers = JSON.parse(p);
      if (l) loadedLocations = JSON.parse(l);
      if (h) allTournaments = JSON.parse(h);
    }

    // Atualiza estados apenas se houver mudanças (React faz shallow compare, mas arrays novos triggeram sempre, então aceitamos o update)
    setPlayers(loadedPlayers);
    setLocations(loadedLocations);

    // Separar Lógica de Ativos vs Histórico
    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    // Lógica vital para sincronização multi-dispositivo
    if (active) {
       setActiveTournament(prev => {
           // Se o torneio que veio da cloud for diferente do que temos em memória, atualizamos a memória
           if (isTournamentDifferent(prev, active)) {
               // Se o torneio tem jogos (live), atualizamos também o estado dos jogos
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData]);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  // AUTO-SYNC / POLLING: Verifica alterações na cloud a cada 5 segundos
  useEffect(() => {
      if (!cloudConfig.enabled) return;

      const intervalId = setInterval(() => {
          // Chamamos o refresh em background sem ativar o estado isLoading para não bloquear a UI
          refreshAllData();
      }, 5000); // 5 segundos

      return () => clearInterval(intervalId);
  }, [cloudConfig, refreshAllData]);


  // Persistence local storage (Backup local)
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamWins = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamWins.has(k1)) teamWins.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamWins.has(k2)) teamWins.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamWins.get(k1)!, s2 = teamWins.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamWins.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  // --- Handlers ---

  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const };
      setActiveTournament(newT);
      // Push imediato para a Cloud para que outros dispositivos vejam
      await pushToCloud('tournaments', newT.id, newT);
      // Forçar refresh para garantir consistência
      refreshAllData();
  };

  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };

  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };

  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }

    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);

    if (m1 && m2) {
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();

      if (nextRoundNumber === 2) {
        nextMatches = [
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          { id: `m-r2-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        nextMatches = [
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          { id: `m-r3-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }

      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);

      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };

  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);

    setMatches(updatedMatches);

    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        // Não fazemos await aqui para não bloquear a UI rápida do score, o polling eventualmente garante consistência se falhar
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };

  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };

  // ... Restantes handlers de CRUD (Jogadores, Locais)
  const handleAddPlayer = async (p: Player) => { 
    setPlayers(prev => [...prev, p]); 
    await pushToCloud('players', p.id, p); 
  };

  const handleUpdatePlayer = async (p: Player) => { 
    setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); 
    await pushToCloud('players', p.id, p); 
  };

  const handleDeletePlayer = async (id: string) => { 
    if (window.confirm('Remover jogador?')) { 
      setPlayers(prev => prev.filter(p => p.id !== id)); 
      await deleteFromCloud('players', id); 
    } 
  };

  const handleAddLocation = async (l: Location) => {
    setLocations(prev => [...prev, l]);
    await pushToCloud('locations', l.id, l);
  };

  const handleUpdateLocation = async (l: Location) => {
    setLocations(prev => prev.map(old => old.id === l.id ? l : old));
    await pushToCloud('locations', l.id, l);
  };

  const handleDeleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(l => l.id !== id));
    await deleteFromCloud('locations', id);
  };

  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { 
          ...activeTournament, 
          status: 'finished', 
          matches: matches.map(m => ({...m, status: 'finished'})), 
        };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">Sincronizando Cloud...</p></div>;

    let ScreenComponent;
    switch (currentScreen) {
      case Screen.HOME: ScreenComponent = <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} />; break;
      case Screen.PROFILE: ScreenComponent = <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />; break;
      case Screen.LIVE_GAME: ScreenComponent = <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />; break;
      case Screen.TOURNAMENT_SUMMARY: ScreenComponent = <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />; break;
      case Screen.TOURNAMENT_RESULTS: ScreenComponent = <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />; break;
      case Screen.GLOBAL_STATS: ScreenComponent = <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />; break;
      case Screen.TOURNAMENT_HISTORY: ScreenComponent = <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />; break;
      case Screen.HISTORY_DETAIL: ScreenComponent = selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} onDeleteTournament={handleDeleteTournament} /> : null; break;
      case Screen.TEAM_SETUP: ScreenComponent = <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />; break;
      case Screen.PLAYERS: ScreenComponent = <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />; break;
      case Screen.LOCATIONS: ScreenComponent = <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />; break;
      case Screen.SETTINGS: ScreenComponent = <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />; break;
      default: ScreenComponent = null;
    }

    return (
        <PullToRefresh onRefresh={refreshAllData}>
            {ScreenComponent}
        </PullToRefresh>
    );
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <div className="absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1 rounded-full border border-white/5 pointer-events-none">
          <div className={`size-1.5 rounded-full ${cloudConfig.enabled ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500 animate-pulse'}`}></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">{cloudConfig.enabled ? 'Live Cloud Sync' : 'Offline'}</span>
        </div>

        {renderScreen()}

        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Screen, Tournament, Location } from '../types';

interface HistoryProps {
  history: Tournament[];
  locations: Location[];
  onViewTournament: (t: Tournament) => void;
  onDeleteTournament?: (id: string) => void;
}

export const TournamentHistoryScreen: React.FC<HistoryProps> = ({ history, locations, onViewTournament, onDeleteTournament }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState<string>('all');
  const [showCancelled, setShowCancelled] = useState(false);

  const filteredHistory = useMemo(() => {
    return history
      .filter(t => {
        const loc = locations.find(l => l.id === t.locationId);
        const locName = loc?.name || 'Local Desconhecido';
        const matchesSearch = locName.toLowerCase().includes(searchTerm.toLowerCase());

        const tDate = new Date(t.date);
        const monthYear = `${tDate.getFullYear()}-${String(tDate.getMonth() + 1).padStart(2, '0')}`;
        const matchesMonth = selectedMonth === 'all' || monthYear === selectedMonth;

        // Exibe se estiver finished ou (se showCancelled for true, também cancelled)
        const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');

        return matchesSearch && matchesMonth && statusMatch;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [history, searchTerm, selectedMonth, locations, showCancelled]);

  const months = useMemo(() => {
    const m = new Set<string>();
    history.forEach(t => {
      const d = new Date(t.date);
      m.add(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
    });
    return Array.from(m).sort().reverse();
  }, [history]);

  return (
    <div className="flex flex-col gap-6 px-4 pt-6 pb-32 animate-fade-in">
      <header>
        <h1 className="text-3xl font-black text-white">Registo <br/><span className="text-primary">Histórico</span></h1>
        <p className="text-gray-500 text-sm mt-1">Consulte todos os torneios realizados.</p>
      </header>

      <div className="space-y-3">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Filtrar por local..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-card-dark border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:ring-2 focus:ring-primary/50 outline-none transition-all"
          />
        </div>

        <div className="flex gap-2 items-center">
             <button onClick={() => setShowCancelled(!showCancelled)} className={`px-3 py-2 rounded-xl border flex items-center gap-2 ${showCancelled ? 'bg-red-500/10 border-red-500 text-red-500' : 'bg-card-dark border-white/10 text-gray-500'}`}>
                 <span className="material-symbols-outlined text-[16px]">{showCancelled ? 'check_box' : 'check_box_outline_blank'}</span>
                 <span className="text-[10px] font-bold uppercase">Cancelados</span>
             </button>
             <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar flex-1">
              <button 
                onClick={() => setSelectedMonth('all')}
                className={`px-4 py-2 rounded-full text-[10px] font-black uppercase whitespace-nowrap border transition-all ${selectedMonth === 'all' ? 'bg-primary border-primary text-background-dark' : 'bg-white/5 border-white/10 text-gray-500'}`}
              >
                Todos
              </button>
              {months.map(m => {
                const [year, month] = m.split('-');
                const date = new Date(parseInt(year), parseInt(month) - 1);
                const label = date.toLocaleDateString('pt-PT', { month: 'short', year: '2-digit' });
                return (
                  <button 
                    key={m}
                    onClick={() => setSelectedMonth(m)}
                    className={`px-4 py-2 rounded-full text-[10px] font-black uppercase whitespace-nowrap border transition-all ${selectedMonth === m ? 'bg-primary border-primary text-background-dark' : 'bg-white/5 border-white/10 text-gray-500'}`}
                  >
                    {label}
                  </button>
                );
              })}
            </div>
        </div>
      </div>

      <div className="flex flex-col gap-4">
        {filteredHistory.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 opacity-30">
            <span className="material-symbols-outlined text-6xl mb-4">history_toggle_off</span>
            <p className="text-sm font-bold">Nenhum registo encontrado</p>
          </div>
        ) : (
          filteredHistory.map(t => {
            const loc = locations.find(l => l.id === t.locationId);
            const locName = loc?.name || 'Local Desconhecido';
            const isCancelled = t.status === 'cancelled';

            return (
              <div key={t.id} className={`relative group ${isCancelled ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                <button 
                  onClick={() => !isCancelled && onViewTournament(t)}
                  disabled={isCancelled}
                  className="w-full bg-card-dark p-5 rounded-3xl border border-white/5 hover:border-primary/30 transition-all text-left group active:scale-[0.98] disabled:cursor-not-allowed"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div>
                      <span className={`text-[10px] font-black uppercase tracking-widest block mb-1 ${isCancelled ? 'text-red-500' : 'text-primary'}`}>
                        {new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                        {isCancelled && ' (CANCELADO)'}
                      </span>
                      <h3 className="text-xl font-black text-white group-hover:text-primary transition-colors">{locName}</h3>
                    </div>
                    {!isCancelled && (
                        <div className="size-10 rounded-2xl bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                            <span className="material-symbols-outlined text-gray-500 group-hover:text-primary">chevron_right</span>
                        </div>
                    )}
                  </div>

                  <div className="flex items-center gap-4 text-gray-500">
                    <div className="flex items-center gap-1.5">
                      <span className="material-symbols-outlined text-[16px]">sports_tennis</span>
                      <span className="text-[10px] font-bold uppercase">{t.matches?.length || 0} Jogos</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="material-symbols-outlined text-[16px]">schedule</span>
                      <span className="text-[10px] font-bold uppercase">{t.time} • {t.duration}h</span>
                    </div>
                  </div>
                </button>
                {/* Botão de eliminar flutuante */}
                <button 
                  onClick={(e) => { e.stopPropagation(); onDeleteTournament?.(t.id); }}
                  className="absolute bottom-4 right-4 p-2 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all opacity-0 group-hover:opacity-100 z-10"
                >
                  <span className="material-symbols-outlined text-base">delete</span>
                </button>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export enum Screen {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PLAYERS = 'PLAYERS',
  LIVE_GAME = 'LIVE_GAME',
  TOURNAMENT_SUMMARY = 'TOURNAMENT_SUMMARY',
  TOURNAMENT_RESULTS = 'TOURNAMENT_RESULTS',
  TEAM_SETUP = 'TEAM_SETUP',
  SETTINGS = 'SETTINGS',
  GLOBAL_STATS = 'GLOBAL_STATS',
  LOCATIONS = 'LOCATIONS',
  HISTORY_DETAIL = 'HISTORY_DETAIL',
  TOURNAMENT_HISTORY = 'TOURNAMENT_HISTORY'
}

export interface CloudConfig {
  url: string;
  key: string;
  enabled: boolean;
}

export interface Player {
  id: string;
  name: string;
  lastName?: string;
  nickname?: string;
  birthDate?: string;
  hand?: 'Destro' | 'Canhoto';
  level: string; 
  rankingPoints?: number; 
  image: string;
  backgroundColor?: string;
}

export interface Location {
  id: string;
  name: string;
  type: 'Indoor' | 'Outdoor';
  address?: string;
  imageUrl?: string;
  googleMapsUrl?: string;
  websiteUrl?: string;
}

export interface Match {
  id: string;
  team1: Player[];
  team2: Player[];
  score1: number;
  score2: number;
  court: number;
  status: 'live' | 'finished' | 'scheduled';
  round: number;
  date?: string;
}

export interface Tournament {
  id: string;
  date: string;
  time: string;
  duration: number;
  locationId: string;
  confirmedPlayerIds: string[];
  status: 'scheduled' | 'live' | 'finished' | 'cancelled';
  rosterClosed?: boolean; // Novo campo para fechar a convocatória antes do sorteio
  matches?: Match[];
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  // Inicializa com listas vazias para permitir introdução manual total (White Label)
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  // Função auxiliar para comparar se dois objetos de torneio são diferentes (para evitar re-renders desnecessários)
  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) return null;
    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };
      const ts = `&ts=${Date.now()}`;
      const [pRes, lRes, tRes] = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/locations?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/tournaments?select=data${ts}`, { headers }).then(r => r.json())
      ]);

      if (!Array.isArray(pRes)) return null;

      // Processamento e Ordenação Segura
      const playersData = pRes.length > 0 ? pRes.map((i: any) => i.data) : [];
      const locationsData = lRes.length > 0 ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = tRes.length > 0 ? tRes.map((i: any) => i.data) : [];

      // Ordenar torneios por data (mais recente primeiro)
      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };
    } catch (e) { 
        console.error("Cloud Fetch Error:", e);
        return null; 
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
        body: JSON.stringify({ id, data })
      });
    } catch (e) {
        console.error("Push Error:", e);
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}` }
      });
    } catch (e) {}
  };

  // Lógica centralizada de atualização de dados
  const refreshAllData = useCallback(async () => {
    const cloudData = await fetchCloudData(cloudConfig);

    let loadedPlayers: Player[] = [];
    let loadedLocations: Location[] = [];
    let allTournaments: Tournament[] = [];

    if (cloudData) {
      loadedPlayers = cloudData.players;
      loadedLocations = cloudData.locations;
      allTournaments = cloudData.tournaments;
    } else {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');
      if (p) loadedPlayers = JSON.parse(p);
      if (l) loadedLocations = JSON.parse(l);
      if (h) allTournaments = JSON.parse(h);
    }

    // Atualiza estados
    setPlayers(loadedPlayers);
    setLocations(loadedLocations);

    // Separar Lógica de Ativos vs Histórico
    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    // Lógica vital para sincronização
    if (active) {
       setActiveTournament(prev => {
           if (isTournamentDifferent(prev, active)) {
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData]);

  // Initial Load (apenas uma vez)
  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  // REMOVIDO: useEffect com setInterval para polling.
  // A atualização agora acontece apenas via refreshAllData (chamado no PullToRefresh ou init).

  // Persistence local storage (Backup local)
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamWins = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamWins.has(k1)) teamWins.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamWins.has(k2)) teamWins.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamWins.get(k1)!, s2 = teamWins.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamWins.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  // --- Handlers ---

  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const, rosterClosed: false };
      setActiveTournament(newT);
      await pushToCloud('tournaments', newT.id, newT);
  };

  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };

  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };

  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }

    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);

    if (m1 && m2) {
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();

      if (nextRoundNumber === 2) {
        nextMatches = [
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          { id: `m-r2-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        nextMatches = [
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          { id: `m-r3-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }

      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);

      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };

  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);

    setMatches(updatedMatches);

    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };

  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };

  // ... Restantes handlers de CRUD
  const handleAddPlayer = async (p: Player) => { 
    setPlayers(prev => [...prev, p]); 
    await pushToCloud('players', p.id, p); 
  };

  const handleUpdatePlayer = async (p: Player) => { 
    setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); 
    await pushToCloud('players', p.id, p); 
  };

  const handleDeletePlayer = async (id: string) => { 
    if (window.confirm('Remover jogador?')) { 
      setPlayers(prev => prev.filter(p => p.id !== id)); 
      await deleteFromCloud('players', id); 
    } 
  };

  const handleAddLocation = async (l: Location) => {
    setLocations(prev => [...prev, l]);
    await pushToCloud('locations', l.id, l);
  };

  const handleUpdateLocation = async (l: Location) => {
    setLocations(prev => prev.map(old => old.id === l.id ? l : old));
    await pushToCloud('locations', l.id, l);
  };

  const handleDeleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(l => l.id !== id));
    await deleteFromCloud('locations', id);
  };

  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { 
          ...activeTournament, 
          status: 'finished', 
          matches: matches.map(m => ({...m, status: 'finished'})), 
        };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">Sincronizando Cloud...</p></div>;

    let ScreenComponent;
    switch (currentScreen) {
      case Screen.HOME: ScreenComponent = <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} />; break;
      case Screen.PROFILE: ScreenComponent = <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />; break;
      case Screen.LIVE_GAME: ScreenComponent = <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />; break;
      case Screen.TOURNAMENT_SUMMARY: ScreenComponent = <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />; break;
      case Screen.TOURNAMENT_RESULTS: ScreenComponent = <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />; break;
      case Screen.GLOBAL_STATS: ScreenComponent = <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />; break;
      case Screen.TOURNAMENT_HISTORY: ScreenComponent = <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />; break;
      case Screen.HISTORY_DETAIL: ScreenComponent = selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} onDeleteTournament={handleDeleteTournament} /> : null; break;
      case Screen.TEAM_SETUP: ScreenComponent = <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />; break;
      case Screen.PLAYERS: ScreenComponent = <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />; break;
      case Screen.LOCATIONS: ScreenComponent = <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />; break;
      case Screen.SETTINGS: ScreenComponent = <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />; break;
      default: ScreenComponent = null;
    }

    return (
        <PullToRefresh onRefresh={refreshAllData}>
            {ScreenComponent}
        </PullToRefresh>
    );
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <div className="absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1 rounded-full border border-white/5 pointer-events-none">
          <div className={`size-1.5 rounded-full ${cloudConfig.enabled ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500 animate-pulse'}`}></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">{cloudConfig.enabled ? 'Cloud Enabled' : 'Offline'}</span>
        </div>

        {renderScreen()}

        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00'); // Hora predefinida para as 22:00
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);

    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) {
        setLocationId(lxIndoor.id);
    } else if (locations.length > 0) {
        setLocationId(locations[0].id);
    }

    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: '' 
    };
    // Adiciona o jogador à base de dados global e atualiza o torneio imediatamente
    onAddPlayer(newPlayer);
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }
    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled',
        rosterClosed: false
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (!activeTournament) return;
    if (activeTournament.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores para fechar a convocatória.");
        return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const handleReopenRoster = () => {
      if (!activeTournament) return;
      if (confirm("Reabrir convocatória para alterações?")) {
          onUpdateTournament({ ...activeTournament, rosterClosed: false });
      }
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark/95 backdrop-blur-md p-4 animate-fade-in flex flex-col">
                    <header className="flex items-center justify-between mb-4"><h2 className="text-xl font-bold">Gestão de Confirmados</h2><button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button></header>
                    {isAddingGuest ? (
                        <div className="bg-primary/10 border border-primary/30 p-4 rounded-2xl mb-4 animate-fade-in-up">
                            <h3 className="text-xs font-bold text-primary uppercase mb-3">Novo Convidado</h3>
                            <div className="space-y-3">
                                <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <input type="text" placeholder="Alcunha" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-sm text-white" />
                                <div className="flex gap-2"><button onClick={() => setIsAddingGuest(false)} className="flex-1 py-2 text-gray-400 font-bold text-xs uppercase">Cancelar</button><button onClick={handleSaveGuest} className="flex-1 py-2 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase">Guardar</button></div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex gap-2 mb-4">
                            <div className="relative flex-1"><span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">search</span><input type="text" placeholder="Pesquisar..." value={playerSearchTerm} onChange={(e) => setPlayerSearchTerm(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white" /></div>
                            <button onClick={() => setIsAddingGuest(true)} className="bg-primary/20 text-primary border border-primary/30 px-4 rounded-xl flex items-center justify-center"><span className="material-symbols-outlined text-sm">person_add</span></button>
                        </div>
                    )}
                    <div className="grid grid-cols-4 gap-3 overflow-y-auto pb-32 hide-scrollbar">
                        {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                            const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                            return (
                                <button key={p.id} onClick={() => togglePlayerInActiveTournament(p.id)} className={`flex flex-col items-center p-2 rounded-2xl border transition-all ${isConfirmed ? 'bg-primary/20 border-primary scale-105' : 'bg-card-dark border-white/5 opacity-50'}`}>
                                    <div className="relative mb-1">
                                        {renderGlobalAvatar(p, 'size-10')}
                                        {isConfirmed && <div className="absolute -bottom-1 -right-1 bg-primary text-black rounded-full p-0.5 border border-background-dark"><span className="material-symbols-outlined text-[10px] font-bold block">check</span></div>}
                                    </div>
                                    <span className="text-[9px] font-bold truncate w-full text-center">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            );
                        })}
                    </div>
                    <div className="fixed bottom-6 left-4 right-4 max-w-md mx-auto space-y-2">
                        {isQuorumReached ? (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-bold py-4 rounded-2xl shadow-xl hover:bg-emerald-400 transition-all flex items-center justify-center gap-2">
                                <span className="material-symbols-outlined">lock</span>
                                <span>FECHAR CONVOCATÓRIA</span>
                             </button>
                        ) : (
                            <div className="bg-card-dark border border-white/10 p-3 rounded-xl text-center">
                                <span className="text-xs font-bold text-gray-400">Selecione {8 - confirmedCount} jogadores para fechar</span>
                            </div>
                        )}
                        <button onClick={() => setIsManagingPlayers(false)} className="w-full bg-white/5 text-gray-400 font-bold py-3 rounded-2xl">Voltar atrás</button>
                    </div>
                </div>
            )}
            <header>
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-slate-400">
                    {isLive ? 'Torneio em andamento!' : isRosterClosed ? 'Tudo pronto para começar.' : 'Fase de convocatória.'}
                </p>
            </header>

            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isLive ? 'ring-primary shadow-primary/20' : isRosterClosed ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                {isLive && <div className="absolute inset-0 bg-primary/5 animate-pulse"></div>}
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isLive ? 'bg-primary text-background-dark border-primary' : isRosterClosed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-white/10 text-gray-400 border-white/20'}`}>
                                    {isLive ? 'A DECORRER' : isRosterClosed ? 'CONVOCATÓRIA FECHADA' : 'ABERTO A INSCRIÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isLive ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/30' : isRosterClosed ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">{isLive ? 'sports_baseball' : isRosterClosed ? 'lock' : 'group_add'}</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isQuorumReached ? 'text-emerald-400' : 'text-white'}`}>
                                {isQuorumReached ? 'LOTAÇÃO ESGOTADA' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isQuorumReached ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 px-6 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-primary/20 animate-bounce-subtle">
                    <span className="material-symbols-outlined">scoreboard</span>
                    <span>IR PARA JOGO (EM DIRETO)</span>
                </button>
            ) : isRosterClosed ? (
                <div className="space-y-3">
                    <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100">
                        <span className="material-symbols-outlined">casino</span>
                        <span>Realizar Sorteio de Equipas</span>
                    </button>
                    <button onClick={handleReopenRoster} className="w-full text-[10px] font-bold text-gray-500 uppercase py-2 flex items-center justify-center gap-1 hover:text-white">
                        <span className="material-symbols-outlined text-sm">lock_open</span> Reabrir Convocatória para Alterações
                    </button>
                </div>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-white/5 text-white border border-white/10 hover:bg-white/10">
                    <span className="material-symbols-outlined">person_add</span>
                    <span>Gerir Jogadores / Convidados</span>
                </button>
            )}

            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    {!isRosterClosed && !isLive && <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Editar</button>}
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => !isRosterClosed && setIsManagingPlayers(true)} className={`flex flex-col items-center gap-2 ${isRosterClosed ? 'opacity-30 cursor-not-allowed' : ''}`}>
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={onCancelTournament} className="text-[10px] font-bold text-red-500/60 hover:text-red-500 text-center mt-6 uppercase tracking-widest border border-red-500/10 hover:border-red-500/30 py-3 rounded-xl transition-all">
                Cancelar e Remover Agendamento
            </button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>
        <section className="grid grid-cols-3 gap-3">
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
            <span className="text-xl font-bold text-white">{totalGames}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
          </div>
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
            <span className="text-xl font-bold text-white">{totalHours}h</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
          </div>
          <button 
            onClick={() => setScreen(Screen.LOCATIONS)}
            className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
          >
            <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
            <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
          </button>
        </section>
        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  // Inicializa com listas vazias para permitir introdução manual total (White Label)
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  // Função auxiliar para comparar se dois objetos de torneio são diferentes (para evitar re-renders desnecessários)
  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) return null;
    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };
      // Adiciona timestamp para evitar cache do browser
      const ts = `&ts=${Date.now()}`;
      const [pRes, lRes, tRes] = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/locations?select=data${ts}`, { headers }).then(r => r.json()),
        fetch(`${config.url}/rest/v1/tournaments?select=data${ts}`, { headers }).then(r => r.json())
      ]);

      if (!Array.isArray(pRes)) return null;

      // Processamento e Ordenação Segura
      const playersData = pRes.length > 0 ? pRes.map((i: any) => i.data) : [];
      const locationsData = lRes.length > 0 ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = tRes.length > 0 ? tRes.map((i: any) => i.data) : [];

      // Ordenar torneios por data (mais recente primeiro)
      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };
    } catch (e) { 
        console.error("Cloud Fetch Error:", e);
        return null; 
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}`, 'Content-Type': 'application/json', 'Prefer': 'resolution=merge-duplicates' },
        body: JSON.stringify({ id, data })
      });
    } catch (e) {
        console.error("Push Error:", e);
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 'apikey': cloudConfig.key, 'Authorization': `Bearer ${cloudConfig.key}` }
      });
    } catch (e) {}
  };

  // Lógica centralizada de atualização de dados
  const refreshAllData = useCallback(async () => {
    // Se estivermos a carregar pela primeira vez, mostra loading. Se for refresh de foco, é silencioso.
    const cloudData = await fetchCloudData(cloudConfig);

    let loadedPlayers: Player[] = [];
    let loadedLocations: Location[] = [];
    let allTournaments: Tournament[] = [];

    if (cloudData) {
      loadedPlayers = cloudData.players;
      loadedLocations = cloudData.locations;
      allTournaments = cloudData.tournaments;
    } else {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');
      if (p) loadedPlayers = JSON.parse(p);
      if (l) loadedLocations = JSON.parse(l);
      if (h) allTournaments = JSON.parse(h);
    }

    // Atualiza estados
    setPlayers(loadedPlayers);
    setLocations(loadedLocations);

    // Separar Lógica de Ativos vs Histórico
    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    // Lógica vital para sincronização
    if (active) {
       setActiveTournament(prev => {
           if (isTournamentDifferent(prev, active)) {
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData]);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  // SMART SYNC: Atualiza quando a janela ganha foco (ex: mudar de aba ou desbloquear telemóvel)
  useEffect(() => {
      const handleFocus = () => {
          if (document.visibilityState === 'visible' && cloudConfig.enabled) {
              refreshAllData();
          }
      };

      window.addEventListener('focus', handleFocus);
      document.addEventListener('visibilitychange', handleFocus);

      return () => {
          window.removeEventListener('focus', handleFocus);
          document.removeEventListener('visibilitychange', handleFocus);
      };
  }, [refreshAllData, cloudConfig.enabled]);

  // Persistence local storage (Backup local)
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamWins = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamWins.has(k1)) teamWins.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamWins.has(k2)) teamWins.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamWins.get(k1)!, s2 = teamWins.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamWins.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  // --- Handlers ---

  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const, rosterClosed: false };
      setActiveTournament(newT);
      await pushToCloud('tournaments', newT.id, newT);
  };

  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };

  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };

  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }

    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);

    if (m1 && m2) {
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();

      if (nextRoundNumber === 2) {
        nextMatches = [
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          { id: `m-r2-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        nextMatches = [
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          { id: `m-r3-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }

      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);

      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };

  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);

    setMatches(updatedMatches);

    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };

  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };

  // ... Restantes handlers de CRUD
  const handleAddPlayer = async (p: Player) => { 
    setPlayers(prev => [...prev, p]); 
    await pushToCloud('players', p.id, p); 
  };

  const handleUpdatePlayer = async (p: Player) => { 
    setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); 
    await pushToCloud('players', p.id, p); 
  };

  const handleDeletePlayer = async (id: string) => { 
    if (window.confirm('Remover jogador?')) { 
      setPlayers(prev => prev.filter(p => p.id !== id)); 
      await deleteFromCloud('players', id); 
    } 
  };

  const handleAddLocation = async (l: Location) => {
    setLocations(prev => [...prev, l]);
    await pushToCloud('locations', l.id, l);
  };

  const handleUpdateLocation = async (l: Location) => {
    setLocations(prev => prev.map(old => old.id === l.id ? l : old));
    await pushToCloud('locations', l.id, l);
  };

  const handleDeleteLocation = async (id: string) => {
    setLocations(prev => prev.filter(l => l.id !== id));
    await deleteFromCloud('locations', id);
  };

  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { 
          ...activeTournament, 
          status: 'finished', 
          matches: matches.map(m => ({...m, status: 'finished'})), 
        };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };

  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">Sincronizando Cloud...</p></div>;

    let ScreenComponent;
    switch (currentScreen) {
      case Screen.HOME: ScreenComponent = <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} />; break;
      case Screen.PROFILE: ScreenComponent = <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />; break;
      case Screen.LIVE_GAME: ScreenComponent = <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />; break;
      case Screen.TOURNAMENT_SUMMARY: ScreenComponent = <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />; break;
      case Screen.TOURNAMENT_RESULTS: ScreenComponent = <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />; break;
      case Screen.GLOBAL_STATS: ScreenComponent = <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />; break;
      case Screen.TOURNAMENT_HISTORY: ScreenComponent = <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />; break;
      case Screen.HISTORY_DETAIL: ScreenComponent = selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} onDeleteTournament={handleDeleteTournament} /> : null; break;
      case Screen.TEAM_SETUP: ScreenComponent = <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />; break;
      case Screen.PLAYERS: ScreenComponent = <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />; break;
      case Screen.LOCATIONS: ScreenComponent = <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />; break;
      case Screen.SETTINGS: ScreenComponent = <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />; break;
      default: ScreenComponent = null;
    }

    return (
        <PullToRefresh onRefresh={refreshAllData}>
            {ScreenComponent}
        </PullToRefresh>
    );
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <button 
          onClick={refreshAllData}
          className="absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1 rounded-full border border-white/5 cursor-pointer hover:bg-black/60 active:scale-95 transition-all"
        >
          <div className={`size-1.5 rounded-full ${cloudConfig.enabled ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-orange-500 animate-pulse'}`}></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">{cloudConfig.enabled ? 'Live Cloud Sync' : 'Offline'}</span>
          <span className="material-symbols-outlined text-[10px] text-gray-500">refresh</span>
        </button>

        {renderScreen()}

        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';

interface PullToRefreshProps {
  onRefresh: () => Promise<void>;
  children: React.ReactNode;
}

export const PullToRefresh: React.FC<PullToRefreshProps> = ({ onRefresh, children }) => {
  const [startY, setStartY] = useState(0);
  const [currentY, setCurrentY] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  // Limiar para ativar o refresh (pixels)
  const THRESHOLD = 70;
  // Fator de resistência (para parecer elástico)
  const DAMPING = 0.4;

  // --- TOUCH HANDLERS (Mobile) ---
  const handleTouchStart = (e: React.TouchEvent) => {
    if (window.scrollY === 0 && !isRefreshing) {
      setStartY(e.touches[0].clientY);
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    const y = e.touches[0].clientY;
    const diff = y - startY;
    if (diff > 0 && window.scrollY === 0 && !isRefreshing) {
      setCurrentY(diff * DAMPING);
    }
  };

  const handleTouchEnd = async () => {
    finishDrag();
  };

  // --- MOUSE HANDLERS (Desktop) ---
  const handleMouseDown = (e: React.MouseEvent) => {
      if (window.scrollY === 0 && !isRefreshing) {
          setStartY(e.clientY);
          setIsDragging(true);
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
      if (!isDragging) return;
      const y = e.clientY;
      const diff = y - startY;
      if (diff > 0 && window.scrollY === 0 && !isRefreshing) {
          setCurrentY(diff * DAMPING);
      }
  };

  const handleMouseUp = () => {
      if (isDragging) {
          setIsDragging(false);
          finishDrag();
      }
  };

  const handleMouseLeave = () => {
      if (isDragging) {
          setIsDragging(false);
          finishDrag();
      }
  };

  // Lógica comum de finalização
  const finishDrag = async () => {
    if (isRefreshing) return;

    if (currentY > THRESHOLD) {
      setIsRefreshing(true);
      setCurrentY(THRESHOLD); // Mantém na posição de loading

      try {
        await onRefresh();
      } finally {
        setTimeout(() => {
            setIsRefreshing(false);
            setCurrentY(0);
        }, 500);
      }
    } else {
      setCurrentY(0);
    }
    setStartY(0);
  };

  // Efeito para bloquear scroll body durante o refresh
  useEffect(() => {
    document.body.style.overflow = isRefreshing ? 'hidden' : '';
    return () => { document.body.style.overflow = ''; };
  }, [isRefreshing]);

  return (
    <div 
      className="min-h-screen relative"
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      ref={contentRef}
    >
      {/* Loading Indicator Container */}
      <div 
        className="absolute top-0 left-0 w-full flex justify-center pointer-events-none z-0 overflow-hidden"
        style={{ 
            height: `${currentY}px`,
            opacity: currentY > 5 ? 1 : 0,
            transition: isRefreshing ? 'height 0.2s' : 'none'
        }}
      >
        <div className="flex items-center justify-center h-full pb-2">
            <div className={`p-2 rounded-full bg-card-dark border border-white/10 shadow-xl flex items-center justify-center transition-transform ${currentY > THRESHOLD ? 'rotate-180' : ''}`}>
                {isRefreshing ? (
                    <span className="material-symbols-outlined text-primary animate-spin">refresh</span>
                ) : (
                    <span className="material-symbols-outlined text-gray-400" style={{ transform: `rotate(${currentY * 2}deg)` }}>arrow_downward</span>
                )}
            </div>
        </div>
      </div>

      {/* Main Content with Transform */}
      <div 
        className="relative z-10 bg-background-dark min-h-screen transition-transform duration-300 ease-out"
        style={{ 
            transform: `translateY(${currentY}px)`,
            transition: isRefreshing || currentY === 0 ? 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)' : 'none'
        }}
      >
        {children}
      </div>
    </div>
  );
};

