  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark flex flex-col animate-fade-in">
                    {/* Header e Search - Fixo no Topo */}
                    <div className="shrink-0 p-4 border-b border-white/5 bg-background-dark/95 backdrop-blur-md z-10">
                        <header className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold">Gestão de Confirmados</h2>
                            <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center border border-white/5">
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </header>

                        {isAddingGuest ? (
                            <div className="bg-primary/10 border border-primary/30 p-4 rounded-2xl animate-fade-in-up">
                                <h3 className="text-xs font-bold text-primary uppercase mb-3">Novo Convidado</h3>
                                <div className="space-y-3">
                                    <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white" />
                                    <input type="text" placeholder="Alcunha" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white" />
                                    <div className="flex gap-2">
                                        <button onClick={() => setIsAddingGuest(false)} className="flex-1 py-3 text-gray-400 font-bold text-xs uppercase border border-white/10 rounded-xl">Cancelar</button>
                                        <button onClick={handleSaveGuest} className="flex-1 py-3 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase shadow-lg shadow-primary/20">Guardar</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <div className="relative flex-1">
                                    <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">search</span>
                                    <input type="text" placeholder="Pesquisar..." value={playerSearchTerm} onChange={(e) => setPlayerSearchTerm(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-3 text-base text-white" />
                                </div>
                                <button onClick={() => setIsAddingGuest(true)} className="bg-primary/20 text-primary border border-primary/30 px-4 rounded-xl flex items-center justify-center active:scale-95 transition-transform"><span className="material-symbols-outlined">person_add</span></button>
                            </div>
                        )}
                    </div>

                    {/* Lista com Scroll - Ocupa o espaço disponível */}
                    <div className="flex-1 overflow-y-auto p-4 hide-scrollbar">
                        <div className="grid grid-cols-4 gap-3 pb-4">
                            {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                                const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                                return (
                                    <button key={p.id} onClick={() => togglePlayerInActiveTournament(p.id)} className={`flex flex-col items-center p-2 rounded-2xl border transition-all active:scale-95 ${isConfirmed ? 'bg-primary/20 border-primary shadow-[0_0_10px_rgba(96,122,251,0.2)]' : 'bg-card-dark border-white/5 opacity-50'}`}>
                                        <div className="relative mb-1">
                                            {renderGlobalAvatar(p, 'size-10')}
                                            {isConfirmed && <div className="absolute -bottom-1 -right-1 bg-primary text-black rounded-full p-0.5 border border-background-dark animate-bounce-subtle"><span className="material-symbols-outlined text-[10px] font-bold block">check</span></div>}
                                        </div>
                                        <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Footer Fixo - Sempre visível mesmo com teclado */}
                    <div className="shrink-0 p-4 bg-background-dark border-t border-white/10 pb-8 safe-area-bottom">
                         {isQuorumReached ? (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-400 transition-all flex items-center justify-center gap-2 active:scale-[0.98]">
                                <span className="material-symbols-outlined">lock</span>
                                <span>FECHAR CONVOCATÓRIA</span>
                             </button>
                        ) : (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl text-center mb-2">
                                <span className="text-xs font-bold text-gray-400">Selecione <span className="text-white">{8 - confirmedCount}</span> jogadores para fechar</span>
                            </div>
                        )}
                        <button onClick={() => setIsManagingPlayers(false)} className="w-full py-3 mt-2 text-gray-500 font-bold text-xs uppercase hover:text-white transition-colors">Voltar atrás</button>
                    </div>
                </div>
            )}

            <header>
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-slate-400">
                    {isLive ? 'Torneio em andamento!' : isRosterClosed ? 'Tudo pronto para começar.' : 'Fase de convocatória.'}
                </p>
            </header>

            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isLive ? 'ring-primary shadow-primary/20' : isRosterClosed ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                {isLive && <div className="absolute inset-0 bg-primary/5 animate-pulse"></div>}
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isLive ? 'bg-primary text-background-dark border-primary' : isRosterClosed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-white/10 text-gray-400 border-white/20'}`}>
                                    {isLive ? 'A DECORRER' : isRosterClosed ? 'CONVOCATÓRIA FECHADA' : 'ABERTO A INSCRIÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isLive ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/30' : isRosterClosed ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">{isLive ? 'sports_baseball' : isRosterClosed ? 'lock' : 'group_add'}</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isQuorumReached ? 'text-emerald-400' : 'text-white'}`}>
                                {isQuorumReached ? 'LOTAÇÃO ESGOTADA' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isQuorumReached ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 px-6 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-primary/20 animate-bounce-subtle">
                    <span className="material-symbols-outlined">scoreboard</span>
                    <span>IR PARA JOGO (EM DIRETO)</span>
                </button>
            ) : isRosterClosed ? (
                <div className="space-y-3">
                    <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100">
                        <span className="material-symbols-outlined">casino</span>
                        <span>Realizar Sorteio de Equipas</span>
                    </button>
                    <button onClick={handleReopenRoster} className="w-full text-[10px] font-bold text-gray-500 uppercase py-2 flex items-center justify-center gap-1 hover:text-white">
                        <span className="material-symbols-outlined text-sm">lock_open</span> Reabrir Convocatória para Alterações
                    </button>
                </div>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-white/5 text-white border border-white/10 hover:bg-white/10">
                    <span className="material-symbols-outlined">person_add</span>
                    <span>Gerir Jogadores / Convidados</span>
                </button>
            )}

            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    {!isRosterClosed && !isLive && <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Editar</button>}
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => !isRosterClosed && setIsManagingPlayers(true)} className={`flex flex-col items-center gap-2 ${isRosterClosed ? 'opacity-30 cursor-not-allowed' : ''}`}>
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={onCancelTournament} className="text-[10px] font-bold text-red-500/60 hover:text-red-500 text-center mt-6 uppercase tracking-widest border border-red-500/10 hover:border-red-500/30 py-3 rounded-xl transition-all">
                Cancelar e Remover Agendamento
            </button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>
        <section className="grid grid-cols-3 gap-3">
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
            <span className="text-xl font-bold text-white">{totalGames}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
          </div>
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
            <span className="text-xl font-bold text-white">{totalHours}h</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
          </div>
          <button 
            onClick={() => setScreen(Screen.LOCATIONS)}
            className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
          >
            <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
            <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
          </button>
        </section>
        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00'); // Hora predefinida para as 22:00
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);

    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) {
        setLocationId(lxIndoor.id);
    } else if (locations.length > 0) {
        setLocationId(locations[0].id);
    }

    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: '' 
    };
    // Adiciona o jogador à base de dados global e atualiza o torneio imediatamente
    onAddPlayer(newPlayer);
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }
    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled',
        rosterClosed: false
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (!activeTournament) return;
    if (activeTournament.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores para fechar a convocatória.");
        return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const handleReopenRoster = () => {
      if (!activeTournament) return;
      if (confirm("Reabrir convocatória para alterações?")) {
          onUpdateTournament({ ...activeTournament, rosterClosed: false });
      }
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark flex flex-col animate-fade-in">
                    {/* Header e Search - Fixo no Topo */}
                    <div className="shrink-0 p-4 border-b border-white/5 bg-background-dark/95 backdrop-blur-md z-10 space-y-3">
                        <header className="flex items-center justify-between">
                            <div className="flex flex-col">
                                <h2 className="text-xl font-bold leading-none">Gestão de Equipa</h2>
                                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mt-1">
                                    <span className={isQuorumReached ? "text-emerald-400" : "text-primary"}>{confirmedCount}</span> de 8 Selecionados
                                </p>
                            </div>
                            <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center border border-white/5 hover:bg-white/10 active:scale-95 transition-all">
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </header>

                        {/* Barra de Progresso Visual */}
                        <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                            <div 
                                className={`h-full transition-all duration-300 ${isQuorumReached ? 'bg-emerald-500' : 'bg-primary'}`} 
                                style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }}
                            ></div>
                        </div>

                        {isAddingGuest ? (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl animate-fade-in-up shadow-xl">
                                <h3 className="text-xs font-bold text-primary uppercase mb-3 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-sm">person_add</span>
                                    Novo Convidado
                                </h3>
                                <div className="space-y-3">
                                    <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <input type="text" placeholder="Alcunha (Opcional)" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <div className="flex gap-2">
                                        <button onClick={() => setIsAddingGuest(false)} className="flex-1 py-3 text-gray-400 font-bold text-xs uppercase border border-white/10 rounded-xl hover:bg-white/5">Cancelar</button>
                                        <button onClick={handleSaveGuest} className="flex-1 py-3 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase shadow-lg shadow-primary/20 hover:bg-primary/90">Guardar</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <div className="relative flex-1">
                                    <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-xl">search</span>
                                    <input 
                                        type="text" 
                                        placeholder="Pesquisar jogador..." 
                                        value={playerSearchTerm} 
                                        onChange={(e) => setPlayerSearchTerm(e.target.value)} 
                                        className="w-full bg-white/5 border border-white/10 rounded-2xl pl-10 pr-4 py-3.5 text-sm text-white focus:ring-2 focus:ring-primary/20 transition-all placeholder:text-gray-600" 
                                    />
                                </div>
                                <button onClick={() => setIsAddingGuest(true)} className="bg-primary/10 text-primary border border-primary/20 px-4 rounded-2xl flex items-center justify-center active:scale-95 transition-transform">
                                    <span className="material-symbols-outlined text-xl">person_add</span>
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Lista com Scroll - Otimizada para Mobile (3 Colunas) */}
                    <div className="flex-1 overflow-y-auto p-4 hide-scrollbar bg-gradient-to-b from-transparent to-black/20">
                        <div className="grid grid-cols-3 gap-3 pb-24">
                            {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                                const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                                return (
                                    <button 
                                        key={p.id} 
                                        onClick={() => togglePlayerInActiveTournament(p.id)} 
                                        className={`relative flex flex-col items-center p-3 rounded-2xl border transition-all duration-200 active:scale-95 ${
                                            isConfirmed 
                                                ? 'bg-primary/20 border-primary shadow-[0_0_15px_rgba(96,122,251,0.15)] ring-1 ring-primary/50' 
                                                : 'bg-card-dark border-white/5 hover:border-white/10'
                                        }`}
                                    >
                                        <div className="relative mb-2">
                                            {renderGlobalAvatar(p, 'size-12')}
                                            {isConfirmed && (
                                                <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark rounded-full size-5 flex items-center justify-center border-2 border-background-dark animate-bounce-subtle shadow-sm">
                                                    <span className="material-symbols-outlined text-[12px] font-black">check</span>
                                                </div>
                                            )}
                                        </div>
                                        <span className={`text-[10px] font-bold truncate w-full text-center leading-tight ${isConfirmed ? 'text-white' : 'text-gray-400'}`}>
                                            {p.nickname || p.name.split(' ')[0]}
                                        </span>
                                        <span className="text-[8px] font-bold text-gray-600 mt-0.5">{p.level}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Footer Fixo - Sempre visível mesmo com teclado */}
                    <div className="shrink-0 p-4 bg-background-dark border-t border-white/10 pb-8 safe-area-bottom z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
                         {isQuorumReached ? (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-400 transition-all flex items-center justify-center gap-2 active:scale-[0.98]">
                                <span className="material-symbols-outlined">lock</span>
                                <span>FECHAR CONVOCATÓRIA</span>
                             </button>
                        ) : (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl flex items-center justify-center gap-3">
                                <span className="material-symbols-outlined text-gray-500 animate-pulse">group_add</span>
                                <span className="text-xs font-bold text-gray-400">
                                    Selecione mais <span className="text-primary text-sm font-black mx-1">{8 - confirmedCount}</span> para fechar
                                </span>
                            </div>
                        )}
                        <button onClick={() => setIsManagingPlayers(false)} className="w-full py-3 mt-2 text-gray-500 font-bold text-xs uppercase hover:text-white transition-colors">Voltar</button>
                    </div>
                </div>
            )}

            <header>
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-slate-400">
                    {isLive ? 'Torneio em andamento!' : isRosterClosed ? 'Tudo pronto para começar.' : 'Fase de convocatória.'}
                </p>
            </header>

            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isLive ? 'ring-primary shadow-primary/20' : isRosterClosed ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                {isLive && <div className="absolute inset-0 bg-primary/5 animate-pulse"></div>}
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isLive ? 'bg-primary text-background-dark border-primary' : isRosterClosed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-white/10 text-gray-400 border-white/20'}`}>
                                    {isLive ? 'A DECORRER' : isRosterClosed ? 'CONVOCATÓRIA FECHADA' : 'ABERTO A INSCRIÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isLive ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/30' : isRosterClosed ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">{isLive ? 'sports_baseball' : isRosterClosed ? 'lock' : 'group_add'}</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isQuorumReached ? 'text-emerald-400' : 'text-white'}`}>
                                {isQuorumReached ? 'LOTAÇÃO ESGOTADA' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isQuorumReached ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 px-6 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-primary/20 animate-bounce-subtle">
                    <span className="material-symbols-outlined">scoreboard</span>
                    <span>IR PARA JOGO (EM DIRETO)</span>
                </button>
            ) : isRosterClosed ? (
                <div className="space-y-3">
                    <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100">
                        <span className="material-symbols-outlined">casino</span>
                        <span>Realizar Sorteio de Equipas</span>
                    </button>
                    <button onClick={handleReopenRoster} className="w-full text-[10px] font-bold text-gray-500 uppercase py-2 flex items-center justify-center gap-1 hover:text-white">
                        <span className="material-symbols-outlined text-sm">lock_open</span> Reabrir Convocatória para Alterações
                    </button>
                </div>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-white/5 text-white border border-white/10 hover:bg-white/10">
                    <span className="material-symbols-outlined">person_add</span>
                    <span>Gerir Jogadores / Convidados</span>
                </button>
            )}

            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    {!isRosterClosed && !isLive && <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Editar</button>}
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => !isRosterClosed && setIsManagingPlayers(true)} className={`flex flex-col items-center gap-2 ${isRosterClosed ? 'opacity-30 cursor-not-allowed' : ''}`}>
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={onCancelTournament} className="text-[10px] font-bold text-red-500/60 hover:text-red-500 text-center mt-6 uppercase tracking-widest border border-red-500/10 hover:border-red-500/30 py-3 rounded-xl transition-all">
                Cancelar e Remover Agendamento
            </button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>
        <section className="grid grid-cols-3 gap-3">
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
            <span className="text-xl font-bold text-white">{totalGames}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
          </div>
          <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
            <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
            <span className="text-xl font-bold text-white">{totalHours}h</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
          </div>
          <button 
            onClick={() => setScreen(Screen.LOCATIONS)}
            className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
          >
            <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
            <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
          </button>
        </section>
        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00'); // Hora predefinida para as 22:00
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  // --- COMPONENTE DE ESTATÍSTICAS REUTILIZÁVEL ---
  const StatsSection = (
    <section className="grid grid-cols-3 gap-3">
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
        <span className="text-xl font-bold text-white">{totalGames}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
      </div>
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
        <span className="text-xl font-bold text-white">{totalHours}h</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
      </div>
      <button 
        onClick={() => setScreen(Screen.LOCATIONS)}
        className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
      >
        <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
        <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
      </button>
    </section>
  );

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);

    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) {
        setLocationId(lxIndoor.id);
    } else if (locations.length > 0) {
        setLocationId(locations[0].id);
    }

    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: '' 
    };
    // Adiciona o jogador à base de dados global e atualiza o torneio imediatamente
    onAddPlayer(newPlayer);
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }
    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled',
        rosterClosed: false
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (!activeTournament) return;
    if (activeTournament.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores para fechar a convocatória.");
        return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const handleReopenRoster = () => {
      if (!activeTournament) return;
      if (confirm("Reabrir convocatória para alterações?")) {
          onUpdateTournament({ ...activeTournament, rosterClosed: false });
      }
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark flex flex-col animate-fade-in">
                    {/* Header e Search - Fixo no Topo */}
                    <div className="shrink-0 p-4 border-b border-white/5 bg-background-dark/95 backdrop-blur-md z-10 space-y-3">
                        <header className="flex items-center justify-between">
                            <div className="flex flex-col">
                                <h2 className="text-xl font-bold leading-none">Gestão de Equipa</h2>
                                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mt-1">
                                    <span className={isQuorumReached ? "text-emerald-400" : "text-primary"}>{confirmedCount}</span> de 8 Selecionados
                                </p>
                            </div>
                            <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center border border-white/5 hover:bg-white/10 active:scale-95 transition-all">
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </header>

                        {/* Barra de Progresso Visual */}
                        <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                            <div 
                                className={`h-full transition-all duration-300 ${isQuorumReached ? 'bg-emerald-500' : 'bg-primary'}`} 
                                style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }}
                            ></div>
                        </div>

                        {isAddingGuest ? (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl animate-fade-in-up shadow-xl">
                                <h3 className="text-xs font-bold text-primary uppercase mb-3 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-sm">person_add</span>
                                    Novo Convidado
                                </h3>
                                <div className="space-y-3">
                                    <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <input type="text" placeholder="Alcunha (Opcional)" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <div className="flex gap-2">
                                        <button onClick={() => setIsAddingGuest(false)} className="flex-1 py-3 text-gray-400 font-bold text-xs uppercase border border-white/10 rounded-xl hover:bg-white/5">Cancelar</button>
                                        <button onClick={handleSaveGuest} className="flex-1 py-3 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase shadow-lg shadow-primary/20 hover:bg-primary/90">Guardar</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <div className="relative flex-1">
                                    <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-xl">search</span>
                                    <input 
                                        type="text" 
                                        placeholder="Pesquisar jogador..." 
                                        value={playerSearchTerm} 
                                        onChange={(e) => setPlayerSearchTerm(e.target.value)} 
                                        className="w-full bg-white/5 border border-white/10 rounded-2xl pl-10 pr-4 py-3.5 text-sm text-white focus:ring-2 focus:ring-primary/20 transition-all placeholder:text-gray-600" 
                                    />
                                </div>
                                <button onClick={() => setIsAddingGuest(true)} className="bg-primary/10 text-primary border border-primary/20 px-4 rounded-2xl flex items-center justify-center active:scale-95 transition-transform">
                                    <span className="material-symbols-outlined text-xl">person_add</span>
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Lista com Scroll - Otimizada para Mobile (3 Colunas) */}
                    <div className="flex-1 overflow-y-auto p-4 hide-scrollbar bg-gradient-to-b from-transparent to-black/20">
                        <div className="grid grid-cols-3 gap-3 pb-24">
                            {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                                const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                                return (
                                    <button 
                                        key={p.id} 
                                        onClick={() => togglePlayerInActiveTournament(p.id)} 
                                        className={`relative flex flex-col items-center p-3 rounded-2xl border transition-all duration-200 active:scale-95 ${
                                            isConfirmed 
                                                ? 'bg-primary/20 border-primary shadow-[0_0_15px_rgba(96,122,251,0.15)] ring-1 ring-primary/50' 
                                                : 'bg-card-dark border-white/5 hover:border-white/10'
                                        }`}
                                    >
                                        <div className="relative mb-2">
                                            {renderGlobalAvatar(p, 'size-12')}
                                            {isConfirmed && (
                                                <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark rounded-full size-5 flex items-center justify-center border-2 border-background-dark animate-bounce-subtle shadow-sm">
                                                    <span className="material-symbols-outlined text-[12px] font-black">check</span>
                                                </div>
                                            )}
                                        </div>
                                        <span className={`text-[10px] font-bold truncate w-full text-center leading-tight ${isConfirmed ? 'text-white' : 'text-gray-400'}`}>
                                            {p.nickname || p.name.split(' ')[0]}
                                        </span>
                                        <span className="text-[8px] font-bold text-gray-600 mt-0.5">{p.level}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Footer Fixo - Sempre visível mesmo com teclado */}
                    <div className="shrink-0 p-4 bg-background-dark border-t border-white/10 pb-8 safe-area-bottom z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
                         {isQuorumReached ? (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-400 transition-all flex items-center justify-center gap-2 active:scale-[0.98]">
                                <span className="material-symbols-outlined">lock</span>
                                <span>FECHAR CONVOCATÓRIA</span>
                             </button>
                        ) : (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl flex items-center justify-center gap-3">
                                <span className="material-symbols-outlined text-gray-500 animate-pulse">group_add</span>
                                <span className="text-xs font-bold text-gray-400">
                                    Selecione mais <span className="text-primary text-sm font-black mx-1">{8 - confirmedCount}</span> para fechar
                                </span>
                            </div>
                        )}
                        <button onClick={() => setIsManagingPlayers(false)} className="w-full py-3 mt-2 text-gray-500 font-bold text-xs uppercase hover:text-white transition-colors">Voltar</button>
                    </div>
                </div>
            )}

            <header>
                <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
                <p className="text-slate-400">
                    {isLive ? 'Torneio em andamento!' : isRosterClosed ? 'Tudo pronto para começar.' : 'Fase de convocatória.'}
                </p>
            </header>

            {StatsSection}

            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isLive ? 'ring-primary shadow-primary/20' : isRosterClosed ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                {isLive && <div className="absolute inset-0 bg-primary/5 animate-pulse"></div>}
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isLive ? 'bg-primary text-background-dark border-primary' : isRosterClosed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-white/10 text-gray-400 border-white/20'}`}>
                                    {isLive ? 'A DECORRER' : isRosterClosed ? 'CONVOCATÓRIA FECHADA' : 'ABERTO A INSCRIÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isLive ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/30' : isRosterClosed ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">{isLive ? 'sports_baseball' : isRosterClosed ? 'lock' : 'group_add'}</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isQuorumReached ? 'text-emerald-400' : 'text-white'}`}>
                                {isQuorumReached ? 'LOTAÇÃO ESGOTADA' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isQuorumReached ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 px-6 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-primary/20 animate-bounce-subtle">
                    <span className="material-symbols-outlined">scoreboard</span>
                    <span>IR PARA JOGO (EM DIRETO)</span>
                </button>
            ) : isRosterClosed ? (
                <div className="space-y-3">
                    <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100">
                        <span className="material-symbols-outlined">casino</span>
                        <span>Realizar Sorteio de Equipas</span>
                    </button>
                    <button onClick={handleReopenRoster} className="w-full text-[10px] font-bold text-gray-500 uppercase py-2 flex items-center justify-center gap-1 hover:text-white">
                        <span className="material-symbols-outlined text-sm">lock_open</span> Reabrir Convocatória para Alterações
                    </button>
                </div>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-white/5 text-white border border-white/10 hover:bg-white/10">
                    <span className="material-symbols-outlined">person_add</span>
                    <span>Gerir Jogadores / Convidados</span>
                </button>
            )}

            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    {!isRosterClosed && !isLive && <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Editar</button>}
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => !isRosterClosed && setIsManagingPlayers(true)} className={`flex flex-col items-center gap-2 ${isRosterClosed ? 'opacity-30 cursor-not-allowed' : ''}`}>
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={onCancelTournament} className="text-[10px] font-bold text-red-500/60 hover:text-red-500 text-center mt-6 uppercase tracking-widest border border-red-500/10 hover:border-red-500/30 py-3 rounded-xl transition-all">
                Cancelar e Remover Agendamento
            </button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>

        {StatsSection}

        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React, { useState } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [isAddingGuest, setIsAddingGuest] = useState(false);
  const [guestName, setGuestName] = useState('');
  const [guestNickname, setGuestNickname] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00'); // Hora predefinida para as 22:00
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  // --- COMPONENTE DE ESTATÍSTICAS REUTILIZÁVEL ---
  const StatsSection = (
    <section className="grid grid-cols-3 gap-3">
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
        <span className="text-xl font-bold text-white">{totalGames}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
      </div>
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
        <span className="text-xl font-bold text-white">{totalHours}h</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
      </div>
      <button 
        onClick={() => setScreen(Screen.LOCATIONS)}
        className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
      >
        <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
        <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
      </button>
    </section>
  );

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);

    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) {
        setLocationId(lxIndoor.id);
    } else if (locations.length > 0) {
        setLocationId(locations[0].id);
    }

    setIsCreating(true);
  };

  const togglePlayerInForm = (id: string) => {
    if (selectedPlayers.includes(id)) {
      setSelectedPlayers(selectedPlayers.filter(pid => pid !== id));
    } else {
      setSelectedPlayers([...selectedPlayers, id]);
    }
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];

    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSaveGuest = () => {
    if (!guestName.trim()) return;
    const newId = `p-${Date.now()}`;
    const newPlayer: Player = {
        id: newId,
        name: guestName,
        nickname: guestNickname || guestName,
        level: 'Nível 3',
        image: '' 
    };
    // Adiciona o jogador à base de dados global e atualiza o torneio imediatamente
    onAddPlayer(newPlayer);
    if (activeTournament) {
        onUpdateTournament({
            ...activeTournament,
            confirmedPlayerIds: [...activeTournament.confirmedPlayerIds, newId]
        });
    }
    setGuestName('');
    setGuestNickname('');
    setIsAddingGuest(false);
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    const newTournament: Tournament = {
        id: `t-${Date.now()}`,
        date,
        time,
        duration,
        locationId,
        confirmedPlayerIds: selectedPlayers,
        status: 'scheduled',
        rosterClosed: false
    };
    onCreateTournament(newTournament);
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (!activeTournament) return;
    if (activeTournament.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores para fechar a convocatória.");
        return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const handleReopenRoster = () => {
      if (!activeTournament) return;
      if (confirm("Reabrir convocatória para alterações?")) {
          onUpdateTournament({ ...activeTournament, rosterClosed: false });
      }
  };

  const getLocationName = (id: string) => locations.find(l => l.id === id)?.name || 'Local Desconhecido';

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5 hover:bg-white/10 transition-colors">
                    <span className="material-symbols-outlined text-white">close</span>
                </button>
                <h2 className="text-lg font-bold">Novo Torneio</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary/50" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                    <div className="grid grid-cols-4 gap-2">
                        {players.sort((a,b) => (a.nickname || a.name).localeCompare(b.nickname || b.name)).map(p => (
                            <button key={p.id} onClick={() => togglePlayerInForm(p.id)} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                {renderGlobalAvatar(p, 'size-8')}
                                <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl shadow-xl shadow-primary/20">Criar Torneio</button>
        </div>
    );
  }

  if (activeTournament) {
    const locName = getLocationName(activeTournament.locationId);
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const confirmedPlayers = activeTournament.confirmedPlayerIds.map(id => players.find(p => p.id === id)).filter((p): p is Player => p !== undefined);

    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark flex flex-col animate-fade-in">
                    {/* Header e Search - Fixo no Topo */}
                    <div className="shrink-0 p-4 border-b border-white/5 bg-background-dark/95 backdrop-blur-md z-10 space-y-3">
                        <header className="flex items-center justify-between">
                            <div className="flex flex-col">
                                <h2 className="text-xl font-bold leading-none">Gestão de Equipa</h2>
                                <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mt-1">
                                    <span className={isQuorumReached ? "text-emerald-400" : "text-primary"}>{confirmedCount}</span> de 8 Selecionados
                                </p>
                            </div>
                            <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center border border-white/5 hover:bg-white/10 active:scale-95 transition-all">
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </header>

                        {/* Barra de Progresso Visual */}
                        <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                            <div 
                                className={`h-full transition-all duration-300 ${isQuorumReached ? 'bg-emerald-500' : 'bg-primary'}`} 
                                style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }}
                            ></div>
                        </div>

                        {isAddingGuest ? (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl animate-fade-in-up shadow-xl">
                                <h3 className="text-xs font-bold text-primary uppercase mb-3 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-sm">person_add</span>
                                    Novo Convidado
                                </h3>
                                <div className="space-y-3">
                                    <input type="text" placeholder="Nome Completo" value={guestName} onChange={(e) => setGuestName(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <input type="text" placeholder="Alcunha (Opcional)" value={guestNickname} onChange={(e) => setGuestNickname(e.target.value)} className="w-full bg-background-dark border border-white/10 rounded-xl px-4 py-3 text-base text-white focus:border-primary/50 transition-colors" />
                                    <div className="flex gap-2">
                                        <button onClick={() => setIsAddingGuest(false)} className="flex-1 py-3 text-gray-400 font-bold text-xs uppercase border border-white/10 rounded-xl hover:bg-white/5">Cancelar</button>
                                        <button onClick={handleSaveGuest} className="flex-1 py-3 bg-primary text-background-dark rounded-xl font-bold text-xs uppercase shadow-lg shadow-primary/20 hover:bg-primary/90">Guardar</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex gap-2">
                                <div className="relative flex-1">
                                    <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-xl">search</span>
                                    <input 
                                        type="text" 
                                        placeholder="Pesquisar jogador..." 
                                        value={playerSearchTerm} 
                                        onChange={(e) => setPlayerSearchTerm(e.target.value)} 
                                        className="w-full bg-white/5 border border-white/10 rounded-2xl pl-10 pr-4 py-3.5 text-sm text-white focus:ring-2 focus:ring-primary/20 transition-all placeholder:text-gray-600" 
                                    />
                                </div>
                                <button onClick={() => setIsAddingGuest(true)} className="bg-primary/10 text-primary border border-primary/20 px-4 rounded-2xl flex items-center justify-center active:scale-95 transition-transform">
                                    <span className="material-symbols-outlined text-xl">person_add</span>
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Lista com Scroll - Otimizada para Mobile (3 Colunas) */}
                    <div className="flex-1 overflow-y-auto p-4 hide-scrollbar bg-gradient-to-b from-transparent to-black/20">
                        <div className="grid grid-cols-3 gap-3 pb-24">
                            {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                                const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                                return (
                                    <button 
                                        key={p.id} 
                                        onClick={() => togglePlayerInActiveTournament(p.id)} 
                                        className={`relative flex flex-col items-center p-3 rounded-2xl border transition-all duration-200 active:scale-95 ${
                                            isConfirmed 
                                                ? 'bg-primary/20 border-primary shadow-[0_0_15px_rgba(96,122,251,0.15)] ring-1 ring-primary/50' 
                                                : 'bg-card-dark border-white/5 hover:border-white/10'
                                        }`}
                                    >
                                        <div className="relative mb-2">
                                            {renderGlobalAvatar(p, 'size-12')}
                                            {isConfirmed && (
                                                <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark rounded-full size-5 flex items-center justify-center border-2 border-background-dark animate-bounce-subtle shadow-sm">
                                                    <span className="material-symbols-outlined text-[12px] font-black">check</span>
                                                </div>
                                            )}
                                        </div>
                                        <span className={`text-[10px] font-bold truncate w-full text-center leading-tight ${isConfirmed ? 'text-white' : 'text-gray-400'}`}>
                                            {p.nickname || p.name.split(' ')[0]}
                                        </span>
                                        <span className="text-[8px] font-bold text-gray-600 mt-0.5">{p.level}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Footer Fixo - Sempre visível mesmo com teclado */}
                    <div className="shrink-0 p-4 bg-background-dark border-t border-white/10 pb-8 safe-area-bottom z-20 shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
                         {isQuorumReached ? (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-400 transition-all flex items-center justify-center gap-2 active:scale-[0.98]">
                                <span className="material-symbols-outlined">lock</span>
                                <span>FECHAR CONVOCATÓRIA</span>
                             </button>
                        ) : (
                            <div className="bg-card-dark border border-white/10 p-4 rounded-2xl flex items-center justify-center gap-3">
                                <span className="material-symbols-outlined text-gray-500 animate-pulse">group_add</span>
                                <span className="text-xs font-bold text-gray-400">
                                    Selecione mais <span className="text-primary text-sm font-black mx-1">{8 - confirmedCount}</span> para fechar
                                </span>
                            </div>
                        )}
                        <button onClick={() => setIsManagingPlayers(false)} className="w-full py-3 mt-2 text-gray-500 font-bold text-xs uppercase hover:text-white transition-colors">Voltar</button>
                    </div>
                </div>
            )}

            <header className="flex justify-between items-start">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1>
                    <p className="text-slate-400">
                        {isLive ? 'Torneio em andamento!' : isRosterClosed ? 'Tudo pronto para começar.' : 'Fase de convocatória.'}
                    </p>
                </div>
            </header>

            {StatsSection}

            <section className={`relative overflow-hidden rounded-3xl bg-card-dark shadow-xl ring-1 transition-all duration-700 ${isLive ? 'ring-primary shadow-primary/20' : isRosterClosed ? 'ring-emerald-500/50 scale-[1.01]' : 'ring-white/10'}`}>
                {isLive && <div className="absolute inset-0 bg-primary/5 animate-pulse"></div>}
                <div className="p-5 relative z-10">
                    <div className="flex items-start justify-between mb-4">
                        <div>
                            <div className="flex items-center gap-2 mb-2">
                                <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border ${isLive ? 'bg-primary text-background-dark border-primary' : isRosterClosed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-white/10 text-gray-400 border-white/20'}`}>
                                    {isLive ? 'A DECORRER' : isRosterClosed ? 'CONVOCATÓRIA FECHADA' : 'ABERTO A INSCRIÇÕES'}
                                </span>
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1">{locName}</h3>
                            <p className="text-slate-400 text-xs flex items-center gap-1.5">
                                <span className="material-symbols-outlined text-sm">calendar_today</span>
                                {new Date(activeTournament.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long' })} • {activeTournament.time}
                            </p>
                        </div>
                        <div className={`p-2.5 rounded-xl border ${isLive ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/30' : isRosterClosed ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-white/5 border-white/10 text-primary'}`}>
                            <span className="material-symbols-outlined text-2xl">{isLive ? 'sports_baseball' : isRosterClosed ? 'lock' : 'group_add'}</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-end">
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Jogadores ({confirmedCount}/8)</span>
                            <span className={`text-xs font-bold font-mono ${isQuorumReached ? 'text-emerald-400' : 'text-white'}`}>
                                {isQuorumReached ? 'LOTAÇÃO ESGOTADA' : `FALTAM ${8 - confirmedCount}`}
                            </span>
                        </div>
                        <div className="h-2.5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-0.5">
                            <div style={{ width: `${Math.min(100, (confirmedCount / 8) * 100)}%` }} className={`h-full transition-all duration-1000 rounded-full ${isQuorumReached ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]' : 'bg-primary'}`}></div>
                        </div>
                    </div>
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 px-6 rounded-2xl flex items-center justify-center gap-3 shadow-xl shadow-primary/20 animate-bounce-subtle">
                    <span className="material-symbols-outlined">scoreboard</span>
                    <span>IR PARA JOGO (EM DIRETO)</span>
                </button>
            ) : isRosterClosed ? (
                <div className="space-y-3">
                    <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-emerald-500 text-background-dark shadow-xl scale-[1.02] active:scale-100">
                        <span className="material-symbols-outlined">casino</span>
                        <span>Realizar Sorteio de Equipas</span>
                    </button>
                    <button onClick={handleReopenRoster} className="w-full text-[10px] font-bold text-gray-500 uppercase py-2 flex items-center justify-center gap-1 hover:text-white">
                        <span className="material-symbols-outlined text-sm">lock_open</span> Reabrir Convocatória para Alterações
                    </button>
                </div>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-2 transition-all bg-white/5 text-white border border-white/10 hover:bg-white/10">
                    <span className="material-symbols-outlined">person_add</span>
                    <span>Gerir Jogadores / Convidados</span>
                </button>
            )}

            <section className="flex flex-col gap-4">
                <div className="flex items-center justify-between px-1">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Confirmados</h3>
                    {!isRosterClosed && !isLive && <button onClick={() => setIsManagingPlayers(true)} className="text-xs font-bold text-primary bg-primary/10 px-4 py-2 rounded-full">Editar</button>}
                </div>
                <div className="grid grid-cols-4 gap-4">
                    {confirmedPlayers.map((p) => (
                        <div key={p.id} className="flex flex-col items-center gap-2 animate-fade-in-up">
                            {renderGlobalAvatar(p, 'size-14')}
                            <span className="text-[10px] font-bold text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                        </div>
                    ))}
                    {Array.from({ length: Math.max(0, 8 - confirmedCount) }).map((_, idx) => (
                        <button key={`empty-${idx}`} onClick={() => !isRosterClosed && setIsManagingPlayers(true)} className={`flex flex-col items-center gap-2 ${isRosterClosed ? 'opacity-30 cursor-not-allowed' : ''}`}>
                            <div className="size-14 rounded-full border-2 border-dashed border-white/10 flex items-center justify-center bg-white/5 hover:bg-white/10 transition-all"><span className="material-symbols-outlined text-gray-700">person_add</span></div>
                            <span className="text-[10px] font-bold text-gray-700">Livre</span>
                        </button>
                    ))}
                </div>
            </section>

            <button onClick={onCancelTournament} className="text-[10px] font-bold text-red-500/60 hover:text-red-500 text-center mt-6 uppercase tracking-widest border border-red-500/10 hover:border-red-500/30 py-3 rounded-xl transition-all">
                Cancelar e Remover Agendamento
            </button>
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in">
        <header className="flex justify-between items-start"><div><h1 className="text-3xl font-bold tracking-tight mb-1">Padel Manager</h1><p className="text-slate-400">Bom dia! Pronto para o próximo jogo?</p></div><button onClick={initCreation} className="bg-primary text-background-dark p-2.5 rounded-xl shadow-lg shadow-primary/20 active:scale-95 transition-all"><span className="material-symbols-outlined font-bold">add</span></button></header>

        {StatsSection}

        <button onClick={initCreation} className="w-full bg-gradient-to-r from-primary to-blue-600 p-6 rounded-3xl shadow-xl shadow-primary/20 flex flex-col items-start gap-1 relative overflow-hidden group active:scale-[0.98] transition-all"><div className="absolute top-0 right-0 p-4 opacity-20 group-hover:scale-125 transition-transform duration-500"><span className="material-symbols-outlined text-6xl">event_available</span></div><span className="text-background-dark font-bold uppercase tracking-widest text-[10px]">Agendamento</span><span className="text-background-dark font-bold text-xl">Criar Novo Torneio</span><span className="text-background-dark/70 text-xs">Selecione local, data e jogadores iniciais.</span></button>
        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1"><h3 className="text-xs font-bold uppercase tracking-widest text-gray-500">Últimos Torneios</h3><button onClick={() => setScreen(Screen.GLOBAL_STATS)} className="text-[10px] font-bold text-primary">Ver Tudo</button></div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 5).map((t) => (
                    <button key={t.id} onClick={() => setScreen(Screen.GLOBAL_STATS)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 hover:border-white/20 hover:bg-white/5 transition-all group"><div className="flex items-center gap-4"><div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center border border-white/5 group-hover:bg-primary/10 transition-colors"><span className="text-[9px] font-bold text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span><span className="text-sm font-bold text-white">{new Date(t.date).getDate()}</span></div><div className="text-left"><p className="text-sm font-bold text-white leading-tight group-hover:text-primary transition-colors">{getLocationName(t.locationId)}</p><p className="text-[10px] text-gray-500">{t.matches?.length || 0} Jogos • Finalizado</p></div></div><span className="material-symbols-outlined text-gray-600">chevron_right</span></button>
                ))}
                {history.length === 0 && <div className="flex flex-col items-center justify-center py-10 opacity-30"><span className="material-symbols-outlined text-4xl mb-2">history</span><p className="text-xs">Ainda não realizou torneios.</p></div>}
            </div>
        </section>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Screen, Player, Tournament, Match } from '../types';

interface ProfileProps {
  playerId: string | null;
  players: Player[];
  history: Tournament[];
  currentMatches: Match[];
  setScreen: (screen: Screen) => void;
  onUpdatePlayer?: (player: Player) => void;
  rankingHistory?: { date: string, points: number, level: string }[];
}

type TabType = 'overview' | 'ranking' | 'relations' | 'activity';

const PRESET_COLORS = [
  'bg-blue-600', 'bg-emerald-600', 'bg-purple-600', 
  'bg-orange-600', 'bg-rose-600', 'bg-cyan-600', 
  'bg-amber-600', 'bg-indigo-600', 'bg-lime-600',
  'bg-pink-600'
];

const getColorForId = (id: string) => {
  const sum = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  return PRESET_COLORS[sum % PRESET_COLORS.length];
};

const getInitials = (player: { name: string, lastName?: string }) => {
  const first = player.name?.[0] || '';
  const last = player.lastName?.[0] || '';
  return (first + last).toUpperCase();
};

export const renderGlobalAvatar = (p: { id: string, name: string, lastName?: string, image?: string, backgroundColor?: string }, sizeClass: string = 'size-10') => {
  const usePlaceholder = !p.image || p.image.trim() === '';

  if (usePlaceholder) {
    const initials = getInitials(p);
    const bgColor = p.backgroundColor || getColorForId(p.id);

    return (
      <div className={`${sizeClass} rounded-full ${bgColor} flex items-center justify-center border-2 border-white/20 text-white shadow-lg shrink-0 relative overflow-hidden group transition-all duration-300`}>
        {/* Background Padel Racket Icon - Ultra Large (350%) */}
        <span className="material-symbols-outlined absolute text-[350%] opacity-30 pointer-events-none rotate-[-15deg] translate-x-2 translate-y-2 select-none">
          sports_tennis
        </span>
        {/* Initials - Gigantic (60%) */}
        <span className="relative z-10 text-[60%] font-black tracking-tighter select-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]">
          {initials}
        </span>
      </div>
    );
  }

  return (
    <img 
      src={p.image} 
      className={`${sizeClass} rounded-full object-cover border-2 border-white/10 shadow-md shrink-0`} 
      alt={`${p.name} Avatar`} 
    />
  );
};

export const ProfileScreen: React.FC<ProfileProps> = ({ playerId, players, history, setScreen, onUpdatePlayer, rankingHistory = [] }) => {
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [drillDown, setDrillDown] = useState<{ title: string; type: 'matches' | 'tournaments'; items: any[] } | null>(null);

  const player = players.find(p => p.id === playerId);

  const [editFirstName, setEditFirstName] = useState('');
  const [editLastName, setEditLastName] = useState('');
  const [editNickname, setEditNickname] = useState('');
  const [editImage, setEditImage] = useState('');
  const [editColor, setEditColor] = useState('');

  useEffect(() => {
    if (player) {
        setEditFirstName(player.name);
        setEditLastName(player.lastName || '');
        setEditNickname(player.nickname || '');
        setEditImage(player.image);
        setEditColor(player.backgroundColor || getColorForId(player.id));
    }
  }, [player, isEditing]);

  const stats = useMemo(() => {
    if (!playerId) return null;
    const myMatches: Match[] = [];
    const myWonMatches: Match[] = [];
    const myTournaments: Tournament[] = [];
    const myWonTournaments: Tournament[] = [];

    const partners = new Map<string, { id: string, name: string, image: string, wins: number, games: number, matches: Match[] }>();
    const rivals = new Map<string, { id: string, name: string, image: string, winsAgainst: number, lossesAgainst: number, games: number, matches: Match[] }>();

    let currentWinStreak = 0;
    let maxWinStreak = 0;
    let pointsScored = 0;
    let pointsConceded = 0;

    const finishedHistory = history.filter(t => t.status === 'finished');

    finishedHistory.forEach(t => {
        const tMatches = t.matches?.filter(m => [...m.team1, ...m.team2].some(p => p.id === playerId)) || [];
        if (tMatches.length > 0) {
            myTournaments.push(t);

            const teamWins = new Map<string, number>();
            t.matches?.forEach(m => {
                const k1 = m.team1.map(p => p.id).sort().join('-');
                const k2 = m.team2.map(p => p.id).sort().join('-');
                if (m.score1 > m.score2) teamWins.set(k1, (teamWins.get(k1) || 0) + 1);
                else if (m.score2 > m.score1) teamWins.set(k2, (teamWins.get(k2) || 0) + 1);
            });
            const sortedTeams = Array.from(teamWins.entries()).sort((a,b) => b[1] - a[1]);
            const winnersIds = sortedTeams.length > 0 ? sortedTeams[0][0].split('-') : [];
            if (winnersIds.includes(playerId)) myWonTournaments.push(t);

            tMatches.forEach(m => {
                myMatches.push(m);
                const inTeam1 = m.team1.some(p => p.id === playerId);
                const won = inTeam1 ? m.score1 > m.score2 : m.score2 > m.score1;

                pointsScored += inTeam1 ? m.score1 : m.score2;
                pointsConceded += inTeam1 ? m.score2 : m.score1;

                if (won) {
                    myWonMatches.push(m);
                    currentWinStreak++;
                    maxWinStreak = Math.max(maxWinStreak, currentWinStreak);
                } else {
                    currentWinStreak = 0;
                }

                const myTeam = inTeam1 ? m.team1 : m.team2;
                const oppTeam = inTeam1 ? m.team2 : m.team1;

                myTeam.forEach(p => {
                    if (p.id === playerId) return;
                    if (!partners.has(p.id)) partners.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, wins: 0, games: 0, matches: [] });
                    const pd = partners.get(p.id)!;
                    pd.games++; pd.matches.push(m); if (won) pd.wins++;
                });

                oppTeam.forEach(p => {
                    if (!rivals.has(p.id)) rivals.set(p.id, { id: p.id, name: p.nickname || p.name, image: p.image, winsAgainst: 0, lossesAgainst: 0, games: 0, matches: [] });
                    const rd = rivals.get(p.id)!;
                    rd.games++; rd.matches.push(m); if (won) rd.winsAgainst++; else rd.lossesAgainst++;
                });
            });
        }
    });

    const rivalsList = Array.from(rivals.values()).map(r => ({
        ...r,
        balance: r.winsAgainst - r.lossesAgainst
    }));

    return {
        totalMatches: myMatches.length,
        totalWins: myWonMatches.length,
        winRate: myMatches.length > 0 ? Math.round((myWonMatches.length / myMatches.length) * 100) : 0,
        myTournaments,
        myWonTournaments,
        myMatches,
        pointsScored,
        pointsConceded,
        maxWinStreak,
        partners: Array.from(partners.values()).sort((a,b) => b.wins - a.wins || b.games - a.games),
        // Vítimas: Ordem Decrescente de saldo (mais saldo positivo primeiro)
        victims: rivalsList.sort((a,b) => b.balance - a.balance).slice(0, 6),
        // Bestas Negras: Ordem Crescente de saldo (mais saldo negativo primeiro)
        blackBeasts: rivalsList.sort((a,b) => a.balance - b.balance).slice(0, 6)
    };
  }, [playerId, history]);

  if (!player || !stats) return null;

  const renderRankingChart = () => {
    if (rankingHistory.length < 2) return (
        <div className="h-48 flex flex-col items-center justify-center text-gray-600 bg-white/5 rounded-3xl border border-white/5">
            <span className="material-symbols-outlined text-4xl mb-2">monitoring</span>
            <p className="text-[10px] font-black uppercase tracking-widest">Aguardando mais jogos...</p>
        </div>
    );

    const width = 340;
    const height = 180;
    const pts = rankingHistory.map(h => h.points);
    const maxPts = Math.max(...pts) + 50;
    const minPts = Math.min(...pts) - 50;
    const range = Math.max(100, maxPts - minPts);

    const points = rankingHistory.map((h, i) => ({
        x: (i * (width / (rankingHistory.length - 1))),
        y: height - ((h.points - minPts) * (height / range))
    }));

    const d = points.reduce((acc, p, i) => i === 0 ? `M ${p.x},${p.y}` : `${acc} L ${p.x},${p.y}`, '');

    return (
        <div className="bg-card-dark p-6 rounded-3xl border border-white/5 shadow-xl relative overflow-hidden group">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <p className="text-[10px] font-black text-primary uppercase tracking-widest">Trajetória</p>
                    <h3 className="text-lg font-black text-white">Evolução de Ranking</h3>
                </div>
                <div className="text-right">
                    <p className="text-[10px] font-black text-gray-500 uppercase">Atual</p>
                    <p className="text-lg font-black text-primary">{player.rankingPoints} pts</p>
                </div>
            </div>
            <div className="relative h-[200px]">
                <svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
                    <path d={d} fill="none" stroke="#607AFB" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />
                    {points.map((p, i) => (
                        <circle key={i} cx={p.x} cy={p.y} r="4" fill="#0f1323" stroke="#607AFB" strokeWidth="2" />
                    ))}
                </svg>
                <div className="flex justify-between mt-4">
                    <span className="text-[8px] font-bold text-gray-500">{rankingHistory[0].date}</span>
                    <span className="text-[8px] font-bold text-gray-500">{rankingHistory[rankingHistory.length-1].date}</span>
                </div>
            </div>
        </div>
    );
  };

  return (
    <div className="flex flex-col gap-6 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="px-4 pt-8 flex flex-col items-center relative">
        <button onClick={() => setIsEditing(true)} className="absolute top-8 right-6 size-10 rounded-full bg-white/5 flex items-center justify-center text-gray-400 border border-white/10">
          <span className="material-symbols-outlined text-[20px]">edit</span>
        </button>
        <div className="relative mb-4">
          <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-110"></div>
          {renderGlobalAvatar(player, 'size-24')}
          <div className="absolute -bottom-1 -right-1 bg-primary text-background-dark text-[10px] font-black px-2 py-0.5 rounded-md border-2 border-background-dark shadow-lg">
             {player.level.toUpperCase()}
          </div>
        </div>
        <h1 className="text-2xl font-black text-white leading-tight">{player.nickname || player.name}</h1>
        <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest mt-1">{player.name} {player.lastName}</p>
      </header>

      <div className="px-4">
          <div className="flex bg-card-dark/50 p-1 rounded-2xl border border-white/5 overflow-x-auto hide-scrollbar">
              {[
                { id: 'overview', label: 'Geral', icon: 'dashboard' },
                { id: 'ranking', label: 'Ranking', icon: 'monitoring' },
                { id: 'relations', label: 'Relações', icon: 'groups' },
                { id: 'activity', label: 'Histórico', icon: 'history' }
              ].map(tab => (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveTab(tab.id as TabType)} 
                  className={`flex-1 min-w-[80px] py-3 flex flex-col items-center gap-1 rounded-xl transition-all ${activeTab === tab.id ? 'bg-primary text-background-dark shadow-lg' : 'text-gray-500'}`}
                >
                    <span className="material-symbols-outlined text-sm">{tab.icon}</span>
                    <span className="text-[8px] font-black uppercase">{tab.label}</span>
                </button>
              ))}
          </div>
      </div>

      <div className="px-4 space-y-6">
          {activeTab === 'overview' && (
              <div className="space-y-4 animate-fade-in">
                  <div className="grid grid-cols-3 gap-3">
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-white">{stats.totalMatches}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Jogos</span>
                      </div>
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-primary">{stats.totalWins}</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span>
                      </div>
                      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-xl font-black text-emerald-400">{stats.winRate}%</span>
                          <span className="text-[8px] font-bold text-gray-500 uppercase">WR</span>
                      </div>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="bg-card-dark border border-white/5 p-4 rounded-2xl flex flex-col items-center">
                        <span className="material-symbols-outlined text-primary text-xl mb-1">local_fire_department</span>
                        <span className="text-xl font-black text-white">{stats.maxWinStreak}</span>
                        <span className="text-[8px] text-gray-500 uppercase font-bold">Streak</span>
                    </div>
                    <div className="bg-card-dark border border-white/5 p-4 rounded-2xl flex flex-col items-center">
                        <span className="material-symbols-outlined text-yellow-500 text-xl mb-1">emoji_events</span>
                        <span className="text-xl font-black text-white">{stats.myWonTournaments.length}</span>
                        <span className="text-[8px] text-gray-500 uppercase font-bold">Títulos</span>
                    </div>
                    <div className="bg-card-dark border border-white/5 p-4 rounded-2xl flex flex-col items-center">
                        <span className="material-symbols-outlined text-blue-400 text-xl mb-1">event_available</span>
                        <span className="text-xl font-black text-white">{stats.myTournaments.length}</span>
                        <span className="text-[8px] text-gray-500 uppercase font-bold">Assiduidade</span>
                    </div>
                  </div>
              </div>
          )}

          {activeTab === 'ranking' && (
              <div className="space-y-4 animate-fade-in">
                  {renderRankingChart()}
                  <div className="bg-primary/10 p-5 rounded-3xl border border-primary/20">
                      <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-2">Sistema de Pontuação</p>
                      <ul className="space-y-2">
                          <li className="flex items-center gap-2 text-[10px] text-gray-300"><span className="size-1 bg-primary rounded-full"></span> Vitória em Jogo: +20 pts</li>
                          <li className="flex items-center gap-2 text-[10px] text-gray-300"><span className="size-1 bg-primary rounded-full"></span> Vitória em Torneio: +50 pts</li>
                          <li className="flex items-center gap-2 text-[10px] text-gray-300"><span className="size-1 bg-primary rounded-full"></span> Derrota em Jogo: -12 pts</li>
                      </ul>
                  </div>
              </div>
          )}

          {activeTab === 'relations' && (
              <div className="space-y-6 animate-fade-in">
                  <section>
                      <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-4">Melhores Parceiros</h3>
                      <div className="flex flex-col gap-2">
                          {stats.partners.slice(0, 4).map(p => (
                              <div key={p.id} className="bg-card-dark p-3 rounded-2xl border border-white/5 flex items-center justify-between">
                                  <div className="flex items-center gap-3">{renderGlobalAvatar(p, 'size-9')}<div><span className="text-xs font-black text-white block">{p.name}</span><span className="text-[9px] text-gray-500 font-bold">{p.games} Jogos</span></div></div>
                                  <div className="text-right"><p className="text-[10px] font-black text-primary">{Math.round((p.wins / p.games) * 100)}% Win Rate</p></div>
                              </div>
                          ))}
                      </div>
                  </section>
                  <section className="grid grid-cols-2 gap-4">
                      <div>
                          <h3 className="text-[10px] font-bold text-emerald-500 uppercase mb-3">Vítimas</h3>
                          <div className="space-y-2">
                            {stats.victims.map(r => (
                                <div key={r.id} className="flex items-center justify-between bg-white/5 p-2 rounded-xl">
                                    <div className="flex items-center gap-2 overflow-hidden">
                                        {renderGlobalAvatar(r, 'size-6')}
                                        <span className="text-[9px] font-bold text-white truncate">{r.name}</span>
                                    </div>
                                    <span className={`text-[8px] font-black whitespace-nowrap ml-2 ${r.balance > 0 ? 'text-emerald-400' : 'text-gray-500'}`}>
                                        {r.winsAgainst}V - {r.lossesAgainst}D
                                    </span>
                                </div>
                            ))}
                          </div>
                      </div>
                      <div>
                          <h3 className="text-[10px] font-bold text-red-500 uppercase mb-3">Bestas Negras</h3>
                          <div className="space-y-2">
                            {stats.blackBeasts.map(r => (
                                <div key={r.id} className="flex items-center justify-between bg-white/5 p-2 rounded-xl">
                                    <div className="flex items-center gap-2 overflow-hidden">
                                        {renderGlobalAvatar(r, 'size-6')}
                                        <span className="text-[9px] font-bold text-white truncate">{r.name}</span>
                                    </div>
                                    <span className={`text-[8px] font-black whitespace-nowrap ml-2 ${r.balance < 0 ? 'text-red-400' : 'text-gray-500'}`}>
                                        {r.winsAgainst}V - {r.lossesAgainst}D
                                    </span>
                                </div>
                            ))}
                          </div>
                      </div>
                  </section>
              </div>
          )}

          {activeTab === 'activity' && (
              <div className="space-y-4 animate-fade-in">
                  <button onClick={() => setDrillDown({ title: 'Jogos Realizados', type: 'matches', items: stats.myMatches })} className="w-full bg-card-dark p-5 rounded-2xl border border-white/5 flex justify-between items-center group">
                      <div><p className="text-sm font-black text-white">Todos os Jogos</p><p className="text-[10px] text-gray-500 uppercase">{stats.myMatches.length} Entradas</p></div>
                      <span className="material-symbols-outlined text-primary">chevron_right</span>
                  </button>
                  <button onClick={() => setDrillDown({ title: 'Torneios Disputados', type: 'tournaments', items: stats.myTournaments })} className="w-full bg-card-dark p-5 rounded-2xl border border-white/5 flex justify-between items-center group">
                      <div><p className="text-sm font-black text-white">Torneios</p><p className="text-[10px] text-gray-500 uppercase">{stats.myTournaments.length} Participações</p></div>
                      <span className="material-symbols-outlined text-primary">chevron_right</span>
                  </button>
              </div>
          )}
      </div>

      {isEditing && (
          <div className="fixed inset-0 z-[110] bg-background-dark/95 backdrop-blur-xl animate-fade-in flex flex-col p-4 overflow-y-auto">
