import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  // Inicializa com listas vazias
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('offline');
  const [lastErrorMessage, setLastErrorMessage] = useState<string>('');

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  // Carregar dados locais (Fallback)
  const loadLocalData = useCallback(() => {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');

      let loadedPlayers = p ? JSON.parse(p) : [];
      let loadedLocations = l ? JSON.parse(l) : [];
      let allTournaments = h ? JSON.parse(h) : [];

      setPlayers(loadedPlayers);
      setLocations(loadedLocations);
      return allTournaments;
  }, []);

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) {
        setSyncStatus('offline');
        return null;
    }

    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };

      // Executa fetchs com cache: 'no-store' para garantir dados frescos sem usar query params inválidos
      const responses = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/locations?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/tournaments?select=data`, { headers, cache: 'no-store' })
      ]);

      // Verifica erros HTTP
      for (const res of responses) {
          if (!res.ok) {
              if (res.status === 404) {
                 throw new Error("Tabelas não encontradas no Supabase. Vá a Configurações > Setup SQL para corrigir.");
              }
              const errorText = await res.text();
              throw new Error(`Erro ${res.status}: ${errorText}`);
          }
      }

      const [pRes, lRes, tRes] = await Promise.all(responses.map(r => r.json()));

      // Processamento
      const playersData = Array.isArray(pRes) ? pRes.map((i: any) => i.data) : [];
      const locationsData = Array.isArray(lRes) ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = Array.isArray(tRes) ? tRes.map((i: any) => i.data) : [];

      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      setSyncStatus('online');
      setLastErrorMessage('');

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };

    } catch (e: any) { 
        console.error("Cloud Fetch Error:", e);
        setSyncStatus('error');
        setLastErrorMessage(e.message || "Erro desconhecido de rede");
        return null;
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      // Upsert: Tenta inserir, se o ID já existir, atualiza
      const res = await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 
            'apikey': cloudConfig.key, 
            'Authorization': `Bearer ${cloudConfig.key}`, 
            'Content-Type': 'application/json', 
            'Prefer': 'resolution=merge-duplicates' // Importante para o Upsert funcionar
        },
        body: JSON.stringify({ id, data })
      });

      if (!res.ok) {
          if (res.status === 404) {
              throw new Error("Tabela inexistente. Verifique o SQL no Supabase.");
          }
          const txt = await res.text();
          throw new Error(`Push falhou (${res.status}): ${txt}`);
      }
      setSyncStatus('online');

    } catch (e: any) {
        console.error("Push Error:", e);
        setSyncStatus('error');
        setLastErrorMessage(e.message || "Falha ao guardar dados.");
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 
          'apikey': cloudConfig.key, 
          'Authorization': `Bearer ${cloudConfig.key}` 
        }
      });
    } catch (e) {
      console.error("Delete Error:", e);
    }
  };

  // Lógica centralizada de atualização de dados
  const refreshAllData = useCallback(async () => {
    let allTournaments: Tournament[] = [];

    // 1. Tenta carregar da Cloud
    const cloudData = await fetchCloudData(cloudConfig);

    if (cloudData) {
        // Sucesso Cloud
        setPlayers(cloudData.players);
        setLocations(cloudData.locations);
        allTournaments = cloudData.tournaments;
    } else {
        // Falha Cloud ou Offline -> Carrega Local
        allTournaments = loadLocalData();
    }

    // Separar Lógica de Ativos vs Histórico
    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    if (active) {
       setActiveTournament(prev => {
           if (isTournamentDifferent(prev, active)) {
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData, loadLocalData]);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  // SMART SYNC
  useEffect(() => {
      const handleFocus = () => {
          if (document.visibilityState === 'visible' && cloudConfig.enabled) {
              refreshAllData();
          }
      };

      window.addEventListener('focus', handleFocus);
      document.addEventListener('visibilitychange', handleFocus);

      return () => {
          window.removeEventListener('focus', handleFocus);
          document.removeEventListener('visibilitychange', handleFocus);
      };
  }, [refreshAllData, cloudConfig.enabled]);

  // Persistence local storage (Backup local sempre atualizado)
  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamResults = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamResults.has(k1)) teamResults.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamResults.has(k2)) teamResults.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamResults.get(k1)!, s2 = teamResults.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamResults.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  // --- Handlers ---
  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const, rosterClosed: false };
      setActiveTournament(newT);
      await pushToCloud('tournaments', newT.id, newT);
  };
  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };
  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };
  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }
    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);
    if (m1 && m2) {
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;
      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();
      if (nextRoundNumber === 2) {
        nextMatches = [
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          { id: `m-r2-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        nextMatches = [
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          { id: `m-r3-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }
      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);
      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };
  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);
    setMatches(updatedMatches);
    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };
  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };
  const handleAddPlayer = async (p: Player) => { setPlayers(prev => [...prev, p]); await pushToCloud('players', p.id, p); };
  const handleUpdatePlayer = async (p: Player) => { setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); await pushToCloud('players', p.id, p); };
  const handleDeletePlayer = async (id: string) => { if (window.confirm('Remover jogador?')) { setPlayers(prev => prev.filter(p => p.id !== id)); await deleteFromCloud('players', id); } };
  const handleAddLocation = async (l: Location) => { setLocations(prev => [...prev, l]); await pushToCloud('locations', l.id, l); };
  const handleUpdateLocation = async (l: Location) => { setLocations(prev => prev.map(old => old.id === l.id ? l : old)); await pushToCloud('locations', l.id, l); };
  const handleDeleteLocation = async (id: string) => { setLocations(prev => prev.filter(l => l.id !== id)); await deleteFromCloud('locations', id); };
  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { ...activeTournament, status: 'finished', matches: matches.map(m => ({...m, status: 'finished'})), };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };
  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const handleStatusClick = () => {
    if (syncStatus === 'error') {
        alert(`Estado da Sincronização:\n\n${lastErrorMessage}`);
        if (lastErrorMessage.includes('Tabelas')) {
             setScreen(Screen.SETTINGS);
        }
    } else {
        refreshAllData();
    }
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">A carregar...</p></div>;

    let ScreenComponent;
    switch (currentScreen) {
      case Screen.HOME: ScreenComponent = <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />; break;
      case Screen.PROFILE: ScreenComponent = <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />; break;
      case Screen.LIVE_GAME: ScreenComponent = <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />; break;
      case Screen.TOURNAMENT_SUMMARY: ScreenComponent = <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />; break;
      case Screen.TOURNAMENT_RESULTS: ScreenComponent = <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />; break;
      case Screen.GLOBAL_STATS: ScreenComponent = <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />; break;
      case Screen.TOURNAMENT_HISTORY: ScreenComponent = <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />; break;
      case Screen.HISTORY_DETAIL: ScreenComponent = selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} players={playersWithDynamicRanking} onDeleteTournament={handleDeleteTournament} /> : null; break;
      case Screen.TEAM_SETUP: ScreenComponent = <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />; break;
      case Screen.PLAYERS: ScreenComponent = <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />; break;
      case Screen.LOCATIONS: ScreenComponent = <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />; break;
      case Screen.SETTINGS: ScreenComponent = <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />; break;
      default: ScreenComponent = null;
    }

    return (
        <PullToRefresh onRefresh={refreshAllData}>
            {ScreenComponent}
        </PullToRefresh>
    );
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <button 
          onClick={handleStatusClick}
          className={`absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 backdrop-blur-md px-3 py-1 rounded-full border cursor-pointer hover:bg-black/60 active:scale-95 transition-all ${syncStatus === 'error' ? 'bg-red-500/20 border-red-500/50' : 'bg-black/40 border-white/5'}`}
        >
          <div className={`size-1.5 rounded-full ${syncStatus === 'online' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : syncStatus === 'error' ? 'bg-red-500 animate-pulse' : 'bg-orange-500'}`}></div>
          <span className={`text-[8px] font-black uppercase tracking-widest ${syncStatus === 'error' ? 'text-red-400' : 'text-gray-400'}`}>
             {syncStatus === 'online' ? 'Cloud Sync' : syncStatus === 'error' ? 'Erro Sync' : 'Offline'}
          </span>
          <span className="material-symbols-outlined text-[10px] text-gray-500">refresh</span>
        </button>

        {renderScreen()}

        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Screen, Tournament, Location } from '../types';

interface HistoryProps {
  history: Tournament[];
  locations: Location[];
  onViewTournament: (t: Tournament) => void;
  onDeleteTournament?: (id: string) => void;
}

export const TournamentHistoryScreen: React.FC<HistoryProps> = ({ history, locations, onViewTournament, onDeleteTournament }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showCancelled, setShowCancelled] = useState(false);
  const [calendarDate, setCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  // Alterado para false: o calendário começa recolhido por defeito
  const [isCalendarExpanded, setIsCalendarExpanded] = useState(false);

  // Lógica do Calendário
  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const currentYear = calendarDate.getFullYear();
  const currentMonth = calendarDate.getMonth();

  const days = useMemo(() => {
    const totalDays = daysInMonth(currentYear, currentMonth);
    const firstDay = firstDayOfMonth(currentYear, currentMonth);
    const daysArray = [];

    // Espaços vazios para alinhar o primeiro dia
    for (let i = 0; i < firstDay; i++) {
      daysArray.push(null);
    }

    for (let i = 1; i <= totalDays; i++) {
      daysArray.push(i);
    }

    return daysArray;
  }, [currentYear, currentMonth]);

  const tournamentDates = useMemo(() => {
    const dates = new Set<string>();
    history.forEach(t => {
      const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');
      if (statusMatch) {
        const d = new Date(t.date);
        if (d.getFullYear() === currentYear && d.getMonth() === currentMonth) {
          dates.add(d.getDate().toString());
        }
      }
    });
    return dates;
  }, [history, currentYear, currentMonth, showCancelled]);

  const filteredHistory = useMemo(() => {
    return history
      .filter(t => {
        const loc = locations.find(l => l.id === t.locationId);
        const locName = loc?.name || 'Local Desconhecido';
        const matchesSearch = locName.toLowerCase().includes(searchTerm.toLowerCase());

        const tDate = new Date(t.date);
        const matchesDay = selectedDay === null || (
          tDate.getDate() === selectedDay && 
          tDate.getMonth() === currentMonth && 
          tDate.getFullYear() === currentYear
        );

        const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');

        return matchesSearch && matchesDay && statusMatch;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [history, searchTerm, selectedDay, currentMonth, currentYear, locations, showCancelled]);

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentYear, currentMonth + offset, 1);
    setCalendarDate(newDate);
    setSelectedDay(null);
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-6 pb-32 animate-fade-in">
      <header className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-black text-white">Registo <br/><span className="text-primary">Histórico</span></h1>
          <p className="text-gray-500 text-sm mt-1">Consulte todos os torneios realizados.</p>
        </div>
        <button 
          onClick={() => setShowCancelled(!showCancelled)} 
          className={`size-12 rounded-2xl border flex items-center justify-center transition-all ${showCancelled ? 'bg-red-500/10 border-red-500/50 text-red-500' : 'bg-card-dark border-white/5 text-gray-500'}`}
          title="Ver Cancelados"
        >
          <span className="material-symbols-outlined">{showCancelled ? 'event_busy' : 'event_available'}</span>
        </button>
      </header>

      {/* Calendário Interativo com Expansão/Colapso */}
      <section className="bg-card-dark rounded-[2.5rem] border border-white/5 shadow-xl overflow-hidden relative transition-all duration-500 ease-in-out">
        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
          <span className="material-symbols-outlined text-8xl">calendar_month</span>
        </div>

        {/* Header do Calendário */}
        <div className="flex items-center justify-between p-6 relative z-10 border-b border-white/5">
          <div className="flex items-center gap-4">
             <button onClick={() => changeMonth(-1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_left</span>
             </button>
             <div className="text-left">
               <h3 className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">
                 {calendarDate.toLocaleDateString('pt-PT', { year: 'numeric' })}
               </h3>
               <h3 className="text-sm font-black text-white uppercase tracking-widest leading-none">
                 {calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}
               </h3>
             </div>
             <button onClick={() => changeMonth(1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_right</span>
             </button>
          </div>

          {/* Botão de Expansão */}
          <button 
            onClick={() => setIsCalendarExpanded(!isCalendarExpanded)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${isCalendarExpanded ? 'bg-primary/20 text-primary' : 'bg-white/5 text-gray-400'}`}
          >
            <span className="material-symbols-outlined text-sm">{isCalendarExpanded ? 'expand_less' : 'expand_more'}</span>
            {isCalendarExpanded ? 'Recolher' : 'Calendário'}
          </button>
        </div>

        {/* Grelha do Calendário (Colapsável) */}
        <div className={`transition-all duration-500 ease-in-out px-6 ${isCalendarExpanded ? 'max-h-[400px] opacity-100 py-6' : 'max-h-0 opacity-0 py-0 overflow-hidden'}`}>
          <div className="grid grid-cols-7 gap-1 mb-2">
            {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map((day, i) => (
              <div key={i} className="text-center text-[8px] font-black text-gray-600 uppercase mb-2">{day}</div>
            ))}
            {days.map((day, i) => {
              const hasTournament = day !== null && tournamentDates.has(day.toString());
              const isSelected = selectedDay === day;
              const isToday = day !== null && new Date().toDateString() === new Date(currentYear, currentMonth, day).toDateString();

              return (
                <button
                  key={i}
                  disabled={day === null}
                  onClick={() => setSelectedDay(isSelected ? null : day)}
                  className={`
                    relative h-10 rounded-xl flex flex-col items-center justify-center transition-all text-[10px] font-bold
                    ${day === null ? 'opacity-0' : 'hover:bg-white/5'}
                    ${isSelected ? 'bg-primary text-background-dark scale-110 shadow-lg shadow-primary/20 z-10' : 'text-gray-400'}
                    ${isToday && !isSelected ? 'border border-primary/30 text-primary' : ''}
                  `}
                >
                  {day}
                  {hasTournament && (
                    <div className={`absolute bottom-1.5 size-1.5 rounded-full ${isSelected ? 'bg-background-dark' : 'bg-primary shadow-[0_0_5px_rgba(96,122,251,0.5)]'}`}></div>
                  )}
                </button>
              );
            })}
          </div>

          {selectedDay && (
            <button 
              onClick={() => setSelectedDay(null)}
              className="w-full mt-4 py-2 bg-white/5 rounded-xl text-[9px] font-black text-primary uppercase tracking-widest flex items-center justify-center gap-2"
            >
              <span className="material-symbols-outlined text-sm">close</span>
              Limpar Filtro de Data
            </button>
          )}
        </div>
      </section>

      <div className="space-y-4">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Pesquisar local..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-card-dark border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:ring-2 focus:ring-primary/50 outline-none transition-all"
          />
        </div>

        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between px-1">
            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">
              {selectedDay ? `Torneios em ${selectedDay} de ${calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}` : 'Lista de Torneios'}
            </h3>
            <span className="text-[10px] font-bold text-primary">{filteredHistory.length} encontrados</span>
          </div>

          {filteredHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 opacity-30 text-center">
              <span className="material-symbols-outlined text-6xl mb-4">history_toggle_off</span>
              <p className="text-sm font-bold">Nenhum registo encontrado</p>
              {selectedDay && <p className="text-[10px] uppercase mt-1">Tente selecionar outro dia ou limpar o filtro.</p>}
            </div>
          ) : (
            filteredHistory.map(t => {
              const loc = locations.find(l => l.id === t.locationId);
              const locName = loc?.name || 'Local Desconhecido';
              const isCancelled = t.status === 'cancelled';

              return (
                <div key={t.id} className={`relative group ${isCancelled ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                  <button 
                    onClick={() => !isCancelled && onViewTournament(t)}
                    disabled={isCancelled}
                    className="w-full bg-card-dark p-5 rounded-3xl border border-white/5 hover:border-primary/30 transition-all text-left group active:scale-[0.98] disabled:cursor-not-allowed"
                  >
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <span className={`text-[10px] font-black uppercase tracking-widest block mb-1 ${isCancelled ? 'text-red-500' : 'text-primary'}`}>
                          {new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                          {isCancelled && ' (CANCELADO)'}
                        </span>
                        <h3 className="text-xl font-black text-white group-hover:text-primary transition-colors">{locName}</h3>
                      </div>
                      {!isCancelled && (
                          <div className="size-10 rounded-2xl bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                              <span className="material-symbols-outlined text-gray-500 group-hover:text-primary">chevron_right</span>
                          </div>
                      )}
                    </div>

                    <div className="flex items-center gap-4 text-gray-500">
                      <div className="flex items-center gap-1.5">
                        <span className="material-symbols-outlined text-[16px]">sports_tennis</span>
                        <span className="text-[10px] font-bold uppercase">{t.matches?.length || 0} Jogos</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <span className="material-symbols-outlined text-[16px]">schedule</span>
                        <span className="text-[10px] font-bold uppercase">{t.time} • {t.duration}h</span>
                      </div>
                    </div>
                  </button>
                  {/* Botão de eliminar flutuante */}
                  <button 
                    onClick={(e) => { e.stopPropagation(); onDeleteTournament?.(t.id); }}
                    className="absolute bottom-4 right-4 p-2 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all opacity-0 group-hover:opacity-100 z-10"
                  >
                    <span className="material-symbols-outlined text-base">delete</span>
                  </button>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('offline');
  const [lastErrorMessage, setLastErrorMessage] = useState<string>('');

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  const loadLocalData = useCallback(() => {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');

      let loadedPlayers = p ? JSON.parse(p) : [];
      let loadedLocations = l ? JSON.parse(l) : [];
      let allTournaments = h ? JSON.parse(h) : [];

      setPlayers(loadedPlayers);
      setLocations(loadedLocations);
      return allTournaments;
  }, []);

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) {
        setSyncStatus('offline');
        return null;
    }

    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };
      const responses = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/locations?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/tournaments?select=data`, { headers, cache: 'no-store' })
      ]);

      for (const res of responses) {
          if (!res.ok) {
              if (res.status === 404) {
                 throw new Error("Tabelas não encontradas no Supabase.");
              }
              const errorText = await res.text();
              throw new Error(`Erro ${res.status}: ${errorText}`);
          }
      }

      const [pRes, lRes, tRes] = await Promise.all(responses.map(r => r.json()));
      const playersData = Array.isArray(pRes) ? pRes.map((i: any) => i.data) : [];
      const locationsData = Array.isArray(lRes) ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = Array.isArray(tRes) ? tRes.map((i: any) => i.data) : [];

      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      setSyncStatus('online');
      setLastErrorMessage('');

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };
    } catch (e: any) { 
        setSyncStatus('error');
        setLastErrorMessage(e.message || "Erro de rede");
        return null;
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      const res = await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 
            'apikey': cloudConfig.key, 
            'Authorization': `Bearer ${cloudConfig.key}`, 
            'Content-Type': 'application/json', 
            'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify({ id, data })
      });
      if (!res.ok) setSyncStatus('error');
      else setSyncStatus('online');
    } catch (e: any) {
        setSyncStatus('error');
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 
          'apikey': cloudConfig.key, 
          'Authorization': `Bearer ${cloudConfig.key}` 
        }
      });
    } catch (e) {
      console.error("Delete Error:", e);
    }
  };

  const refreshAllData = useCallback(async () => {
    let allTournaments: Tournament[] = [];
    const cloudData = await fetchCloudData(cloudConfig);

    if (cloudData) {
        setPlayers(cloudData.players);
        setLocations(cloudData.locations);
        allTournaments = cloudData.tournaments;
    } else {
        allTournaments = loadLocalData();
    }

    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    if (active) {
       setActiveTournament(prev => {
           if (isTournamentDifferent(prev, active)) {
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData, loadLocalData]);

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamResults = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamResults.has(k1)) teamResults.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamResults.has(k2)) teamResults.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamResults.get(k1)!, s2 = teamResults.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamResults.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  // --- LOGICA DE RONDAS ATUALIZADA ---
  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }

    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);

    if (m1 && m2) {
      // Identificar Vencedores e Derrotados da Ronda 1
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();

      if (nextRoundNumber === 2) {
        // REGRA: Vencedores mantêm campo, Derrotados trocam
        nextMatches = [
          // Campo 1: Vencedor C1 vs Derrotado C2
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          // Campo 2: Vencedor C2 vs Derrotado C1
          { id: `m-r2-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        // REGRA: Ronda 3 com oponentes que ainda não se defrontaram
        nextMatches = [
          // Campo 1: Vencedor C1 vs Vencedor C2
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          // Campo 2: Derrotado C1 vs Derrotado C2
          { id: `m-r3-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }

      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);
      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };

  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const, rosterClosed: false };
      setActiveTournament(newT);
      await pushToCloud('tournaments', newT.id, newT);
  };
  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };
  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };
  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);
    setMatches(updatedMatches);
    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };
  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };
  const handleAddPlayer = async (p: Player) => { setPlayers(prev => [...prev, p]); await pushToCloud('players', p.id, p); };
  const handleUpdatePlayer = async (p: Player) => { setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); await pushToCloud('players', p.id, p); };
  const handleDeletePlayer = async (id: string) => { if (window.confirm('Remover jogador?')) { setPlayers(prev => prev.filter(p => p.id !== id)); await deleteFromCloud('players', id); } };
  const handleAddLocation = async (l: Location) => { setLocations(prev => [...prev, l]); await pushToCloud('locations', l.id, l); };
  const handleUpdateLocation = async (l: Location) => { setLocations(prev => prev.map(old => old.id === l.id ? l : old)); await pushToCloud('locations', l.id, l); };
  const handleDeleteLocation = async (id: string) => { setLocations(prev => prev.filter(l => l.id !== id)); await deleteFromCloud('locations', id); };
  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { ...activeTournament, status: 'finished', matches: matches.map(m => ({...m, status: 'finished'})), };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };
  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">A carregar...</p></div>;

    switch (currentScreen) {
      case Screen.HOME: return <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />;
      case Screen.PROFILE: return <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />;
      case Screen.LIVE_GAME: return <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />;
      case Screen.TOURNAMENT_SUMMARY: return <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />;
      case Screen.TOURNAMENT_RESULTS: return <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />;
      case Screen.GLOBAL_STATS: return <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY: return <TournamentHistoryScreen history={tournamentHistory} locations={locations} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />;
      case Screen.HISTORY_DETAIL: return selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} players={playersWithDynamicRanking} onDeleteTournament={handleDeleteTournament} /> : null;
      case Screen.TEAM_SETUP: return <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS: return <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />;
      case Screen.LOCATIONS: return <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />;
      case Screen.SETTINGS: return <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <button 
          onClick={() => refreshAllData()}
          className={`absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 backdrop-blur-md px-3 py-1 rounded-full border cursor-pointer hover:bg-black/60 active:scale-95 transition-all ${syncStatus === 'error' ? 'bg-red-500/20 border-red-500/50' : 'bg-black/40 border-white/5'}`}
        >
          <div className={`size-1.5 rounded-full ${syncStatus === 'online' ? 'bg-emerald-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-orange-500'}`}></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">
             {syncStatus === 'online' ? 'Cloud Sync' : syncStatus === 'error' ? 'Erro Sync' : 'Offline'}
          </span>
          <span className="material-symbols-outlined text-[10px] text-gray-500">refresh</span>
        </button>
        <PullToRefresh onRefresh={refreshAllData}>
            {renderScreen()}
        </PullToRefresh>
        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

