                                </div>
                             </foreignObject>
                           )}
                        </g>
                      );
                    })}

                    {/* Labels de Datas Base */}
                    <text x={paddingX} y={height + 25} textAnchor="start" fontSize="8" fontWeight="bold" fill="#666" className="uppercase">{rankingHistory[0].date}</text>
