import React, { useState, useMemo } from 'react';
import { Screen, Tournament, Location } from '../types';

interface HistoryProps {
  history: Tournament[];
  locations: Location[];
  onViewTournament: (t: Tournament) => void;
  onDeleteTournament?: (id: string) => void;
}

export const TournamentHistoryScreen: React.FC<HistoryProps> = ({ history, locations, onViewTournament, onDeleteTournament }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showCancelled, setShowCancelled] = useState(false);
  const [calendarDate, setCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  // Definido como false: o calendário começa recolhido por defeito
  const [isCalendarExpanded, setIsCalendarExpanded] = useState(false);

  // Lógica do Calendário
  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const currentYear = calendarDate.getFullYear();
  const currentMonth = calendarDate.getMonth();

  const days = useMemo(() => {
    const totalDays = daysInMonth(currentYear, currentMonth);
    const firstDay = firstDayOfMonth(currentYear, currentMonth);
    const daysArray = [];

    // Espaços vazios para alinhar o primeiro dia
    for (let i = 0; i < firstDay; i++) {
      daysArray.push(null);
    }

    for (let i = 1; i <= totalDays; i++) {
      daysArray.push(i);
    }

    return daysArray;
  }, [currentYear, currentMonth]);

  const tournamentDates = useMemo(() => {
    const dates = new Set<string>();
    history.forEach(t => {
      const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');
      if (statusMatch) {
        const d = new Date(t.date);
        if (d.getFullYear() === currentYear && d.getMonth() === currentMonth) {
          dates.add(d.getDate().toString());
        }
      }
    });
    return dates;
  }, [history, currentYear, currentMonth, showCancelled]);

  const filteredHistory = useMemo(() => {
    return history
      .filter(t => {
        const loc = locations.find(l => l.id === t.locationId);
        const locName = loc?.name || 'Local Desconhecido';
        const matchesSearch = locName.toLowerCase().includes(searchTerm.toLowerCase());

        const tDate = new Date(t.date);
        const matchesDay = selectedDay === null || (
          tDate.getDate() === selectedDay && 
          tDate.getMonth() === currentMonth && 
          tDate.getFullYear() === currentYear
        );

        const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');

        return matchesSearch && matchesDay && statusMatch;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [history, searchTerm, selectedDay, currentMonth, currentYear, locations, showCancelled]);

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentYear, currentMonth + offset, 1);
    setCalendarDate(newDate);
    setSelectedDay(null);
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-6 pb-32 animate-fade-in">
      <header className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-black text-white">Registo <br/><span className="text-primary">Histórico</span></h1>
          <p className="text-gray-500 text-sm mt-1">Consulte todos os torneios realizados.</p>
        </div>
        <button 
          onClick={() => setShowCancelled(!showCancelled)} 
          className={`size-12 rounded-2xl border flex items-center justify-center transition-all ${showCancelled ? 'bg-red-500/10 border-red-500/50 text-red-500' : 'bg-card-dark border-white/5 text-gray-500'}`}
          title="Ver Cancelados"
        >
          <span className="material-symbols-outlined">{showCancelled ? 'event_busy' : 'event_available'}</span>
        </button>
      </header>

      {/* Calendário Interativo com Expansão/Colapso */}
      <section className="bg-card-dark rounded-[2.5rem] border border-white/5 shadow-xl overflow-hidden relative transition-all duration-500 ease-in-out">
        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
          <span className="material-symbols-outlined text-8xl">calendar_month</span>
        </div>

        {/* Header do Calendário */}
        <div className="flex items-center justify-between p-6 relative z-10 border-b border-white/5">
          <div className="flex items-center gap-4">
             <button onClick={() => changeMonth(-1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_left</span>
             </button>
             <div className="text-left">
               <h3 className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">
                 {calendarDate.toLocaleDateString('pt-PT', { year: 'numeric' })}
               </h3>
               <h3 className="text-sm font-black text-white uppercase tracking-widest leading-none">
                 {calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}
               </h3>
             </div>
             <button onClick={() => changeMonth(1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_right</span>
             </button>
          </div>

          {/* Botão de Expansão */}
          <button 
            onClick={() => setIsCalendarExpanded(!isCalendarExpanded)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${isCalendarExpanded ? 'bg-primary/20 text-primary' : 'bg-white/5 text-gray-400'}`}
          >
            <span className="material-symbols-outlined text-sm">{isCalendarExpanded ? 'expand_less' : 'expand_more'}</span>
            {isCalendarExpanded ? 'Recolher' : 'Calendário'}
          </button>
        </div>

        {/* Grelha do Calendário (Colapsável) */}
        <div className={`transition-all duration-500 ease-in-out px-6 ${isCalendarExpanded ? 'max-h-[400px] opacity-100 py-6' : 'max-h-0 opacity-0 py-0 overflow-hidden'}`}>
          <div className="grid grid-cols-7 gap-1 mb-2">
            {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map((day, i) => (
              <div key={i} className="text-center text-[8px] font-black text-gray-600 uppercase mb-2">{day}</div>
            ))}
            {days.map((day, i) => {
              const hasTournament = day !== null && tournamentDates.has(day.toString());
              const isSelected = selectedDay === day;
              const isToday = day !== null && new Date().toDateString() === new Date(currentYear, currentMonth, day).toDateString();

              return (
                <button
                  key={i}
                  disabled={day === null}
                  onClick={() => setSelectedDay(isSelected ? null : day)}
                  className={`
                    relative h-10 rounded-xl flex flex-col items-center justify-center transition-all text-[10px] font-bold
                    ${day === null ? 'opacity-0' : 'hover:bg-white/5'}
                    ${isSelected ? 'bg-primary text-background-dark scale-110 shadow-lg shadow-primary/20 z-10' : 'text-gray-400'}
                    ${isToday && !isSelected ? 'border border-primary/30 text-primary' : ''}
                  `}
                >
                  {day}
                  {hasTournament && (
                    <div className={`absolute bottom-1.5 size-1.5 rounded-full ${isSelected ? 'bg-background-dark' : 'bg-primary shadow-[0_0_5px_rgba(96,122,251,0.5)]'}`}></div>
                  )}
                </button>
              );
            })}
          </div>

          {selectedDay && (
            <button 
              onClick={() => setSelectedDay(null)}
              className="w-full mt-4 py-2 bg-white/5 rounded-xl text-[9px] font-black text-primary uppercase tracking-widest flex items-center justify-center gap-2"
            >
              <span className="material-symbols-outlined text-sm">close</span>
              Limpar Filtro de Data
            </button>
          )}
        </div>
      </section>

      <div className="space-y-4">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Pesquisar local..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-card-dark border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:ring-2 focus:ring-primary/50 outline-none transition-all"
          />
        </div>

        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between px-1">
            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">
              {selectedDay ? `Torneios em ${selectedDay} de ${calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}` : 'Lista de Torneios'}
            </h3>
            <span className="text-[10px] font-bold text-primary">{filteredHistory.length} encontrados</span>
          </div>

          {filteredHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 opacity-30 text-center">
              <span className="material-symbols-outlined text-6xl mb-4">history_toggle_off</span>
              <p className="text-sm font-bold">Nenhum registo encontrado</p>
              {selectedDay && <p className="text-[10px] uppercase mt-1">Tente selecionar outro dia ou limpar o filtro.</p>}
            </div>
          ) : (
            filteredHistory.map(t => {
              const loc = locations.find(l => l.id === t.locationId);
              const locName = loc?.name || 'Local Desconhecido';
              const isCancelled = t.status === 'cancelled';

              return (
                <div key={t.id} className={`relative group ${isCancelled ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                  <button 
                    onClick={() => !isCancelled && onViewTournament(t)}
                    disabled={isCancelled}
                    className="w-full bg-card-dark p-5 rounded-3xl border border-white/5 hover:border-primary/30 transition-all text-left group active:scale-[0.98] disabled:cursor-not-allowed"
                  >
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <span className={`text-[10px] font-black uppercase tracking-widest block mb-1 ${isCancelled ? 'text-red-500' : 'text-primary'}`}>
                          {new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                          {isCancelled && ' (CANCELADO)'}
                        </span>
                        <h3 className="text-xl font-black text-white group-hover:text-primary transition-colors">{locName}</h3>
                      </div>
                      {!isCancelled && (
                          <div className="size-10 rounded-2xl bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                              <span className="material-symbols-outlined text-gray-500 group-hover:text-primary">chevron_right</span>
                          </div>
                      )}
                    </div>

                    <div className="flex items-center gap-4 text-gray-500">
                      <div className="flex items-center gap-1.5">
                        <span className="material-symbols-outlined text-[16px]">sports_tennis</span>
                        <span className="text-[10px] font-bold uppercase">{t.matches?.length || 0} Jogos</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <span className="material-symbols-outlined text-[16px]">schedule</span>
                        <span className="text-[10px] font-bold uppercase">{t.time} • {t.duration}h</span>
                      </div>
                    </div>
                  </button>
                  {/* Botão de eliminar flutuante */}
                  <button 
                    onClick={(e) => { e.stopPropagation(); onDeleteTournament?.(t.id); }}
                    className="absolute bottom-4 right-4 p-2 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all opacity-0 group-hover:opacity-100 z-10"
                  >
                    <span className="material-symbols-outlined text-base">delete</span>
                  </button>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
  onViewTournament: (t: Tournament) => void;
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history,
    onViewTournament
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const [timeRemaining, setTimeRemaining] = useState<string>('');

  useEffect(() => {
    if (!activeTournament) return;

    const calculateTimeLeft = () => {
        const start = new Date(`${activeTournament.date}T${activeTournament.time}`);
        const now = new Date();
        const diff = start.getTime() - now.getTime();

        if (diff <= 0) {
             if (diff > -1000 * 60 * 60 * activeTournament.duration) return 'A DECORRER';
             return 'TERMINADO';
        }

        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
        const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

        if (days > 0) return `Faltam ${days}d ${hours}h`;
        if (hours > 0) return `Faltam ${hours}h ${minutes}m`;
        return `Faltam ${minutes}m`;
    };

    setTimeRemaining(calculateTimeLeft());
    const timer = setInterval(() => setTimeRemaining(calculateTimeLeft()), 60000);
    return () => clearInterval(timer);
  }, [activeTournament]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);
    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) setLocationId(lxIndoor.id);
    else if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
    setIsEditing(false);
  };

  const initEdit = () => {
    if (!activeTournament) return;
    setDate(activeTournament.date);
    setTime(activeTournament.time);
    setDuration(activeTournament.duration);
    setLocationId(activeTournament.locationId);
    setSelectedPlayers(activeTournament.confirmedPlayerIds);
    setIsCreating(true);
    setIsEditing(true);
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];
    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    if (isEditing && activeTournament) {
        onUpdateTournament({ 
            ...activeTournament, 
            date, 
            time, 
            duration, 
            locationId, 
            confirmedPlayerIds: selectedPlayers 
        });
    } else {
        onCreateTournament({ 
            id: `t-${Date.now()}`, 
            date, 
            time, 
            duration, 
            locationId, 
            confirmedPlayerIds: selectedPlayers, 
            status: 'scheduled', 
            rosterClosed: false 
        });
    }
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (activeTournament?.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores."); return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const StatsSection = (
    <section className="grid grid-cols-3 gap-3">
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
        <span className="text-xl font-bold text-white">{totalGames}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
      </div>
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
        <span className="text-xl font-bold text-white">{totalHours}h</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
      </div>
      <button 
        onClick={() => setScreen(Screen.LOCATIONS)}
        className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
      >
        <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
        <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
      </button>
    </section>
  );

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5"><span className="material-symbols-outlined text-white">close</span></button>
                <h2 className="text-lg font-bold">{isEditing ? 'Editar Torneio' : 'Novo Torneio'}</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                {!isEditing && (
                    <div className="space-y-3">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                        <div className="grid grid-cols-4 gap-2">
                            {players.map(p => (
                                <button key={p.id} onClick={() => { if(selectedPlayers.includes(p.id)) setSelectedPlayers(selectedPlayers.filter(i => i !== p.id)); else setSelectedPlayers([...selectedPlayers, p.id]); }} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                    {renderGlobalAvatar(p, 'size-8')}
                                    <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </div>
            <button onClick={handleSubmitTournament} className="mt-auto w-full bg-primary text-background-dark font-bold py-4 rounded-xl">{isEditing ? 'Guardar Alterações' : 'Criar Torneio'}</button>
        </div>
    );
  }

  if (activeTournament) {
    const loc = locations.find(l => l.id === activeTournament.locationId);
    const locName = loc?.name || 'Local Desconhecido';
    const confirmedCount = activeTournament.confirmedPlayerIds.length;
    const isLive = activeTournament.status === 'live';
    const isRosterClosed = activeTournament.rosterClosed;
    const isQuorumReached = confirmedCount === 8;
    const progress = Math.min(100, (confirmedCount / 8) * 100);

    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in relative">
            {isManagingPlayers && (
                <div className="fixed inset-0 z-[60] bg-background-dark flex flex-col animate-fade-in p-4">
                    <header className="flex items-center justify-between mb-4">
                        <h2 className="text-xl font-bold">Gerir Jogadores ({confirmedCount}/8)</h2>
                        <button onClick={() => setIsManagingPlayers(false)} className="size-10 rounded-full bg-white/5 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
                    </header>
                    <div className="flex-1 overflow-y-auto grid grid-cols-3 gap-3 pb-40 hide-scrollbar">
                        {players.filter(p => (p.nickname || p.name).toLowerCase().includes(playerSearchTerm.toLowerCase())).map(p => {
                            const isConfirmed = activeTournament.confirmedPlayerIds.includes(p.id);
                            return (
                                <button key={p.id} onClick={() => togglePlayerInActiveTournament(p.id)} className={`flex flex-col items-center p-3 rounded-2xl border transition-all ${isConfirmed ? 'bg-primary/20 border-primary' : 'bg-card-dark border-white/5'}`}>
                                    {renderGlobalAvatar(p, 'size-12')}
                                    <span className="text-[10px] font-bold mt-1 text-center truncate w-full">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            );
                        })}
                    </div>
                    <div className="absolute bottom-4 left-4 right-4 safe-area-bottom pb-28">
                         {isQuorumReached && (
                             <button onClick={handleCloseRoster} className="w-full bg-emerald-500 text-background-dark font-black py-4 rounded-2xl">FECHAR CONVOCATÓRIA</button>
                         )}
                    </div>
                </div>
            )}

            <header className="flex justify-between items-start">
                <div className="flex gap-3 items-center">
                    <img src="/favicon.svg" className="w-14 h-14 object-contain" alt="Logo" />
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight mb-1 leading-none">Padel <br/><span className="text-primary">Manager</span></h1>
                        <p className="text-slate-400 text-xs mt-1">{isLive ? 'Em direto!' : 'Fase de convocatória'}</p>
                    </div>
                </div>
                {!isLive && (
                    <div className="flex gap-2">
                         <button onClick={initEdit} className="bg-white/5 text-white size-10 flex items-center justify-center rounded-xl border border-white/10 active:scale-95 transition-all"><span className="material-symbols-outlined text-[20px]">edit</span></button>
                         <button onClick={onCancelTournament} className="bg-red-500/10 text-red-500 size-10 flex items-center justify-center rounded-xl border border-red-500/20 active:scale-95 transition-all"><span className="material-symbols-outlined text-[20px]">delete</span></button>
                    </div>
                )}
            </header>

            {StatsSection}

            <section className="relative overflow-hidden rounded-3xl min-h-[280px] flex flex-col justify-end bg-card-dark border border-white/10 p-5 shadow-2xl">
                {loc?.imageUrl && <img src={loc.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-40" alt={locName} />}
                <div className="relative z-10 space-y-4">
                    <div className="flex justify-between items-center">
                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase ${isLive ? 'bg-red-500 text-white animate-pulse' : 'bg-primary text-background-dark'}`}>
                            {isLive ? 'LIVE' : 'AGENDADO'}
                        </span>
                        <span className="text-xs font-black text-white">{timeRemaining}</span>
                    </div>

                    <div>
                        <h3 className="text-2xl font-black text-white leading-tight">{locName}</h3>
                        <p className="text-gray-400 text-xs font-bold">{new Date(activeTournament.date).toLocaleDateString('pt-PT', { weekday: 'long', day: 'numeric', month: 'long' })} • {activeTournament.time}</p>
                    </div>

                    {!isLive && (
                        <div className="space-y-2">
                            <div className="flex justify-between items-end">
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Convocatória</span>
                                <span className={`text-[10px] font-black uppercase ${isQuorumReached ? 'text-emerald-400' : 'text-primary'}`}>
                                    {isQuorumReached ? 'QUORUM ATINGIDO' : `Faltam ${8 - confirmedCount} jogadores`}
                                </span>
                            </div>
                            <div className="h-2 w-full bg-white/10 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ease-out ${isQuorumReached ? 'bg-emerald-500' : 'bg-primary'}`}
                                    style={{ width: `${progress}%` }}
                                />
                            </div>
                            <div className="flex justify-between text-[8px] font-black text-gray-500 uppercase">
                                <span>{confirmedCount} Confirmados</span>
                                <span>8 Necessários</span>
                            </div>
                        </div>
                    )}
                </div>
            </section>

            {isLive ? (
                <button onClick={() => setScreen(Screen.LIVE_GAME)} className="w-full bg-primary text-background-dark font-black py-5 rounded-2xl shadow-xl shadow-primary/20 flex items-center justify-center gap-2">
                    <span className="material-symbols-outlined font-black">sports_tennis</span>
                    IR PARA JOGO
                </button>
            ) : isRosterClosed ? (
                <button onClick={() => setScreen(Screen.TEAM_SETUP)} className="w-full bg-emerald-500 text-background-dark font-black py-5 rounded-2xl shadow-xl shadow-emerald-500/20 flex items-center justify-center gap-2">
                    <span className="material-symbols-outlined font-black">shuffle</span>
                    REALIZAR SORTEIO
                </button>
            ) : (
                <button onClick={() => setIsManagingPlayers(true)} className="w-full bg-white/5 border border-white/10 font-bold py-5 rounded-2xl flex items-center justify-center gap-2 active:bg-white/10 transition-all">
                    <span className="material-symbols-outlined font-black">group_add</span>
                    GERIR CONVOCATÓRIA
                </button>
            )}
        </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen">
        <header className="flex justify-between items-start">
            <div className="flex gap-3 items-center">
                <img src="/favicon.svg" className="w-14 h-14 object-contain" alt="Logo" />
                <div>
                    <h1 className="text-3xl font-bold tracking-tight leading-none">Padel <br/><span className="text-primary">Manager</span></h1>
                    <p className="text-slate-400 text-xs mt-1">Pronto para o próximo jogo?</p>
                </div>
            </div>
        </header>

        {StatsSection}

        <section className="bg-card-dark/50 border border-white/5 rounded-[2.5rem] p-8 flex flex-col items-center text-center gap-6 shadow-xl">
             <div className="size-20 bg-primary/10 rounded-full flex items-center justify-center">
                <span className="material-symbols-outlined text-4xl text-primary animate-bounce">event_available</span>
             </div>
             <div>
                <h3 className="text-xl font-black text-white">Nenhum jogo agendado</h3>
                <p className="text-gray-500 text-sm mt-2">Dá o primeiro passo e organiza o próximo torneio para o teu grupo.</p>
             </div>
             <button 
                onClick={initCreation} 
                className="w-full bg-primary text-background-dark font-black py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-primary/10 active:scale-95 transition-all"
             >
                <span className="material-symbols-outlined font-black">add</span>
                AGENDAR TORNEIO
             </button>
        </section>

        <section className="flex flex-col gap-4">
            <div className="flex items-center justify-between px-1">
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Últimos Torneios</h3>
              <button onClick={() => setScreen(Screen.TOURNAMENT_HISTORY)} className="text-[10px] font-black text-primary uppercase tracking-widest">Ver Tudo</button>
            </div>
            <div className="flex flex-col gap-3">
                {history.slice(0, 3).map((t) => (
                    <button key={t.id} onClick={() => onViewTournament(t)} className="flex items-center justify-between p-4 bg-card-dark rounded-2xl border border-white/5 active:bg-white/5 transition-all">
                        <div className="flex items-center gap-4">
                            <div className="size-10 rounded-xl bg-white/5 flex flex-col items-center justify-center">
                                <span className="text-[9px] font-black text-gray-500 uppercase">{new Date(t.date).toLocaleDateString('pt-PT', { month: 'short' })}</span>
                                <span className="text-sm font-black text-white">{new Date(t.date).getDate()}</span>
                            </div>
                            <div className="text-left">
                                <p className="text-sm font-black text-white leading-tight truncate max-w-[150px]">{locations.find(l => l.id === t.locationId)?.name || 'Local'}</p>
                                <p className="text-[9px] text-gray-500 font-bold uppercase tracking-widest">{t.matches?.length || 0} Jogos Realizados</p>
                            </div>
                        </div>
                        <span className="material-symbols-outlined text-gray-600">chevron_right</span>
                    </button>
                ))}
            </div>
        </section>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Screen, Match, Player } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface ResultsProps {
  setScreen: (screen: Screen) => void;
  matches?: Match[];
}

export const TournamentResultsScreen: React.FC<ResultsProps> = ({ setScreen, matches = [] }) => {

  const standings = useMemo(() => {
    const stats = new Map<string, { id: string, teamName: string, wins: number, pointsDiff: number, players: Player[] }>();
    const getStats = (team: Player[]) => {
        const key = team.map(p => p.id).sort().join('-');
        if (!stats.has(key)) stats.set(key, { id: key, teamName: team.map(p => p.nickname || p.name.split(' ')[0]).join(' & '), wins: 0, pointsDiff: 0, players: team });
        return stats.get(key)!;
    };
    matches.forEach(m => {
        const s1 = getStats(m.team1), s2 = getStats(m.team2);
        s1.pointsDiff += (m.score1 - m.score2); s2.pointsDiff += (m.score2 - m.score1);
        if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
    });
    return Array.from(stats.values()).sort((a, b) => b.wins - a.wins || b.pointsDiff - a.pointsDiff);
  }, [matches]);

  const winner = standings[0];

  const handleShare = async () => {
    if (standings.length === 0) return;

    let shareText = `🏆 *PADEL PRO - RESULTADOS DO TORNEIO*\n\n`;
    shareText += `🥇 *CAMPEÕES:* ${winner.teamName.toUpperCase()}\n`;
    shareText += `📊 Registo: ${winner.wins} Vitórias | Saldo: ${winner.pointsDiff > 0 ? '+' : ''}${winner.pointsDiff}\n\n`;
    shareText += `--- *CLASSIFICAÇÃO GERAL* ---\n`;

    standings.forEach((team, idx) => {
        const medal = idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : '🔹';
        shareText += `${medal} ${idx + 1}º ${team.teamName} (${team.wins}V | ${team.pointsDiff > 0 ? '+' : ''}${team.pointsDiff})\n`;
    });

    shareText += `\n_Gerado por Padel Pro Manager_ 🎾`;

    try {
        if (navigator.share) {
            await navigator.share({
                title: 'Resultados do Torneio de Padel',
                text: shareText
            });
        } else {
            await navigator.clipboard.writeText(shareText);
            alert('Resultados copiados para a área de transferência! Prontos para colar.');
        }
    } catch (err) {
        console.error('Erro ao partilhar:', err);
    }
  };

  return (
    <div className="flex-1 flex flex-col w-full max-w-md mx-auto px-4 pb-32 animate-fade-in bg-background-dark min-h-screen">
        <header className="py-8 text-center">
            <span className="text-[10px] font-black text-primary uppercase tracking-[0.3em]">Torneio Terminado</span>
            <h1 className="text-2xl font-black text-white mt-1">Classificação Final</h1>
        </header>

        {winner && (
            <section className="flex flex-col items-center mb-10 animate-fade-in-up">
                <div className="relative mb-6">
                    <div className="absolute inset-0 bg-primary/20 blur-3xl rounded-full scale-150"></div>
                    <div className="relative bg-card-dark border border-primary/30 p-6 rounded-[3rem] shadow-2xl flex flex-col items-center justify-center size-56">
                        <span className="material-symbols-outlined text-primary text-[60px] opacity-20 absolute top-4">emoji_events</span>

                        {/* Imagens dos Vencedores */}
                        <div className="flex -space-x-4 mb-4 relative z-10">
                            {winner.players.map((p, idx) => (
                                <div key={p.id} className={`ring-4 ring-card-dark rounded-full shadow-2xl transform ${idx === 0 ? '-rotate-6' : 'rotate-6'}`}>
                                    {renderGlobalAvatar(p, 'size-20')}
                                </div>
                            ))}
                        </div>

                        <div className="bg-primary text-background-dark font-black px-4 py-1 rounded-xl shadow-xl whitespace-nowrap text-[9px] uppercase tracking-widest mb-2">Campeões</div>
                        <h2 className="text-white text-xl font-black text-center leading-tight max-w-[160px]">{winner.teamName}</h2>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <div className="bg-white/5 px-4 py-2 rounded-2xl border border-white/5 flex flex-col items-center">
                        <span className="text-lg font-black text-white">{winner.wins}</span>
                        <span className="text-[8px] font-bold text-gray-500 uppercase">Vitórias</span>
                    </div>
                    <div className="bg-white/5 px-4 py-2 rounded-2xl border border-white/5 flex flex-col items-center">
                        <span className="text-lg font-black text-primary">+{winner.pointsDiff}</span>
                        <span className="text-[8px] font-bold text-gray-500 uppercase">Diferença</span>
                    </div>
                </div>
            </section>
        )}

        <div className="w-full bg-card-dark rounded-3xl p-6 shadow-xl border border-white/5 mb-8">
            <header className="grid grid-cols-[3rem_1fr_3rem_3rem] gap-2 pb-4 border-b border-white/10 mb-4">
                <div className="text-center text-[9px] font-black text-gray-500 uppercase tracking-widest">Pos</div>
                <div className="text-left pl-2 text-[9px] font-black text-gray-500 uppercase tracking-widest">Equipa</div>
                <div className="text-center text-[9px] font-black text-gray-500 uppercase tracking-widest">V</div>
                <div className="text-right text-[9px] font-black text-gray-500 uppercase tracking-widest">DP</div>
            </header>

            <div className="flex flex-col gap-4">
                {standings.map((team, idx) => (
                    <div key={idx} className="grid grid-cols-[3rem_1fr_3rem_3rem] gap-2 items-center">
                        <div className="flex justify-center">
                            <div className={`flex items-center justify-center size-8 rounded-xl font-black text-xs ${idx === 0 ? 'bg-primary text-background-dark shadow-lg' : 'bg-white/5 text-gray-400'}`}>
                                {idx + 1}
                            </div>
                        </div>
                        <div className="pl-2 truncate font-black text-white text-sm">{team.teamName}</div>
                        <div className="text-center font-black text-white text-sm">{team.wins}</div>
                        <div className={`text-right font-black text-sm ${team.pointsDiff > 0 ? 'text-primary' : team.pointsDiff === 0 ? 'text-gray-500' : 'text-red-400'}`}>
                            {team.pointsDiff > 0 ? '+' : ''}{team.pointsDiff}
                        </div>
                    </div>
                ))}
            </div>
        </div>

        <footer className="space-y-4">
            <button 
                onClick={() => setScreen(Screen.GLOBAL_STATS)} 
                className="w-full bg-primary/10 hover:bg-primary/20 text-primary border border-primary/30 font-black text-sm py-5 rounded-3xl flex items-center justify-center gap-3 transition-all shadow-lg active:scale-95"
            >
                <span className="material-symbols-outlined">bar_chart</span>
                <span>VER ESTATÍSTICAS GLOBAIS</span>
            </button>

            <button 
                onClick={handleShare}
                className="w-full bg-white text-background-dark font-black text-sm py-5 rounded-3xl flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"
            >
                <span className="material-symbols-outlined">share</span>
                <span>PARTILHAR RESULTADOS</span>
            </button>

            <button 
                onClick={() => setScreen(Screen.HOME)} 
                className="w-full text-gray-600 hover:text-white font-black text-[10px] uppercase py-2 tracking-widest text-center"
            >
                Voltar ao Início
            </button>
        </footer>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Tournament, Player, Match, Location, Screen } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface GlobalStatsProps {
  history?: Tournament[];
  players?: Player[];
  locations?: Location[];
  onViewTournament?: (tournament: Tournament) => void;
  onViewPlayer?: (id: string) => void;
}

interface PlayerStats extends Player {
  gamesPlayed: number;
  wins: number;
  losses: number;
  pointsScored: number;
  pointsConceded: number;
  tournamentsPlayed: number;
  tournamentsWon: number;
  maxWinStreak: number;
  currentStreak: number;
  balance: number;
}

type SortKey = keyof Pick<PlayerStats, 'gamesPlayed' | 'wins' | 'losses' | 'balance' | 'pointsScored' | 'pointsConceded' | 'tournamentsWon'>;

export const GlobalStatsScreen: React.FC<GlobalStatsProps> = ({ history = [], players = [], locations = [], onViewTournament, onViewPlayer }) => {
  const [timeRange, setTimeRange] = useState<'all' | 'month' | 'year'>('all');
  const [drillDown, setDrillDown] = useState<{ title: string; type: string; data: any[] } | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' }>({ 
    key: 'tournamentsWon', 
    direction: 'desc' 
  });

  const handleSort = (key: SortKey) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'desc' ? 'asc' : 'desc'
    }));
  };

  const filteredHistory = useMemo(() => {
    const finished = history.filter(t => t.status === 'finished');
    if (timeRange === 'all') return finished;
    const now = new Date();
    return finished.filter(t => {
      const tDate = new Date(t.date);
      if (timeRange === 'month') return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      if (timeRange === 'year') return tDate.getFullYear() === now.getFullYear();
      return true;
    });
  }, [history, timeRange]);

  const stats = useMemo(() => {
    const pStats = new Map<string, PlayerStats>();
    const duoStats = new Map<string, { wins: number, games: number, p1: Player, p2: Player }>();
    const locStats = new Map<string, number>();

    let totalMatches = 0;
    let totalPoints = 0;
    let allMatches: (Match & { tournamentId: string, locationName: string })[] = [];

    players.forEach(p => {
      pStats.set(p.id, { 
        ...p, gamesPlayed: 0, wins: 0, losses: 0, 
        pointsScored: 0, pointsConceded: 0, 
        tournamentsPlayed: 0, tournamentsWon: 0, 
        maxWinStreak: 0, currentStreak: 0,
        balance: 0
      });
    });

    filteredHistory.forEach(t => {
      const locationName = locations.find(l => l.id === t.locationId)?.name || 'Local N/A';
      locStats.set(t.locationId, (locStats.get(t.locationId) || 0) + 1);
      const tPlayers = new Set<string>();

      if (t.matches) {
        const teamResults = new Map<string, { wins: number, diff: number, ids: string[] }>();

        t.matches.forEach(m => {
          allMatches.push({ ...m, tournamentId: t.id, locationName });
          totalMatches++;
          totalPoints += (m.score1 + m.score2);

          const k1 = m.team1.map(p => p.id).sort().join('-');
          const k2 = m.team2.map(p => p.id).sort().join('-');

          if (!duoStats.has(k1)) duoStats.set(k1, { wins: 0, games: 0, p1: m.team1[0], p2: m.team1[1] });
          if (!duoStats.has(k2)) duoStats.set(k2, { wins: 0, games: 0, p1: m.team2[0], p2: m.team2[1] });

          const ds1 = duoStats.get(k1)!; ds1.games++;
          const ds2 = duoStats.get(k2)!; ds2.games++;

          if (!teamResults.has(k1)) teamResults.set(k1, { wins: 0, diff: 0, ids: m.team1.map(p => p.id) });
          if (!teamResults.has(k2)) teamResults.set(k2, { wins: 0, diff: 0, ids: m.team2.map(p => p.id) });

          const tr1 = teamResults.get(k1)!; tr1.diff += (m.score1 - m.score2);
          const tr2 = teamResults.get(k2)!; tr2.diff += (m.score2 - m.score1);

          if (m.score1 > m.score2) {
             ds1.wins++; tr1.wins++;
          } else if (m.score2 > m.score1) {
             ds2.wins++; tr2.wins++;
          }

          [m.team1, m.team2].forEach((team, idx) => {
             const isT1 = idx === 0;
             const won = isT1 ? m.score1 > m.score2 : m.score2 > m.score1;
             team.forEach(p => {
                tPlayers.add(p.id);
                const ps = pStats.get(p.id);
                if (ps) {
                  ps.gamesPlayed++;
                  ps.pointsScored += isT1 ? m.score1 : m.score2;
                  ps.pointsConceded += isT1 ? m.score2 : m.score1;
                  if (won) { ps.wins++; ps.currentStreak++; ps.maxWinStreak = Math.max(ps.maxWinStreak, ps.currentStreak); }
                  else { ps.losses++; ps.currentStreak = 0; }
                  ps.balance = ps.wins - ps.losses;
                }
             });
          });
        });

        const sortedStandings = Array.from(teamResults.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
        if (sortedStandings.length > 0) {
          const winners = sortedStandings[0].ids;
          winners.forEach(id => {
            const ps = pStats.get(id);
            if (ps) ps.tournamentsWon++;
          });
        }
      }
      tPlayers.forEach(id => { const ps = pStats.get(id); if (ps) ps.tournamentsPlayed++; });
    });

    const activePlayers = Array.from(pStats.values()).filter(p => p.gamesPlayed > 0);
    const duos = Array.from(duoStats.values())
      .filter(d => d.games >= 2)
      .map(d => ({ ...d, winRate: Math.round((d.wins / d.games) * 100) }))
      .sort((a,b) => b.winRate - a.winRate || b.games - a.games);

    const locationsRanked = Array.from(locStats.entries())
      .map(([id, count]) => ({ ...locations.find(l => l.id === id), count }))
      .sort((a,b) => b.count - a.count);

    const matchEquilibrium = [...allMatches].sort((a,b) => Math.abs(a.score1 - a.score2) - Math.abs(b.score1 - b.score2));
    const matchUnbalanced = [...allMatches].sort((a,b) => Math.abs(b.score1 - b.score2) - Math.abs(a.score1 - a.score2));

    const tournamentEquilibrium = filteredHistory.map(t => {
      const diffs = t.matches?.map(m => Math.abs(m.score1 - m.score2)) || [];
      const avgDiff = diffs.length > 0 ? diffs.reduce((a,b) => a+b, 0) / diffs.length : 99;
      const totalPts = t.matches?.reduce((a,b) => a + b.score1 + b.score2, 0) || 0;
      return { ...t, avgDiff, totalPts, locName: locations.find(l => l.id === t.locationId)?.name };
    }).sort((a,b) => a.avgDiff - b.avgDiff);

    const tournamentMostPoints = [...tournamentEquilibrium].sort((a,b) => b.totalPts - a.totalPts);

    return {
      totalTournaments: filteredHistory.length,
      totalMatches,
      totalPoints,
      activePlayers,
      mostWins: [...activePlayers].sort((a,b) => b.wins - a.wins),
      mostAttendance: [...activePlayers].sort((a,b) => b.tournamentsPlayed - a.tournamentsPlayed),
      mostPointsELO: [...activePlayers].sort((a,b) => (b.rankingPoints || 0) - (a.rankingPoints || 0)),
      mostStreaks: [...activePlayers].sort((a,b) => b.maxWinStreak - a.maxWinStreak),
      duos,
      locationsRanked,
      matchEquilibrium,
      matchUnbalanced,
      tournamentEquilibrium,
      tournamentMostPoints
    };
  }, [filteredHistory, players, locations]);

  // Novo Memo para ordenar os jogadores ativos dinamicamente
  const sortedActivePlayers = useMemo(() => {
    return [...stats.activePlayers].sort((a, b) => {
      const valA = a[sortConfig.key] as number;
      const valB = b[sortConfig.key] as number;

      if (sortConfig.direction === 'desc') {
        return valB - valA || (b.rankingPoints || 0) - (a.rankingPoints || 0);
      }
      return valA - valB || (a.rankingPoints || 0) - (b.rankingPoints || 0);
    });
  }, [stats.activePlayers, sortConfig]);

  const StatBox = ({ label, value, sub, icon, color, onClick }: any) => (
    <button onClick={onClick} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left active:scale-95 transition-all group">
      <div className={`size-10 rounded-2xl bg-${color}/10 flex items-center justify-center text-${color} group-hover:bg-${color}/20 transition-colors`}>
        <span className="material-symbols-outlined">{icon}</span>
      </div>
      <div>
        <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest">{label}</p>
        <p className="text-xl font-black text-white">{value}</p>
        {sub && <p className="text-[9px] font-bold text-gray-600 uppercase">{sub}</p>}
      </div>
    </button>
  );

  const SortHeader = ({ label, sortKey, align = 'center' }: { label: string, sortKey: SortKey, align?: 'center' | 'left' | 'right' }) => {
    const isActive = sortConfig.key === sortKey;
    return (
      <th 
        onClick={() => handleSort(sortKey)} 
        className={`px-2 py-3 text-[8px] font-black uppercase cursor-pointer select-none transition-colors active:bg-white/10 ${isActive ? 'text-primary' : 'text-gray-500'}`}
      >
        <div className={`flex items-center gap-0.5 ${align === 'center' ? 'justify-center' : align === 'right' ? 'justify-end' : 'justify-start'}`}>
          {label}
          {isActive ? (
            <span className="material-symbols-outlined text-[12px]">
              {sortConfig.direction === 'desc' ? 'keyboard_arrow_down' : 'keyboard_arrow_up'}
            </span>
          ) : (
            <span className="material-symbols-outlined text-[12px] opacity-0 group-hover:opacity-100">unfold_more</span>
          )}
        </div>
      </th>
    );
  };

  return (
    <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in bg-background-dark min-h-screen">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-white">Central <span className="text-primary">Global</span></h1>
          <p className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em]">Dashboard de Performance</p>
        </div>
        <div className="flex bg-white/5 rounded-xl p-1 border border-white/5">
          {['all', 'month', 'year'].map(r => (
            <button key={r} onClick={() => setTimeRange(r as any)} className={`px-3 py-1.5 text-[8px] font-black rounded-lg transition-all ${timeRange === r ? 'bg-primary text-background-dark' : 'text-gray-500'}`}>{r === 'all' ? 'TOTAL' : r === 'month' ? 'MÊS' : 'ANO'}</button>
          ))}
        </div>
      </header>

      <section className="grid grid-cols-2 gap-3">
        <StatBox label="Torneios" value={stats.totalTournaments} icon="emoji_events" color="yellow-500" onClick={() => setDrillDown({ title: 'Torneios Realizados', type: 'tournaments', data: filteredHistory })} />
        <StatBox label="Jogos" value={stats.totalMatches} sub={`${stats.totalPoints} Pontos`} icon="sports_tennis" color="primary" onClick={() => setDrillDown({ title: 'Histórico de Jogos', type: 'matches', data: stats.matchEquilibrium })} />
        <StatBox label="Ativos" value={stats.activePlayers.length} icon="group" color="emerald-400" onClick={() => setDrillDown({ title: 'Jogadores Ativos', type: 'players-attendance', data: stats.mostAttendance })} />
        <StatBox label="Clube Favorito" value={stats.locationsRanked[0]?.name || '-'} icon="location_on" color="purple-400" onClick={() => setDrillDown({ title: 'Locais Frequentes', type: 'locations', data: stats.locationsRanked })} />
      </section>

      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Liderança & Rankings</h3>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Líderes de Vitórias', type: 'players-wins', data: stats.mostWins })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-3">
            <span className="text-[8px] font-black text-primary uppercase">Vitórias Individuais</span>
            <div className="flex items-center gap-2">
              {stats.mostWins[0] && renderGlobalAvatar(stats.mostWins[0], 'size-8')}
              <div className="flex flex-col">
                <span className="text-xs font-black text-white">{stats.mostWins[0]?.nickname || stats.mostWins[0]?.name.split(' ')[0] || '-'}</span>
                <span className="text-[10px] font-bold text-gray-500">{stats.mostWins[0]?.wins || 0}V</span>
              </div>
            </div>
          </button>
          <button onClick={() => setDrillDown({ title: 'Ranking de Pontos', type: 'players-elo', data: stats.mostPointsELO })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-3">
            <span className="text-[8px] font-black text-orange-400 uppercase">Ranking ELO</span>
            <div className="flex items-center gap-2">
              {stats.mostPointsELO[0] && renderGlobalAvatar(stats.mostPointsELO[0], 'size-8')}
              <div className="flex flex-col">
                <span className="text-xs font-black text-white">{stats.mostPointsELO[0]?.nickname || stats.mostPointsELO[0]?.name.split(' ')[0] || '-'}</span>
                <span className="text-[10px] font-bold text-gray-500">{stats.mostPointsELO[0]?.rankingPoints || 0} pts</span>
              </div>
            </div>
          </button>
        </div>
      </section>

      {/* Tabela de Ranking Geral com Ordenação */}
      <section className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Ranking de Dados dos Jogadores</h3>
          <span className="text-[8px] text-primary font-bold uppercase tracking-wider">Clique nos títulos para ordenar</span>
        </div>
        <div className="bg-card-dark rounded-[2rem] border border-white/5 shadow-xl overflow-hidden">
          <div className="overflow-x-auto hide-scrollbar">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-white/5">
                  <th className="px-4 py-3 text-[8px] font-black text-gray-500 uppercase min-w-[120px]">Jogador</th>
                  <SortHeader label="J" sortKey="gamesPlayed" />
                  <SortHeader label="V" sortKey="wins" />
                  <SortHeader label="D" sortKey="losses" />
                  <SortHeader label="S" sortKey="balance" />
                  <SortHeader label="PG" sortKey="pointsScored" />
                  <SortHeader label="PS" sortKey="pointsConceded" />
                  <th onClick={() => handleSort('tournamentsWon')} className={`px-3 py-3 text-[8px] font-black uppercase text-center cursor-pointer transition-colors ${sortConfig.key === 'tournamentsWon' ? 'bg-yellow-500/20 text-yellow-500' : 'bg-yellow-500/5 text-gray-500'}`}>
                    <div className="flex items-center justify-center gap-0.5">
                      Tít
                      {sortConfig.key === 'tournamentsWon' && (
                        <span className="material-symbols-outlined text-[12px]">
                          {sortConfig.direction === 'desc' ? 'keyboard_arrow_down' : 'keyboard_arrow_up'}
                        </span>
                      )}
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {sortedActivePlayers.map((p, idx) => (
                  <tr key={p.id} className={`${idx === 0 && sortConfig.key === 'tournamentsWon' ? 'bg-primary/5' : ''} active:bg-white/5 transition-colors`} onClick={() => onViewPlayer?.(p.id)}>
                    <td className="px-4 py-3 whitespace-nowrap">
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-700 w-3 shrink-0">{idx + 1}</span>
                        {renderGlobalAvatar(p, 'size-7')}
                        <span className="text-[10px] font-black text-white">{p.nickname || p.name}</span>
                      </div>
                    </td>
                    <td className={`px-2 py-3 text-[10px] font-bold text-center ${sortConfig.key === 'gamesPlayed' ? 'text-primary' : 'text-white'}`}>{p.gamesPlayed}</td>
                    <td className={`px-2 py-3 text-[10px] font-bold text-center ${sortConfig.key === 'wins' ? 'text-emerald-400' : 'text-emerald-400/70'}`}>{p.wins}</td>
                    <td className={`px-2 py-3 text-[10px] font-bold text-center ${sortConfig.key === 'losses' ? 'text-red-400' : 'text-red-400/70'}`}>{p.losses}</td>
                    <td className={`px-2 py-3 text-[10px] font-black text-center ${sortConfig.key === 'balance' ? 'text-primary' : p.balance >= 0 ? 'text-white/80' : 'text-red-500'}`}>
                      {p.balance > 0 ? `+${p.balance}` : p.balance}
                    </td>
                    <td className={`px-2 py-3 text-[10px] font-bold text-center ${sortConfig.key === 'pointsScored' ? 'text-emerald-500' : 'text-emerald-500/50'}`}>{p.pointsScored}</td>
                    <td className={`px-2 py-3 text-[10px] font-bold text-center ${sortConfig.key === 'pointsConceded' ? 'text-red-500' : 'text-red-500/50'}`}>{p.pointsConceded}</td>
                    <td className={`px-3 py-3 text-[10px] font-black text-center ${sortConfig.key === 'tournamentsWon' ? 'text-yellow-500 bg-yellow-500/10' : 'text-yellow-500/60 bg-yellow-500/5'}`}>{p.tournamentsWon}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </section>

      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Duplas em Destaque</h3>
        <button onClick={() => setDrillDown({ title: 'Ranking de Duplas', type: 'duos', data: stats.duos })} className="w-full bg-gradient-to-br from-primary/20 to-card-dark p-6 rounded-[2.5rem] border border-primary/20 flex flex-col gap-4 text-left shadow-xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-8 opacity-10"><span className="material-symbols-outlined text-7xl">groups</span></div>
           <div className="flex justify-between items-start">
             <div><p className="text-[9px] font-black text-primary uppercase mb-1">Dupla Imbatível</p><h4 className="text-xl font-black text-white">{stats.duos[0] ? `${stats.duos[0].p1.name.split(' ')[0]} & ${stats.duos[0].p2.name.split(' ')[0]}` : 'Sem dados'}</h4></div>
             <div className="bg-primary/20 px-3 py-1 rounded-full text-primary text-[10px] font-black">{stats.duos[0]?.winRate || 0}% WR</div>
           </div>
           <div className="flex items-center gap-4">
             <div className="flex -space-x-3">{stats.duos[0] && renderGlobalAvatar(stats.duos[0].p1, 'size-10')}{stats.duos[0] && renderGlobalAvatar(stats.duos[0].p2, 'size-10')}</div>
             <p className="text-[10px] font-bold text-gray-500 uppercase">{stats.duos[0]?.wins} Vitórias em {stats.duos[0]?.games} Jogos</p>
           </div>
        </button>
      </section>

      <section className="space-y-4">
        <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest px-1">Equilíbrio & Recordes</h3>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setDrillDown({ title: 'Jogos Mais Equilibrados', type: 'matches-eq', data: stats.matchEquilibrium })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-emerald-400 uppercase">Jogo + Equilibrado</span>
            <p className="text-xs font-black text-white truncate">{stats.matchEquilibrium[0] ? `${stats.matchEquilibrium[0].score1}-${stats.matchEquilibrium[0].score2}` : '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">{stats.matchEquilibrium[0]?.locationName || '-'}</p>
          </button>
          <button onClick={() => setDrillDown({ title: 'Jogos Mais Desequilibrados', type: 'matches-un', data: stats.matchUnbalanced })} className="bg-card-dark p-4 rounded-3xl border border-white/5 flex flex-col gap-2 text-left">
            <span className="text-[8px] font-black text-red-400 uppercase">Jogo + Desequilibrado</span>
            <p className="text-xs font-black text-white truncate">{stats.matchUnbalanced[0] ? `${stats.matchUnbalanced[0].score1}-${stats.matchUnbalanced[0].score2}` : '-'}</p>
            <p className="text-[8px] text-gray-500 uppercase font-bold">{stats.matchUnbalanced[0]?.locationName || '-'}</p>
          </button>
        </div>
      </section>

      {drillDown && (
        <div className="fixed inset-0 z-[100] bg-background-dark/98 backdrop-blur-2xl animate-fade-in flex flex-col p-4">
          <header className="flex items-center justify-between mb-8 shrink-0">
            <div>
              <h2 className="text-xl font-black text-white">{drillDown.title}</h2>
              <p className="text-[9px] font-black text-primary uppercase tracking-widest">{drillDown.data.length} Entradas</p>
            </div>
            <button onClick={() => setDrillDown(null)} className="size-11 rounded-full bg-white/10 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
          </header>
          <div className="flex-1 overflow-y-auto space-y-3 pb-24 hide-scrollbar">
            {drillDown.type.startsWith('players') && drillDown.data.map((p, i) => (
              <button key={p.id} onClick={() => { onViewPlayer?.(p.id); setDrillDown(null); }} className="w-full bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between text-left">
                <div className="flex items-center gap-4">
                  <span className="text-[10px] font-black text-gray-700 w-4">{i+1}</span>
                  {renderGlobalAvatar(p, 'size-10')}
                  <div><p className="text-sm font-black text-white">{p.nickname || p.name}</p><p className="text-[9px] text-gray-500 uppercase">{p.level}</p></div>
                </div>
                <p className="text-xs font-black text-primary">
                  {drillDown.type === 'players-wins' ? `${p.wins}V` : drillDown.type === 'players-streaks' ? `${p.maxWinStreak}S` : drillDown.type === 'players-elo' ? `${p.rankingPoints} pts` : `${p.tournamentsPlayed} T`}
                </p>
              </button>
            ))}
            {drillDown.type === 'duos' && drillDown.data.map((d, i) => (
              <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-3">{renderGlobalAvatar(d.p1, 'size-9')}{renderGlobalAvatar(d.p2, 'size-9')}</div>
                  <div><p className="text-xs font-black text-white">{d.p1.name.split(' ')[0]} & {d.p2.name.split(' ')[0]}</p><p className="text-[9px] text-gray-500">{d.games} Jogos</p></div>
                </div>
                <p className="text-sm font-black text-primary">{d.winRate}% WR</p>
              </div>
            ))}
            {drillDown.type.startsWith('matches') && drillDown.data.map((m, i) => (
              <div key={i} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col gap-2">
                <div className="flex justify-between items-center text-[8px] font-black text-gray-600 uppercase mb-1"><span>Campo {m.court}</span><span>{m.locationName}</span></div>
                <div className="flex items-center justify-between gap-3">
                  <span className="flex-1 text-[10px] font-black text-white text-right">{m.team1.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</span>
                  <div className="bg-background-dark px-4 py-1.5 rounded-xl border border-white/10 flex items-center gap-2">
                    <span className={`text-base font-black ${m.score1 > m.score2 ? 'text-primary' : 'text-gray-600'}`}>{m.score1}</span>
                    <span className="text-[10px] text-gray-800">-</span>
                    <span className={`text-base font-black ${m.score2 > m.score1 ? 'text-primary' : 'text-gray-600'}`}>{m.score2}</span>
                  </div>
                  <span className="flex-1 text-[10px] font-black text-white text-left">{m.team2.map((p: any) => p.nickname || p.name.split(' ')[0]).join('/')}</span>
                </div>
              </div>
            ))}
            {drillDown.type.startsWith('tournaments') && drillDown.data.map((t) => (
              <button key={t.id} onClick={() => { onViewTournament?.(t); setDrillDown(null); }} className="w-full bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between text-left">
                <div><p className="text-[10px] font-black text-primary uppercase">{new Date(t.date).toLocaleDateString()}</p><p className="text-sm font-black text-white">{locations.find(l => l.id === t.locationId)?.name}</p></div>
                <p className="text-xs font-black text-white">
                  {drillDown.type === 'tournaments-eq' ? `±${t.avgDiff.toFixed(1)} diff` : drillDown.type === 'tournaments-pts' ? `${t.totalPts} pts` : `${t.matches?.length || 0} Jogos`}
                </p>
              </button>
            ))}
            {drillDown.type === 'locations' && drillDown.data.map((loc, i) => (
              <div key={loc.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-4"><span className="text-[10px] font-black text-gray-700 w-4">{i+1}</span><div><p className="text-sm font-black text-white">{loc.name}</p><p className="text-[9px] text-gray-500 uppercase">{loc.type}</p></div></div>
                <div className="bg-primary/10 px-3 py-1 rounded-lg text-primary text-[10px] font-black">{loc.count} Torneios</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Screen, Tournament, Location, Player, Match } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HistoryProps {
  history: Tournament[];
  locations: Location[];
  players: Player[];
  onViewTournament: (t: Tournament) => void;
  onDeleteTournament?: (id: string) => void;
}

export const TournamentHistoryScreen: React.FC<HistoryProps> = ({ history, locations, players, onViewTournament, onDeleteTournament }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showCancelled, setShowCancelled] = useState(false);
  const [calendarDate, setCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  const [isCalendarExpanded, setIsCalendarExpanded] = useState(false);

  // Lógica do Calendário
  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const currentYear = calendarDate.getFullYear();
  const currentMonth = calendarDate.getMonth();

  const days = useMemo(() => {
    const totalDays = daysInMonth(currentYear, currentMonth);
    const firstDay = firstDayOfMonth(currentYear, currentMonth);
    const daysArray = [];

    for (let i = 0; i < firstDay; i++) {
      daysArray.push(null);
    }

    for (let i = 1; i <= totalDays; i++) {
      daysArray.push(i);
    }

    return daysArray;
  }, [currentYear, currentMonth]);

  const tournamentDates = useMemo(() => {
    const dates = new Set<string>();
    history.forEach(t => {
      const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');
      if (statusMatch) {
        const d = new Date(t.date);
        if (d.getFullYear() === currentYear && d.getMonth() === currentMonth) {
          dates.add(d.getDate().toString());
        }
      }
    });
    return dates;
  }, [history, currentYear, currentMonth, showCancelled]);

  const filteredHistory = useMemo(() => {
    return history
      .filter(t => {
        const loc = locations.find(l => l.id === t.locationId);
        const locName = loc?.name || 'Local Desconhecido';
        const matchesSearch = locName.toLowerCase().includes(searchTerm.toLowerCase());

        const tDate = new Date(t.date);
        const matchesDay = selectedDay === null || (
          tDate.getDate() === selectedDay && 
          tDate.getMonth() === currentMonth && 
          tDate.getFullYear() === currentYear
        );

        const statusMatch = t.status === 'finished' || (showCancelled && t.status === 'cancelled');

        return matchesSearch && matchesDay && statusMatch;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [history, searchTerm, selectedDay, currentMonth, currentYear, locations, showCancelled]);

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentYear, currentMonth + offset, 1);
    setCalendarDate(newDate);
    setSelectedDay(null);
  };

  const getWinnersOfTournament = (t: Tournament) => {
    if (!t.matches || t.matches.length === 0) return null;

    const stats = new Map<string, { wins: number, diff: number, pids: string[] }>();
    t.matches.forEach(m => {
        const k1 = m.team1.map(p => p.id).sort().join('-');
        const k2 = m.team2.map(p => p.id).sort().join('-');
        if (!stats.has(k1)) stats.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p => p.id) });
        if (!stats.has(k2)) stats.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p => p.id) });
        const s1 = stats.get(k1)!, s2 = stats.get(k2)!;
        s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
        if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
    });

    const standings = Array.from(stats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
    if (standings.length === 0) return null;

    return standings[0].pids.map(id => players.find(p => p.id === id)).filter((p): p is Player => !!p);
  };

  return (
    <div className="flex flex-col gap-6 px-4 pt-6 pb-32 animate-fade-in">
      <header className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-black text-white">Registo <br/><span className="text-primary">Histórico</span></h1>
          <p className="text-gray-500 text-sm mt-1">Consulte todos os torneios realizados.</p>
        </div>
        <button 
          onClick={() => setShowCancelled(!showCancelled)} 
          className={`size-12 rounded-2xl border flex items-center justify-center transition-all ${showCancelled ? 'bg-red-500/10 border-red-500/50 text-red-500' : 'bg-card-dark border-white/5 text-gray-500'}`}
          title="Ver Cancelados"
        >
          <span className="material-symbols-outlined">{showCancelled ? 'event_busy' : 'event_available'}</span>
        </button>
      </header>

      <section className="bg-card-dark rounded-[2.5rem] border border-white/5 shadow-xl overflow-hidden relative transition-all duration-500 ease-in-out">
        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
          <span className="material-symbols-outlined text-8xl">calendar_month</span>
        </div>

        <div className="flex items-center justify-between p-6 relative z-10 border-b border-white/5">
          <div className="flex items-center gap-4">
             <button onClick={() => changeMonth(-1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_left</span>
             </button>
             <div className="text-left">
               <h3 className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">
                 {calendarDate.toLocaleDateString('pt-PT', { year: 'numeric' })}
               </h3>
               <h3 className="text-sm font-black text-white uppercase tracking-widest leading-none">
                 {calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}
               </h3>
             </div>
             <button onClick={() => changeMonth(1)} className="size-9 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white transition-colors">
               <span className="material-symbols-outlined text-xl">chevron_right</span>
             </button>
          </div>

          <button 
            onClick={() => setIsCalendarExpanded(!isCalendarExpanded)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${isCalendarExpanded ? 'bg-primary/20 text-primary' : 'bg-white/5 text-gray-400'}`}
          >
            <span className="material-symbols-outlined text-sm">{isCalendarExpanded ? 'expand_less' : 'expand_more'}</span>
            {isCalendarExpanded ? 'Recolher' : 'Calendário'}
          </button>
        </div>

        <div className={`transition-all duration-500 ease-in-out px-6 ${isCalendarExpanded ? 'max-h-[400px] opacity-100 py-6' : 'max-h-0 opacity-0 py-0 overflow-hidden'}`}>
          <div className="grid grid-cols-7 gap-1 mb-2">
            {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map((day, i) => (
              <div key={i} className="text-center text-[8px] font-black text-gray-600 uppercase mb-2">{day}</div>
            ))}
            {days.map((day, i) => {
              const hasTournament = day !== null && tournamentDates.has(day.toString());
              const isSelected = selectedDay === day;
              const isToday = day !== null && new Date().toDateString() === new Date(currentYear, currentMonth, day).toDateString();

              return (
                <button
                  key={i}
                  disabled={day === null}
                  onClick={() => setSelectedDay(isSelected ? null : day)}
                  className={`
                    relative h-10 rounded-xl flex flex-col items-center justify-center transition-all text-[10px] font-bold
                    ${day === null ? 'opacity-0' : 'hover:bg-white/5'}
                    ${isSelected ? 'bg-primary text-background-dark scale-110 shadow-lg shadow-primary/20 z-10' : 'text-gray-400'}
                    ${isToday && !isSelected ? 'border border-primary/30 text-primary' : ''}
                  `}
                >
                  {day}
                  {hasTournament && (
                    <div className={`absolute bottom-1.5 size-1.5 rounded-full ${isSelected ? 'bg-background-dark' : 'bg-primary shadow-[0_0_5px_rgba(96,122,251,0.5)]'}`}></div>
                  )}
                </button>
              );
            })}
          </div>

          {selectedDay && (
            <button 
              onClick={() => setSelectedDay(null)}
              className="w-full mt-4 py-2 bg-white/5 rounded-xl text-[9px] font-black text-primary uppercase tracking-widest flex items-center justify-center gap-2"
            >
              <span className="material-symbols-outlined text-sm">close</span>
              Limpar Filtro de Data
            </button>
          )}
        </div>
      </section>

      <div className="space-y-4">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Pesquisar local..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-card-dark border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:ring-2 focus:ring-primary/50 outline-none transition-all"
          />
        </div>

        <div className="flex flex-col gap-3">
          <div className="flex items-center justify-between px-1">
            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest">
              {selectedDay ? `Torneios em ${selectedDay} de ${calendarDate.toLocaleDateString('pt-PT', { month: 'long' })}` : 'Lista de Torneios'}
            </h3>
            <span className="text-[10px] font-bold text-primary">{filteredHistory.length} encontrados</span>
          </div>

          {filteredHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 opacity-30 text-center">
              <span className="material-symbols-outlined text-6xl mb-4">history_toggle_off</span>
              <p className="text-sm font-bold">Nenhum registo encontrado</p>
              {selectedDay && <p className="text-[10px] uppercase mt-1">Tente selecionar outro dia ou limpar o filtro.</p>}
            </div>
          ) : (
            filteredHistory.map(t => {
              const loc = locations.find(l => l.id === t.locationId);
              const locName = loc?.name || 'Local Desconhecido';
              const isCancelled = t.status === 'cancelled';
              const winnerPlayers = getWinnersOfTournament(t);

              return (
                <div key={t.id} className={`relative group ${isCancelled ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                  <button 
                    onClick={() => !isCancelled && onViewTournament(t)}
                    disabled={isCancelled}
                    className="w-full bg-card-dark p-5 rounded-3xl border border-white/5 hover:border-primary/30 transition-all text-left group active:scale-[0.98] disabled:cursor-not-allowed"
                  >
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <span className={`text-[10px] font-black uppercase tracking-widest block mb-1 ${isCancelled ? 'text-red-500' : 'text-primary'}`}>
                          {new Date(t.date).toLocaleDateString('pt-PT', { day: 'numeric', month: 'long', year: 'numeric' })}
                          {isCancelled && ' (CANCELADO)'}
                        </span>
                        <h3 className="text-xl font-black text-white group-hover:text-primary transition-colors">{locName}</h3>
                      </div>
                      {!isCancelled && (
                          <div className="size-10 rounded-2xl bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                              <span className="material-symbols-outlined text-gray-500 group-hover:text-primary">chevron_right</span>
                          </div>
                      )}
                    </div>

                    <div className="flex items-center justify-between gap-4">
                      {winnerPlayers ? (
                        <div className="flex gap-4">
                          {winnerPlayers.map(p => (
                             <div key={p.id} className="flex flex-col items-center gap-1">
                                {renderGlobalAvatar(p, 'size-8 ring-1 ring-white/10')}
                                <span className="text-[7px] font-black text-white uppercase tracking-tighter opacity-80">{p.nickname || p.name.split(' ')[0]}</span>
                             </div>
                          ))}
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 opacity-30">
                          <span className="material-symbols-outlined text-[16px]">sports_tennis</span>
                          <span className="text-[10px] font-bold uppercase">{t.matches?.length || 0} Jogos</span>
                        </div>
                      )}

                      <div className="flex items-center gap-1.5 text-gray-500 bg-white/5 px-2 py-1 rounded-lg">
                        <span className="material-symbols-outlined text-[14px]">schedule</span>
                        <span className="text-[9px] font-bold uppercase whitespace-nowrap">{t.time} • {t.duration}h</span>
                      </div>
                    </div>
                  </button>
                  <button 
                    onClick={(e) => { e.stopPropagation(); onDeleteTournament?.(t.id); }}
                    className="absolute bottom-4 right-4 p-2 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all opacity-0 group-hover:opacity-100 z-10"
                  >
                    <span className="material-symbols-outlined text-base">delete</span>
                  </button>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Screen, Match, Player, Tournament, Location, CloudConfig } from './types';
import { Navigation } from './components/Navigation';
import { PullToRefresh } from './components/PullToRefresh';
import { HomeScreen } from './screens/HomeScreen';
import { ProfileScreen } from './screens/ProfileScreen';
import { LiveGameScreen } from './screens/LiveGameScreen';
import { TournamentResultsScreen } from './screens/TournamentResultsScreen';
import { GlobalStatsScreen } from './screens/GlobalStatsScreen';
import { TeamSetupScreen } from './screens/TeamSetupScreen';
import { PlayerListScreen } from './screens/PlayerListScreen';
import { LocationManagerScreen } from './screens/LocationManagerScreen';
import { TournamentSummaryScreen } from './screens/TournamentSummaryScreen';
import { HistoryDetailScreen } from './screens/HistoryDetailScreen';
import { TournamentHistoryScreen } from './screens/TournamentHistoryScreen';
import { SettingsScreen } from './screens/SettingsScreen';

const App: React.FC = () => {
  const [players, setPlayers] = useState<Player[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [tournamentHistory, setTournamentHistory] = useState<Tournament[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'online' | 'offline' | 'error'>('offline');
  const [lastErrorMessage, setLastErrorMessage] = useState<string>('');

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const envUrl = (import.meta as any).env?.VITE_SUPABASE_URL;
    const envKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY;
    if (envUrl && envKey) return { url: envUrl, key: envKey, enabled: true };
    const saved = localStorage.getItem('padel_cloud_config');
    return saved ? JSON.parse(saved) : { url: '', key: '', enabled: false };
  });

  const [currentScreen, setScreen] = useState<Screen>(Screen.HOME);
  const [matches, setMatches] = useState<Match[]>([]);
  const [currentRound, setCurrentRound] = useState(1);
  const [activeTournament, setActiveTournament] = useState<Tournament | null>(null);
  const [selectedPlayerId, setSelectedPlayerId] = useState<string | null>(null);
  const [selectedHistoryTournament, setSelectedHistoryTournament] = useState<Tournament | null>(null);

  const isTournamentDifferent = (t1: Tournament | null, t2: Tournament | null) => {
      if (!t1 && !t2) return false;
      if (!t1 || !t2) return true;
      return JSON.stringify(t1) !== JSON.stringify(t2);
  };

  const loadLocalData = useCallback(() => {
      const p = localStorage.getItem('padel_players');
      const l = localStorage.getItem('padel_locations');
      const h = localStorage.getItem('padel_history');

      let loadedPlayers = p ? JSON.parse(p) : [];
      let loadedLocations = l ? JSON.parse(l) : [];
      let allTournaments = h ? JSON.parse(h) : [];

      setPlayers(loadedPlayers);
      setLocations(loadedLocations);
      return allTournaments;
  }, []);

  const fetchCloudData = useCallback(async (config: CloudConfig) => {
    if (!config.enabled || !config.url || !config.key) {
        setSyncStatus('offline');
        return null;
    }

    try {
      const headers = { 'apikey': config.key, 'Authorization': `Bearer ${config.key}`, 'Content-Type': 'application/json' };
      const responses = await Promise.all([
        fetch(`${config.url}/rest/v1/players?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/locations?select=data`, { headers, cache: 'no-store' }),
        fetch(`${config.url}/rest/v1/tournaments?select=data`, { headers, cache: 'no-store' })
      ]);

      for (const res of responses) {
          if (!res.ok) {
              if (res.status === 404) {
                 throw new Error("Tabelas não encontradas no Supabase.");
              }
              const errorText = await res.text();
              throw new Error(`Erro ${res.status}: ${errorText}`);
          }
      }

      const [pRes, lRes, tRes] = await Promise.all(responses.map(r => r.json()));
      const playersData = Array.isArray(pRes) ? pRes.map((i: any) => i.data) : [];
      const locationsData = Array.isArray(lRes) ? lRes.map((i: any) => i.data) : [];
      const tournamentsData = Array.isArray(tRes) ? tRes.map((i: any) => i.data) : [];

      tournamentsData.sort((a: Tournament, b: Tournament) => {
          return new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime();
      });

      setSyncStatus('online');
      setLastErrorMessage('');

      return {
        players: playersData,
        locations: locationsData,
        tournaments: tournamentsData
      };
    } catch (e: any) { 
        setSyncStatus('error');
        setLastErrorMessage(e.message || "Erro de rede");
        return null;
    }
  }, []);

  const pushToCloud = async (table: 'players' | 'locations' | 'tournaments', id: string, data: any) => {
    if (!cloudConfig.enabled) return;
    try {
      const res = await fetch(`${cloudConfig.url}/rest/v1/${table}`, {
        method: 'POST',
        headers: { 
            'apikey': cloudConfig.key, 
            'Authorization': `Bearer ${cloudConfig.key}`, 
            'Content-Type': 'application/json', 
            'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify({ id, data })
      });
      if (!res.ok) setSyncStatus('error');
      else setSyncStatus('online');
    } catch (e: any) {
        setSyncStatus('error');
    }
  };

  const deleteFromCloud = async (table: 'players' | 'locations' | 'tournaments', id: string) => {
    if (!cloudConfig.enabled) return;
    try {
      await fetch(`${cloudConfig.url}/rest/v1/${table}?id=eq.${id}`, {
        method: 'DELETE',
        headers: { 
          'apikey': cloudConfig.key, 
          'Authorization': `Bearer ${cloudConfig.key}` 
        }
      });
    } catch (e) {
      console.error("Delete Error:", e);
    }
  };

  const refreshAllData = useCallback(async () => {
    let allTournaments: Tournament[] = [];
    const cloudData = await fetchCloudData(cloudConfig);

    if (cloudData) {
        setPlayers(cloudData.players);
        setLocations(cloudData.locations);
        allTournaments = cloudData.tournaments;
    } else {
        allTournaments = loadLocalData();
    }

    const active = allTournaments.find(t => t.status === 'scheduled' || t.status === 'live');
    const history = allTournaments.filter(t => t.status === 'finished' || t.status === 'cancelled');

    setTournamentHistory(history);

    if (active) {
       setActiveTournament(prev => {
           if (isTournamentDifferent(prev, active)) {
               if (active.matches && active.matches.length > 0) {
                   setMatches(active.matches);
                   const maxRound = Math.max(...active.matches.map(m => m.round));
                   setCurrentRound(maxRound);
               }
               return active;
           }
           return prev;
       });
    } else {
       setActiveTournament(null);
       setMatches([]);
    }
  }, [cloudConfig, fetchCloudData, loadLocalData]);

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await refreshAllData();
      setIsLoading(false);
    };
    init();
  }, [refreshAllData]);

  useEffect(() => {
    if (!isLoading) {
      localStorage.setItem('padel_players', JSON.stringify(players));
      localStorage.setItem('padel_locations', JSON.stringify(locations));
      const allTournaments = [...tournamentHistory];
      if (activeTournament) allTournaments.push(activeTournament);
      localStorage.setItem('padel_history', JSON.stringify(allTournaments));
      localStorage.setItem('padel_cloud_config', JSON.stringify(cloudConfig));
    }
  }, [players, locations, tournamentHistory, activeTournament, cloudConfig, isLoading]);

  const playerRankings = useMemo(() => {
    const rankings = new Map<string, { current: number, history: { date: string, points: number, level: string }[] }>();
    players.forEach(p => rankings.set(p.id, { current: 1000, history: [{ date: 'Início', points: 1000, level: 'Nível 1' }] }));
    const finishedTournaments = tournamentHistory.filter(t => t.status === 'finished');
    const sortedHistory = [...finishedTournaments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedHistory.forEach(t => {
        if (!t.matches) return;
        const teamResults = new Map<string, { wins: number, diff: number, pids: string[] }>();
        t.matches.forEach(m => {
            const k1 = m.team1.map(p => p.id).sort().join('-');
            const k2 = m.team2.map(p => p.id).sort().join('-');
            if (!teamResults.has(k1)) teamResults.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p=>p.id) });
            if (!teamResults.has(k2)) teamResults.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p=>p.id) });
            const s1 = teamResults.get(k1)!, s2 = teamResults.get(k2)!;
            s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
            if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
        });
        const standingsArr = Array.from(teamResults.values()).sort((a,b) => b.wins - a.wins || b.diff - a.diff);
        const championsIds = standingsArr[0]?.pids || [];
        t.matches.forEach(m => {
            const updateP = (p: Player, won: boolean) => {
                const d = rankings.get(p.id); if (d) { d.current += won ? 20 : -12; if (d.current < 800) d.current = 800; }
            };
            m.team1.forEach(p => updateP(p, m.score1 > m.score2)); m.team2.forEach(p => updateP(p, m.score2 > m.score1));
        });
        const affected = new Set<string>();
        t.matches.forEach(m => [...m.team1, ...m.team2].forEach(p => affected.add(p.id)));
        affected.forEach(pid => {
            const d = rankings.get(pid);
            if (d) {
                if (championsIds.includes(pid)) d.current += 50;
                const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
                d.history.push({ date: new Date(t.date).toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' }), points: d.current, level: getL(d.current) });
            }
        });
    });
    return rankings;
  }, [players, tournamentHistory]);

  const playersWithDynamicRanking = useMemo(() => {
    return players.map(p => {
        const r = playerRankings.get(p.id); const pts = r?.current || 1000;
        const getL = (pts: number) => pts >= 1600 ? 'Pro' : pts >= 1400 ? 'Nível 3' : pts >= 1200 ? 'Nível 2' : 'Nível 1';
        return { ...p, rankingPoints: pts, level: getL(pts) };
    });
  }, [players, playerRankings]);

  const handleNextRound = async () => {
    const nextRoundNumber = currentRound + 1;
    if (nextRoundNumber > 3) {
      setScreen(Screen.TOURNAMENT_SUMMARY);
      return;
    }

    const r1 = matches.filter(m => m.round === 1);
    const m1 = r1.find(m => m.court === 1);
    const m2 = r1.find(m => m.court === 2);

    if (m1 && m2) {
      const winner1 = m1.score1 > m1.score2 ? m1.team1 : m1.team2;
      const loser1 = m1.score1 > m1.score2 ? m1.team2 : m1.team1;
      const winner2 = m2.score1 > m2.score2 ? m2.team1 : m2.team2;
      const loser2 = m2.score1 > m2.score2 ? m2.team2 : m2.team1;

      let nextMatches: Match[] = [];
      const timestamp = Date.now();
      const dateStr = new Date().toISOString();

      if (nextRoundNumber === 2) {
        nextMatches = [
          { id: `m-r2-c1-${timestamp}`, team1: winner1, team2: loser2, score1: 0, score2: 0, court: 1, status: 'live', round: 2, date: dateStr },
          { id: `m-r2-c2-${timestamp}`, team1: winner2, team2: loser1, score1: 0, score2: 0, court: 2, status: 'live', round: 2, date: dateStr }
        ];
      } else if (nextRoundNumber === 3) {
        nextMatches = [
          { id: `m-r3-c1-${timestamp}`, team1: winner1, team2: winner2, score1: 0, score2: 0, court: 1, status: 'live', round: 3, date: dateStr },
          { id: `m-r3-c2-${timestamp}`, team1: loser1, team2: loser2, score1: 0, score2: 0, court: 2, status: 'live', round: 3, date: dateStr }
        ];
      }

      const updatedMatches = [...matches, ...nextMatches];
      setMatches(updatedMatches);
      setCurrentRound(nextRoundNumber);
      if (activeTournament) {
         const updatedTournament = { ...activeTournament, matches: updatedMatches };
         setActiveTournament(updatedTournament);
         await pushToCloud('tournaments', updatedTournament.id, updatedTournament);
      }
    }
  };

  const handleCreateTournament = async (t: Tournament) => {
      const newT = { ...t, status: 'scheduled' as const, rosterClosed: false };
      setActiveTournament(newT);
      await pushToCloud('tournaments', newT.id, newT);
  };
  const handleUpdateActiveTournament = async (t: Tournament) => {
      setActiveTournament(t);
      await pushToCloud('tournaments', t.id, t);
  };
  const handleCancelTournament = async () => {
      if (activeTournament && window.confirm('Deseja cancelar este agendamento?')) {
          const cancelledT = { ...activeTournament, status: 'cancelled' as const };
          setActiveTournament(null);
          setMatches([]);
          setTournamentHistory(prev => [cancelledT, ...prev]);
          await pushToCloud('tournaments', cancelledT.id, cancelledT);
      }
  };
  const updateMatchScore = async (id: string, team: 1 | 2, increment: boolean) => {
    const updatedMatches = matches.map(m => m.id === id ? {
      ...m, 
      [team === 1 ? 'score1' : 'score2']: increment 
        ? m[team === 1 ? 'score1' : 'score2'] + 1 
        : Math.max(0, m[team === 1 ? 'score1' : 'score2'] - 1)
    } : m);
    setMatches(updatedMatches);
    if (activeTournament) {
        const updatedTournament = { ...activeTournament, matches: updatedMatches };
        setActiveTournament(updatedTournament);
        pushToCloud('tournaments', updatedTournament.id, updatedTournament);
    }
  };
  const handleStartTournament = async (initialMatches: Match[]) => {
      setMatches(initialMatches);
      setCurrentRound(1);
      if (activeTournament) {
          const liveTournament: Tournament = { 
              ...activeTournament, 
              status: 'live', 
              matches: initialMatches 
          };
          setActiveTournament(liveTournament);
          await pushToCloud('tournaments', liveTournament.id, liveTournament);
      }
      setScreen(Screen.LIVE_GAME);
  };
  const handleAddPlayer = async (p: Player) => { setPlayers(prev => [...prev, p]); await pushToCloud('players', p.id, p); };
  const handleUpdatePlayer = async (p: Player) => { setPlayers(prev => prev.map(old => old.id === p.id ? p : old)); await pushToCloud('players', p.id, p); };
  const handleDeletePlayer = async (id: string) => { if (window.confirm('Remover jogador?')) { setPlayers(prev => prev.filter(p => p.id !== id)); await deleteFromCloud('players', id); } };
  const handleAddLocation = async (l: Location) => { setLocations(prev => [...prev, l]); await pushToCloud('locations', l.id, l); };
  const handleUpdateLocation = async (l: Location) => { setLocations(prev => prev.map(old => old.id === l.id ? l : old)); await pushToCloud('locations', l.id, l); };
  const handleDeleteLocation = async (id: string) => { setLocations(prev => prev.filter(l => l.id !== id)); await deleteFromCloud('locations', id); };
  const handleFinishTournament = async () => {
    if (activeTournament) {
        const finished: Tournament = { ...activeTournament, status: 'finished', matches: matches.map(m => ({...m, status: 'finished'})), };
        setTournamentHistory(prev => [finished, ...prev]);
        setActiveTournament(null);
        setMatches([]);
        await pushToCloud('tournaments', finished.id, finished);
    }
    setScreen(Screen.TOURNAMENT_RESULTS);
  };
  const handleDeleteTournament = async (id: string) => { 
    if (window.confirm('Apagar do histórico permanentemente?')) { 
      setTournamentHistory(prev => prev.filter(t => t.id !== id)); 
      await deleteFromCloud('tournaments', id); 
      setScreen(Screen.TOURNAMENT_HISTORY); 
    } 
  };

  const renderScreen = () => {
    if (isLoading) return <div className="h-screen flex flex-col items-center justify-center text-primary bg-background-dark"><span className="material-symbols-outlined animate-spin text-5xl mb-4">sync</span><p className="font-black uppercase tracking-widest text-xs">A carregar...</p></div>;

    switch (currentScreen) {
      case Screen.HOME: return <HomeScreen setScreen={setScreen} activeTournament={activeTournament} players={playersWithDynamicRanking} locations={locations} onCreateTournament={handleCreateTournament} onAddPlayer={handleAddPlayer} onUpdateTournament={handleUpdateActiveTournament} onCancelTournament={handleCancelTournament} history={tournamentHistory.filter(t => t.status === 'finished')} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} />;
      case Screen.PROFILE: return <ProfileScreen playerId={selectedPlayerId} players={playersWithDynamicRanking} history={tournamentHistory.filter(t => t.status === 'finished')} currentMatches={matches} setScreen={setScreen} onUpdatePlayer={handleUpdatePlayer} rankingHistory={selectedPlayerId ? playerRankings.get(selectedPlayerId)?.history : []} />;
      case Screen.LIVE_GAME: return <LiveGameScreen setScreen={setScreen} matches={matches.filter(m => m.round === currentRound)} updateMatchScore={updateMatchScore} onNextRound={handleNextRound} currentRound={currentRound} />;
      case Screen.TOURNAMENT_SUMMARY: return <TournamentSummaryScreen setScreen={setScreen} matches={matches} updateMatchScore={updateMatchScore} onFinish={handleFinishTournament} />;
      case Screen.TOURNAMENT_RESULTS: return <TournamentResultsScreen setScreen={setScreen} matches={tournamentHistory[0]?.matches || []} />;
      case Screen.GLOBAL_STATS: return <GlobalStatsScreen history={tournamentHistory.filter(t => t.status === 'finished')} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onViewPlayer={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} locations={locations} />;
      case Screen.TOURNAMENT_HISTORY: return <TournamentHistoryScreen history={tournamentHistory} locations={locations} players={playersWithDynamicRanking} onViewTournament={(t) => { setSelectedHistoryTournament(t); setScreen(Screen.HISTORY_DETAIL); }} onDeleteTournament={handleDeleteTournament} />;
      case Screen.HISTORY_DETAIL: return selectedHistoryTournament ? <HistoryDetailScreen setScreen={setScreen} tournament={selectedHistoryTournament} locations={locations} players={playersWithDynamicRanking} onDeleteTournament={handleDeleteTournament} /> : null;
      case Screen.TEAM_SETUP: return <TeamSetupScreen setScreen={setScreen} players={playersWithDynamicRanking.filter(p => activeTournament?.confirmedPlayerIds.includes(p.id))} onStartTournament={handleStartTournament} />;
      case Screen.PLAYERS: return <PlayerListScreen setScreen={setScreen} players={playersWithDynamicRanking} onPlayerClick={(id) => { setSelectedPlayerId(id); setScreen(Screen.PROFILE); }} onAddPlayer={handleAddPlayer} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} />;
      case Screen.LOCATIONS: return <LocationManagerScreen setScreen={setScreen} locations={locations} onAddLocation={handleAddLocation} onUpdateLocation={handleUpdateLocation} onDeleteLocation={handleDeleteLocation} history={tournamentHistory} />;
      case Screen.SETTINGS: return <SettingsScreen setScreen={setScreen} players={players} locations={locations} history={tournamentHistory} cloudConfig={cloudConfig} onUpdateCloudConfig={setCloudConfig} onImportData={(d) => { setPlayers(d.players); setLocations(d.locations); setTournamentHistory(d.history); }} onResetData={() => { localStorage.clear(); window.location.reload(); }} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-background-dark text-white font-sans selection:bg-primary selection:text-background-dark">
      <div className="max-w-md mx-auto min-h-screen relative shadow-2xl border-x border-white/5 bg-background-dark">
        <button 
          onClick={() => refreshAllData()}
          className={`absolute top-2 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-2 backdrop-blur-md px-3 py-1 rounded-full border cursor-pointer hover:bg-black/60 active:scale-95 transition-all ${syncStatus === 'error' ? 'bg-red-500/20 border-red-500/50' : 'bg-black/40 border-white/5'}`}
        >
          <div className={`size-1.5 rounded-full ${syncStatus === 'online' ? 'bg-emerald-500' : syncStatus === 'error' ? 'bg-red-500' : 'bg-orange-500'}`}></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">
             {syncStatus === 'online' ? 'Cloud Sync' : syncStatus === 'error' ? 'Erro Sync' : 'Offline'}
          </span>
          <span className="material-symbols-outlined text-[10px] text-gray-500">refresh</span>
        </button>
        <PullToRefresh onRefresh={refreshAllData}>
            {renderScreen()}
        </PullToRefresh>
        {[Screen.HOME, Screen.PROFILE, Screen.GLOBAL_STATS, Screen.PLAYERS, Screen.SETTINGS, Screen.TOURNAMENT_HISTORY].includes(currentScreen) && <Navigation currentScreen={currentScreen} setScreen={setScreen} />}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Screen, Tournament, Player, Location } from '../types';
import { renderGlobalAvatar } from './ProfileScreen';

interface HomeScreenProps {
  setScreen: (screen: Screen) => void;
  activeTournament: Tournament | null;
  players: Player[];
  locations: Location[];
  onCreateTournament: (tournament: Tournament) => void;
  onAddPlayer: (player: Player) => void;
  onUpdateTournament: (tournament: Tournament) => void;
  onCancelTournament: () => void;
  history: Tournament[];
  onViewTournament: (t: Tournament) => void;
}

export const HomeScreen: React.FC<HomeScreenProps> = ({ 
    setScreen, 
    activeTournament, 
    players, 
    locations,
    onCreateTournament,
    onAddPlayer,
    onUpdateTournament,
    onCancelTournament,
    history,
    onViewTournament
}) => {
  const [isCreating, setIsCreating] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isManagingPlayers, setIsManagingPlayers] = useState(false);
  const [playerSearchTerm, setPlayerSearchTerm] = useState('');

  const [date, setDate] = useState('');
  const [time, setTime] = useState('22:00');
  const [duration, setDuration] = useState(2);
  const [locationId, setLocationId] = useState('');
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([]);

  const [timeRemaining, setTimeRemaining] = useState<string>('');

  useEffect(() => {
    if (!activeTournament) return;

    const calculateTimeLeft = () => {
        const start = new Date(`${activeTournament.date}T${activeTournament.time}`);
        const now = new Date();
        const diff = start.getTime() - now.getTime();

        if (diff <= 0) {
             if (diff > -1000 * 60 * 60 * activeTournament.duration) return 'A DECORRER';
             return 'TERMINADO';
        }

        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
        const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

        if (days > 0) return `Faltam ${days}d ${hours}h`;
        if (hours > 0) return `Faltam ${hours}h ${minutes}m`;
        return `Faltam ${minutes}m`;
    };

    setTimeRemaining(calculateTimeLeft());
    const timer = setInterval(() => setTimeRemaining(calculateTimeLeft()), 60000);
    return () => clearInterval(timer);
  }, [activeTournament]);

  const totalGames = history.reduce((acc, t) => acc + (t.matches?.length || 0), 0);
  const totalHours = history.reduce((acc, t) => acc + t.duration, 0);

  const locationUsage: Record<string, number> = {};
  history.forEach(t => {
    locationUsage[t.locationId] = (locationUsage[t.locationId] || 0) + 1;
  });
  const favLocationId = Object.entries(locationUsage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const favLocation = locations.find(l => l.id === favLocationId)?.name || 'N/A';

  const getWinnersOfTournament = (t: Tournament) => {
    if (!t.matches || t.matches.length === 0) return null;

    const stats = new Map<string, { wins: number, diff: number, pids: string[] }>();
    t.matches.forEach(m => {
        const k1 = m.team1.map(p => p.id).sort().join('-');
        const k2 = m.team2.map(p => p.id).sort().join('-');
        if (!stats.has(k1)) stats.set(k1, { wins: 0, diff: 0, pids: m.team1.map(p => p.id) });
        if (!stats.has(k2)) stats.set(k2, { wins: 0, diff: 0, pids: m.team2.map(p => p.id) });
        const s1 = stats.get(k1)!, s2 = stats.get(k2)!;
        s1.diff += (m.score1 - m.score2); s2.diff += (m.score2 - m.score1);
        if (m.score1 > m.score2) s1.wins++; else if (m.score2 > m.score1) s2.wins++;
    });

    const standings = Array.from(stats.values()).sort((a, b) => b.wins - a.wins || b.diff - a.diff);
    if (standings.length === 0) return null;

    return standings[0].pids.map(id => players.find(p => p.id === id)).filter((p): p is Player => !!p);
  };

  const initCreation = () => {
    const today = new Date().toISOString().split('T')[0];
    setDate(today);
    setSelectedPlayers([]);
    const lxIndoor = locations.find(l => l.name.toLowerCase().includes('lx indoor'));
    if (lxIndoor) setLocationId(lxIndoor.id);
    else if (locations.length > 0) setLocationId(locations[0].id);
    setIsCreating(true);
    setIsEditing(false);
  };

  const initEdit = () => {
    if (!activeTournament) return;
    setDate(activeTournament.date);
    setTime(activeTournament.time);
    setDuration(activeTournament.duration);
    setLocationId(activeTournament.locationId);
    setSelectedPlayers(activeTournament.confirmedPlayerIds);
    setIsCreating(true);
    setIsEditing(true);
  };

  const togglePlayerInActiveTournament = (id: string) => {
    if (!activeTournament) return;
    const isAlreadyConfirmed = activeTournament.confirmedPlayerIds.includes(id);
    const updatedIds = isAlreadyConfirmed 
        ? activeTournament.confirmedPlayerIds.filter(pid => pid !== id)
        : [...activeTournament.confirmedPlayerIds, id];
    onUpdateTournament({ ...activeTournament, confirmedPlayerIds: updatedIds });
  };

  const handleSubmitTournament = () => {
    if (!date || !time || !locationId) return;
    if (isEditing && activeTournament) {
        onUpdateTournament({ 
            ...activeTournament, 
            date, 
            time, 
            duration, 
            locationId, 
            confirmedPlayerIds: selectedPlayers 
        });
    } else {
        onCreateTournament({ 
            id: `t-${Date.now()}`, 
            date, 
            time, 
            duration, 
            locationId, 
            confirmedPlayerIds: selectedPlayers, 
            status: 'scheduled', 
            rosterClosed: false 
        });
    }
    setIsCreating(false);
  };

  const handleCloseRoster = () => {
    if (activeTournament?.confirmedPlayerIds.length !== 8) {
        alert("São necessários exatamente 8 jogadores."); return;
    }
    if (confirm("Fechar convocatória e preparar sorteio?")) {
        onUpdateTournament({ ...activeTournament, rosterClosed: true });
        setIsManagingPlayers(false);
    }
  };

  const StatsSection = (
    <section className="grid grid-cols-3 gap-3">
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-primary mb-1">sports_tennis</span>
        <span className="text-xl font-bold text-white">{totalGames}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Jogos</span>
      </div>
      <div className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm">
        <span className="material-symbols-outlined text-purple-400 mb-1">schedule</span>
        <span className="text-xl font-bold text-white">{totalHours}h</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Tempo</span>
      </div>
      <button 
        onClick={() => setScreen(Screen.LOCATIONS)}
        className="bg-card-dark p-4 rounded-2xl border border-white/5 flex flex-col items-center shadow-sm overflow-hidden active:scale-95 transition-all group"
      >
        <span className="material-symbols-outlined text-emerald-400 mb-1 group-hover:scale-110 transition-transform">star</span>
        <span className="text-[10px] font-bold text-white text-center truncate w-full">{favLocation}</span>
        <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wider">Clube</span>
      </button>
    </section>
  );

  if (isCreating) {
    return (
        <div className="flex flex-col gap-6 p-4 pb-32 animate-fade-in min-h-screen bg-background-dark relative z-20">
            <header className="flex items-center justify-between">
                <button onClick={() => setIsCreating(false)} className="size-10 rounded-full flex items-center justify-center bg-white/5"><span className="material-symbols-outlined text-white">close</span></button>
                <h2 className="text-lg font-bold">{isEditing ? 'Editar Torneio' : 'Novo Torneio'}</h2>
                <div className="w-10"></div>
            </header>
            <div className="space-y-5">
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Data</label>
                        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white" />
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hora</label>
                        <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white" />
                    </div>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between"><label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Duração</label><span className="text-xs font-bold text-primary">{duration}h</span></div>
                    <input type="range" min="1" max="4" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-primary h-2 bg-card-dark rounded-lg appearance-none cursor-pointer" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Local</label>
                    <select value={locationId} onChange={(e) => setLocationId(e.target.value)} className="w-full bg-card-dark border border-white/10 rounded-xl px-4 py-3 text-white appearance-none">
                        {locations.map(loc => <option key={loc.id} value={loc.id}>{loc.name}</option>)}
                    </select>
                </div>
                {!isEditing && (
                    <div className="space-y-3">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Confirmados Iniciais ({selectedPlayers.length})</label>
                        <div className="grid grid-cols-4 gap-2">
                            {players.map(p => (
                                <button key={p.id} onClick={() => { if(selectedPlayers.includes(p.id)) setSelectedPlayers(selectedPlayers.filter(i => i !== p.id)); else setSelectedPlayers([...selectedPlayers, p.id]); }} className={`flex flex-col items-center p-2 rounded-xl border transition-all ${selectedPlayers.includes(p.id) ? 'bg-primary/20 border-primary' : 'bg-card-dark border-transparent opacity-60'}`}>
                                    {renderGlobalAvatar(p, 'size-8')}
                                    <span className="text-[9px] font-bold truncate w-full text-center mt-1">{p.nickname || p.name.split(' ')[0]}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </div>
