                                </div>
                             </foreignObject>
                           )}
                        </g>
                      );
                    })}

                    {/* Labels de Datas no Eixo X */}
                    {points.length > 0 && (
                      <>
                        <text x={points[0].x} y={height + 25} textAnchor="start" fontSize="8" fontWeight="900" fill="#4b5563" className="uppercase tracking-tighter">{points[0].data.date}</text>
