    standings.forEach((team, idx) => {
        shareText += `${idx + 1}º ${team.teamName} (${team.wins}V/${team.gamesPlayed - team.wins}D)\n`;
    });

    shareText += `\n--- JOGOS ---\n`;
    rounds.forEach(r => {
        shareText += `\n*RONDA ${r}*\n`;
        matches.filter(m => m.round === r).forEach(m => {
